const b=[{id:"state-emotion-decisions",title:"Lerner ve arkadaşları · 2015 · Duygu ve karar verme · ST01 dosyası",url:"https://doi.org/10.1146/annurev-psych-010213-115043",type:"research",finding:"Yaklaşık 35 yıllık araştırmayı ele alan anlatı derlemesine göre, bir olaydan kalan duygular başka bir konudaki kararı da etkileyebilir. Bu etki, duyguya ve karara bağlı olarak yararlı veya zararlı olabilir.",limitation:"Birleştirilmiş tahmin yok. Üç parçalı bir ruh hâli mekanizmasını, herkese uyan en iyi ruh hâlini veya bir dakikalık toparlanmayı doğrulamaz."},{id:"state-regulation-meta",title:"Webb, Miles ve Sheeran · 2012 · Duygu düzenleme yöntemleri · ST02 dosyası",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"306 deneysel karşılaştırmada ortalama etki, düşünme biçimini değiştirmede d = 0,36; tepkiyi düzenlemede 0,16; dikkati yönlendirmede 0,00’dı. Alt kategoriler ve ölçülen duygusal sonuçlar farklıydı.",limitation:"Çoğunlukla deneysel olarak oluşturulan duygular incelendi. Tedavi gören gruplar değil. Duygunun ifadesi ve yaşanması farklıdır. Belirli soru kalıplarını veya her zaman en iyi olan yöntemi doğrulamaz."},{id:"state-acute-exercise",title:"Reed ve Ones · 2006 · Bir seferlik egzersiz ve enerji · ST03 dosyası",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 çalışma, 450 etki, 13.101 katılımcı: enerjik olumlu duygularda egzersizle ilişkili düzeltilmiş ortalama değişim 0,47’ydi. Kontrol koşulunun değişimi ayrı olarak -0,17 bildirildi.",limitation:"Ayrı bildirilen bu değişimler, rastgele kontrollü tedavi karşılaştırması değildir. Çoğunlukla sağlıklı gönüllüler vardı, yanıtlar değişkendi. Kanıtlanmış iki dakikalık süre veya depresyon tedavisi gösterilmedi."},{id:"state-exercise-mental-health",title:"Singh ve arkadaşları · 2023 · Fiziksel etkinlik ve sıkıntı · ST04 dosyası",url:"https://doi.org/10.1136/bjsports-2022-106195",type:"research",finding:"1.039 ayrı rastgele kontrollü deneyi ve 128.119’dan fazla katılımcıyı kapsayan 97 derleme, belirtilerde ortalama azalma buldu. Depresyon ve kaygı etkilerinin ortancaları -0,43 ve -0,42’ydi.",limitation:"77 derlemenin kalitesi çok düşüktü. Uzun programlar kısa hareketten farklıdır. Sıkıntıdaki -0,60, 508 katılımcılı altı deney içeren tek derlemeden geldi. Başka küçük deneyde istatistiksel olarak anlamlı sonuç bulunmadı."},{id:"state-facial-feedback",title:"Coles, Larsen ve Lench · 2019 · Yüz ifadesi geri bildirimi · ST05 dosyası",url:"https://doi.org/10.1037/bul0000194",type:"research",finding:"138 çalışma ve 286 etkide genel d = 0,20; %95 güven aralığı 0,14 ile 0,26’ydı. Duyguların yaşanması ve duygusal yargılar birleştirildi. Etkiler küçük ve değişkendi.",limitation:"Yayımlanmış sayı 138, 136 değil. Bazı yargı etkileri yayın yanlılığı işaretleri gösterdi. Gülümsemeyi güvenilir bir sıkıntı tedavisi olarak belirlemez."},{id:"state-cyclic-sighing",title:"Balban ve arkadaşları · 2023 · Kısa nefes uygulamaları · ST09 dosyası",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 yetişkin rastgele gruplara ayrılıp 28 gün boyunca günde beş dakika uyguladı. Çoğu Stanford’daki bir lisans psikoloji dersinden alındı. Modelleme, olumlu duygularda nefes uygulamalarını destekledi.",limitation:"Keşif amaçlı deneyin kaydı sonradan yapıldı. Kaygıda üstünlük, iki nefeslik süre, kalıcılık veya tedavi etkisi göstermez."},{id:"state-affect-labeling",title:"Lieberman ve arkadaşları · 2007 · Duyguları adlandırma · ST11 dosyası",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"30 sağlıklı yetişkin, beyin görüntüleme sırasında yüzlerdeki duyguları adlandırdı. Duygu sözcüğü ile cinsiyete uygun isim koşulları, amigdalada ölçülen bir değerde farklıydı. Bildirilen d = 0,79’du.",limitation:"Öznel sıkıntıdan toparlanma sonucu değildir. Daha hafif sözcüklerin, kendi duygunu adlandırmanın, kalıcı belirti azalmasının veya bu çalışma sayfasının yararını göstermez."},{id:"state-gratitude-expressed",title:"Kirca, Malouff ve Meynadier · 2023 · İfade edilen şükran · ST13 dosyası",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"23 çalışma ve 25 rastgele atanmış örneklemde olumlu iyi oluş üzerindeki etki, nötr kontrol koşullarına göre g = 0,22’ydi. İyi oluş için kullanılan başka etkinliklere göre g = 0,12’ydi. Bu ikinci karşılaştırmanın güven aralığı sıfırı içeriyordu.",limitation:"Makalede katılımcı toplamları çelişiyor. Bu yüzden tam sayı öğretilmiyor. Sabah hazırlık paketini, gelecek sahnelerini canlandırmayı veya güvenilir alternatiflere üstünlüğü doğrulamaz."},{id:"state-positive-self-statements",title:"Wood ve arkadaşları · 2009 · Olumlu kişisel cümleler · ST12 dosyası",url:"https://doi.org/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"İlk üniversite örneklemi deneyleri, tekrarlanan olumlu cümlelere yanıtların öz saygıya göre farklı olabileceğini gösterdi. Bazı katılanlar için daha kötü yanıt da olasıydı.",limitation:"Sonraki tekrar denemeleri ruh hâli, o anki öz saygı veya etkiyi değiştiren koşullara dair bulguları yeniden elde etmedi. Evrensel yarar veya zarar gösterilmedi. Coşkulu telkin üstünlüğü kanıtı yok."},{id:"state-mental-contrasting",title:"Wang, Wang ve Gai · 2021 · Hedefe ulaşma · ST15 dosyası",url:"https://doi.org/10.3389/fpsyg.2021.565202",type:"research",finding:"21 makale, 24 bağımsız etki, 15.907 katılımcı: zihinsel karşılaştırmayla yanıt planlamada g = 0,336 bulundu. Yayın yanlılığına göre düzeltilmiş tahmin daha küçüktü: 0,242.",limitation:"Çalışmalar farklıydı, yayın yanlılığı olasıydı. Dickens canlandırmasını, utancı, katı mecburiyet dilini veya bir uygulama biçiminin nedensel olarak üstün olduğunu doğrulamaz."},{id:"state-self-compassion-motivation",title:"Breines ve Chen · 2012 · Kendini geliştirme isteği · ST16 dosyası",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Dört kısa deney, şefkatle gelişme isteğinin birlikte bulunabileceğini destekledi. Başarısız sınavdan sonra çalışma süresi ortalama 306,5 saniyeydi. Hatırlatma almayan koşulda 203,2 saniyeydi.",limitation:"İkinci sınav notlarında istatistiksel olarak anlamlı fark bulunmadı. Öz saygı karşılaştırması kesin sonuç vermedi. Kalıcı değişimi, gerçek düzeltmeyi veya Dickens yönteminin etkisini kanıtlamaz."},{id:"state-nhs-panic",title:"NHS · Panik bozukluğu · ST18 dosyası",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Tekrar eden beklenmedik panik, uzman değerlendirmesi gerektirir. Kabul görmüş tedavi seçenekleri arasında bilişsel davranışçı terapi ve ilaç bulunur.",limitation:"Rehberdir, koçluk etkisi araştırması değildir. ODA paniğe tanı koyamaz. Yeni göğüs ağrısını, bayılmayı veya açıklanamayan nefes güçlüğünü zararsız kaygı sayamaz. Uygun tıbbi veya acil yardım kullan."},{id:"state-affirmation-replication",title:"Flynn ve Bordieri · 2020 · Olumlama tekrar çalışmaları · ST20 dosyası",url:"https://doi.org/10.1016/j.jcbs.2020.03.003",type:"research",finding:"İki üniversite benzetim deneyinde, olumlamalar için önceki ruh hâli ve o anki öz saygı bulguları yeniden elde edilemedi. Kişinin genel öz saygısına göre etkinin değişmesi de doğrulanmadı.",limitation:"Bu sonuçlar eşdeğerliği kanıtlamaz veya her olumlama için kesin bir sonuca varmamızı sağlamaz. İki başarısız tekrar denemesi, önceki yararları ve öz saygı farklarını belirsiz bırakır."}],m=[{schemaVersion:2,revision:2,id:"state-1",courseId:"state",locale:"tr",title:"Bir tartışmanın öfkesini sonraki konuşmaya taşıma",goal:"Başka bir olaydan kalan duyguyu fark et. Sonra güvenli bir ortamda yararlı bir isteğini ilet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Önceki konuşmanın öfkesi hâlâ içinde mi? Sıradaki isteğini kendi koşullarına göre değerlendir.",reason:{id:"state-1-reason",label:"Önceki duygunun sürmesi, bu yeni konuşmada sana neye mal oluyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Evde isteğimi açıkça dile getirmek","İş ilişkimi bu gerginlikten korumak","Bir tartışmanın etkisini diğerine taşımamak"]},why:{id:"state-1-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-1-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir duygu, ona neden olmuş gibi görünen durumdan önce başlamış olabilir. Zor bir vardiyadan kalan öfke, evdeki tamir isteğini etkileyebilir. Araştırmalar, duyguların ilgisiz başka kararlara taşınabildiğini gösteriyor. Bu, duygunun yanlış olduğu anlamına gelmez. Hangi olaydan geldiğine bak. Şu anki kişi, önceki tartışmanın sorumlusu olmayabilir.","Bu kurs için tekrarlanan bir geçiş anı seç: bir arama, mesaj veya önem verdiğin işe başlamadan önce. Duyguyu ve nereden gelmiş olabileceğini adlandır. Önce sakinleşmeyi şart koşmadan yararlı bir adım at. Gerçek zarara işaret eden öfkeyi gözden kaçırma. Açık bir istek, korunmak veya destek almak, ruh hâlini değiştirmekten daha önemli olabilir."],example:{title:"Derya tamir için mesaj gönderiyor",text:"Saat 18.00. Derya gergin bir vardiyadan sonra eve öfkeli geliyor. Akan musluğun onarılması gerekiyor. İşteki tartışmaya ev sahibinin neden olmadığını fark ediyor. Mutfak masasına oturup açık bir tamir isteği gönderiyor. Gelen yanıtta fotoğraf isteniyor. İlettiği isteği kaydedip fotoğrafı gönderiyor. Öfkesi hâlâ sürüyor. Ev sahibiyle konuşmasını, işte olanlardan ayrı tutuyor."}},move:{invitation:"Seçtiğin geçiş anında yararlı bir isteğini ilet. Duyguyu fark et, sonra cümlenle isteğini ilet.",instructions:["Duygunun nerede başlamış olabileceğini söyle.","Güvenli bir ortamda açık bir isteğini dile getir."],prompts:[],suggestions:{action:["Tamir için tek bir açık istek gönder","Gereken bir ayrıntıyı öğrenmek için sor","Somut bir ihtiyaç için destek iste"],minimum:["İsteğimi anlatan tek bir cümle gönder","Belirli bir konu hakkında tek soru sor","Destek gereken tek bir ihtiyacımı belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Sıradaki gerekli mesajımı göndermeden önce","Bir sonraki güvenli görüşmem başladığında"],place:["Mutfak masamın başında otururken","Güvenle kullanabildiğim mesajlaşma kanalında"],minutes:[2,1,5],fallback:["Güvenli bir yazılı mesaj kullan","Daha sonraki güvenli bir fırsatı seç"],observation:["İlettiğim istek ve gelen gerçek yanıt","İsteğimi gerçekten iletip iletmediğim"]},suggested:{action:"Tamir için tek bir açık istek gönder",minimum:"İsteğimi anlatan tek bir cümle gönder",minutes:2,cueHint:"Sıradaki gerekli mesajımı göndermeden önce",placeHint:"Mutfak masamın başında otururken",obstacleHint:"Önceki konuşma hâlâ aklımda.",fallbackHint:"Güvenli bir yazılı mesaj kullan",observationHint:"İlettiğim istek ve gelen gerçek yanıt"},stopRule:"Gerçek tehlike varsa ara ver. Korunmayı veya destek almayı seç.",accessibleAlternative:"Gözlerini açık tut. Oturmaya devam et. Odaya dikkatini ver ve her zamanki iletişim yöntemini kullan."},result:{question:"Seçtiğin isteği gerçekten ilettin mi?",observationPrompt:"Tam olarak ne istedin, ardından nasıl bir yanıt geldi?"},judgment:{primary:{id:"state-1-carryover-request",scenario:"Tamir randevusu istemek için iki dakika kalmış. Gergin bir vardiyadan çıkan Derya, akan musluğun bu hafta onarılmasını istiyor. Ev sahibi daha önce makul yanıtlar verdi.",question:"Bu isteği duruma uygun biçimde nasıl iletebilir?",bestOptionId:"name-and-request",options:[{id:"pause-then-request",text:"Düşüncelerini toparlamak için beş dakika ara versin. Sonra durumu anlatan isteğini, tamir tarihini soran bir cümleyle göndersin.",feedback:"Süresi belli bir ara, isteğini düzenlemene yardımcı olabilir. Ama burada randevu fırsatı kaçıyor. Mesajı şimdi göndermek mümkün. Derya öfkesi sürerken de gerçek durumu anlatıp tarih isteyebilir."},{id:"describe-without-date",text:"Sızıntıyı kısaca anlatan bir mesajı hemen göndersin. Sonraki adımın ne olacağını ev sahibinin önermesine izin versin.",feedback:"Bu seçim sorunu doğru anlatıyor, randevu fırsatına yetişiyor. Ama Derya’nın bu hafta tamir ihtiyacı varken zamanı belirsiz bırakıyor. Tarih sormak, kabul edilmesini şart koşmadan ihtiyacını görünür kılar."},{id:"name-and-request",text:"Önceki olaydan kalan öfkeyi fark etsin. Musluktaki sızıntıyı anlatsın. Tamirin yapılacağı bir tarihi açıkça sorsun.",feedback:"Bu seçim duyguyu, bu konuşmaya dair gördüklerinden ayırıyor. Derya gereken isteği iletiyor, gelen yanıtı kaydedebilir. Sakinleşmek veya karşı tarafla anlaşmak, tamamlanma şartı değil. İstek ile yanıt ayrı kalır."}]}},carry:{takeaway:"Duygu nereden geldi, ona bak. Sıradaki isteğini o konuşmanın gerçeklerine göre dile getir.",followUp:{questionId:"state-1-return",question:"Ruh hâlin aynı kalsa da önceki duyguyu fark etmek, ilettiğin isteği değiştirdi mi?",observationPrompt:"İsteğinde veya ruh hâlinde ne değişti? İkisinin de aynı kalması geçerli bir yanıt.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Duygular bir karardan diğerine taşınabilir",paragraphs:["Lerner ve arkadaşları, duygu ve karar verme üzerine yaklaşık 35 yıllık araştırmayı inceledi. Başka bir yerde başlayıp yeni bir yargıyı etkileyen duyguları anlatıyorlar. Duygular kararları zorlaştırabilir, yardımcı da olabilir. İşe yarayan soru şu: bu duygu, şimdiki durum hakkında bilgi mi veriyor, yoksa daha önce olan bir şeyi mi yansıtıyor? Nereden geldiğine bakmak, onu yok saymak değildir. [ST01: state-emotion-decisions]","Bu ayrım öfkeyi, üzüntüyü veya kaygıyı silmeni istemiyor. Tekrarlanan hakaret, karşılanmamış ihtiyaç ve yorucu vardiya farklı gerçeklerdir. Yanıtını seçmeden önce şu anki kanıtı belirt. Tamir gerekiyorsa tamir iste. Korunman gerekiyorsa korunmayı seç. Bu ders, kararı görünür kılmak için gündelik bir istek kullanıyor. Önceki duyguyu adlandırmanın onu değiştirdiğini, karşı tarafın iş birliğini garantilediğini veya güvenli olmayan ilişkiyi çözdüğünü göstermiyor. Kötü muameleyi başka bir olaydan kalan öfke diye açıklamak zorunda değilsin."]},{heading:"Duygu testi yerine aynı denemeyi sürdür",paragraphs:["Bu kursta tekrarlanan tek bir geçiş anını ve hayatında istediğin tek bir yönü koru. Sonraki dersler, ancak kayıtların bir sorun gösterdiğinde o soruna uygun bir araç sunar. Yedi ayrı görev biriktirmiyorsun. Anlamlı gözlem, o anda ne istediğin, neye başladığın, neyi değiştirdiğin veya durdurduğundur. Ruh hâlin aynı kalmış olabilir. Mesajın yanıtsız kalabilir. Yine de isteğini iletmiş olabilirsin.","Webb ve arkadaşları, duygu düzenleme yöntemlerinin 306 deneysel karşılaştırmasını birleştirdi. Yorumu değiştirmek ortalama yararlar gösterdi. Ama yöntemler ve ölçülen sonuçlar farklıydı. Bazı sonuçlar duygunun ifadesiyle, bazıları yaşanmasıyla ilgiliydi. Bir duyguyu gizlemek, geçtiğini göstermez. Bu laboratuvar karşılaştırmaları beden, dikkat ve dil üçlüsünü veya ODA’nın kısa alıştırmasını doğrulamıyor. [ST02: state-regulation-meta] Kaydını kısa ve somut tut. Sonra verdiğin yanıta ve koşullarına bakarak sıradaki denemeyi seç."]}],sourceIds:["state-emotion-decisions","state-regulation-meta"]}},{schemaVersion:2,revision:2,id:"state-2",courseId:"state",locale:"tr",title:"Hâlâ enerjin yok mu? Küçük işi yine de dene",goal:"Aynı geçiş anında rahat bir hazırlığı dene. Sonra işin yararlı küçük bir kısmını yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hareket ettin ama beklediğin enerji gelmedi. Sıradaki küçük işi yine de yapabilir misin?",reason:{id:"state-2-reason",label:"Hangi yararlı iş bekliyor? Ne zaman dinlenip toparlanmak sana daha iyi gelir?",kind:"text",maxLength:160,optional:!0,suggestions:["Gücümün yettiği yerden işe başlamak","Yapmam gereken işte ilerlemek","Dinlenip toparlanmaya da yer bırakmak"]},why:{id:"state-2-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-2-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Tek seferlik aerobik egzersiz, enerjik hissetmeyi ortalama olarak artırabilir. Bu sonuç, fiziksel etkinlik programlarının klinik belirtilere etkisinden farklıdır. İki araştırma türü de iki dakikayı ruh hâlini güvenilir biçimde değiştiren bir süre olarak belirlemez. Kısa hareketin ardından herkes aynı sonucu yaşamaz.","Aynı geçiş anını ve yararlı işi koru. Hareket gücüne uyuyorsa müziği ve duruşunu değiştirmeden tek bir rahat seçenek dene. Sonra uygunsa işin en küçük kısmını yap. Dinlenmek veya hareket gerektirmeyen bir başlama işareti daha iyi uyabilir. Hazırlığını ve yaptığın yararlı işi ayrı kaydet. Birini yapmak, diğerinin yapıldığını göstermez."],example:{title:"Mert ilk slayt cümlesini yazıyor",text:"Saat 09.00. Mert bir bilgilendirme sunumu hazırlamadan önce enerjisiz hissediyor. Kısa, rahat bir yürüyüş seçiyor. Müzik listesini açmıyor. Masasına dönünce enerjisi aynı. Yine de slayta işe yarayan tek bir cümle yazıyor. İki gerçeği de kaydediyor. Slaytta daha yapılacak iş var. Sıradaki denemede oturarak başlamayı seçiyor. Yürüyüşü ve yazdığı cümleyi ayrı değerlendiriyor."}},move:{invitation:"Aynı geçiş anında, yararı olacaksa tek bir rahat hazırlık dene. Sonra işinin en küçük kısmını yap.",instructions:["Tek bir araç seç veya her zamanki hareketsiz hazırlığını koru.","Gücün yettiği ölçüde işte yararlı tek bir adım at."],prompts:[],suggestions:{action:["İşim için kullanılabilir tek bir cümle yaz","İşimde küçük bir düzeltmeyi tamamla","Seçtiğim açık isteği karşı tarafa gönder"],minimum:["İşe yarayan tek bir cümle yaz","İşimdeki tek bir hatayı düzelt","İsteğimi anlatan tek bir cümle gönder"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["İsteğe bağlı rahat bir hareketten sonra","İşime geçmek için zaten seçtiğim anda"],place:["Çalışma masamın başında otururken","Rahatça erişebildiğim çalışma yerinde"],minutes:[2,1,5],fallback:["Hareket etmeden oturarak başlamayı seç","Dinlen, başka bir uygun fırsat seç"],observation:["Yaptığım hazırlık ve ardından tamamladığım iş","Hareketin rahatsızlık verip vermediği"]},suggested:{action:"İşim için kullanılabilir tek bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",minutes:2,cueHint:"İsteğe bağlı rahat bir hareketten sonra",placeHint:"Çalışma masamın başında otururken",obstacleHint:"Hazırlıktan sonra da enerjim düşük kalıyor.",fallbackHint:"Hareket etmeden oturarak başlamayı seç",observationHint:"Yaptığım hazırlık ve ardından tamamladığım iş"},stopRule:"Hareket rahatsızlık veriyorsa dur. Gerektiğinde dinlenmeyi veya destek almayı seç.",accessibleAlternative:"Oturarak hareket et, gözlerin açıkken odaya dikkatini ver veya hareketsiz bir işaret seç. Gülümsemek şart değil."},result:{question:"İşin işe yarayan en küçük kısmını yaptın mı?",observationPrompt:"Gerçekte hangi hazırlığı yaptın, işte hangi adımı attın?"},judgment:{primary:{id:"state-2-unchanged-energy",scenario:"Rahat bir yürüyüşten sonra Mert’in enerjisi değişmedi. Rahatsızlık yok. Slayttaki bilgiler kontrol edildi. Tek bir cümle yazabilecek durumda. Üç dakikası kaldı.",question:"Hangi sonraki adım bu denemeyi işe yarar kılar?",bestOptionId:"task-and-record",options:[{id:"timed-seated-start",text:"Oturarak başlamaya hazırlanmak için iki dakika ayırsın. Sonra geriye kalan bir dakikada slayta tek bir cümle yazsın.",feedback:"Hareket rahatsızlık veriyorsa veya oturarak başlamak senin için daha erişilebilirse bu seçenek yararlı olabilir. Mert burada ikisini de bildirmiyor. Ek hazırlık, belirlenmiş bir engeli ele almadan kalan zamanın çoğunu tüketir."},{id:"task-and-record",text:"İşe yarayan cümleyi yazsın. Enerjisinin değişmediğini kaydetsin. Bir sonraki denemede başka rahat bir hazırlık yapmayı düşünsün.",feedback:"Beklenen duygu değişimi olmadan da iş yapılabilir. Mert hangi hazırlığı denediğini, başlayıp başlamadığını öğrenir. Sonra bunu değiştirebilir. Ruh hâlini zorla yükseltmek için çabasını artırmak zorunda değil."},{id:"check-and-draft",text:"Kontrol edilmiş slayt bilgisini bir iş arkadaşına doğrulatsın. Gelen yanıtı beklerken slayt için geçici bir taslak cümle yazsın.",feedback:"Geçici taslak ve ikinci kontrol, gerçek bilgi belirsizliğini giderebilir. Burada bilgiler zaten kontrol edilmiş. Tek bir kullanılabilir cümleyi şimdi yazıp kaydetmek mümkünken bu seçim başka birinin yanıtını beklemeyi gerektiriyor."}]}},carry:{takeaway:"Hazırlığı dürüstçe dene. Yararlı işin sonucuna bakarken gerçekten ne yaptığını esas al.",followUp:{questionId:"state-2-return",question:"Hazırlık başlamana yardımcı mı oldu, rahatsızlık mı verdi, yoksa dinlenmen gerektiğini mi gösterdi?",observationPrompt:"Yardımı, rahatsızlığı, toparlanma ihtiyacını veya belirgin fark olmadığını, işin sonucundan ayrı anlat.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Kısa süreli enerji ile tedavi farklı sorulardır",paragraphs:["Reed ve Ones, 13.101 kişinin katıldığı 158 çalışmayı ve tek seferlik aerobik egzersizleri birleştirdi. Derleme, enerjik ve uyanık hissetmek gibi olumlu, etkin duygularda egzersizle ilişkili ortalama değişimi 0,47 olarak bildirdi. Kontrol koşulunun değişimi ayrı bildirildi. Bunlar, egzersiz ile kontrolü karşılaştıran rastgele kontrollü bir tedavi etkisinin 0,47 olduğunu göstermez. Kişisel yanıtlar ve çalışma yöntemleri farklıydı. [ST03: state-acute-exercise]","Bu sonuç iki dakikalık süreyi, herkes için güvenilir enerjiyi veya depresyon tedavisini kanıtlamaz. Daha uzun fiziksel etkinlik programlarının ayrı bir üst derlemesinde belirtilerde ortalama azalmalar bulundu. Altındaki birçok derlemenin kalitesi çok düşük olarak değerlendirildi. [ST04: state-exercise-mental-health] Senin kısa hazırlığın, isteğe bağlı kişisel bir deneme. Erişimine, sağlığına ve gücüne uysun. Kaydın yorgunluk veya rahatsızlık gösteriyorsa aracı değiştirmek, destek istemek veya toparlanmaya zaman ayırmak, egzersizi uzatmaktan daha iyi katkı sağlayabilir."]},{heading:"İsteğe bağlı ekler zorunlu hâle gelmesin",paragraphs:["İşine başlamak için gülümsemen, geniş yer kaplayan bir duruş veya belirli bir şarkı gerekmez. Coles ve arkadaşları 138 çalışmayı ve 286 etkiyi inceledi. Duyguların yaşanması ile yargıları birleştiren genel yüz ifadesi geri bildirimi tahmini küçüktü: 0,20. Etkiler değişiyordu. Bazı yargılarda yayın yanlılığı işaretleri vardı. Bu, gülümsemenin sıkıntıya güvenilir bir yanıt olduğunu göstermez. [ST05: state-facial-feedback] Hazırlığında zorla gülümsemek şart olmamalı.","Sürdürdüğün bu denemede bir seferde tek hazırlığı değiştir. Hangi işi yapmak istediğin açık kalsın. Şarkı, duruş ve hareketi birlikte ekleyip hangisinin işe yaradığını tahmin etmek yerine diğer koşullarını her zamanki gibi tut. Kişisel bir gözlem, başka bir deneme seçmene yardımcı olabilir. Biyolojik mekanizmayı ayıramaz veya neden-sonuç belirleyemez. Sıradaki iş gücüne hâlâ uyuyorsa enerji artışı olmadan da en küçük kısmını yapabilirsin. Toparlanmak daha uygunsa daha iyi hissetmeyi zorlamak yerine o seçimi dürüstçe kaydet."]}],sourceIds:["state-acute-exercise","state-exercise-mental-health","state-facial-feedback"]}},{schemaVersion:2,revision:2,id:"state-3",courseId:"state",locale:"tr",title:"Çok mu gerginsin? Sakinleşmeye uğraşmadan ara ver",goal:"Rahat bir ara seç. Sonra mevcut yararlı davranışını sürdür veya uygun bir destek adımı at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bir nefes alıştırması daha bekleyebilir. Hangi yanıtı vermeden önce durup seçim yapman gerekiyor?",reason:{id:"state-3-reason",label:"Ara vermek neyi destekler, neyi geciktirir?",kind:"text",maxLength:160,optional:!0,suggestions:["Yanıtımı düşünerek vermek","Durmam gerektiğini gösteren işarete uymak","İşe yarayan somut destek istemek"]},why:{id:"state-3-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-3-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Çok konuşulan iç çekme araştırmasında 28 gün boyunca günde beş dakika uygulandı. İki nefesin anında sakinleştiren bir düğme olup olmadığı sınanmadı. Nefesini zorlamadığın bir mola, isteğe bağlı hazırlıktır. Seçtiğin yolun gerektirdiği asıl davranışın kendisi değildir.","Aynı geçiş anına ve davranışına dön. Güvenli bir yerde otur. Normal nefesini koruyabilir, gözlerini açık tutup odayı fark edebilirsin. Rahatsa hafifçe nefes al, ardından küçük bir nefes daha al ve zorlamadan yavaşça ver. Baş dönmesi, karıncalanma, nefes darlığı veya rahatsızlıkta dur. Sonra uygun yanıtı, dinlenmeyi veya desteği seç. Yeni, şiddetli fiziksel belirtiler tıbbi değerlendirme gerektirir. Bunları stres diye açıklama."],example:{title:"Elif’in bekleyen e-posta yanıtı",text:"Öğle yemeğinden sonra Elif masasında, acil olmayan bir e-posta yüzünden gergin. Nefesine odaklanmak rahatsızlık veriyor. Gözlerini açık tutup pencere çerçevesine dikkat ediyor. Sonra gerçek durumu açıklığa kavuşturan tek bir cümle gönderiyor. Kaygısı sürüyor. Yanıt henüz gelmedi. Dikkatini çevresine verdiği molayı ve gönderdiği cümleyi kaydediyor. Bunu başarılı bir nefes alıştırması gibi göstermiyor."}},move:{invitation:"Aynı davranışından önce rahat bir ara seç. Normal nefes alıp dikkatini çevrene vermek de geçerli seçenekler.",instructions:["Otur. Araç kullanma, sudan ve düşme riski olan yerlerden uzak dur.","Aradan sonra uygunsa seçtiğin davranışın en küçük kısmını yap."],prompts:[],suggestions:{action:["Düşünerek seçtiğim tek yanıt cümlesini gönder","Gereken bir ayrıntıyı öğrenmek için sor","Tek bir ihtiyaç için destek iste"],minimum:["Gerçek durumu anlatan tek bir cümle gönder","Tek bir açık soru sor","Destek gereken tek bir ihtiyacımı belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["İsteğe bağlı rahat bir aradan sonra","Sıradaki acil olmayan yanıtımdan önce"],place:["Kendi masamda güvenle otururken","Güvenli, yalnız kalabildiğim bir koltukta"],minutes:[2,1,5],fallback:["Normal nefes al, dikkatini çevrende olup bitene ver","Dur, destek için bir adım seç"],observation:["Moladaki rahatlığım ve gerçekten verdiğim yanıt","Durma işaretine uyup uymadığım"]},suggested:{action:"Düşünerek seçtiğim tek yanıt cümlesini gönder",minimum:"Gerçek durumu anlatan tek bir cümle gönder",minutes:2,cueHint:"İsteğe bağlı rahat bir aradan sonra",placeHint:"Kendi masamda güvenle otururken",obstacleHint:"Nefesime odaklanmak rahatsızlık veriyor.",fallbackHint:"Normal nefes al, dikkatini çevrende olup bitene ver",observationHint:"Moladaki rahatlığım ve gerçekten verdiğim yanıt"},stopRule:"Baş dönmesi, karıncalanma, nefes darlığı veya rahatsızlıkta dur. Normal nefesine dön. Yeni, şiddetli göğüs ağrısı veya açıklanamayan nefes güçlüğü tıbbi değerlendirme gerektirir.",accessibleAlternative:"Gözlerini açık tut. Oturmaya devam et. Nötr bir nesneye bak. Nefesini değiştiren alıştırmayı atla."},result:{question:"Seçtiğin davranışı gerçekten yaptın mı?",observationPrompt:"Neyi rahat buldun, ardından gerçekte nasıl bir yanıt verdin?"},judgment:{primary:{id:"state-3-uncomfortable-pause",scenario:"Elif nefes denemesini durdurup otururken normal nefesine dönüyor. Sersemlik sürüyor ve daha önce yaşamadığı bir şey. Yanıtı acil değil. Yakındaki bir iş arkadaşı yardım edebilir.",question:"Şimdi hangi adım değişmeli?",bestOptionId:"stop-and-support",options:[{id:"stop-and-support",text:"Oturmayı ve normal nefesi sürdürsün. E-postayı ertelesin. Tıbbi görüş almak için iş arkadaşından yardım istesin.",feedback:"Uygun biçimde durdu. Belirti sürüyor ve daha önce yaşamadığı bir şey. Zamanında yardım, e-postadan veya başka bir araçtan önce gelir. Şiddetli belirti veya acil tehlike, acil yardım gerektirir."},{id:"stop-and-look-outward",text:"Oturarak normal nefesini sürdürsün. Dikkatini pencere çerçevesine versin. Sonra yanıt vermeden önce durumuna yeniden baksın.",feedback:"Dikkatini çevrene vermek, rahatsızlık veren nefese odaklanmanın yerini alabilir. Burada yeni belirti, durduktan sonra da sürüyor. Bir nesneye odaklanmak, yardım istemeyi ve uygun tıbbi görüş almayı geciktirmemeli."},{id:"stop-and-defer",text:"Oturarak normal nefesini sürdürsün. E-postayı yarına bıraksın. Daha sonra sersemliğinin geçip geçmediğini kontrol ederek nasıl hissedeceğine baksın.",feedback:"Acil olmayan mesajı ertelemek, sağlıkla ilgilenmeye zaman bırakır. Ama mesajı geciktirmek, süren ve tanımadığı belirtiyi ele almıyor. Değerlendirmeyi de ertelemek yerine şimdi uygun yardım iste. İki işi birbirine karıştırma."}]}},carry:{takeaway:"Güvenle durmak yararlı bilgi verir. Düşünerek yanıt vermek için sakinleşmiş olman şart değil.",followUp:{questionId:"state-3-return",question:"Ara vermek rahat mıydı? Davranışını destekledi mi, yoksa başka bir araç mı gerekiyor?",observationPrompt:"Rahatlığı, durma veya destek ihtiyacını ve sonraki yanıtını ayrı ayrı anlat.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"İç çekme deneyinde gerçekte ne sınandı?",paragraphs:["Balban ve arkadaşları 108 yetişkini rastgele kısa nefes uygulamalarına veya farkındalık çalışmasına ayırdı. Katılanlar 28 gün boyunca günde beş dakika uygulama yaptı. Çoğu, Stanford’daki bir lisans psikoloji dersinden alındı. Çalışma keşif amaçlıydı ve araştırma kaydı sonradan yapıldı. Modelleme, olumlu duygularda nefes uygulamalarını destekledi. Kaygıda üstünlük veya iki nefesten güvenilir sonuç göstermedi. [ST09: state-cyclic-sighing]","Araştırılan döngüsel iç çekme, otururken veya uzanırken yavaş nefes almak, daha kısa ikinci bir nefes almak ve yavaş vermekti. Bu ders, rahat ve isteğe bağlı bir denemeyle normal nefes alternatifleri sunuyor. Güvenlik ve erişim seçimleri ODA uyarlamalarıdır. Akciğerlerini zorlayarak doldurup boşaltma. Nefesini tutma veya etkiyi zorlamak için hızlanma. Kaydında hazırlığı, durdurduğun denemeyi ve asıl yanıtını ayırabilirsin. Biri diğerlerinin yerine geçmez. Bir yanıt gönderdiğinde bunu nefes denemesinden ayrı bir davranış olarak kaydet."]},{heading:"Nefes alıştırması bir belirtiye tanı koymaz",paragraphs:["Nefes alıştırması fiziksel belirtinin nedenini söyleyemez. NHS rehberi, tekrar eden beklenmedik panik için uzman değerlendirmesi önerir ve kabul görmüş tedavi seçeneklerini anlatır. Kursun sınırı açık: ODA eğitimdir, tanı veya tedavi değildir. Tanımadığın göğüs ağrısını, bayılmayı veya açıklanamayan nefes güçlüğünü zararsız kaygı sayma. Yeni, şiddetli belirtiler tıbbi değerlendirme gerektirir. Acil tehlike, acil yardım gerektirir. [ST18: state-nhs-panic]","Nefesini değiştirmeden de somut bir yanıt seçebilirsin. Gözlerin açık kalsın. Nötr bir nesneyi fark et, otur veya destek iste. Ara vermek seni daha rahatsız ediyorsa bırak. Dayanmayı ilerleme sayma. Ortam güvenliyse ve yanıtı verebilecek durumdaysan yararlı bir isteği iletmeden önce sakinleşmek zorunda değilsin. Dinlenmek, korunmak veya birinden yardım almak uygunsa isteği sürdürmek zorunda da değilsin. O andaki koşullara göre seçim yap. Ders, asıl isteği her durumda göndermeni şart koşmuyor."]}],sourceIds:["state-cyclic-sighing","state-nhs-panic"]}},{schemaVersion:2,revision:2,id:"state-4",courseId:"state",locale:"tr",title:"Yine başa mı sardın? İşe yarayan soruyu sor",goal:"Tekrarlanan durumunla ilgili tek bir soruyu, yararlı bir davranışa veya uygun destek isteğine dönüştür.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bir kez daha “Neden?” sormak yeni bilgi getirmiyorsa hangi yanıt önündeki on dakikayı değiştirir?",reason:{id:"state-4-reason",label:"Bu durumu tekrar tekrar düşünürken hangi işi sonraya bırakıyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek bir sorunu açıklığa kavuşturmak","Öğrendiğim bilgiyi işimde kullanmak","Yararlı bir isteği artık ertelememek"]},why:{id:"state-4-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-4-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir soru, yanıtı seçimini değiştirdiğinde işe yarar. “Neden?” sormak bir nedeni, beceri eksiğini veya düzeltmenin kimin sorumluluğu olduğunu gösterebilir. Kendiliğinden zararlı değildir. Ama yeni bilgi olmadan aynı durumu yeniden düşünmek, sıradaki adımını değiştirmeyebilir. Araştırmakla düşünceyi tekrar edip durmayı ayır. Birinden bilgi alabilir, diğerinde aynı noktada kalabilirsin.","Seçtiğin geçiş anında neyi netleştirmek, değiştirmek veya hangi desteği almak gerektiğini sor. Yanıtında yapacağın iş olsun: gönder, düzelt, sor, dinlen. Araştırmalar bu cümleleri değil, geniş yöntemleri karşılaştırıyor. Bunu pratik bir yardımcı olarak gör. Mümkünse yanıtın gerektirdiğini yap. Sonra cesaret verici sözleri değil, ne yaptığını kaydet. Yanıt, gerçek durumundaki seçime katkı sağlasın."],example:{title:"Ömer bütçeyi onaylayacak kişiye ulaşmamış",text:"Saat 14.00. Ömer masasında ilerlemeyen proje isteğine bakıyor. “Neden?” diye sormak, kişisel başarısızlık yerine eksik bütçe onayını gösteriyor. Proje notlarında belirtilen kişiyi bulup tek bir açıklama isteği gönderiyor. O öğleden sonra yanıt gelmiyor. Daha fazla cesaret verici soru yazmak yerine sorduğu soruyu, mesajı ve hâlâ bekleyen onayı kaydediyor. Henüz onay almış değil."}},move:{invitation:"Aynı durum hakkında yararlı tek bir soru sor. Yanıtın gösterdiği, uygun en küçük davranışı yap.",instructions:["Gerektiğinde araştırmayı sürdür ve kimin sorumlu olduğunu açık tut.","Yanıta göre bir istek ilet veya bir düzeltme yap."],prompts:[],suggestions:{action:["Gereken bir ayrıntı için açıklama iste","İşimde belirlediğim tek bir sorunu düzelt","Eksik olan tek bir kaynağı iste"],minimum:["Açıklama isteyen tek bir cümle gönder","İşimdeki tek bir hatayı düzelt","Eksik olan tek bir kaynağı belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["İşe yarayan sorumu yanıtladıktan sonra","İşime geçmek için zaten seçtiğim anda"],place:["Kendi masamın veya telefonumun başında","Güvenle kullanabildiğim mesajlaşma kanalında"],minutes:[2,1,5],fallback:["Yanıtı bulmak için yardım iste","Yanıt vermek için uygun bir fırsat planla"],observation:["Bulduğum yanıt ve gerçekten attığım adım","Henüz çözüme ulaşmamış olan kısım"]},suggested:{action:"Gereken bir ayrıntı için açıklama iste",minimum:"Açıklama isteyen tek bir cümle gönder",minutes:2,cueHint:"İşe yarayan sorumu yanıtladıktan sonra",placeHint:"Kendi masamın veya telefonumun başında",obstacleHint:"Sıradaki adımı atmadan tekrar tekrar inceliyorum.",fallbackHint:"Yanıtı bulmak için yardım iste",observationHint:"Bulduğum yanıt ve gerçekten attığım adım"},stopRule:"Gereken korunmanın veya desteğin yerine bir düşünme alıştırması daha koyma.",accessibleAlternative:"İçinden veya her zamanki iletişim yönteminle yanıtla. Destek istemek de yararlı davranışın olabilir."},result:{question:"Yararlı yanıtına göre gerçekten adım attın mı?",observationPrompt:"Soru neyi gösterdi, hemen ardından gerçekte ne yaptın?"},judgment:{primary:{id:"state-4-question-to-action",scenario:"Ömer, isteğinde gereken bütçe alanlarının dolu olduğunu doğruluyor. Ama istek, onu onaylayacak kişiye hiç ulaşmamış. Listede belirtilen kişi şu an açıklama mesajlarını alabiliyor.",question:"Yararlı sorunun ardından hangi adım gelmeli?",bestOptionId:"contact-approver",options:[{id:"check-budget-field",text:"Onaylayacak kişiye eksiksiz bir istek ulaşsın diye açıklama mesajını göndermeden önce doldurduğu bütçe alanlarını bir kez daha kontrol etsin.",feedback:"Gerekli alanları kontrol etmek, boşa gidecek mesajı önleyebilir. Ömer bunları zaten doğruladı. Eksik adım, iletmek. Kontrolü tekrarlamak, bilinen bu eksiği gidermeden hazırlık ekliyor. Mesaj henüz gereken kişiye ulaşmıyor."},{id:"break-then-contact",text:"Beş dakika ara versin. Sonra can sıkıntısını mesaja yansıtmadan, gerçek durumu anlatan açıklama isteğini göndersin.",feedback:"Bu seçimin bir bitişi var. Ara gerektiğinde yardımcı olabilir. Burada böyle bir ihtiyaç görülmedi. Gerçek durumu anlatan açıklama isteği hazır ve eksik onayı doğrudan ele alıyor."},{id:"contact-approver",text:"Listedeki onaylayacak kişiye gerçek durumu anlatan bir açıklama isteği göndersin. Sonra gelen yanıtı veya yanıt gelmediğini kaydetsin.",feedback:"Bu seçim belirlenen nedeni, kişinin yapabileceği bir davranışa dönüştürüyor. Yanıt gelmeyebilir. Onay başkasına bağlı kalır. Ömer yine de yararlı isteği iletip iletmediğini kaydedebilir. Başkasının kararını kendi davranışıyla karıştırmaz."}]}},carry:{takeaway:"Bir yanıt, bundan sonra yapacağın yararlı adımı değiştirdiğinde ona ayırdığın zamana değer.",followUp:{questionId:"state-4-return",question:"Sorduğun soru bir şeyi netleştirip ne yapacağını değiştirdi mi, yoksa yalnızca cesaret verici mi geldi?",observationPrompt:"Neyin netleştiğini, neyin değiştiğini belirt. Yeni bilgi veya değişiklik olmaması da geçerli.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Dikkat bulguları belirli bir soru listesini doğrulamaz",paragraphs:["Webb ve arkadaşları 306 deneysel karşılaştırmayı birleştirdi. Düşünme biçimini değiştiren geniş yöntemlerin duygusal sonuçlardaki ortalama etkisi 0,36’ydı. Dikkati yönlendirmenin genel ortalaması sıfıra yakındı. Ama alt türleri farklıydı. Bu kategoriler farklı yönergeleri ve deneysel olarak oluşturulan kısa duyguları kapsıyordu. Adı olan bir sabah soru listesinin ruh hâlini iyileştirdiğini kanıtlamıyorlar. “Neden?” sormanın veya soruna odaklanmanın genel olarak zararlı olduğunu da göstermiyorlar. [ST02: state-regulation-meta]","Bir sorunun ne işe yaradığını anlamak için bu ayrımı kullan. Araştırmak gerçekleri belirleyebilir. Sorumluluğa bakmak, kimin ilgilenmesi gerektiğini gösterebilir. Planlamak eksik kaynağı ortaya koyabilir. Her biri zaman ayırmaya değer olabilir. Yanıtın yapabileceğin bir davranış gösteriyorsa onu seç. Dışarıdaki bir kısıtı gösteriyorsa o kısıtı tutum sorunu diye anlatma. ODA’nın soru ve davranışı birleştirmesi bir uyarlamadır. Doğrulanmış süresi veya duygusal sonuç sözü olan sınanmış bir uygulama değildir."]},{heading:"Yanıtı sürdürdüğün denemeyle bağlantılı tut",paragraphs:["Denemenin zaten bir yönü, geçiş anı ve yararlı davranışı var. Bunlar görünür kalsın. Soru, yeni bir günlük ritüel olmak yerine davranışını geliştirsin. Örneğin açıklama isteği, eksik onayı ele alabilir. İşteki bir adımla belirlediğin bir hatayı düzeltebilirsin. Korunma adımı, zararlı iletişime yanıt verebilir. Sadece sıradaki seçimin için gerekli bilgiyi sor. Daha fazla soru yazmak tek başına daha fazla ilerleme değildir.","Duygular bir yanıtı nasıl yorumladığını etkileyebilir. Başka bir olaydan taşınmış da olabilir. Lerner ve arkadaşları, duygunun kararlara yararlı ve zararlı etkilerini anlatır. [ST01: state-emotion-decisions] Edindiğin kanıtı ve yaptığın davranışı kaydet. Yararlı yanıt, büyük sorunu hâlâ çözümsüz bırakabilir. Güvenle yapabileceğin bir şey yoksa o kısıtı kaydet veya destek seç. Düşünerek verdiğin arayı başarısızlık sayma. Yazılmış bir soruyu da ardından gereken davranışın yapıldığına dair kanıt sayma."]}],sourceIds:["state-regulation-meta","state-emotion-decisions"]}},{schemaVersion:2,revision:2,id:"state-5",courseId:"state",locale:"tr",title:"Mesaj canını yaktı. Gerçekleri değiştirme",goal:"Gerçeği, niyet hakkındaki tahmininden ayır. Sonra aynı tekrarlanan durumda açıklama iste veya kendini koru.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"O mesaj canını yaktı. Gönderenin niyetini tahmin etmeden önce sözlere bak. Güvenli bir yanıt seç.",reason:{id:"state-5-reason",label:"Daha güvenli bir yanıt neyi korur, sana neye mal olur?",kind:"text",maxLength:160,optional:!0,suggestions:["Kendime saldırmadan geri bildirimden yararlanmak","Haksız davranışları artık kabul etmemek","Niyet tahmin etmek yerine soru sormak"]},why:{id:"state-5-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-5-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir olay ile onu açıklama biçimin farklıdır. “Mesajda hakaret var” kontrol edebileceğin bir kanıt. “Kariyerimi mahvetmek istiyorlar” ise niyet tahmini. Başka bir açıklama da gerçeklere uymalı. Zararı zararsız gibi anlatmamalı. Daha olumlu geldiği için bir tahmini gerçek sayma. Mesajdaki sözleri olduğu gibi aktar.","Aynı geçiş anında, bir gerçeği ve hâlâ bilmediğin şeyi belirt. Sonra açıklama iste, düzelt, sınır koy veya destek al. Daha hafif duygu sözcükleri kendiliğinden daha doğru değildir. Klasik adlandırma çalışması, sıkıntıyı yeniden isimlendirince rahatlamayı değil, yüzlere verilen beyin yanıtını ölçtü. Olumluluk yerine doğruluğu seç. Öfkenin adını değiştirmek, bir hakareti ortadan kaldırmaz."],example:{title:"Nazan hakaret içeren mesajları saklıyor",text:"Saat 16.00. Nazan ekipten yine hakaret içeren bir mesaj alıyor. Kimsenin olmadığı bir yerde oturup sakladığı sözleri, gönderenin niyeti hakkındaki tahmininden ayırıyor. Öfkesi sürüyor. Buna yanlış anlaşılma demek yerine güvendiği yöneticiye güvenli bildirim yolunu soruyor. Yöneticinin kontrol etmek için zamana ihtiyacı var. Nazan isteğini kaydediyor, mesajları güvenli biçimde saklıyor."}},move:{invitation:"Bir gerçeğe dayanarak mevcut davranışını geliştir. Belirsizliği netleştir veya zarar belgelenmişse korunmayı seç.",instructions:["Gözleyebildiğin gerçeklerle niyet tahminlerini birbirinden ayır.","Duruma göre açıklama iste, düzeltme yap, sınır koy veya destek iste."],prompts:[],suggestions:{action:["Güvenli bir destek yolunu sor","Gerçek durumu açıklayan tek bir mesaj gönder","İşimde doğrulanmış tek bir hatayı düzelt"],minimum:["Tek bir ihtiyaç için destek iste","Gerçek durum hakkında tek bir soru sor","İşimdeki tek bir hatayı düzelt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Canımı sıkan mesajı kontrol ettikten sonra","Sıradaki planlı yanıtımı vermeden önce"],place:["Güvenli, yalnız kalabildiğim bir koltukta","Güvendiğim bir destek kanalında"],minutes:[2,1,5],fallback:["Kanıtı koru, daha güvenli destek ara","Başka bir güvenli yanıt fırsatı seç"],observation:["Dayandığım gerçek ve verdiğim yanıt","Yorumumu değiştiren kanıtın ne olduğu"]},suggested:{action:"Güvenli bir destek yolunu sor",minimum:"Tek bir ihtiyaç için destek iste",minutes:2,cueHint:"Canımı sıkan mesajı kontrol ettikten sonra",placeHint:"Güvenli, yalnız kalabildiğim bir koltukta",obstacleHint:"Olumlu açıklama, gerçek zararı gizleyebilir.",fallbackHint:"Kanıtı koru, daha güvenli destek ara",observationHint:"Dayandığım gerçek ve verdiğim yanıt"},stopRule:"İstismarı veya tehlikeyi yanlış anlaşılma diye yorumlama. Korunmayı ve destek almayı seç.",accessibleAlternative:"Gerçekleri içinden belirt, yaz, işaret dili kullan veya yardım iste. Bedene odaklanmak veya daha hafif adlandırmak gerekmez."},result:{question:"Seçtiğin, gerçeklere dayanan yanıtı gerçekten verdin mi?",observationPrompt:"Hangi kanıta dayandın, ardından nasıl bir yanıt verdin?"},judgment:{primary:{id:"state-5-documented-insults",scenario:"Nazan tekrar eden hakaretleri içeren mesajları güvenle sakladı. Güvendiği yönetici şimdi ulaşılabilir. Bildirim portalı yarın açılıyor. Acil tehlike yok. Gönderenin niyeti bilinmiyor.",question:"Hangi sonraki adım, gerçekleri ve elindeki desteği kullanır?",bestOptionId:"facts-and-support",options:[{id:"copy-and-wait",text:"Sakladığı hakaret mesajlarının korumalı bir kopyasını daha oluştursun. Sonra bildirim portalının yarın açılmasını bekleyerek o kanalı kullansın.",feedback:"Kanıtı korumak korunmaya hizmet eder. Ama mesajlar zaten güvence altında. Başka kopya, belirlenmiş yeni bir koruma sağlamıyor. Ulaşılabilir yönetici, gönderenle iletişimi gerektirmeden şimdi güvenli bir yolu netleştirebilir."},{id:"facts-and-support",text:"Belgelenmiş hakaretleri, niyet tahminlerinden ayırsın. Sonra güvendiği bir kişiye başvurup destek alabileceği güvenli bir yol sorsun.",feedback:"Bu seçim niyetin belirsizliğini korurken gerçek zararı tanıyor. Nazan gizli niyeti kanıtlamadan, duygusunun adını değiştirmeden veya gönderenle doğrudan yüzleşmeden korunma isteyebilir. Yardım istemek için bunları tamamlaması gerekmez."},{id:"wait-safe-portal",text:"Gönderene ulaşmasın. Yarınki bildirim portalını beklesin. Sakladığı mesajları kullanarak o kanaldan nasıl destek alabileceği hakkında soru sorsun.",feedback:"Doğrudan iletişimden kaçınmak ve bildirim kanalı kullanmak koruyabilir. Burada güvenilir destek daha erken ulaşılabilir. Yolu şimdi sormak, seçeneklerini korur. Bildirimde bulunmaya veya yüzleşmeye zorlamaz. Sonraki kararı yine kendisi verebilir."}]}},carry:{takeaway:"Yorumunu yalnızca kanıtın izin verdiği kadar değiştir. Sonra duruma uygun davranışı seçip yap.",followUp:{questionId:"state-5-return",question:"Yorumunu hangi kanıt destekledi, hangisi ona uymadı? Verdiğin yanıt bu kanıta uydu mu?",observationPrompt:"İlgili gerçeği, kalan belirsizliği ve verdiğin yanıtın kanıta uyup uymadığını belirt.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Beyinde ölçülen fark, sıkıntı tedavisi değildir",paragraphs:["Lieberman ve arkadaşları, beyin görüntüleme sırasında yüzlerdeki duyguları adlandıran 30 sağlıklı yetişkini inceledi. Duygu sözcüğü koşulu ile cinsiyete uygun isim koşulu, amigdalada ölçülen bir değerde farklıydı. Çalışma, “çok öfkeliyim” yerine “sinirlendim” demenin günlük sıkıntıyı azalttığını göstermedi. Kendi duygunu adlandırmanın aynı etkiyi yarattığını veya yararın sürdüğünü de göstermedi. [ST11: state-affect-labeling] Bunlar farklı uygulamalar ve sonuçlardır.","Bu derste ODA, gerçeğe, duyguya ve belirsizliğe bakmanı ister. Amaç, sıradaki seçimini açıkça görmen. Yaşadığın güçlü duygunun adını doğru koyabilir, hiç adlandırmayabilir veya notu kendine saklayabilirsin. Sonradan daha az öfkeli hissetsen de belgelenmiş hakaret yine hakarettir. Şu an çok kaygılı olsan da geciken kısa bir yanıt belirsiz kalabilir. Mesajın tam sözlerini kullanabilirsin. Kontrol edilebilene dayan, bilinmeyeni koru. Güvenliğine ve istediğin yola uyan davranışı seç. Bir başkasının niyetini yalnızca duygundan çıkaramazsın. Duyguyla gerçeği aynı ölçü gibi kullanma."]},{heading:"Yeniden değerlendirmek sınır koymayı da içerebilir",paragraphs:["Bir yorumu değiştirmek, çoğu zaman yeniden değerlendirme diye adlandırılır. Webb ve arkadaşları farklı deneysel karşılaştırmalarda ortalama yararlar buldu. Yöntemler ve sonuçlar arasında açık farklar vardı. Bu, olumlu açıklamayı her zaman en iyi yapmaz. Kanıt, tam bu bir dakikalık çalışmayı doğrulamıyor. Geri bildirimi, kaynak kısıtlarını veya zararı görmezden gelmeyi haklı da çıkarmıyor. [ST02: state-regulation-meta]","Adil bir yorum sorumluluğu belirginleştirebilir: işin bu kısmını atladım, onu düzelteceğim. Dayanaksız suçlamayı da azaltabilir: yanıt neden gecikti bilmiyorum, soracağım. Zarar belgelenmişse korunmayı destekleyebilir: yardım istemeden önce niyeti kanıtlamam gerekmiyor. Hangi davranışın yapıldığını, hangi yeni kanıtın çıktığını kaydederek aynı denemeyi sürdür. Yanıtsız istek, yanıtsız kalır. Güvenliğin için durduysan kaydında da durduğunu belirt. Kaydın kabul edilebilir olması için ikisini de daha iyimser bir hikâyeye dönüştürmen gerekmez. Olanı olduğu gibi anlatabilirsin."]}],sourceIds:["state-affect-labeling","state-regulation-meta"]}},{schemaVersion:2,revision:2,id:"state-6",courseId:"state",locale:"tr",title:"Olumlu sözler sahte mi geliyor? Somut adım at",goal:"Minnettarlığı veya ruh hâli değişimini şart koşmadan mevcut işine başlamak için inanabileceğin bir davranış cümlesi kullan.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Sabah hazırlığın tamam. Peki ardından gerçekten bir adım attın mı?",reason:{id:"state-6-reason",label:"Bu hazırlığı uzattıkça hangi iş hâlâ sonraya kalıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Seçtiğim davranışı yapmaya başlamak","İnanabileceğim sözlerle kendime yol göstermek","Hazırlığı kısa tutup işi denemek"]},why:{id:"state-6-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-6-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Büyük olumlu sözlerin herkesin ruh hâlini iyileştirdiği kanıtlanmış değil. İlk çalışmalardaki yarar ve ters etki bulguları, sonraki tekrar çalışmalarında elde edilemedi. Güçlü söyleyişin veya coşkulu telkinlerin bunu çözdüğüne dair burada doğrulanmış kanıt yok. Yapabileceğin bir işi anlatan sade bir yönerge seç. Söylediğini kusursuz biçimde hissedene kadar beklemen gerekmiyor.","Aynı geçiş anında “Emin değilken de açık bir istek gönderebilirim” de. Sonra uygunsa gönder. İstersen minnettarlık için gerçek bir şeyi an. Hayal edilen başarıyı değil. Zoraki geliyorsa atla. Cümle hazırlıktır. Davranışı ayrı kaydet. Kendini ikna olmuş hissetmek veya bütün ritüeli tamamlamak gerekmez. Yapılan işin ne olduğu açık kalsın."],example:{title:"Ayşe ilk isteğini iletiyor",text:"Saat 08.00. Ayşe sabah çayını bitirmiş. Çıkmasına iki dakika var. “Beni hiçbir şey durduramaz” sözü sahte geliyor. “Emin değilken de açık bir soru sorabilirim” diyor. Ertelediği isteği gönderiyor. Bugün minnettarlık kısmını atlıyor. Çıkmadan önce yanıt gelmiyor. Belirsizliği başarısızlık saymadan gönderdiği cümleyi kaydediyor. İstek gönderildi, yanıt hâlâ bekliyor."}},move:{invitation:"Hazırlığı kısa tut. İnanabileceğin tek bir cümle kullan. Sonra mevcut yararlı davranışını yap.",instructions:["Kendi yapabileceğin bir davranış hakkında cümle seç.","Uygunsa şimdi dene. Değilse gerçekten başlayacağın anı kaydet."],prompts:[],suggestions:{action:["Seçtiğim açık isteği karşı tarafa gönder","İşim için kullanılabilir tek bir cümle yaz","Somut bir ihtiyaç için destek iste"],minimum:["Tek bir açık cümle gönder","İşe yarayan tek bir cümle yaz","Destek gereken tek bir ihtiyacımı belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Sabah çayımı bitirdikten sonra","İşime geçmek için zaten seçtiğim anda"],place:["Mutfak masamın başında otururken","Genellikle kullandığım çalışma yerinde"],minutes:[2,1,5],fallback:["Ritüeli atla, seçtiğim cümleyi kullan","Bir sonraki gerçekçi fırsatı seç"],observation:["Sözlerimin davranışa götürüp götürmediği","Hangi hazırlığın davranışımı geciktirdiği"]},suggested:{action:"Seçtiğim açık isteği karşı tarafa gönder",minimum:"Tek bir açık cümle gönder",minutes:2,cueHint:"Sabah çayımı bitirdikten sonra",placeHint:"Mutfak masamın başında otururken",obstacleHint:"Hazırlığı tekrar tekrar uzatıyorum.",fallbackHint:"Ritüeli atla, seçtiğim cümleyi kullan",observationHint:"Sözlerimin davranışa götürüp götürmediği"},stopRule:"Sıkıntını artıran minnettarlığı, canlandırmayı veya cümleleri atla. Yerine gündelik destek seç.",accessibleAlternative:"Normal nefes al. Gözlerin açıkken çevrene dikkat et. Yönergeyi söyle, yaz, işaret diliyle veya içinden kullan."},result:{question:"Cümlenden sonra seçtiğin davranışı gerçekten yaptın mı?",observationPrompt:"Gerçekte neye başladın, ne gönderdin veya neyi değiştirdin?"},judgment:{primary:{id:"state-6-believable-start",scenario:"Ayşe’nin çıkmasına iki dakika var. Kontrol ettiği sorusu açık, nazik ve güvenli bir kanaldan gönderilmeye hazır. Kendinden emin görünmek istediği için tekrar tekrar erteliyor.",question:"Bu sabaha hangi seçenek daha iyi uyar?",bestOptionId:"credible-and-send",options:[{id:"rehearse-and-send",text:"Doksan saniye mesajı sesli söyleyerek prova yapsın. Sonra kontrol etmiş olduğu soruyu evden çıkmadan önce göndersin.",feedback:"Süreli prova, belirsiz veya tanımadığın bir isteğe yardımcı olabilir. Bu soru zaten açık ve kontrol edilmiş. Prova, önce kendinden emin olmak gerektiği inancına yanıt vermeden fırsatın çoğunu tüketiyor."},{id:"credible-and-send",text:"Emin değilken soru sormaya dair inanabileceği bir yönerge kullansın. Ardından hazır olan soruyu güvenli kanaldan göndersin.",feedback:"Bu seçim, uygulayabileceği bir yönergeyi hemen yapabileceği bir işle birleştiriyor. Ayşe yararlı isteğini iletmeden önce büyük bir iddiaya inanmak, minnettarlık hissetmek veya belirsizliğini yok etmek zorunda değil."},{id:"polish-and-send",text:"Mesaj için kısa bir giriş ve kapanış taslağı yazsın. Sonra hazır sorusunu evden çıkmadan önce göndersin.",feedback:"Giriş ve kapanış gerektiğinde nezaket katabilir. Hazır soru isteği zaten iletiyor. Daha fazla düzeltmek, göndermek için daha az zaman bırakır. İnanabileceği yönerge, emin değilken başlamayı doğrudan ele alır."}]}},carry:{takeaway:"Sözlerin kullanabileceğin kadar inandırıcı olsun. Kanıt olarak ardından gerçekten yaptığın davranışı göster.",followUp:{questionId:"state-6-return",question:"Cümle adım atmana yardımcı mı oldu, geciktirdi mi, yoksa belirgin fark yaratmadı mı?",observationPrompt:"Yardımı veya gecikmeyi davranışın sonucundan ayrı anlat. Belirgin fark olmaması da geçerli.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Olumlamalara dair kanıtlar karışık",paragraphs:["Wood ve arkadaşları üniversite örneklemlerinde, olumlu kişisel cümlelerin tekrarlanmasını inceledi. İlk bulgular öz saygıya göre farklı yanıtlar olabileceğini gösterdi. Bazı katılanlarda daha kötü yanıt da vardı. Flynn ve Bordieri’nin sonraki iki tekrar denemesi; ruh hâli, o anki öz saygı veya etkiyi değiştiren koşullara dair bulguları yeniden elde etmedi. Doğru sınır, karışık kanıttır. Olumlamaların herkese yaradığı veya herkese zarar verdiği iddiası değil. [ST12: state-positive-self-statements; ST20: state-affirmation-replication]","Bu kanıt, bedeni de kullanarak yapılan coşkulu telkinleri çözüm olarak belirlemiyor. Tek bir davranış hakkında inanabileceğin bir yönergeyi burada pratik koçluk olarak sunuyoruz. Kanıtlanmış psikolojik tedavi olarak değil. Kendi sözlerini kullanabilir, cümleyi atlayabilir veya destek seçebilirsin. İş ve en küçük adım, gözleyebileceğin kadar açık kalsın. Gelecekte yapacağın iş hakkında cümle söylemek hazırlıktır. İsteği göndermek, işteki hatayı düzeltmek veya destek istemek ise sonra bildirebileceğin davranıştır."]},{heading:"Minnettarlığın sınırları var, zorunluluğu yok",paragraphs:["Kirca ve arkadaşları, ifade edilen şükran üzerine 25 rastgele atanmış örneklem içeren 23 çalışmayı inceledi. Nötr kontrol koşullarına göre olumlu iyi oluşta küçük bir ortalama yarar bulundu: etki 0,22. İyi oluşu desteklemeyi amaçlayan başka etkinliklere göre tahmin daha küçüktü ve istatistiksel sonuç kesin değildi. [ST13: state-gratitude-expressed] Görülen yararı değerlendirirken karşılaştırılan etkinliğin ne olduğu önem taşıyor.","Bu araştırma on dakikalık hazırlık paketini, gelecekteki üç sahneyi hayal etmeyi, en iyi sabah sırasını veya uygun klinik tedaviye üstünlüğü belirlemiyor. Minnettarlığı seçersen sana iyi gelen gerçek bir ayrıntıyı kullan. Kayıptan güzel bir yan çıkarmayı veya güvenli olmayan birine şükran duymayı şart koşma. Umduğun gelecek bir olasılık. Anı veya başarılmış sonuç değil. Sürdürdüğün denemede pratik soru şu: isteğe bağlı hazırlık aynı yararlı davranışı destekledi mi? Gecikme veya rahatsızlık ekliyorsa bırak."]}],sourceIds:["state-positive-self-statements","state-affirmation-replication","state-gratitude-expressed"]}},{schemaVersion:2,revision:2,id:"state-7",courseId:"state",locale:"tr",title:"Hazırlık biriktirme. Gelecek hafta işe yarayanı seç",goal:"Gerçek kayıtlarına bakarak aynı denemeyi gelecek hafta korumayı, küçültmeyi, değiştirmeyi veya ara vermeyi seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hazırlık uzuyor, iş hâlâ bekliyor. Hangi kısmı başlamana yardımcı oldu, hangisi başlamanı geciktirdi?",reason:{id:"state-7-reason",label:"Bu denemeyi sürdürürsen gelecek hafta hangi işe daha az yer kalır?",kind:"text",maxLength:160,optional:!0,suggestions:["Sıradaki yararlı adımımı korumak","Gereken dinlenme ve toparlanmayı korumak","Beni geciktiren ritüeli bırakmak"]},why:{id:"state-7-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-7-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İstenen gelecek için engel ve yanıt planının, kötü sonuçları gözünde canlandırmaya göre daha doğrudan araştırma desteği var. Gözünde canlandırdığın kötü sonuçlar birer tahmindir. Yaşanmış olaylar değildir. Utanç veya daha güçlü sözler gerekmez. Plan yapmak için kendini kötü hissetmeni şart koşma.","Aynı geçiş anındaki gerçek kayıtlarına bak. Hangi hazırlık yararlı davranışını destekledi? Hangisi rahatsızlık, gecikme veya belirgin fark olmamasıyla sonuçlandı? İşe yarayan tek bir biçimi koru, tek bir sorunu değiştir veya ara ver. Gelecek haftanın en küçük adımı gücüne uysun. Mümkünse uygun bir adım dene. Dinlenmek, korunmak ve destek de plana dâhil olabilir."],example:{title:"Emre daha küçük bir hedef seçiyor",text:"Pazar öğleden sonra Emre masasında, portfolyosuna başlama kayıtlarını inceliyor. Dikkatini çevresine verdiği bir ara başlamasına yardım etti. Uzun ritüel ise iki kez geciktirdi. Bugün kötü uyuduğu için ritüeli atlayıp tek bir görsel açıklamasını düzeltiyor. Salı için aynı küçük adımı planlıyor. Portfolyo bitmedi. Ama yeni planı artık gördüklerine uyuyor."}},move:{invitation:"Aynı denemenin kayıtlarını kullan. İşe yarayan tek bir biçimi koru, yapabileceğin en küçük adımı dene.",instructions:["Bildirdiğin denemeleri gözden geçir. Sonucu yazılmamış olanlar bilinmeyen kalsın.","Gelecek hafta için tek bir biçimi koru, küçült, değiştir veya ara ver."],prompts:[],suggestions:{action:["İşimdeki yararlı adımı yeniden at","Sıradaki açık isteğimi dile getir","Seçtiğim toparlanma adımını uygula"],minimum:["İşimdeki tek bir hatayı düzelt","İsteğimi anlatan tek bir cümle kullan","Seçtiğim süreyi dinlenip toparlanmaya ayır"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Daha önce deneyip yararlı bulduğum geçiş anında","Bir sonraki gerçekçi fırsatım geldiğinde"],place:["Genellikle kullandığım çalışma yerinde","Toparlanmak için seçtiğim yerde"],minutes:[2,1,5],fallback:["Adımı bugünkü gücüme uydurmak için küçült","Ara ver, destek için bir adım seç"],observation:["Tekrarladığım veya değiştirdiğim şey","Gerçekte karşıma çıkan engelin ne olduğu"]},suggested:{action:"İşimdeki yararlı adımı yeniden at",minimum:"İşimdeki tek bir hatayı düzelt",minutes:2,cueHint:"Daha önce deneyip yararlı bulduğum geçiş anında",placeHint:"Genellikle kullandığım çalışma yerinde",obstacleHint:"Her zamanki planım gücümün yettiğinden daha fazlasını istiyor.",fallbackHint:"Adımı bugünkü gücüme uydurmak için küçült",observationHint:"Tekrarladığım veya değiştirdiğim şey"},stopRule:"Sıkıntı veren kötü sonuçları gözünde canlandırmayı atla. Dinlenmek, korunmak ve destek almak uygun sonraki adımlar olabilir.",accessibleAlternative:"İçinden veya yardımla değerlendir. Ara yardımcı olacaksa gözlerin açık, oturarak ve hareket etmeden ilerleyebilirsin."},result:{question:"Sıradaki deneme için seçtiğin en küçük adımı attın mı?",observationPrompt:"Neyi korudun, değiştirdin veya durdurdun? Gerçekte ne oldu?"},judgment:{primary:{id:"state-7-capacity-review",scenario:"Emre kötü uyuduktan sonra ayırabileceği beş dakikası var. Görsel açıklamasında bilinen bir hata var, düzeltmesi hazır. Teslim haftaya. Uzun hazırlık son iki başlangıcını geciktirdi.",question:"Hangi sonraki plan gördüklerine daha iyi uyar?",bestOptionId:"small-caption",options:[{id:"small-caption",text:"Bir portfolyo görselinin açıklamasını düzeltsin. Küçültülmüş denemeyi kaydetsin. Gücüne göre bir sonraki gerçekçi çalışma zamanını seçsin.",feedback:"Bu seçim amacı korurken bugüne uyması için miktarı değiştiriyor. Emre kayıtlarından yararlanıp başka fırsat planlayabilir. Uzun ritüel veya kusursuz enerji şartı koyması gerekmiyor. Küçük işi bugün yapabilir."},{id:"sort-next-section",text:"Beş dakikayı sıradaki bölümün kaynak notlarını sıralamak için kullansın. Görsel açıklamasında yapacağı belli olan düzeltmeyi salı yapmaya bıraksın.",feedback:"Notları sıralamak sonraki bölüme hazırlık olabilir. Ama hazırlık, yararlı işi tekrar tekrar geciktirdi. Mevcut düzeltme hazır. Bu küçük kısmı tamamlamak, kayıtta görünen engeli ele alan bir planı sınar."},{id:"defer-for-checking",text:"Görsel açıklamasını düzeltmeyi yarın dinlenmiş olacağı zamana bıraksın. Bu beş dakikayı, kontrol için bir çalışma zamanı ayırmaya kullansın.",feedback:"Yorgunluk işi uygunsuz kılıyorsa veya doğruluk kontrolü gerekiyorsa ertelemek uygundur. Burada düzeltme hazır, kullanabileceği güce de uyuyor. Başka kontrol planlamak, şimdi yapabileceği anlamlı bir kısmı sonraya bırakıyor."}]}},carry:{takeaway:"Amacını koru. Sıradaki planını, gerçek denemelerine ve bugün elindeki güce bakarak şekillendir.",followUp:{questionId:"state-7-return",question:"Sıradaki planın gücüne uydu mu? Gerçekte hangi engel onu etkiledi?",observationPrompt:"Neyin uyduğunu, önüne ne çıktığını veya toparlanmanın ya da başka değişikliğin neden uygun olduğunu anlat.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Engel planının kanıtı var. Felaket sahnelerini atlayabilirsin",paragraphs:["Wang ve arkadaşları, 15.907 kişinin katıldığı 21 makaleden 24 bağımsız etkiyi birleştirdi. Zihinsel karşılaştırmayla yanıt planlamanın, hedefe ulaşmada küçük ile orta arasında ortalama etkisi 0,336’ydı. Yayın yanlılığına göre düzeltilmiş tahmin daha küçüktü. Araştırma sonuçları farklılık gösteriyordu. Yöntem, ulaşılabilir bir gelecek isteğini, önündeki engeli ve “bu engel çıkarsa şunu yaparım” planını birleştirir. Dickens yöntemini, utanç yaratmayı veya her “yapmalıyım”ı “mecburum”a çevirmeyi doğrulamaz. [ST15: state-mental-contrasting]","Kayıtlarının veya koşullarının desteklediği bir engel kullan. İçinde yaşadığın bir tepkiyse yapabileceğin bir yanıt belirt. Dışarıdaki bir engelse kaynak, başka ortam veya yardım gerekebilir. Gözünde canlandırdığın gelecekteki kötü sonuçlar, tahmin olarak kalır. Bu planın geçerli olması için acı anıları yeniden yaşamak veya giderek büyüyen zararı gözünde canlandırmak gerekmez. Buradaki daha kısa, kayda dayalı yaklaşım ODA uyarlamasıdır. Süresi bir tahmindir. Doğrulanmış en iyi süre değildir."]},{heading:"Yeni ritüel eklemek yerine denemeni toparla",paragraphs:["Kurs tek bir geçiş anı ve yararlı davranışla başladı. Gelecek haftaya neyi taşımaya değer bulduğuna karar vermeden önce tam o denemelere bak. Denenmiş hazırlığı tamamlanmış işten ayır. Değişmemiş duyguyu, yapılmamış en küçük adımla aynı sayma. Eksik bildirim hiçbir sonuç vermez. Koşula bağlı fırsat hiç gelmediyse fırsat olmadığını kaydedebilirsin. Her sonraki seçimin, bilinen gerçeğe yanıt versin.","Breines ve Chen, kısa deneylerde kendine şefkatin gelişme isteğiyle birlikte bulunabileceğini gösterdi. Başarısız sınavdan sonra şefkat grubu, hatırlatma almayan koşuldan daha uzun çalıştı. İkinci sınav performansında istatistiksel olarak anlamlı fark bulunmadı. Öz saygı karşılaştırması da kesin sonuç vermedi. [ST16: state-self-compassion-motivation] Bu, çaba için kendini aşağılamanın gerekli olduğu varsayımını bırakmayı destekler. Davranış değişiminin sürmesini garanti etmez. Sıradaki planın destek almayı, toparlanmayı veya koşullarına uymayan planı bırakmayı içerebilir. Kayıt ve tarihli değerlendirme, kesintisiz gün sayısını zorunlu tutmadan bu kararları dürüst tutar."]}],sourceIds:["state-mental-contrasting","state-self-compassion-motivation"]}}],g=[{id:"state-1",schemaVersion:2,practice:["Duygunun nerede başlamış olabileceğini söyle.","Tamir için tek bir açık istek gönder","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:2,photo:{id:"1758192139097-1e7f30c2498e",alt:"Güneş ışığı alan ağaçların altında sakin şehir sokağından karşıya geçen adam"}},{id:"state-2",schemaVersion:2,practice:["Tek bir araç seç veya her zamanki hareketsiz hazırlığını koru.","İşim için kullanılabilir tek bir cümle yaz","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:1,photo:{id:"1692933216024-8de20c41321a",alt:"Yeşil bitkilerin arasındaki ahşap yürüyüş yolunda ilerleyen kadın"}},{id:"state-3",schemaVersion:2,practice:["Otur. Araç kullanma, sudan ve düşme riski olan yerlerden uzak dur.","Düşünerek seçtiğim tek yanıt cümlesini gönder","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:0,photo:{id:"1763713383838-5cd702c13160",alt:"Ormanda gözleri kapalı, kendine nazikçe sarılan kadın"}},{id:"state-4",schemaVersion:2,practice:["Gerektiğinde araştırmayı sürdür ve kimin sorumlu olduğunu açık tut.","Gereken bir ayrıntı için açıklama iste","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:2,photo:{id:"1543379232-77ee894c85dd",alt:"Örgü bere takmış, alçalan güneşe doğru bakan kadın"}},{id:"state-5",schemaVersion:2,practice:["Gözleyebildiğin gerçeklerle niyet tahminlerini birbirinden ayır.","Güvenli bir destek yolunu sor","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:1,photo:{id:"1534330207526-8e81f10ec6fc",alt:"Aydınlık bir pencerenin önünde sessizce duran adam"}},{id:"state-6",schemaVersion:2,practice:["Kendi yapabileceğin bir davranış hakkında cümle seç.","Seçtiğim açık isteği karşı tarafa gönder","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:1,photo:{id:"1552838671-0e948f9f69b5",alt:"Yeşil çimende oturup sabah güneşine bakan kadın"}},{id:"state-7",schemaVersion:2,practice:["Bildirdiğin denemeleri gözden geçir. Sonucu yazılmamış olanlar bilinmeyen kalsın.","İşimdeki yararlı adımı yeniden at","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:0,photo:{id:"1633210155534-e43f00c1d627",alt:"Doğada bir kayanın üstüne oturup defterine yazan kadın"}}],c={id:"state",title:"Hâlâ gergin misin? Sıradaki adımını seç",subtitle:"7 ders. İşe yarayan bir davranışı dene. Öncesinde yardımcı olabilecek araçları istersen kullan.",description:"Gündelik bir geçiş anı seç. Rahat bir hazırlık yap, durumu doğru yorumla, adım at ve olanı değerlendir. Daha iyi hissetmeyi şart koşmadan hayatına katkısı olanı koru.",scope:"Ruh hâlini ve enerjisini gündelik araçlarla değiştirmek isteyen yetişkinler için eğitimdir. Tanı veya tedavi değildir. Kaygı bozuklukları, panik bozukluğu veya depresyon tedavisi değildir. Terapinin veya ilacın yerini tutmaz. Nefes alıştırmasında başın dönerse, sersemlemiş hissedersen, karıncalanma veya nefes darlığı olursa hemen dur. Normal nefesine dön ve otur. Kalp veya akciğer hastalığın varsa ya da hamileysen enerji artırmayı amaçlayan nefes çalışmasını denemeden önce bir sağlık uzmanına danış. Araç kullanırken veya su içindeyken asla yapma. Kriz yaşıyorsan veya kendine zarar verme düşüncelerin varsa yerel acil yardım numarasını ara: Türkiye’de ve Avrupa’nın büyük bölümünde 112, ABD’de 911.",outcome:"Tekrarlanan bir geçiş anında yararlı bir davranış, dürüst deneme kayıtları ve gücüne uyan gelecek hafta planı.",photo:{id:"1500080628126-901233e80205",alt:"Akşamın altın ışığında ahşap iskelede bir elini ışığa doğru kaldıran kadın"},lang:"tr",lessons:m.map((a,t)=>{const i=g[t],e=a.judgment.primary,l=e.options.find(r=>r.id===e.bestOptionId),n=e.options.filter(r=>r.id!==l.id).map(r=>r.text);return n.splice(i.correct,0,l.text),{...i,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:n,feedback:l.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}})},_=Object.freeze(Object.defineProperty({__proto__:null,COURSE:c,LESSONS_V2:m,SOURCES:b},Symbol.toStringTag,{value:"Module"})),p=[{id:"optimism-maier-seligman",title:"O01 · Maier ve Seligman · 2016 · Öğrenilmiş çaresizliğe elli yıl sonra bakış",url:"https://doi.org/10.1037/rev0000033",type:"research",finding:"Derleme, öğrenilmiş çaresizlik açıklamasını yeniler: hayvanların olumsuz uyaranlara maruz bırakıldığı deneylerde uzun süren uyarım pasiflik doğurur. Kontrolü fark etmek koruyucu sinir devrelerini harekete geçirir.",limitation:"Çoğunlukla hayvan deneyleri. İnsan tedavilerini birleştiren bir derleme değil. Donup kalmanın her insanda varsayılan tepki olduğunu veya kontrol listesi alıştırmasının etkisini göstermez."},{id:"optimism-malouff-schutte",title:"O03 · Malouff ve Schutte · 2017 · Çalışmalar iyimserliği artırabilir mi?",url:"https://doi.org/10.1080/17439760.2016.1221122",type:"research",finding:"3.319 kişiyi kapsayan 29 randomize araştırmada psikolojik çalışmalar iyimserlik puanlarını ortalama olarak artırdı: g = 0,41.",limitation:"Yöntem ve takip süreleri farklıydı. Kısa takip ve takibi tamamlayanlarla yapılan analizler daha büyük etkiler verdi. Açılan kayıtta güven aralığı doğrulanmadı. Kalıcı değişimi veya ODA’nın etkisini göstermez."},{id:"optimism-sweeney",title:"O02 · Sweeney, Anderson ve Bailey · 1986 · Açıklamalar ve depresyon",url:"https://doi.org/10.1037/0022-3514.50.5.974",type:"research",finding:"Yaklaşık 15.000 kişiyi kapsayan 104 araştırmada depresyon, olumsuz olayları kişinin kendisine bağlayan, kalıcı ve yaygın açıklamalarla ilişkiliydi.",limitation:"İlişki neden-sonucu göstermez veya olumsuz açıklamayı yanlış kılmaz. Açılan özette birleştirilmiş etki ve güven aralıkları doğrulanmadı. Rahatlatıcı bir açıklama her zaman doğru değildir."},{id:"optimism-hofmann",title:"O06 · Hofmann ve arkadaşları · 2012 · BDT meta-analizlerinin derlemesi",url:"https://doi.org/10.1007/s10608-012-9476-1",type:"research",finding:"Derleme 269 bilişsel davranışçı terapi meta-analizi belirledi, temsili 106’sını inceledi. Kanıt tedavi programlarının bütünüyle ilgiliydi ve soruna göre değişiyordu.",limitation:"Bu sayılar, düşünce kayıtlarının tek başına sınandığı deney sayıları değildir. ODA formunu doğrulamaz. Ayrı düzeltme notunun metnine doğrulama için ulaşılamadı."},{id:"optimism-brunwasser",title:"O05 · Brunwasser, Gillham ve Kim · 2009 · Penn Resiliency Programı derlemesi",url:"https://doi.org/10.1037/a0017671",type:"research",finding:"2.498 genci kapsayan 17 kontrollü araştırmada çok oturumlu program, hiçbir uygulama yapılmamasına göre depresyon belirtilerinde küçük faydalar gösterdi.",limitation:"Başka etkin uygulamalara üstünlük ve depresyon tanılarını önleme gösterilmedi. Gençlere yönelik bu program, yetişkinin tek bir ABCDE çalışmasını doğrulamaz."},{id:"optimism-ellis-abc",title:"O12 · Albert Ellis Institute · Uzmanlar için ABC açıklaması",url:"https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf",type:"guidance",finding:"Uzmanlara yönelik açıklama olayı, inançları, sonuçları, katı inançları sorgulamayı ve daha işlevsel bir bakış geliştirmeyi anlatır.",limitation:"Bir yöntem belgesi, etki deneyi değil. Ellis’in son adımı, sonraki “enerji kazanma” sürümleriyle aynı sayılmamalı. ODA’nın kısa çalışması bir uyarlama."},{id:"optimism-beck-thought-record",title:"O13 · Beck Institute · Düşünce kaydı formu",url:"https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf",type:"guidance",finding:"Klinik form durumu, düşünceyi, duyguyu, kanıtı, dengeli yanıtı ve sonraki puanları kaydeder.",limitation:"Klinik bir yöntem, tek başına etki deneyi değil. ODA’nın kısa uyarlaması BDT tedavisi değildir. Dengeli yanıt sıkıntıyı azaltmak zorunda değil."},{id:"optimism-reivich-mrt",title:"O14 · Reivich, Seligman ve McBride · 2011 · Psikolojik dayanıklılık eğitimi",url:"https://doi.org/10.1037/a0021897",type:"guidance",finding:"Program açıklaması ABC’yi, düşünce hatalarına bakmayı, en kötü, en iyi ve en olası ihtimalleri düşünüp plan yapmayı içerir.",limitation:"On günlük eğitici kursunun açıklaması. Bu alıştırmaların tek başına veya ODA kursunun bütün olarak etkisini göstermez."},{id:"optimism-landau-inquiry",title:"O11 · Landau ve arkadaşları · 2021 · Rehberli sorgulama araştırması",url:"https://doi.org/10.1001/jamanetworkopen.2021.39670",type:"research",finding:"BRCA varyantları olan 100 kadınla kaydı yapılmış randomize araştırma, 12 haftalık rehberli sorgulamayı olağan sağlık bakımıyla karşılaştırdı. Bazı iyi oluş sonuçlarında fayda bildirdi.",limitation:"Haftalık üç saatlik gruplar ve rehber desteğiyle çalışma, kısa bir kişisel ders değildir. Olağan sağlık bakımında eşit ilgi yoktu. BDT eşdeğerliğini veya istismar ve travmaya uygunluğu göstermez."},{id:"optimism-katie-instructions",title:"O15 · Byron Katie International · The Work yönergeleri",url:"https://thework.com/instruction-the-work-byron-katie/",type:"technique",finding:"Uygulama yönergeleri dört sorgulama sorusunu, ardından düşünceyi başka yönden ele almayı ve gerçek örnekler bulmayı anlatır.",limitation:"Yönergeler bilimsel kanıt değildir. Farklı yorum isteğe bağlı kalsın. Örnek uydurma veya kendini suçlamaya zorlama. Uzun programı sınayan araştırma rehber desteği kullandı."},{id:"optimism-nhs-cbt",title:"O16 · NHS · Bilişsel davranışçı terapi",url:"https://www.nhs.uk/tests-and-treatments/cognitive-behavioural-therapy-cbt/",type:"guidance",finding:"NHS rehberi düzenli BDT tedavisini ve profesyonel yardıma ulaşma yollarını anlatır.",limitation:"Rehber ODA’yı tedavi olarak onaylamaz veya sonuç garantilemez. Pratik korunma ve profesyonel bakım, kendi başına düşünme alıştırmasından önce gelir."},{id:"optimism-three-good-things",title:"O07 · Seligman ve arkadaşları · 2005 · Pozitif psikoloji çalışmaları",url:"https://doi.org/10.1037/0003-066X.60.5.410",type:"research",finding:"İlk çevrim içi deney bir haftalık alıştırmalar kullandı. “Üç iyi şey”, bir hafta boyunca her gece üç olayı ve nedenlerini yazmaktı.",limitation:"Başlangıçtaki 577 kişiden 411’i takibi tamamladı. Çoğu beyaz, eğitimli gönüllülerdi. Devam etmek rastgele belirlenmedi. Kalıcı fayda garantisini veya klinik tedaviyi kanıtlamaz."},{id:"optimism-mongrain",title:"O08 · Mongrain ve Anselmo-Matthews · 2012 · Olumlu alıştırmaların tekrarı",url:"https://doi.org/10.1002/jclp.21839",type:"research",finding:"Tekrar araştırmasında adı geçen alıştırmalarla da olumlu plaseboyla da mutluluk artışı görüldü. Depresyon için özgül bir fayda gösterilmedi.",limitation:"Açılan özette katılımcı sayısı ve sayısal etkiler doğrulanmadı. Bulgular, alıştırmaya özgü etkiyi daha az destekler. Bütün olumlu alıştırmaların işe yaramadığını kanıtlamaz."},{id:"optimism-nimh-support",title:"O20 · NIMH · Depresyon rehberi",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Süren belirtiler veya günlük işleri yapmakta güçlük, uzman değerlendirmesi gerektirir. Kriz desteği alınabilir.",limitation:"Bu bir rehber, uygulamayla konulan tanı değil. Yardım istemek için iki hafta beklemek veya kursu bitirmek gerekmez."}],s=[{schemaVersion:2,revision:2,id:"optimism-1",courseId:"optimism",locale:"tr",title:"Reddedildin mi? Elindeki bir imkânı dene",goal:"Önemsediğin, riski düşük bir aksilik seç. Etki edebileceğin konuda işe yarayan tek bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bir ret cevabı yüzünden her yol kapandı mı? Sonraki kararından önce elindeki bir imkânı dene.",reason:{id:"optimism-1-reason-available-step",label:"Yapabileceğin hangi adımı baştan eledin? Bu kararını hangi bilgi destekliyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Elediğim bir seçeneğe yeniden bakmak","Yerinde bir bırakma kararını korumak","Yapabileceğim bir düzeltmeyi denemek"]},why:{id:"optimism-1-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir aksilik yaşamanla bundan sonra yapabileceğin şey aynı değil. Başkasını işini onaylamaya zorlayamazsın. Ama hangi koşulu karşılamadığını sorabilir, bir beceriyi deneyebilir veya yardım isteyebilirsin. Bütün durumu kontrol edebildiğini söylemek yerine, deneyebileceğin tek bir kısmı seç. Sonuç hakkındaki belirsizliği de olduğu gibi bırak.","Araştırmalarda psikolojik uygulamalar iyimserlik puanlarını ortalama olarak değiştirdi. Bu puanlar beklentileri ölçer. Ret cevabının değişeceğini kanıtlamaz. Bu kursta gündelik bir aksiliği ve ardından attığın adımı takip edeceğiz. Adımını kaydet, dene, gelen yanıtı veya yanıt gelmediğini yaz. Takvime eklemek hazırlık; soruyu göndermek ise işi yapmaktır."],example:{title:"Ece soruyor, yanıt henüz gelmiyor",text:"Ece’nin taslağı reddedilince önemsediği projeyi bırakmak aklına geliyor. Saat 12.30’da güvenle konuşabildiği ekip grubuna soruyor: “Önce hangi eksiği gidermeliyim?” O öğleden sonra yanıt gelmiyor. Kaydına soruyu gönderdiğini yazıyor. Geri bildirim istemeyi denedi. Projenin kabul edileceğini kanıtlamış olmadı. Yanıt gelmemesi, soruyu sormadığı anlamına da gelmiyor. Sonraki kararında bu ayrımı koruyor."}},move:{invitation:"Gündelik bir aksilik seç. Elindeki bir imkânı dene, sonra gerçekte ne olduğunu kaydet.",instructions:["Kurs boyunca aynı aksilik ve seçtiğin amaç üzerinde çalış.","Yalnızca takvime ekleme; gerçekten yapacağın bir iş seç."],prompts:[],suggestions:{action:["Belirli bir eksik hakkında tek soru gönder","Bildiğim eksiklerden birini gider","Bu aksilik için pratik yardım iste"],minimum:["Geri bildirim isteyen tek açık cümle gönder","Bildiğim tek bir hatayı düzelt","Pratik yardım için tek bir istekte bulun"],cue:["Sıradaki güvenli ekip görüşmemiz başladığında","Reddedilen taslağı yeniden açıp başına geçtiğimde","İhtiyacım olan desteğe ulaşabildiğim ilk fırsatta"],place:["Güvenle konuşabildiğim mesaj grubumuzda","Her zamanki çalışma yerimde"],fallback:["Birinden eksik koşullardan birini açıkça belirtmesini iste","Bildiğim bir eksiği gidermeye başla","Yanıt gelmiyorsa başka bir iletişim yolu seç"],observation:["Soruyu gerçekten gönderip göndermediğim","Gelen yanıt veya yanıt gelmemesi","Hangi kısma etki edebildiğim"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Belirli bir eksik hakkında tek soru gönder",minimum:"Geri bildirim isteyen tek açık cümle gönder",minutes:2,cueHint:"Sıradaki güvenli ekip görüşmemiz başladığında",placeHint:"Güvenle konuşabildiğim mesaj grubumuzda",obstacleHint:"Etki edebileceğim bir koşulu henüz belirleyemiyorum.",fallbackHint:"Birinden eksik koşullardan birini açıkça belirtmesini iste",observationHint:"Soruyu gerçekten gönderip göndermediğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-1-review-window-decision",scenario:"Ece’nin taslağı neden belirtilmeden reddedilmiş. Raporu inceleyen kişiye soru sormak için on dakikası kalmış. Düzeltme iki saat alacak. Bu zamanı ayırmaya değip değmeyeceğini öğrenmek istiyor.",question:"Şimdi hangi adım bu kararı daha sağlam bilgiyle vermesini sağlar?",options:[{id:"optimism-1-inspect-brief",text:"Eski yönergeyi on dakika inceleyip ret sebebi olduğunu düşündüğü koşulu ardından düzeltmeye başlamak.",feedback:"Yönergeye bakmak gerçekten eksik bir şeyi gösterebilir. Ama ret nedenini hâlâ öğrenmiş olmaz ve soru sorabileceği son dakikaları kullanır. Önce şimdi sor; ardından ilgili koşula dönüp bak."},{id:"optimism-1-ask-criterion",text:"Hangi koşulun eksik kaldığını sorup gelen yanıta göre yapabileceği tek bir düzeltme seçmek.",feedback:"Bu seçim, bilgi alabileceği fırsatı kapanmadan kullanır. Yanıt, düzeltmeyi, yardım istemeyi veya bırakmayı haklı kılabilir. Ece’nin yaptığı iş soruyu göndermektir. Yanıt alması, bu adımı tamamlamasının şartı değildir."},{id:"optimism-1-send-partial-rewrite",text:"Soru sorma süresi dolmadan çabasını göstermek için taslağın on dakikada düzeltebildiği kısmını göndermek.",feedback:"Kısmi düzeltme asıl eksiği giderirse işe yarayabilir. Ama ret nedeni bilinmiyor. Ece tahminle ilerlemiş olur. Düzeltmeye zaman ayırmadan önce bu fırsatta hangi değişikliğin gerektiğini sorsun."}],bestOptionId:"optimism-1-ask-criterion"}},carry:{takeaway:"Aksilikten sonra etki edebileceğin tek bir adımı dene. Bu adımın gerçekte neyi değiştirdiğini kaydet.",followUp:{questionId:"optimism-1-return",question:"Yapabileceğin adımı attın mı? Yeni bilgi mi geldi, yanıt mı gelmedi, yoksa yeni bir engel mi çıktı?",observationPrompt:"Adımdan sonra hangi bilgi veya yeni engel çıktı? Yanıt gelmediyse onu da yaz.",adjustmentPrompt:"Öğrendiklerine göre şimdi hangi adım sana daha uygun?"}},goDeeper:{sections:[{heading:"Hayvan araştırmalarındaki açıklama sonradan değişti",paragraphs:["Maier ve Seligman’ın 2016 derlemesi, onlarca yıllık hayvan araştırmasına bakarak öğrenilmiş çaresizliğin açıklamasını yeniden ele alır. [O01] İncelenen deneylerde uzun süre olumsuz uyarana maruz kalmak pasifliği doğurur. Kontrolü fark etmek ise koruyucu sinir devrelerini harekete geçirir. Bu açıklama, uzun süre olumsuz olaylara maruz bırakılan sıçan ve köpeklerle ilgilidir. Bir yetişkinin gündelik hayatta reddedilen taslağına ilişkin doğrudan bir deney değildir.","Derleme, donup kalmanın her insanda varsayılan tepki olduğunu, her çaresizliğin aynı mekanizmadan kaynaklandığını veya kontrol edilebilir işleri listelemenin klinik bir sorunu giderdiğini göstermez. Bu yüzden ders, tepkine bir beyin açıklaması yapıştırarak başlamıyor. Önce pratik bir ayrım yapıyoruz: raporu inceleyen kişinin kararı başka bir olay, senin gönderebileceğin soru başka bir olay. İkisini aynı sonuca bağlamak zorunda değilsin.","ODA’nın aksilikten sonra tek adım denemesi bir uyarlama. Elindeki imkânın pek bir şeyi değiştirmediğini de görebilirsin. Koşullar yardım almayı veya başka bir yön seçmeyi gerektirebilir. Bu sonucu da sakla. Bir şeyi gerçekten denemek, umudunun geri geleceğine söz vermeden sana bilgi sağlar. Bu bilgiyle aynı adımı sürdürmek, değiştirmek veya bırakmak arasında daha somut bir karar verebilirsin."]},{heading:"Beklentinin değişmesi, sonucun garantisi değil",paragraphs:["Malouff ve Schutte, 3.319 kişinin katıldığı 29 randomize araştırmayı birleştirdi. [O03] Psikolojik çalışmalar iyimserlik puanlarını ortalama olarak artırdı: g = 0,41. Yöntem, sunuluş biçimi ve takip süresi değişiyordu. Daha kısa takipte ve yalnızca takibi tamamlayanlara bakan analizlerde daha büyük etkiler bulundu. Bu ortalama araştırma gruplarını anlatır. Tek denemeden sonra senin beklentinin ne kadar değişeceğini söylemez.","Derleme, kişiliğin kalıcı değiştiğini, nesnel sonuçların iyileştiğini veya bu ODA kursunun etkisini göstermiyor. Geri bildirim isteyerek hangi koşulun arandığını öğrenmeyi denersin. Sonradan kabul edileceğine söz veremez. Yine de gelen yanıt, düzeltmenin ayıracağın zamana değip değmediğini, yardım gerektirip gerektirmediğini veya artık sana uymadığını anlamana yardım edebilir. Henüz yanıt yoksa sonucu biliyormuş gibi yazmak yerine belirsizliği kayıtta koru.","Bir sonraki adımın başka bir iş yerine destek istemek olabilir. NIMH rehberi, süren belirtilerde veya günlük işleri yapmak zorlaştığında uzman değerlendirmesini önerir. [O20] Dersleri bitirmeden yardım isteyebilirsin. Belirli bir süre dolmasını da beklemek gerekmez. Birinden gerçekten yardım istemek, kendi başına anlamlı bir adım olabilir. Yardım istemeyi planlamanla isteği göndermen ayrı olaylar olarak kalsın."]}],sourceIds:["optimism-maier-seligman","optimism-malouff-schutte","optimism-nimh-support"]}},{schemaVersion:2,revision:2,id:"optimism-2",courseId:"optimism",locale:"tr",title:"Tek taslak yüzünden kendini silip attın mı?",goal:"Aksiliğin nedenini doğru anlat. Kendin hakkında toptan hüküm vermeden işe yarayan tek bir düzeltme dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Reddedilen taslak “Ben bu işi yapamam”a mı dönüştü? Olanı doğru anlat, sonra tek bir düzeltme dene.",reason:{id:"optimism-2-reason",label:"Hangi kısmı sen değiştirebilirsin? Hangi kısmı henüz bilmiyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Düzeltebileceğim kısmın sorumluluğunu almak","Henüz bilmediğim kısmı belirtmek","İşe yarayan tek düzeltmeye dönmek"]},why:{id:"optimism-2-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı aksiliğe ve kaydettiğin yanıta geri dön. Aksilikleri kalıcı, hayatın birçok alanını etkileyen ve kişinin kendisinden kaynaklanan olaylar olarak açıklamak depresyonla ilişkili. Bu ilişki, birinin diğerine neden olduğunu kanıtlamaz. Canını acıtan her açıklamanın yanlış olduğu anlamına da gelmez. Elindeki bilgiye bakarak hangi kısmın doğru kaldığını ayır.","Sor: Bu durumun nedeni ne kadar sürebilir? Hayatın hangi kısmını etkiliyor? Hangi kısım bana ait, hangisi bilinmiyor? Uzun süren bir beceri eksiği gerçek olabilir. Bunu söyle, ama tek taslaktan her şey hakkında hüküm çıkarma. Bir düzeltme dene. Rahatlatıcı bir neden uydurmak yerine sorumluluğunu ve belirsizliği koru."],example:{title:"Ece belirli bir eksiği düzeltiyor",text:"Ece, reddedilen taslağın müşterinin bütçe sorusuna yanıt vermediğini öğreniyor. Saat 7.00’de “Ben bu işte iyi değilim” yerine eksiği açıkça anlatıyor: bütçe bölümü tamamlanmamıştı. İşe yarayan tek bir açıklama ekleyip değerlendirmeye gönderiyor. Raporu inceleyen kişi hâlâ daha çok ayrıntı istiyor. Ece bir düzeltme yaptı. Projenin bütünü hakkındaki sonuç ise henüz belli değil."}},move:{invitation:"Aynı aksiliği kullan. Doğru bir neden belirle, sonra onun gerektirdiği düzeltmeyi yap.",instructions:["Bilgi destekliyorsa kalıcı koşulları ve kendi payını açıkça koru.","İşe yarayan tek düzeltmeyi yap. Gerçekte çıkan sonucu kaydet."],prompts:[],suggestions:{action:["Bildiğim eksiklerden birini gider","Yönergenin hangi kısmının eksik kaldığını sor","Belirlediğim beceriyi bir kez dene"],minimum:["Taslakta tamamlanmamış tek satırı düzelt","Eksik bilgiyi açıklığa kavuşturan tek soru gönder","Beceriyi bir kez dene"],cue:["Aynı taslağı yeniden açıp başına geçtiğimde","Sıradaki güvenli geri bildirim fırsatımız geldiğinde","İstenen koşulu okuduktan sonra"],place:["Düzelttiğim taslağın ilgili bölümünde","Güvenle geri bildirim alabildiğim iletişim kanalında"],fallback:["Koşulu yeniden oku, bilgilerin gösterdiği eksiği düzelt","Gerekli bilgi eksikse bunu açıkça sor","Beceri eksiğim için birinden yardım iste"],observation:["Gerçekte hangi kısmı düzelttiğim","Hangi nedenin hâlâ bilinmediği","Geri bildirimin açıklamama uyup uymadığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Bildiğim eksiklerden birini gider",minimum:"Taslakta tamamlanmamış tek satırı düzelt",minutes:2,cueHint:"Aynı taslağı yeniden açıp başına geçtiğimde",placeHint:"Düzelttiğim taslağın ilgili bölümünde",obstacleHint:"Tek başarısızlıktan bütün işlerim hakkında hüküm çıkarıyorum.",fallbackHint:"Koşulu yeniden oku, bilgilerin gösterdiği eksiği düzelt",observationHint:"Gerçekte hangi kısmı düzelttiğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-2-budget-gap-decision",scenario:"Ece’nin raporunu inceleyen kişi bütçede eksik tek bir varsayımı belirtmiş. Diğer bölümler yönergeye uyuyor. Düzeltme için on dakika kalmış. Ece bu eksiğin işi yapamadığını kanıtladığını düşünüyor.",question:"Hangi yanıt bilgiye ve kalan süreye daha uygun?",options:[{id:"optimism-2-rewrite-budget",text:"Raporu inceleyen kişinin bütünüyle yeni bir sürümü inceleyebilmesi için şimdi bütçe bölümünün tamamını yeniden yazmak.",feedback:"Bir bölümde birbiriyle bağlantılı birçok sorun varsa yeniden yazmak işe yarayabilir. Burada tek bir varsayım eksik ve süre kısa. Kabul edilmiş kısımları değiştirmeden bu belirli eksiği tamamla."},{id:"optimism-2-clarify-first",text:"Bölümü değiştirmeden önce raporu inceleyen kişiden eksik varsayımı yeniden anlatmasını isteyip gelecek açıklamayı beklemek.",feedback:"Geri bildirim belirsizse açıklama istemek işe yarar. Burada gereken koşul zaten belirtilmiş. Beklemek süreyi kaçırabilir. Bilinen eksiği düzelt, sonra bu düzeltmenin koşulu karşılayıp karşılamadığını sor."},{id:"optimism-2-specific-correction",text:"Bütçedeki eksiği kabul edip tek bir kısmı düzeltmek, işi yapamadığına ilişkin geniş hükmü kesinleştirmemek.",feedback:"Bu seçim bilgilerin desteklediği eksiği kabul eder ve kısa süreyi onu gidermek için kullanır. Düzeltmenin koşulu karşılayıp karşılamadığını sor. Yeni geri bildirim de bu taslak hakkında bilgi sağlar. Mesleğin hakkında kesin hüküm vermez."}],bestOptionId:"optimism-2-specific-correction"}},carry:{takeaway:"Doğru bir açıklama canını sıkabilir. Yine de işe yarayan bir düzeltmenin yolunu gösterebilir.",followUp:{questionId:"optimism-2-return",question:"Düzeltmen, bilgilerin desteklediği bir nedeni ele aldı mı? Açıklamanın hangi kısmı hâlâ bilinmiyor?",observationPrompt:"Hangi nedeni ele aldın? Hangi kısmı hâlâ bilmiyorsun, henüz ne öğrenmedin?",adjustmentPrompt:"Şimdi hangi eksik için düzeltme, açıklama veya birinden yardım gerekiyor?"}},goDeeper:{sections:[{heading:"Rahatlatıcı cevap aramak yerine soruyu açık tut",paragraphs:["Sweeney ve arkadaşları, yaklaşık 15.000 kişinin yer aldığı 104 araştırmayı inceledi. [O02] Farklı örneklem ve görevlerde, olumsuz olayları kişinin kendisine bağlayan, kalıcı ve yaygın açıklamalar depresyonla ilişkiliydi. Bu boyutlar kişinin payını, süren nedenleri ve geniş etkileri ele alır. Her aksiliğin yalnızca tek bir nedeni olması gerektiğini söylemez. Bulunan ilişki de hangi etkenin diğerine neden olduğunu göstermez.","Bu derste bu boyutlarla açıklamana bakıyoruz. Sana neşeli bir sonuç dayatmıyoruz. Uzun süren bir koşul uzun sürebilir. Senin atladığın bir gereklilik yine senin düzeltmen gereken kısım olabilir. Ortak nedenler de bulunabilir; bazılarıysa hâlâ bilinmeyebilir. Her açıklamayı “Geçici ve benim dışımda” diye değiştirmek doğruluğu kaybettirir. Rahatlamasan da eldeki bilgiye uyan bir açıklamayı koruyabilirsin.","Bu soruyu, kurs boyunca denediğin aynı adım için sor. Hangi kısmı düzeltebilir, kontrol edebilir veya yardım alarak ele alabilirsin? Belirli bir işi denemek, yeteneğin hakkındaki geniş bir iddiayı sınamaktan daha kolaydır. Yaptığın işi kaydet. Bu işin sonucuna getirdiğin yorumu ayrı tut. Bir düzeltmenin yapılması, hem o düzeltme hem bütün kariyerin hakkında aynı ölçüde bilgi sağlamaz."]},{heading:"Adil bir açıklamada gerçek sorun da kalabilir",paragraphs:["Beck Institute’un düşünce kaydı yöntemi kanıtları, başka açıklamaları, dengeli bir yanıtı ve sonraki gözlemleri içerir. [O13] Bu klinik form, buradaki kısa açıklama çalışmasının tek başına ruh hâlini iyileştirdiğinin kanıtı değildir. ODA’nın kısa uyarlamasının bağımsız bir tedavi etkisi gösterilmiş değil. Onu rahatlatıcı bir açıklama üretme zorunluluğu olarak değil, bilgilere uyan bir düzeltme bulmak için kullan.","Dengeli bir açıklama hoşuna gitmeyen gerçekleri de içerebilir. Bütçe bölümü eksik, süre dar veya bir beceriyi geliştirmek gerekiyor olabilir. Bilinmeyen kısımlar da açık kalabilir. Sonraki işin başka bir rahatlatıcı cümle kurmak olmayabilir. Bir düzeltme yapman, tarafsız bir soru sorman veya yardım istemen gerekebilir. Yanıtın daha iyi hissettirmesi ile önündeki soruna uygun olması aynı şey değil.","NHS rehberi, bilişsel davranışçı terapiyi düzenli bir tedavi olarak anlatır ve profesyonel yardıma ulaşma yollarını gösterir. [O16] Bu kurs eğitim sunar. Kendi başına aynı düşünceyi tekrar tekrar irdelemek sıkıntını artırıyorsa veya günlük işlerini aksatıyorsa çalışmayı durdur ve uygun destek iste. Güvenliğin ve pratik ihtiyaçların, iyimser görünmekten önce gelir. Kendini korumak da yerinde bir sonraki adım olabilir."]}],sourceIds:["optimism-sweeney","optimism-beck-thought-record","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-3",courseId:"optimism",locale:"tr",title:"Öfkeli mesaj hazır mı? Önce olanı ayır",goal:"Aynı aksiliğe kısaca bak. Ardından arkasında durabileceğin, işe yarayan tek bir yanıtı ver veya düzeltmeyi yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kendini savunmak için yazdığın mesajı göndermek üzeresin. Olanı doğru anlat, ardından yarın da arkasında duracağın bir yanıt seç.",reason:{id:"optimism-3-reason",label:"Hangi yanıt hem bugün hem yarın istediğin hayata katkı sağlar?",kind:"text",maxLength:160,optional:!0,suggestions:["Belirli bir hatamı kabul etmek","Mesleğim hakkında kesin yargıya varmadan yanıtlamak","Önümdeki pratik sorunu çözmek"]},why:{id:"optimism-3-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Teslim tarihini kaçırmak, gerçekleşmiş bir olay. “Ben bu işi yapamam” ise daha geniş bir inanç. Kaynaklarda anlatılan bir yöntem, olayı, inancı ve ardından gelen duygu veya davranışı ayırır. Düşünceler yanıtını etkileyebilir. Ama her duyguyu tek başına açıklamaz. Hangi kısmın olay, hangi kısmın yorum olduğunu bilerek başla.","Aynı aksiliğe dön. Tek bir olayı tarafsızca anlat, inancını eldeki bilgilerle karşılaştır ve işe yarayan bir yanıt seç. Kaygın doğruysa o kısmı koru, çözüm ara. Adil bir yanıtla sorumluluk alabilir, bir istekte bulunabilir veya sınır koyabilirsin. Utancın veya öfkenin geçmesini beklemeden bu adımı atabilirsin."],example:{title:"Ece sorumluluk alarak yanıtlıyor",text:"Ece düzeltilmiş raporun teslim tarihini kaçırıyor. Saat 6.30’da kendini savunmak için mesaj yazmaya başlıyor. Sonra olayı “Ben bu işi yapamam” hükmünden ayırıyor. “Bugünkü teslimi kaçırdım. Düzeltilmiş bölümü yarın öğlene kadar gönderebilirim. Uyar mı?” diye yazıp gönderiyor. Yöneticisi saati kabul ediyor ama hâlâ kızgın. Ece hem anlaşmayı hem bitmemiş işini kaydediyor."}},move:{invitation:"Aynı aksilikte inancına kısaca bak. Ardından duruma uygun, adil tek bir yanıtı ver.",instructions:["Gözleyebildiğin tek olayı kendin hakkındaki geniş hükümden ayır.","İşe yarayan bir düzeltme, istek veya sınır cümlesi gönder."],prompts:[],suggestions:{action:["Sorumluluk alıp düzeltme öneren tek yanıt gönder","Yapabileceğim bir teslim tarihi için istekte bulun","Anlaştığımız düzeltmelerden işe yarayan birini tamamla"],minimum:["İşe yarayan tek bir yanıt cümlesi gönder","Yapabileceğim tek bir sonraki adımı açıkça söyle","Anlaştığımız işin tek yararlı parçasını bitir"],cue:["Zor mesajı göndermeden hemen önce","Sıradaki güvenli düzeltme görüşmemiz başladığında","Anlaştığımız işe yeniden başladığımda"],place:["Güvenle konuşabildiğim iş mesajı grubumuzda","Her zamanki çalışma yerimde"],fallback:["Olayı ve yapılabilir adımı yaz, sonra gönder","Birinden olayları anlattığım yanıta bakmasını iste","Bunun yerine pratik yardım almayı seç"],observation:["Gerçekte ne gönderdiğim veya değiştirdiğim","Anlaştığımız konu veya anlaşmaya varılamaması","Kaygımın hangi kısmının doğru kaldığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sorumluluk alıp düzeltme öneren tek yanıt gönder",minimum:"İşe yarayan tek bir yanıt cümlesi gönder",minutes:2,cueHint:"Zor mesajı göndermeden hemen önce",placeHint:"Güvenle konuşabildiğim iş mesajı grubumuzda",obstacleHint:"Asıl hatayı ele almadan önce kendimi savunmak istiyorum.",fallbackHint:"Olayı ve yapılabilir adımı yaz, sonra gönder",observationHint:"Gerçekte ne gönderdiğim veya değiştirdiğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-3-decision",scenario:"Ece’nin yöneticisi teslim tarihini kaçırdığını söylüyor. Bu doğru. Ece “Ben bu işi yapamam” diye düşünüyor ve kendini savunmak istiyor.",question:"İnancına adilce bakmayı hangi adımla daha iyi uygular?",options:[{id:"optimism-3-own-and-correct",text:"Kaçırdığı tarihi kabul edip mesleği hakkındaki hükmü açık bırakmak ve yapabileceği bir düzeltmede anlaşmak.",feedback:"Bu seçim gerçek olayı korur ve geniş hükmü sınar. Utanç sürse de yapabileceği bir düzeltme önerir. Yöneticinin onayı, gözlenecek bir sonuçtur. Ece’nin kendi adımını tamamlaması için şart değildir."},{id:"optimism-3-past-reviews",text:"Eleştiri daha az tehdit edici gelene kadar eski olumlu yorumları okuyup ardından yanıt verip vermeyeceğine karar vermek.",feedback:"Eski geri bildirim, toptan hükmünü sorgulatabilir. Ama bugünkü kaçırılmış tarihi ele almaz. Rahatlamayı beklemek pratik yanıtı geciktirir. İlgili bilgilere kısaca bak, sonra yapabileceğin tek bir düzeltmeyi öner."},{id:"optimism-3-pressure-first",text:"Düzeltmeyi konuşmadan önce yaşadığı baskıyı açıklayıp yöneticisinden gösterdiği çabanın farkına varmasını istemek.",feedback:"İş yükü baskısı gerçek olabilir. Sınır koymak veya destek almak gerekebilir. Ama çabanın görülmesini şart koşmak düzeltmeyi erteler. Belirli teslim eksiğini kabul ederken yapabileceğin bir değişiklik de iste."}],bestOptionId:"optimism-3-own-and-correct"}},carry:{takeaway:"Gerçek olayı koru. Geniş hükmü sınayıp işe yarayan sonuca göre bir adım at.",followUp:{questionId:"optimism-3-return",question:"Verdiğin yanıt, zor duygu sürse de gerçek sorunu ele aldı mı?",observationPrompt:"Yanıtın, gerçekte yaşanan hangi sorunu ele aldı veya hangi kısmı çözümsüz bıraktı?",adjustmentPrompt:"Hangi kısım hâlâ düzeltme, bir istek veya güvenli bir sınır gerektiriyor?"}},goDeeper:{sections:[{heading:"ABCDE yöntemi nereden geliyor?",paragraphs:["Albert Ellis Institute’un uzmanlara yönelik açıklaması olayı, inançları ve sonuçları ayırır. Ardından katı inançların sorgulanmasını ve daha işlevsel bir bakış geliştirmeyi anlatır. [O12] Daha sonraki psikolojik dayanıklılık eğitimlerinde son adım için “enerji kazanma” ifadesi kullanılır. [O14] Bu adlar aynı şeyi anlatan, kesin duygu değişimi vaatleri değildir. Ellis’in son adımını sonraki bütün sürümlerle aynı saymak kaynaklar arasındaki farkı siler.","Bu kaynaklar yöntemleri anlatır. Yetişkinin kısa bir ABCDE çalışmasından tek başına fayda göreceğini göstermez. ODA daha kısa bir sıra kullanır: olayı anlat, inancına bak ve durumun gerektirdiği ölçüde yanıt ver. Duygular koşullardan, kayıptan, sağlıktan ve destekten de etkilenir. İnançları sıralamak, duygunun tam açıklaması değildir. Hangi kısmın gerçekten değiştirilebileceğini anlamaya yardım eden bir araç olarak kalabilir.","Sürdürdüğün denemede bu yöntemi yalnızca gözlediğin bir sorunu çözmeye yardım ediyorsa kullan. Her adım attığında beş harfin hepsine karşılık gelen alanları doldurman gerekmiyor. Kaygın haklıysa yararlı yanıt, onu tartışarak ortadan kaldırmak yerine pratik çözüm veya destek olabilir. Teslim tarihi gerçekten kaçtıysa önce düzeltme gerekir. Kendin hakkında geniş hüküm vermemek, sorumluluğunu görmezden gelmek anlamına gelmez. Hem olayı hem yapılabilecek işi açık tut."]},{heading:"Gençlere yönelik program tek alıştırmadan fazlasıydı",paragraphs:["Brunwasser ve arkadaşları, Penn Resiliency Programı’nın 2.498 genci kapsayan 17 kontrollü araştırmasını inceledi. [O05] Hiçbir uygulama yapılmayan gruplara göre depresyon belirtilerindeki etkiler küçüktü: hemen ardından d = 0,11, altı ile sekiz ayda 0,21, on iki ayda 0,20. Başka etkin uygulamalara üstünlük ve depresyon tanılarını önleme gösterilmedi.","Program birçok düşünme ve davranış becerisini öğretiyordu. Bulgular, yetişkinin tek bir ABCDE çalışmasını doğrulamaz veya ODA’nın yanıt alıştırmasının etkisini söylemez. Yöntemi öğrenmek, planı kaydetmek ve işe yarayan bir yanıtı göndermek ayrı olaylar olarak kalsın. Gerçek adımın kanıtı, gönderdiğini bildirdiğin yanıttır. Planı güzel yazmış olman, mesajı kullandığını veya işin düzeldiğini tek başına göstermez. Bunları gözle.","Kurstaki denemeyi gündelik, güvenli bir aksilikle sınırla. Teslim tarihinin kaçırılması düzeltme gerektirebilir. Değerin hakkında bir hükme dönüşmesi gerekmez. Planın zamanına veya imkânlarına sığmıyorsa beklentiyi değiştir ya da yardım iste. Aynı düşünceyi tekrar tekrar tartışıp durmak, eksik zamanı yaratmaz. Yapılabilir bir adım ve koşullara uyan bir süre seç. Gerçekte neyi yaptığını ve neyin kaldığını ayrı ayrı kaydet."]}],sourceIds:["optimism-ellis-abc","optimism-reivich-mrt","optimism-brunwasser"]}},{schemaVersion:2,revision:2,id:"optimism-4",courseId:"optimism",locale:"tr",title:"Yanıt yok. Kaygılandığın şeyin kanıtı var mı?",goal:"Bildiğin olayla tahminini ayır. Sonra aynı aksilik hakkında ulaşabileceğin tek bir bilgiyi kontrol et.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yanıt gelmedi, sen şimdiden hüküm verdin mi? Planını bu yoruma göre kurmadan önce tek bir bilgiyi kontrol et.",reason:{id:"optimism-4-reason",label:"Hangi bilgi, atmak üzere olduğun bir sonraki adımı değiştirirdi?",kind:"text",maxLength:160,optional:!0,suggestions:["Tahmin etmeden önce kontrol etmek","Gerçek bir kaygıyı görünür tutmak","Eksik olan bilgiyi doğrudan sormak"]},why:{id:"optimism-4-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı aksiliğe dön. “Bugün yanıt gelmedi” bildiğin bir olay. “Beni yine reddettiler” ise destekleyen bilgi yoksa tahmin. Dengeli bir yanıt, gerçek kaygıyla eksik bilgiyi birlikte tutar. Belirsizlik kalabilir. Açıklama hâlâ canını sıkabilir. Rahatlatıcı olması, doğru olmasıyla aynı şey değildir. Önce gerçekten bildiğin kısmı bul.","Kaynaklarda anlatılan düşünce kaydı klinik bir araç. Tedavinin bütünü için bulunan kanıt, kısa bir formun tek başına işe yaradığını göstermez. Kısa bir kontrol yap: olay, yorum, ulaşabileceğin bilgi ve sonraki iş. Tarafsız bir soru sor veya bilinen sorunu düzelt. Tekrarlayan irdeleme sıkıntını artırırsa dur. Kaygı puanının düşmesi şart değil."],example:{title:"Ece eksik yanıtı soruyor",text:"Ece’nin düzelttiği bölüme yanıt gelmemiş. Yöneticisinin seyahatte olduğunu biliyor. Planlı görüşmede bütçe açıklamasının yönergeye uyup uymadığını soruyor. “Az kaldı, varsayımı ekle” yanıtını alıp bunu düzeltiyor. Daha geniş bir ret bekliyordu. Ama bütün kaygılarını temelsiz ilan etmek yerine gerçekten aldığı geri bildirimi kaydediyor. Sorunun ne olduğunu bu yanıttan öğrendi. Sonraki adımını ona göre seçti."}},move:{invitation:"Aynı aksilikte ulaşabileceğin tek bilgiyi kontrol et. Sonra onun gösterdiği adımı at.",instructions:["Bildiğin olayı tahmin ettiğin anlamdan ayrı tut.","Tarafsız tek soru sor veya bilgilerin gösterdiği sorunu düzelt."],prompts:[],suggestions:{action:["İşin durumu hakkında tarafsız tek soru sor","Gerçekte istenen koşulu bir kez kontrol et","Doğrulanan sorunu ele alıp düzelt"],minimum:["Bir bilgiyi kontrol eden tek cümle gönder","İlgili tek bir koşulu doğrula","Bilgilerin gösterdiği tek hatayı düzelt"],cue:["Planladığımız güvenli görüşmenin zamanı geldiğinde","İlgili bilgiye ulaşabileceğim fırsat geldiğinde","Tahminime göre harekete geçmeden önce"],place:["Güvenle geri bildirim alabildiğim iletişim kanalında","Gerçekte istenen koşul önümde açıkken"],fallback:["Kontrol için daha sonraki uygun fırsatı seç","Bunun yerine birinden pratik yardım iste","Aynı irdelemeyi tekrarlamayı bırak ve ara ver"],observation:["Kontrolden önce gerçekten ne bildiğim","Aldığım yanıtın hangi bilgiyi doğruladığı","Yeni bilgiyle planımın değişip değişmediği"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşin durumu hakkında tarafsız tek soru sor",minimum:"Bir bilgiyi kontrol eden tek cümle gönder",minutes:2,cueHint:"Planladığımız güvenli görüşmenin zamanı geldiğinde",placeHint:"Güvenle geri bildirim alabildiğim iletişim kanalında",obstacleHint:"Gerçek bilgi gereken bir belirsizliği tekrar tekrar düşünüyorum.",fallbackHint:"Kontrol için daha sonraki uygun fırsatı seç",observationHint:"Kontrolden önce gerçekten ne bildiğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-4-deadline-check-decision",scenario:"Ece’nin taslağına yanıt gelmemiş. Seyahatteki yöneticisi bugünkü görüşmede konuşabilir. Göndermek için otuz dakika kalmış. Gerek düzeltme gerek yedek öneri yirmi dakika alacak.",question:"Kalan zamanı ilk hangi adımla daha iyi kullanır?",options:[{id:"optimism-4-submit-current",text:"Yanıt gelmemesini seyahatte olması açıklayabileceği ve süre daraldığı için taslağın mevcut hâlini şimdi hemen göndermek.",feedback:"Şimdi göndermek süreyi korur. Ama seyahat, taslağın yönergeye uyduğunu kanıtlamaz. Kısa görüşme gereken düzeltmeyi gösterebilir. Ardından bunu yapmak için yirmi dakika kalır. Önce ulaşılabilir bilgiyi kullan."},{id:"optimism-4-check-uncertainty",text:"Sessizliğin nedenini belirsiz bırakıp görüşmede taslağı sormak ve gerçekten gelen yanıta göre düzeltmek.",feedback:"Yönetici ulaşılabilirken ve iş yapmak için hâlâ zaman varken ilgili belirsizliği kontrol eder. Yanıt düzeltmeyi veya yedek öneriyi destekleyebilir. Denemenin ölçüsü kaygının azalması değil, bilgiyi kullanarak harekete geçmesidir."},{id:"optimism-4-backup-and-timeline",text:"Her iki seçeneği açık tutmak için yedek öneriye başlarken kararın ne zaman verileceğini mesajla sormak.",feedback:"Geri bildirim alınamıyorsa yedek plan seçenekleri koruyabilir. Burada yönetici şimdi ulaşılabilir ve iki yol da yirmi dakika alır. Kalan zamanı bilinen ihtiyaca ayırmak için önce taslağı sor."}],bestOptionId:"optimism-4-check-uncertainty"}},carry:{takeaway:"Dengeli yanıt, gerçek kaygıyı ve belirsizliği korur. Bilgiyi kontrol etmek için işe yarayan bir yol gösterir.",followUp:{questionId:"optimism-4-return",question:"Kontrol ettiğin bilgi neyi doğruladı? Sonraki planın bu bilgiye göre değişti mi?",observationPrompt:"Yeni bilgi neyi doğruladı? Hangi kısım hâlâ bilinmiyor veya yanıt bekliyor?",adjustmentPrompt:"Bu bilgiye göre sıradaki hangi adımını değiştirmelisin?"}},goDeeper:{sections:[{heading:"Tedavi kanıtı bütün programa aittir",paragraphs:["Hofmann ve arkadaşları bilişsel davranışçı terapiye ait 269 meta-analiz belirledi ve bunlardan temsili 106’sını inceledi. [O06] Bu sayılar derlemelerin sayısını gösterir. Düşünce kayıtlarının tek başına sınandığı 269 deney demek değil. Makale, farklı bileşenleri ve sorunları içeren tedavi programlarını özetler. Bu alıştırma için tek bir toplam katılımcı sayısı veya her duruma uyan etki vermez. Araştırmadaki tedavi programını buradaki kısa alıştırmayla aynı sayma.","Tedavi programları birden fazla yöntem ve desteği birleştirir. Kanıtları, bu kısa bilgi kontrolünün kendi başına etkisini göstermez. Kontrolü pratik bir belirsizliği gidermek için kullan: Hangi koşul önemli? Düzeltme gerekiyor mu? Karar ne zaman gelecek? Yeni bilgi yoksa aynı irdelemeyi tekrarlamak yerine belirsizliği açık bırak. “Henüz bilmiyorum” kaydı, olmayan bir yanıtı varsaymaktan daha doğrudur. Sonraki uygun kontrol fırsatını ayrıca seçebilirsin.","Beck Institute’un formu klinik bir yöntemi anlatır. [O13] Yöntemin tek başına etkisini bağımsız olarak göstermez. Bu ders, tek bir tahmine bakabilmek için kısaltılmış bir uyarlama kullanır. Sonra öğrendiklerini zaten üzerinde çalıştığın aynı işte kullanırsın. Formu doldurmayı işin yerine koyma. Soruyu sormak veya desteklenen düzeltmeyi yapmak, ayrı olarak kaydedeceğin gerçek adım olabilir."]},{heading:"Puanlar hedef değil, gözlem sağlar",paragraphs:["Kaynakta anlatılan düşünce kaydı, düşünce ve duygu puanlarını, kanıtı, dengeli yanıtı ve sonraki puanları içerir. [O13] Sayılar değişen şeyi anlatabilir. Puanı düşürmek zorunlu olursa senden istenen cevabı yazman için baskı doğar. Dengeli yanıt, kaygı hâlâ haklı görünse de eldeki bilgiye uymalı. Puanın aynı kalması, adımı atmadığın anlamına gelmez.","ODA belirli bir düşünce hatasının adını koymanı veya belli bir duygu puanına ulaşmanı istemez. “Bildiğim” ve “tahmin ettiğim” ayrımı, kontrol edeceğin tek bilgiyi seçmene yetebilir. Bilgilerin desteklediği kaygı bir düzeltme, sınır veya pratik yardım gerektirebilir. Yeni bir rahatlatıcı açıklama her zaman en yararlı adım değildir. Önündeki sorunun gerçek kısmını koru ve yapabileceğin işin ne olduğunu açıkça söyle.","NHS rehberi bilişsel davranışçı terapiyi düzenli profesyonel tedavi olarak anlatır. [O16] Kendi başına irdelemek sıkıntını artırıyorsa veya yeni bilgi olmadan tekrarlanıyorsa durabilirsin. Gerektiğinde uygun yardım iste. Gerçek yanıtı ve yaptığın işi kurs kaydına ekle. Kaygının azalmasını, asıl işin yapıldığının kanıtı olarak kullanma. Yanıt gelmemesi veya sorunun sürmesi de yazılabilir. Bunlar sonraki kararın için bilgi sağlar."]}],sourceIds:["optimism-hofmann","optimism-beck-thought-record","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-5",courseId:"optimism",locale:"tr",title:"Yine mi iptal? İhtiyacını açıkça söyle",goal:"Aynı aksilikte riski düşük bir varsayımına bak. Sonra güvenli bir istek veya sınırı açıkça ilet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Görüşme iptal olunca üstüne mi alınıyorsun? Nedenini merak ederken hâlâ gereken isteği de açıkça söyle.",reason:{id:"optimism-5-reason",label:"Varsayımını gözden geçirdikten sonra hangi istek veya sınır hâlâ gerekli?",kind:"text",maxLength:160,optional:!0,suggestions:["Tahmin etmek yerine doğrudan sormak","Gerekli olan bir sınırı korumak","Merak ederken bütün suçu üstlenmemek"]},why:{id:"optimism-5-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Karşı tarafın amacı bilinmese de senin ihtiyacın gerçek olabilir. Aynı aksiliğe dön. Güvenli bir değerlendirme görüşmesi iptal edildiğinde “Umursamıyorlar” demek olanı aşabilir. “Katılabileceğim bir görüşme saatine ihtiyacım var” ise doğru kalabilir. Birini haklı veya haksız ilan etmeden de bu ihtiyacını açıkça söyleyebilirsin.","Rehber eşliğindeki uzun sorgulama programı, katılımcıların rastgele gruplara ayrıldığı bir araştırmada sınandı. Bu, kendi kendine soracağın dört sorunun tedavi olduğunu göstermez. Sorgulama işe yarıyorsa kullan, sonra isteğini veya sınırını ilet. Düşünceyi tersine çevirip kendini suçlaman veya örnek uydurman gerekmiyor. Tehlike ve kötü davranışı dışarıda tut. Merak etmek, o kişiyle görüşmeni veya kendini korumaktan vazgeçmeni gerektirmez."],example:{title:"Ece görüşme isteğini netleştiriyor",text:"Ece’nin iş arkadaşı rapor görüşmesini iki kez iptal ediyor. Saat 8.00’de “Beni umursamıyor” varsayımına bakıyor. Tersinin kesin doğru olduğunu da söylemiyor. “Perşembeye kadar bakabilir misin? Olmazsa başka birinden değerlendirme alacağım” diye gönderiyor. Arkadaşı söz veremiyor. Ece isteğini kaydedip güvenle görüşebileceği başka birini buluyor. Hayal kırıklığı sürüyor. Yine de ihtiyacını açıkça iletmiş oluyor."}},move:{invitation:"Güvenli bir durumda, nedenini henüz bilmesen de ihtiyacını veya sınırını açıkça söyle.",instructions:["Gerçek ihtiyaçlarını ve sana gereken sınırları görünür tut.","Tek bir açık istek gönder. Tamamlamak için karşı tarafın kabul etmesi gerekmiyor."],prompts:[],suggestions:{action:["Bana uyan bir geri bildirim saati iste","Değerlendirme için pratik tek sınır belirt","Güvenli başka bir yoldan geri bildirim al"],minimum:["Görüşme saati isteyen tek açık mesaj gönder","Tek bir sınırı saygıyla açıkça söyle","Alternatif tek bir değerlendirme iste"],cue:["Güvenli bir değerlendirme görüşmemiz iptal edildiğinde","Sıradaki uygun görüşmemizin zamanı geldiğinde","Üzerinde anlaştığımız sınıra gelindiğinde"],place:["Güvenle geri bildirim alabildiğim mesaj grubunda","Her zamanki iletişim yöntemimi kullanırken"],fallback:["Rapora güvenle bakacak başka birini seç","Bunun yerine pratik yardım almayı seç","Sıkıntımı artıran sorgulamaya ara ver"],observation:["Gerçekte hangi isteği ilettiğim","Gelen yanıt veya anlaşmaya varılamaması","Sınırın hâlâ duruma uyup uymadığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Bana uyan bir geri bildirim saati iste",minimum:"Görüşme saati isteyen tek açık mesaj gönder",minutes:2,cueHint:"Güvenli bir değerlendirme görüşmemiz iptal edildiğinde",placeHint:"Güvenle geri bildirim alabildiğim mesaj grubunda",obstacleHint:"Düşünüp duruyorum, ama hâlâ iletmem gereken doğrudan isteği erteliyorum.",fallbackHint:"Rapora güvenle bakacak başka birini seç",observationHint:"Gerçekte hangi isteği ilettiğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri dışarıda tut. Kendini suçlamaya zorlama. Sıkıntı veren sorgulamaya ara ver.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-5-decision",scenario:"Ece güvenle konuşabildiği iş arkadaşıyla rapora bakacaktı. Arkadaşı iki kez iptal etti. Nedenleri belirsiz. Ece’nin bu hafta geri bildirim alması gerekiyor.",question:"Hangi yanıt hem merakı hem işe yarayan bir sınırı korur?",options:[{id:"optimism-5-finish-alone",text:"Gerginliği azaltmak için değerlendirmeyi tek başına bitirip sonraki projede arkadaşından yardım istemeyi yeniden düşünmek.",feedback:"Değerlendirme isteğe bağlıysa veya gereken beceri varsa tek başına çalışmak uygun olabilir. Burada Ece’nin bu hafta hâlâ geri bildirime ihtiyacı var. Uyan bir saat iste veya rapora güvenle bakacak başka birini bul."},{id:"optimism-5-flexible-slot",text:"Arkadaşı uygun olduğunda seçebilsin diye yeni, esnek bir saat önerip görüşme düzenlemesini ucu açık bırakmak.",feedback:"Esneklik iş birliğini koruyabilir. Ama iki iptal ve bu haftaki son tarih, ucu açık düzenlemeyi riskli yapıyor. İhtiyacın karşılanabilsin diye uygun saatin yanında bir alternatif de belirle."},{id:"optimism-5-request-with-limit",text:"Arkadaşının amacını kesinleştirmeden uygun bir değerlendirme saati istemek, olamazsa kullanacağı alternatifi de açıkça söylemek.",feedback:"Belirsizliği ve pratik ihtiyacı birlikte korur. Arkadaşı reddederse Ece alternatif yolu kullanabilir. Onun kendi adımı isteği göndermektir. Diğer kişinin iş birliği yapması, Ece’nin kontrolünde olmayan bir sonuç olarak kalır."}],bestOptionId:"optimism-5-request-with-limit"}},carry:{takeaway:"Nedeninden emin olmadığın yorumu sorgula. Gerçek isteğini veya gerekli sınırını korumaya devam et.",followUp:{questionId:"optimism-5-return",question:"İsteğin veya sınırın neyi değiştirdi? Aynı sınır hâlâ seçtiğin amaca hizmet ediyor mu?",observationPrompt:"İstekten veya sınırdan sonra ne değişti? Yanıt gelmediyse bunu da ayrı yaz.",adjustmentPrompt:"Bu sınır hâlâ sana uyuyor mu, yoksa şimdi değişmesi mi gerekiyor?"}},goDeeper:{sections:[{heading:"Araştırmada uzun bir program ve rehber desteği vardı",paragraphs:["Landau ve arkadaşları, BRCA varyantları olan 100 kadınla kaydı yapılmış randomize bir araştırmada sorgulamaya dayalı stres azaltmayı sınadı. [O11] Program on iki hafta sürdü. Her hafta üç saatlik grup ve bir saatlik rehber desteğiyle çalışma vardı. Karşılaştırma olağan sağlık bakımıydı. Bazı iyi oluş sonuçlarında fayda bildirildi. Ama karşılaştırma grubuna aynı miktarda ilgi ve zaman sağlanmamıştı. Bu fark, bulgunun yorumunu sınırlar.","Bulgular, kendi kendine soracağın dört kısa sorunun tedavi olduğunu, yöntemin bilişsel davranışçı terapiye eşdeğerliğini veya sonuçların istismar ve travmaya uyduğunu göstermez. Katılımcılar, süre ve uygulama biçimi, buradaki gündelik rapor görüşmesi örneğinden oldukça farklı. İsteğini pratik bir ihtiyaca dayandır. Klinik iyileşme vaadine dayanması gerekmez. Kullanılabilir bir değerlendirme saati istemek, bu araştırmanın programıyla aynı işlem değildir.","ODA’nın istek alıştırması bir eğitim uyarlaması. Düşünmek yardım ediyorsa gereken gerçek görüşmeye geri dön. Kullanabileceğin bir saat iste ve elinde alternatif bulundur. Etkisini henüz bilmeden de isteğini göndermiş olabilirsin. Başkasının iş birliği yapması iyimserliğini ölçen bir sınav değildir. Yanıt gelmediyse veya karşı taraf uygun değilse bu bilgiyi koru. Sonraki adımı ihtiyacına ve koşullarına göre seç."]},{heading:"Sorgulama isteğe bağlı, kendini suçlamak zorunlu değil",paragraphs:["Byron Katie’nin uygulama yönergeleri dört soru kullanır: Düşünce doğru mu? Kesin emin olabilir misin? Ona inanmak yanıtını nasıl etkiliyor? Ona daha az tutunduğunda ne değişiyor? [O15] Ardından düşünceyi başka yönden ele almayı ve gerçek örnekler bulmayı anlatır. Bu kaynak yöntemi anlatır. Tek başına bu soruların etkili tedavi olduğunun kanıtı değildir. Buradaki kısa çalışmayla araştırmadaki uzun uygulama birbirinden ayrı kalır.","Düşünceyi tersine çevirmek her zaman isteğe bağlı. Belli sayıda örnek bulman gerekmiyor. Örnek uydurma. Sana verilen zararın sorumluluğunu üstüne atan bir yorum, bulman gereken sonuç değildir. Karşı tarafın nedenleri belirsizken de açık bir istek veya sınır gerekli olabilir. Merakla yaklaşmak ihtiyacından vazgeçmek demek değil. Bilmediğin şeyi açık tutarken bildiğin ihtiyacı doğrudan söyleyebilirsin.","Sorgulamayı gündelik, güvenli sıkıntılarla sınırla. NHS rehberi tedavi için profesyonel yardım yollarını anlatır. [O16] ODA bunların yerini almaz. Tehlike, istismar, kendine zarar verme kaygısı ve ciddi belirtilerde korunma ile uygun destek gerekir. Alıştırmayı durdurup pratik bir yanıt seçebilirsin. Bunun için önce bir düşünceyi çözmen veya başka biriyle yeniden görüşmen gerekmez. Güvenli sınır, dinlenme ve yardım isteme seçeneklerin açık kalsın."]}],sourceIds:["optimism-landau-inquiry","optimism-katie-instructions","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-6",courseId:"optimism",locale:"tr",title:"Zor hafta geçti. İşe yarayan neyi sürdüreceksin?",goal:"Aynı aksilikte yaptığın denemelere bak. Yardım eden koşulu ve yapabileceğin sonraki fırsatı seçerek devam et.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hafta hâlâ zordu. İşe yarayan hangi adımı veya desteği bir kez daha denemeye değer buluyorsun?",reason:{id:"optimism-6-reason",label:"Seçtiğin amaca ne yardım etti? Hangi sorun hâlâ bir adım gerektiriyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Yardım eden tek koşulu tekrarlamak","Çözülemeyen sorunu görünür tutmak","Yapabileceğim bir sonraki denemeyi seçmek"]},why:{id:"optimism-6-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı aksiliğe ve attığın adıma bak. Ne yaptın, ne yardım etti, hangi sorun çözülemedi? Zor bir haftada işe yarayan destek de olabilir. İyi hissetmeni şart koşmadan, gördüğün bu bilgilere göre sonraki fırsatı seç. Zorluğu silmen veya bütün haftayı başarılı ilan etmen gerekmiyor. Yardım eden kısmı açıkça belirle.","İlk “üç iyi şey” araştırması, bir hafta boyunca her gece üç olayı ve nedenlerini yazdırdı. Tekrar araştırmasında olumlu plaseboyla da mutluluk artışı görüldü. Bu, yalnızca adı geçen alıştırmanın işe yaradığını söylemeyi zorlaştırır. Burada gerçek bir yararlı olay fark edebilirsin; hiçbiri de olmayabilir. Yeni bir gece rutini eklemeden aynı denemeyi sürdür."],example:{title:"Ece yardım eden koşulu sürdürüyor",text:"Cuma günü Ece’nin raporu hâlâ onay bekliyor. Kaydında işe yarayan bir neden var: rapora bakacak başka birini bulunca belirli bir düzeltme öğrendi. Masasında bu düzeltmeyi yapıp sonraki uygun görüşmeyi ayarlıyor. Haftayı başarılı saymadan yardımı not ediyor. Sonraki denemesinde aynı raporu, daha küçük işi ve koşullarına uyan bir dönüş tarihini koruyor. Onay gelip gelmeyeceği hâlâ belirsiz."}},move:{invitation:"Aynı denemeye dönüp bak. Yardım eden tek koşulu tekrarla ve yapabileceğin sonraki adımı seç.",instructions:["Gerçek yardımı not ederken çözülememiş sorunları da görünür tut.","Sonraki tek denemeyi, destek isteğini veya ara vermeyi seç."],prompts:[],suggestions:{action:["Geri bildirimin gösterdiği düzeltmeyi gerçekten yap","İşe yarayan toparlanma adımımı tekrar dene","İşime yarayan desteği yeniden iste"],minimum:["Taslağın bilinen tek eksiğini gider","Seçtiğim toparlanma adımının bir kısmını tamamla","Belirli bir destek isteyen tek mesaj gönder"],cue:["Taslak üzerinde çalışabileceğim ilk uygun fırsatta","İşime yarayan geri bildirim geldiğinde","Destek istemek için seçtiğim an geldiğinde"],place:["Üzerinde çalıştığım mevcut taslağın başında","Güvenle yardım isteyebildiğim iletişim yolunda"],fallback:["Gerçekte yapacağım toparlanma adımını küçült","Ara ver, yeniden bakmak için tarih seç","Yapabileceğim başka bir destek yolunu kullan"],observation:["Adımı atmama neyin yardım ettiği","Hangi sorunun hâlâ çözülemediği","Sonraki adımın haftama uyup uymadığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Geri bildirimin gösterdiği düzeltmeyi gerçekten yap",minimum:"Taslağın bilinen tek eksiğini gider",minutes:2,cueHint:"Taslak üzerinde çalışabileceğim ilk uygun fırsatta",placeHint:"Üzerinde çalıştığım mevcut taslağın başında",obstacleHint:"İşe yarayan adımı iyileştirmek yerine yeni rutinler ekliyorum.",fallbackHint:"Gerçekte yapacağım toparlanma adımını küçült",observationHint:"Adımı atmama neyin yardım ettiği"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-6-correction-scope-decision",scenario:"Raporu inceleyen kişi Ece’nin raporunda eksik bir varsayım bulmuş. Kalanı yönergeye uyuyor. Beş dakikalık düzeltmeyi yapmak için teslim öncesi yirmi dakika var. Onay hâlâ belirsiz.",question:"Yardım eden geri bildirimi hangi sonraki adımla daha iyi kullanır?",options:[{id:"optimism-6-repeat-helpful-cause",text:"Doğrulanan eksiği düzeltip süre dolmadan göndermek ve onay alacağını varsaymadan gerçekte çıkan sonucu kaydetmek.",feedback:"Bu seçim, onayı belirsiz tutarken belirli geri bildirimi kullanır. Düzeltme kalan zamana sığar ve aynı raporu ilerletir. Değişen kısmı ve gelen yanıtı kaydet. Yanıt yoksa onu da açıkça yaz."},{id:"optimism-6-check-scope",text:"Daha geniş bir sorunu kaçırmamak için düzeltmeden önce raporu inceleyen kişiden kapsamı bir kez daha kontrol etmesini istemek.",feedback:"Kapsam belirsizse bir kontrol daha işe yarayabilir. Burada raporu inceleyen kişi kapsamı zaten doğruladı. Beklemek, yeni bir belirsizliği çözmeden teslim süresini tüketebilir. Önce belirtilen tek düzeltmeyi yap."},{id:"optimism-6-request-extension",text:"Düzeltmeyi yapmadan önce raporun tamamına yeniden bakabilmek için teslim tarihinin kısa bir süre uzatılmasını istemek.",feedback:"Zaman veya güç yetmiyorsa ek süre işi koruyabilir. Burada belirtilen düzeltme süreye sığıyor. Yeni bir düzenleme istemek, bilinen engeli çözmeden başka iş ekler. Daha geniş kontrol bekleyebilir."}],bestOptionId:"optimism-6-repeat-helpful-cause"}},carry:{takeaway:"Yardım eden koşulu ve yapılabilir adımı sürdür. Haftanın zor olduğu gerçeğini değiştirmeye çalışma.",followUp:{questionId:"optimism-6-return",question:"Yardım eden koşulu tekrarlamak sonraki adımına destek oldu mu? Hangi kısım düzeltme, yardım veya bırakma gerektiriyor?",observationPrompt:"Hangi koşul yardım etti? Hangi sorun hâlâ çözülmedi veya yanıt bekliyor?",adjustmentPrompt:"Koşulu tekrarlamak, işi değiştirmek, yardım almak veya bırakmak arasından hangisi uygun?"}},goDeeper:{sections:[{heading:"Araştırmada üç olay ve nedenleri yazılıyordu",paragraphs:["Seligman ve arkadaşlarının ilk çevrim içi araştırmasında katılımcılar, bir hafta boyunca her gece iyi giden üç şeyi ve her birinin nedenini yazdı. [O07] Başlangıçta 577 kişi vardı. Analizde takibi tamamlayan 411 kişi kullanıldı. Çoğu beyaz, eğitimli, çevrim içi gönüllülerdi. Alıştırmalarla erken bir anıyı yazma karşılaştırmasına katılımcılar rastgele atandı. Sonradan çalışmayı sürdürüp sürdürmemeleri ise rastgele belirlenmedi.","İlk deney mutluluk ve depresyon anketlerinde değişim bildirdi. Bu, devam etmenin sonraki faydayı koruduğunu, on dakikanın zorunlu süre olduğunu veya şükranın depresyonu tedavi ettiğini göstermez. Daha sonraki tekrar araştırmasında olumlu plaseboyla da mutluluk iyileşmesi görüldü. Depresyon için bu alıştırmaya özgü bir fayda gösterilmedi. [O08] Ortalamanın değişmesiyle değişimi yalnızca belirli bir alıştırmaya bağlamak, aynı iddia değildir. Araştırmanın sınırlarını birlikte tut.","Uygunsa ilk araştırmadaki bir haftalık çalışmayı ayrıca seçebilirsin. Tek bir iyi veya nötr olay fark etmek ya da zor bir gecede ara vermek, kişiye alan tanıyan bir uyarlamadır. Araştırmada sınanan yöntemin aynısı değildir. Bu kursun sonu ise mevcut toparlanma adımını sürdürmeye yarar. Yeni gece görevleri biriktirmek zorunda değilsin. Ne yaptığınla ne hissettiğini birbirine karıştırmadan sonraki uygun fırsatı belirle."]},{heading:"Gelecek hafta işe yarasa da sonuç belirsiz kalabilir",paragraphs:["Psikolojik dayanıklılık eğitiminin açıklaması, plan yapmadan önce en kötü, en iyi ve en olası ihtimalleri düşünmeyi anlatır. [O14] Bu kısa çalışmanın tek başına etkisini göstermez. Mevcut denemende belirli bir belirsizlik için plan gerekiyorsa kullan. Başka bir zorunlu rutine dönüşmesi gerekmez. Sadece gözlediğin ihtiyaca cevap veren kısmı seç.","Duruma gerçekçi bakmak, hem işe yarayan koşulu hem kalan sorunu görmeyi gerektirir. Rapor onaylanmamışken de raporu inceleyen kişinin yardımı işe yaramış olabilir. Belirli bir soru sormak, zaman ayırmak veya destek almak işe yaramış olabilir. Sonraki fırsata uyuyorsa tekrarla. Şükran hissetmek şart değil. Yardımın önemini yazmak, haftanın zor taraflarını silmez. Yardım eden şeyin kendisini ve henüz çözülmeyen ihtiyacı ayrı ayrı söyleyebilirsin.","Gelecek haftadan önce aynı denemenin kayıtlarını gözden geçir. İşe yarayan küçük adımı, tanıyabileceğin başlama anını ve kullanabileceğin alternatifi koru. Duruma göre destek, dinlenme, sınır veya bırakma seç. Gelecek planları, düşünme çalışması ve sorulara verdiğin yanıtlar, gerçek denemelerden ayrı kalsın. Neyin belirsiz kaldığını ve yanıt gelmediğini de kaydet. Yeni fırsatı, hayal edilen sonuç yerine gerçekte gördüğün koşullara göre belirle."]}],sourceIds:["optimism-three-good-things","optimism-mongrain","optimism-reivich-mrt"]}}],z=[{id:"optimism-1",practice:["Gündelik bir aksilik seç. Elindeki bir imkânı dene, sonra gerçekte ne olduğunu kaydet.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:1,photo:{id:"1527580094867-0e719f119120",alt:"Güneşin doğmasını beklerken sabahın erken saatinde gri kayalardan geçen yürüyüşçü"}},{id:"optimism-2",practice:["Aynı aksiliği kullan. Doğru bir neden belirle, sonra onun gerektirdiği düzeltmeyi yap.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:2,photo:{id:"1509029032154-54ba8b3216d4",alt:"Gözlüklü bir adam düşünceli biçimde pencereden dışarı bakıyor"}},{id:"optimism-3",practice:["Aynı aksilikte inancına kısaca bak. Ardından duruma uygun, adil tek bir yanıtı ver.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:0,photo:{id:"1643148636630-0b0fb138fc74",alt:"Kalemle deftere yazı yazan bir kişi"}},{id:"optimism-4",practice:["Aynı aksilikte ulaşabileceğin tek bilgiyi kontrol et. Sonra onun gösterdiği adımı at.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:1,photo:{id:"1681396059172-7532b1ef8b47",alt:"Yumuşak sabah ışığında masada açık duran günlük"}},{id:"optimism-5",practice:["Güvenli bir durumda, nedenini henüz bilmesen de ihtiyacını veya sınırını açıkça söyle.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:2,photo:{id:"1503541517233-120571491cf3",alt:"Ağaçların arasında park bankında gözleri kapalı oturan bir adam"}},{id:"optimism-6",practice:["Aynı denemeye dönüp bak. Yardım eden tek koşulu tekrarla ve yapabileceğin sonraki adımı seç.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:0,photo:{id:"1750885847789-f5748b585e3a",alt:"Balkondan şehre bakan bir kadın"}}],h={id:"optimism",title:"Tek bir aksilik yüzünden her yol kapandı mı?",subtitle:"6 ders. Aynı aksiliği incele, uygun bir adım at, gerçekte olandan öğren.",description:"Gündelik bir aksiliği yerli yerine koy. Canını acıtan gerçekleri gözden kaçırma, belirsiz yorumlara bak ve istediğin hayata katkı sağlayan pratik bir yanıt seç.",outcome:"Bir aksilik, deneyebileceğin bir toparlanma adımı ve gerçekte olana göre sonraki plan.",scope:"Aksilikten sonra vazgeçmeye, kendini suçlamaya veya en kötüsünü beklemeye yatkın yetişkinler için. Martin Seligman’ın öğrenilmiş iyimserliğinden, bilişsel davranışçı terapiden (BDT) ve Byron Katie’nin The Work yönteminden yararlanır. Kişisel gelişim desteğidir. Depresyon, kaygı veya başka bir durumun tedavisi değildir; terapi veya ilacın yerini almaz. Umutsuzluk sürüyorsa veya günlük hayatı sürdürmek zorlaşıyorsa bir doktora ya da ruh sağlığı uzmanına başvur. Daha erken yardım da isteyebilirsin. İntihar düşüncelerinde veya duygusal krizde bulunduğun yerdeki kriz desteğine ulaş. ABD’de 988’i arayabilir veya mesaj gönderebilirsin. Acil tehlikede yerel acil yardım hizmetlerini kullan.",photo:{id:"1465188162913-8fb5709d6d57",alt:"Akşamın altın rengi ışığında tepede yürüyen bir kadın"},lang:"tr",lessons:s.map((a,t)=>{const i=z[t],e=a.judgment.primary,l=e.options.find(r=>r.id===e.bestOptionId),n=e.options.filter(r=>r.id!==e.bestOptionId).map(r=>r.text);return n.splice(i.correct,0,l.text),{...i,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:n,feedback:l.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}})},L=Object.freeze(Object.defineProperty({__proto__:null,COURSE:h,LESSONS_V2:s,SOURCES:p},Symbol.toStringTag,{value:"Module"})),v=[{id:"stoic-epictetus-iep",title:"S09 · Seddon · Epiktetos · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/epictetu/",type:"guidance",finding:"Epiktetos, bize bağlı olanla olmayanı ayırarak çabamızı yargılarımıza, amaçlarımıza ve davranışlarımıza yöneltmemizi önerir. Bu, felsefi bir yol gösterme biçimidir.",limitation:"Tarih ve felsefe kaynağı. Düşünce ve davranışların bütünüyle irademizde olduğuna dair psikolojik kanıt değil. Engellilik, hastalık, baskı ve eldeki imkânlar yapabileceklerini sınırlar."},{id:"stoic-seneca-iep",title:"S10 · Wagoner · Seneca · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/seneca/",type:"guidance",finding:"Seneca öfkeyi anlatırken kendiliğinden gelen ilk tepkiyle sonradan o tepkiyi benimsemeyi birbirinden ayırır.",limitation:"Tarihsel felsefe; duyguları bütünüyle açıklayan, doğrulanmış bir model değil. Panik veya travma belirtilerini seçerek yok edebileceğin ya da bunların ahlaki bir kusur olduğu anlamına gelmez."},{id:"stoic-week-handbook",title:"S08 · Stoicism Today · Stoic Week 2016 el kitabı",url:"https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf",type:"technique",finding:"Kontrol ayrımını, zorluklara hazırlanmayı, daha geniş açıdan bakmayı ve yatağa girmeden önce beş ile on dakikalık adil akşam değerlendirmesini anlatır.",limitation:"Uygulayıcı el kitabı. Tek tek ritüellerin veya en iyi sürelerin deneyi değil. Kontrolü ayırma, olumsuz canlandırma, uzaydan dünyaya bakma ve akşam değerlendirmesi için bağımsız etki doğrulanmadı."},{id:"stoic-planning",title:"S03 · Gollwitzer ve Sheeran · 2006 · Şu olursa bunu yaparım planları",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 katılımcılı 94 bağımsız sınamada belirli bir durumu belirli davranışla eşleştiren planlar hedefe ulaşmada ortalama fayda gösterdi: d = 0,65 [0,60, 0,70].",limitation:"Hedefler, tasarımlar ve karşılaştırmalar farklıydı. Yalnızca güncel, önceden kaydedilmiş rastgele atamalı deneyler yoktu. Bu sayı başarı yüzdesi, garanti veya olumsuz canlandırmanın kanıtı değil."},{id:"stoic-mcii",title:"S04 · Wang, Wang ve Gai · 2021 · Zihinsel karşılaştırma ve planlama",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makalede 15.907 katılımcıdan 24 bağımsız tahmin birleştirildi. İstenen sonuç, mevcut engel ve şu olursa bunu yaparım planı, hedefe ulaşmada ortalama g = 0,336 [0,229, 0,443] gösterdi.",limitation:"Çalışmalar arası ciddi farklılık, I² = %59,3, ve değişen kalite tahminin kesinliğini sınırlar. Olumsuz canlandırmayı tek başına sınamaz, her hedefin yapılabilir olduğunu kanıtlamaz veya ODA’nın kısa uyarlamasını doğrulamaz."},{id:"stoic-thought-record",title:"S11 · NHS · Düşünce kaydı · Every Mind Matters",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/thought-record/",type:"guidance",finding:"Yedi soru; durumu, duyguları, düşünceyi, destekleyen kanıtı, karşı kanıtı, gerçekçi alternatifi ve sonraki duyguları ayırır. Tarafsız bir sonuç uygun olabilir.",limitation:"Resmî kişisel destek rehberi. Tek başına etki büyüklüğünü ölçen çalışma değil. Olumlu düşünmeyi veya gerçekten kötü davranılmış olmasını zararsız diye yorumlamayı gerektirmez."},{id:"stoic-cbt",title:"S01 · Hofmann ve diğerleri · 2012 · BDT meta-analizleri derlemesi",url:"https://www.europsy.net/app/uploads/2017/08/Hofmann-2012-The-efficacy-of-CBT-a-review-of-meta-analyses.pdf",type:"research",finding:"Yazarlar 269 meta-analiz bulup bunların temsili 106’sını ele aldı. Bazı kaygı sorunları, öfke ve stres için soruna özgü güçlü tedavi kanıtları anlattı.",limitation:"Tek bir birleşik BDT etkisi veya katılımcı sayısı vermeyen anlatı derlemesi. Tedavi kanıtı Stoacı derse aktarılamaz; kısa bir düşünce kaydının etkisini tek başına göstermez."},{id:"stoic-kross-self-talk",title:"S05 · Kross ve diğerleri · 2014 · Kendinle konuşma biçimi",url:"https://rascl.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Toplam 585 katılımcılı yedi çalışma, kişinin kendini birinci kişi dışında anlatmasını inceledi. 1a çalışmasında 60 saniye düşünmenin ardından katılımcılar daha fazla mesafe aldıklarını bildirdi.",limitation:"Tek araştırma programındaki birbirini destekleyen deneyler. Yedi bağımsız klinik deney değil. Kendi adını kullanmak kanıtlanmış tedavi değil; ODA’nın hafif, güncel durum alıştırması bir uyarlama."},{id:"stoic-kross-distancing",title:"S06 · Murdoch ve diğerleri · 2023 · Mesafeden düşünme meta-analizi",url:"https://onlinelibrary.wiley.com/doi/full/10.1002/smi.3199",type:"research",finding:"17 makalede 2.397 katılımcılı 25 deney, farklı sonuçlar genelinde mütevazı bir birleşik etki buldu: g = 0,19 [0,05, 0,33].",limitation:"Çoğunlukla genç, görünürde sağlıklı yetişkinler. Kalite belirsiz; çalışmalar ciddi ölçüde farklı. Tahmin aralığı sıfırı kapsadı. Nesnel sonuçlarda istatistiksel olarak anlamlı fark bulunmadı; uzaydan dünyaya bakma veya on yıl sonrasını düşünme alıştırmaları tek başına sınanmadı."},{id:"stoic-distancing-sleep",title:"S16 · Riddell ve diğerleri · 2023 · Stresi düşünme ve uyku",url:"https://onlinelibrary.wiley.com/doi/10.1002/smi.3201",type:"research",finding:"Önceden kaydedilmiş deney, mesafeden düşünmenin uykuya faydasını desteklemedi. Uyku kalitesindeki değişim olaya kendi gözünden bakan grubu destekledi; uyku süresinde istatistiksel olarak anlamlı fark bulunmadı.",limitation:"Başlangıçta 318 kişi vardı; 257 kişi analiz edildi. Mesafeden düşünme grubundan 51 kişi birinci kişiyle yazdığı için çıkarıldı. Tablo ve anlatımdaki çelişkili işaretler, iyi oluşun değişim yönü hakkında iddiaya izin vermiyor."},{id:"stoic-training-trial",title:"S13 · Maclellan ve Derakshan · 2021 · Çok kaygılanan kişilerde eğitim",url:"https://link.springer.com/article/10.1007/s10608-020-10183-4",type:"research",finding:"Çok kaygılanan 45 kişi; sekiz oturumluk Stoacı eğitim, birleşik eğitim ve aktif one-back kontrolüne rastgele dağıtıldı. Özet, tekrarlayan düşüncelerde ve kişinin yapabileceğine inancında değişimler bildiriyor.",limitation:"Küçük çalışma; burada yalnızca özet erişilebildi. Kesin etkiler, güven aralıkları, ayrılan kişi sayısı ve kayıt doğrulanmadı. Tek bir ritüeli sınamaz; tanı konmuş kaygı için tedavi etkisi göstermez."},{id:"stoic-training-thesis",title:"S15 · King · 2025 · Modern Stoacılık ve ruh sağlığı tezi",url:"https://pure.royalholloway.ac.uk/en/publications/modern-stoicism-and-mental-health-a-randomised-controlled-trial/",type:"research",finding:"Klinik örneklem dışındaki 119 yetişkin, iki haftalık çevrim içi Stoacı eğitim veya bekleme listesine ayrıldı. Kurum özeti, bütün ölçümleri bulunan kişilerde bazı ruh sağlığı ölçümlerinde olumlu değişimler bildiriyor.",limitation:"Yayımlanmamış tek doktora tezi. Hakemli araştırmaların ortak tedavi sonucu değil. Tamamlayanların sayısı, etkiler, aralıklar ve kayıt doğrulanmadı. Bekleme listesi, tek ritüellerin etkisini veya psikoterapiyle eşdeğerliği göstermez."}],y=[{schemaVersion:2,revision:2,id:"stoic-1",courseId:"stoic",locale:"tr",title:"Yanıtı yine mi kontrol ediyorsun? Yapabileceğin işe dön.",goal:"Sonuç belirsizken seçtiğin hedefe yarayan somut bir iş yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Gelen kutusunu yine yeniledin mi? O dikkatin birazını hedefin için yapabileceğin işe ayır.",reason:{id:"stoic-1-reason",label:"Yanıtı beklerken hangi yararlı işi geri plana attın?",kind:"text",maxLength:160,optional:!0,suggestions:["Hedefimi somut bir işle desteklemek","İçim rahatlasın diye sürekli yenilemeyi bırakmak","İşe yarayan yardım istemek"]},why:{id:"stoic-1-why",label:"Yanıtı beklerken hangi yararlı işi geri plana attın?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sonuç senin için önemli olabilir ama kararı tek başına sen veremezsin. Epiktetos bu ayrımla çabayı itibara veya sonuca değil, davranışa yöneltirdi. Bu bir felsefi öneri. Her düşünceyi ve hareketi bütünüyle seçebildiğinin kanıtı değil. Sağlık, baskı, engellilik ve eldeki imkânlar ne yapabileceğini sınırlayabilir. Bunları yok sayman gerekmiyor.","Kurs boyunca bir hedef ve ona yarayan bir işi deneyeceksin. Yapmayı deneyebileceğin işi, gereken desteği ve başkasının kararını ayır. Sonra sana uygun kısmını yap. İşverenden yanıt gelmese de portföyüne yazdığın cümle oradadır. Sonuçtan bilgi al; önemsemeyi bırakmak zorunda değilsin."],example:{title:"Kerem’in proje cümlesi",text:"Pazartesi öğle molasında Kerem başvuru için gelen kutusunu dört kez yenilediğini fark ediyor. İş ararken yaptığı projeleri somut biçimde göstermek istiyor. Masasında portföyüne bir cümle yazıyor. İyileştirdiği kontrol listesini ve nasıl kullanıldığını anlatıyor. Yazdığı cümleyi kaydediyor. Gelen kutusu hâlâ boş; belirsizlik de sürüyor. Ama yazdığı cümle başvurusuna ekleyebileceği gerçek bir parça."}},move:{invitation:"Sonuç hâlâ belirsizken hedefin için yapabileceğin yararlı bir iş seç.",instructions:["Yapabileceğin işi, gereken desteği ve sonucu ayır. Her şeyi kontrol etmen gerekmiyor.","Sana uygun kısmını yap ve ne yaptığını kaydet."],prompts:[],suggestions:{action:["Projede yaptığım işi anlatan bir cümle yaz","Uygun bir açıklama sorusu gönder","İşe yarayan bir destek iste"],minimum:["Kullanabileceğim bir proje cümlesi yaz","Açık bir soru gönder","Belirli bir konuda destek iste"],cue:["Öğle molasından döndüğümde","Sonraki güvenli fırsatta","Projenin sıradaki işinden önce"],place:["Her zamanki çalışma masamda","Güvenli bir mesajlaşmada","Planımı rahatça yapabildiğim yerde"],minutes:[2,5],fallback:["Cümleyi sesli notla anlat","İşe yarayan daha küçük bir katkı seç","Erişim için yardım iste"],observation:["Yazdığım işe yarar cümle","Gönderdiğim soru ve gelen yanıt","Hangi desteği istediğim"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Projede yaptığım işi anlatan bir cümle yaz",minimum:"Kullanabileceğim bir proje cümlesi yaz",minutes:2,cueHint:"Öğle molasından döndüğümde",placeHint:"Her zamanki çalışma masamda",obstacleHint:"Enerjim veya kullanabildiğim imkânlar sınırlı.",fallbackHint:"Cümleyi sesli notla anlat",observationHint:"Yazdığım işe yarar cümle"},stopRule:"Tehlike varken uygulamayı sürdürme. Yapabileceklerin kısıtlıysa korunma veya destek ara.",accessibleAlternative:"Sesle yazdır, iletişim desteği al, güvenli bir sınır koy veya işe yarayan destek iste."},result:{question:"Sana uygun en küçük adımı attın mı?",observationPrompt:"Ne yazdın veya sordun, hangi karar hâlâ verilmedi?"},judgment:{primary:{id:"stoic-1-decision",scenario:"Kerem’in öğle molasından sonra on dakikası var. Acil yanıt vermesi gerekmiyor. Başvurusunun girişi açık, ama işe alım sorumlusu projede yaptığı işe dair somut bilgi istemiş. Anlatabileceği uygun bir örnek var.",question:"Bu zamanı nasıl kullansın?",options:[{id:"keep-checking",text:"Olası işverene hemen yanıt verebilmek için birkaç dakikada bir gelen kutusunu kontrol etmeye devam etsin.",feedback:"Ulaşılabilir olmak gerekebilir. Burada acil yanıt beklenmiyor ve yazabileceği yararlı bir örnek var. Gelen kutusuna bakacağı saati seçip bu cümleyi yazmaya zaman ayırsın."},{id:"write-evidence",text:"İlgili proje cümlesini şimdi yazsın, sonra kendi seçtiği saatte gelen kutusunu yeniden kontrol etsin.",feedback:"Bu seçim, iş teklifi vaat etmeden yapılabilir bir işe zaman ayırıyor. Cümleyi kaydet, gerekli iletişim yollarını açık tut. Sonradan gelecek yanıtı yeni bilgi olarak değerlendir."},{id:"revise-opening",text:"Projesini daha açık sunmak için elindeki on dakikayı başvurunun giriş paragrafını yeniden yazmaya ayırsın.",feedback:"Giriş anlaşılmıyorsa düzeltmek işe yarar. Burada giriş zaten açık; eksik olan somut proje bilgisi. Onu şimdi yaz. Sonraki geri bildirim bunu gerektirirse girişe yeniden bak."}],bestOptionId:"write-evidence"}},carry:{takeaway:"Sonucu önemseyebilirsin. Senin yapabileceğin işe de zaman ayır ve gerçekten dene.",followUp:{questionId:"stoic-1-return",question:"Hangi yararlı işi yaptın veya talebi ilettin? Destekle ilgili hangi engel sürdü?",observationPrompt:"Yaptığın işi veya talebi belirt; yapamadıysan hangi koşulun eksik kaldığını yaz.",adjustmentPrompt:"Sıradaki denemeye hangi destek veya başlama anı uyuyor?"}},goDeeper:{sections:[{heading:"Çabanı yönelt, yardımın payını da gör",paragraphs:["Epiktetos’u anlatan akademik kaynak, yargıların, amaçların ve davranışların bize bağlı olduğunu; itibar gibi dış sonuçların ise olmadığını söyler [S09]. Epiktetos Hierapolis’te köle olarak doğdu, daha sonra Nikopolis’te ders verdi. Öğrettiklerini Arrian kaydetti. Bu tarihsel bilgiler geleneği açıklar. Bugün kullanılan bir çalışma kâğıdının etkisini göstermez. Ayrım çabanı yönlendirebilir. Ama bir kişinin dikkatini, duygularını veya davranışını her zaman bütünüyle seçebildiğini kanıtlamaz. Felsefi bir öneriyi psikolojik garanti gibi kullanma.","ODA bu ayrımı, tam kontrol ile çaresizlik arasında yardımın payına da yer vererek uyarlar. Neyi deneyebilirsin? Neyi yardımla etkileyebilirsin? Hangi kararı tek başına veremezsin? Stoic Week el kitabı kontrol ayrımını bir uygulama olarak anlatır [S08]. Bu, tek başına etkisi sınanmış bir deney değil, yol gösteren bir metindir. İş yerindeki sorun ortak hareket etmeyi gerektirebilir. Sağlık sorunu değerlendirme ve sağlık desteği isteyebilir. Zarar veren bir karşılaşmada korunmak gerekebilir. Başkası veya koşullar sonucu etkiliyor diye bunların hiçbiri senin tutumundaki bir kusura dönüşmez."]},{heading:"Yaptığın iş görülebilsin",paragraphs:["Gollwitzer ve Sheeran, 8.461 katılımcılı 94 bağımsız planlama sınamasını birleştirdi [S03]. Belirli bir durumu ve yapılacak davranışı söylemek, hedefe ulaşmayı ortalama olarak artırdı. Hedefler, tasarımlar ve karşılaştırmalar farklıydı. Çalışmalar yalnızca güncel, önceden kaydedilmiş rastgele atamalı deneylerden oluşmuyordu. Standartlaştırılmış etki bir başarı yüzdesi değildir. Çalışma kontrolü ayırma alıştırmasını sınamaz, Stoacılığın etkisini kanıtlamaz. Başlama işaretinin yorgunluğu veya imkân eksikliğini aşacağını da garanti etmez. Bunlar planın uygulanıp uygulanamayacağını hâlâ etkiler.","Bu plan biçimini küçük bir işte kullan: öğle molasından sonra masanda, projede yaptığını anlatan işe yarar bir cümle yaz. Dosyayı açmak hazırlıktır. Mülakat cevabının provası da hazırlıktır; böyle adlandır ve kullanacağın sonraki fırsatı seç. Dışarıdan yanıt gelmesi, adımını tamamlamanın şartı değildir. Yine de gelen geri bildirimi kontrolüm dışında diye gözden çıkarma. Sıradaki planın, öğrendiğin bilgiye, gereken desteğe ve seçtiğin hayat yönüne göre değişsin. Yazdığın cümle ile başvurunun sonucu ayrı şeyler olarak kayıtta kalsın."]}],sourceIds:["stoic-epictetus-iep","stoic-week-handbook","stoic-planning"]}},{schemaVersion:2,revision:2,id:"stoic-2",courseId:"stoic",locale:"tr",title:"Yanıt gelmedi. Sebebini gerçekten biliyor musun?",goal:"Bir yorumunu kanıtlarla kontrol et. Sonra durumu netleştir veya kendini koruyacak bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yanıt gecikti. Bildiklerine göre mi davranıyorsun, yoksa nedenini tahmin mi ediyorsun?",reason:{id:"stoic-2-reason",label:"Henüz doğrulamadığın bu yorum sana ne yaptırdı?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek teslim tarihini netleştirmek","Tahmine göre davranmayı bırakmak","Gereken sınırı korumak"]},why:{id:"stoic-2-why",label:"Henüz doğrulamadığın bu yorum sana ne yaptırdı?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Yanıt gelmemesi bir olgu. “Bana saygı duymuyorlar” ise kanıt gerektirebilecek bir yorum. Bu ayrım, olanların seni incitemeyeceği anlamına gelmez. Seneca öfkeyi anlatırken kendiliğinden gelen ilk tepkiyle sonradan o tepkiyi benimsemeyi ayırıyordu. Bu felsefi bir açıklamaydı. Sıkıntıyı bütünüyle açıklayan bilimsel bir model değildi.","Aynı hedefe ve işe dön. Önüne çıkan bir yorumun lehinde ve aleyhinde ne biliyorsun? Gerçekçi başka bir açıklama “Henüz bilmiyorum” olabilir. Sonra teslim tarihini netleştir, yanlış bilgiyi düzelt veya sınır koy. Gerçekten kötü davranılmış olmasını gözden kaçırma. Daha az üzülmen şart değil; burada denediğin şey bildiklerine uygun davranmak."],example:{title:"Kerem geciken yanıtı soruyor",text:"Salı günü Kerem masasında, referans yazısıyla ilgili iki mesajının yanıtsız kaldığını görüyor. İş arkadaşının yaptığı işi yetersiz bulduğunu düşünüyor. Sebebi doğrulayamıyor, ama teslim tarihi belli. Yazının perşembeye yetişip yetişmeyeceğini soran tek bir mesaj gönderiyor. Akşama kadar yanıt gelmiyor. Kerem gönderdiği soruyu ve hâlâ bilmediği sebebi kaydediyor. Yaptığı işi, karşı tarafın henüz vermediği yanıttan ayırıyor."}},move:{invitation:"Bir yorumuna yeniden bak. Sonra bildiklerine dayanan bir adım at.",instructions:["Olanı ve ona verdiğin anlamı ayrı ayrı belirt.","Durumu netleştir, yanlış bilgiyi düzelt veya güvenli bir sınır koy."],prompts:[],suggestions:{action:["Hedefimle ilgili durumu netleştiren soru gönder","Projede kanıta dayalı bir düzeltme yap","Güvenli bir sınır iste"],minimum:["Teslim tarihini soran açık mesaj gönder","Düzeltilmiş bir cümle yaz","Güvenli ve belirli bir sınır söyle"],cue:["Sıradaki yanıtımı vermeden önce","Sonraki proje görüşmemde","Teslim tarihini netleştirmem gerektiğinde"],place:["Güvenli bir mesajlaşmada","Her zamanki çalışma masamda","Rahatça kullanabildiğim özel bir yerde"],minutes:[2,5],fallback:["Netleştirmek için başka güvenli yol seç","Niyeti tahmin etmeden bildiklerimi kullan","Yeniden iletişim kurmadan önce destek al"],observation:["Sorum ve gerçekten gelen yanıt","Düzelttiğim bilgi","İlettiğim sınır"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Hedefimle ilgili durumu netleştiren soru gönder",minimum:"Teslim tarihini soran açık mesaj gönder",minutes:2,cueHint:"Sıradaki yanıtımı vermeden önce",placeHint:"Güvenli bir mesajlaşmada",obstacleHint:"İletişim güvenli değil veya karşı taraf yanıt vermiyor.",fallbackHint:"Netleştirmek için başka güvenli yol seç",observationHint:"Sorum ve gerçekten gelen yanıt"},stopRule:"Gerçek zarar varsa korunmak gerekir. Kötü davranıldığına dair kanıtın yerine rahatlatıcı bir tahmin koyma.",accessibleAlternative:"Alıştığın yolla veya güvenli bir yazılı mesajla yanıt ver. İletişim kurmak yerine destek de alabilirsin."},result:{question:"Bildiklerine dayanan yanıtını kullandın mı?",observationPrompt:"Gerçekte ne söyledin? Karşı taraftan nasıl bir yanıt geldi?"},judgment:{primary:{id:"stoic-2-decision",scenario:"İş arkadaşı, söz verdiği referans yazısı hakkında iki kez yanıt vermedi. Kerem’in yazıya perşembe ihtiyacı var. Gecikmenin sebebiyle ilgili elinde kanıt yok.",question:"Hangi yanıt hem yorumu kontrol eder hem tarihle ilgilenir?",options:[{id:"comfort-guess",text:"İş arkadaşının çok yoğun olduğunu varsaysın ve ilişkiyi germemek için herhangi bir mesaj göndermeden beklesin.",feedback:"Yoğunluk mümkün, ama henüz doğrulanmış bir açıklama değil. Verilen sözler ve yaklaşan tarih, bildiklerine dayanan bir soru gerektiriyor. İş arkadaşının niyeti hâlâ bilinmeyebilir; yine de tarihi sorabilir."},{id:"withdraw-work",text:"Eksik yanıtların etkisini iş arkadaşına göstermek için şimdilik birlikte yaptığı işlerdeki yardımını biraz azaltsın.",feedback:"Sınır koymak gerekebilir. Ama sebebi bilmeden iş birliğini azaltmak yeni bir varsayım ekler. Uygun sınırı seçmeden önce teslim tarihini ve gecikmeye neyin yol açtığını netleştirsin."},{id:"clarify-deadline",text:"Yanıtsız mesajları belirtip perşembenin uygun olup olmadığını veya başka bir yol gerekip gerekmediğini sorsun.",feedback:"Bu seçim, gerçek bir örüntüyü gözden kaçırmadan eksik bilgiyi soruyor. Tarafsız açıklama, zorla olumlu düşünmek değildir. Sessizlik dâhil sonucu kaydet. Sonraki destek veya sınır ihtiyacını buna göre seç."}],bestOptionId:"clarify-deadline"}},carry:{takeaway:"Yorumunu kanıtla kontrol et, gerçekten olanla ilgilen. Rahatlatan bir tahmin de hâlâ tahmindir.",followUp:{questionId:"stoic-2-return",question:"Yeni kanıt yorumunu destekledi mi, değiştirdi mi? Sebep belirsiz mi kaldı, yoksa zarar mı ortaya çıktı?",observationPrompt:"Hangi kanıt değişti? Karşı tarafın niyetini hâlâ bilmiyor musun?",adjustmentPrompt:"Yeniden netleştirmek, planı değiştirmek veya destek almak mı gerekiyor?"}},goDeeper:{sections:[{heading:"İlk tepki başka, yorumu kontrol etmek başka",paragraphs:["Seneca öfkeyi anlatırken istemeden gelen ilk hareketlerle, öfkenin bütünüyle oluşmasında yer alan benimsemeyi ayırır [S10]. Bu tarihsel bir felsefi ayrımdır. Duyguları bütünüyle açıklayan deneysel bir model değildir. Panik, ağrı, travma belirtileri veya kendiliğinden beliren bir düşünce, yanlış seçim yaptığını göstermez. Gerçek olay, içinde bulunduğun koşullar ve yorumların birlikte önem taşıyabilir. Bir yoruma bakmak, işe yarayan bir bakış açısıdır. Birinin neden sıkıntı çektiğinin tek açıklaması değildir. İlk duyguyu bastırmak veya yanlış bulmak zorunda değilsin.","NHS düşünce kaydında yedi soru sunar: durum, duygular, düşünce, destekleyen kanıt, karşı kanıt, gerçekçi alternatif ve sonrasındaki duygular [S11]. Her iki taraftaki kanıt önemlidir. Alternatif yorum rahatlatıcı olmak zorunda değil; tarafsız olabilir. Örnekte “Söz verilen tarih geçti ve sebebini bilmiyorum” hem sorunu hem belirsizliği korur. ODA’nın kısa kontrolü ve sonraki adımı bu rehberi sadeleştirir. Terapi sunmaz veya sonraki duyguların daha iyi olmasını gerektirmez. Sorduğun soruyu ve gerçekte gelen yanıtı ayrı kaydetmen, tahminin değişip değişmediğine bakmanı sağlar."]},{heading:"Tedaviye benzemek, aynı etkiyi vermek değildir",paragraphs:["Hofmann ve çalışma arkadaşları bilişsel davranışçı terapiyi, yani BDT’yi derlerken 269 meta-analiz buldu. Bunların temsili 106’sını ele aldı [S01]. Derleme özellikle bazı kaygı sorunları, öfke ve genel stres için soruna özgü güçlü kanıtlar anlattı. Bütün BDT için tek bir birleşik etki veya katılımcı sayısı vermedi. Bu bulgular araştırılan tedavilere aittir. Tedavideki bir fikre benzeyen her alıştırmaya aktarılamaz. Felsefe dersi okumak klinik BDT almak değildir; benzer bir ayrımı kullanmak da tedavinin tamamını sunmaz.","Düşünce kaydı resmî bir kişisel destek rehberinde anlatılır [S11]. Fakat o kaynak kaydın tek başına klinik etki büyüklüğünü belirlemez. Kanıtı yorumdan ayırmak ve uygun yanıtı seçmek için kullanabilirsin. Geciken her mesajı düşünce hatası sayma, istismarı zararsız diye yeniden yorumlama. Sıkıntı ağırsa, sürüyorsa veya günlük işlerini etkiliyorsa uzman desteği uygun adım olabilir. Kaydında değişmeyen öfke, durumu netleştiren bir soru veya kendini koruyan bir seçim yer alabilir. Bunların hiçbirini dersin başarısızlığı gibi değerlendirmek zorunda değilsin."]}],sourceIds:["stoic-seneca-iep","stoic-thought-record","stoic-cbt"]}},{schemaVersion:2,revision:2,id:"stoic-3",courseId:"stoic",locale:"tr",title:"İşin yine bölündü. Sonra ne yapacaksın?",goal:"Bir engelle karşılaştığında ne yapabileceğini seç. Aynı yararlı işi yapmanı destekleyecek bir yol olsun.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Planın her şey yolundayken işliyor. Alıştığın kesinti geldiğinde ne yapacaksın?",reason:{id:"stoic-3-reason",label:"Bu kez hangi gerçek engel için bir yol gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Her zamanki kesintiden sonra işe dönmek","Kısa çalışma zamanını korumak","Erişim için yardım istemek"]},why:{id:"stoic-3-why",label:"Bu kez hangi gerçek engel için bir yol gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ters gidecek şeyleri hayal etmekle ne yapacağını planlamak farklıdır. Planlama araştırmaları belirli bir engeli veya fırsatı yapılabilir bir işle eşleştirir. Canlı olumsuz sahneler hayal etmenin seni dayanıklı kıldığını göstermez. Burada işe yarayacak şey daha kötü bir sahne değil, gerektiğinde kullanabileceğin bir yoldur.","Aynı hedefi ve işi koru. Kaydından gündelik, gerçekçi bir engel seç. “Şu olursa bunu yaparım” diye planla, gerekirse kullan. Hayalinde canlandırmak isteğe bağlı. Felaketi veya travmayı yeniden yaşama. Engel hiç çıkmazsa bu yanıt için “Fırsat olmadı” seç. O sırada normal işini yapmayı denediysen onu ayrıca kaydet; yedek yolu kullanmış sayma."],example:{title:"Kerem aramadan sonra dönüyor",text:"Çarşamba portföyü üzerinde çalışacağı öğle molasından önce Kerem, sık gelen arama için plan yapıyor. Arama bitince işe yarar bir proje cümlesiyle başlayacak. Masasındayken arama geliyor. Bitince dönüyor, cümleyi sesle yazdırıp kaydediyor. O öğleden sonra daha fazlasını yapamıyor. Yine de o gün gerçekten kullandığı yolu kaydediyor: aramayı cevapladı, sonra cümlesine döndü. Yalnızca hazırladığı planı yapmış saymıyor."}},move:{invitation:"Aynı işte karşılaştığın engel için kullanabileceğin bir yol hazırla.",instructions:["Gözünde canlı sahneler kurmadan olası bir engeli belirt.","Gerekirse seçtiğin yolu kullan; sonra gerçekte ne olduğunu kaydet."],prompts:[],suggestions:{action:["Kesinti olursa seçtiğim yolla işe dön","Proje için uygulanabilir bir sınır iste","Gerekirse erişim desteğimi kullan"],minimum:["Kullanabileceğim bir proje cümlesi yaz","Belirli bir sınır talebi ilet","Belirli bir erişim talebi ilet"],cue:["Her zamanki kesinti bittiğinde","Koruduğum çalışma zamanından önce","Erişim engeli ortaya çıktığında"],place:["Her zamanki çalışma masamda","Güvenli bir mesajlaşmada","Planımı rahatça yapabildiğim yerde"],minutes:[2,5],fallback:["İşe yarayan cümleyi sesle yazdır","Sonraki uygun çalışma fırsatını seç","Güvendiğim birinden yardım iste"],observation:["Kesinti oldu mu, işe döndüm mü","Seçtiğim yolu kullanıp kullanmadığım","Yazdığım işe yarar cümle"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Kesinti olursa seçtiğim yolla işe dön",minimum:"Kullanabileceğim bir proje cümlesi yaz",minutes:2,cueHint:"Her zamanki kesinti bittiğinde",placeHint:"Her zamanki çalışma masamda",obstacleHint:"Seçtiğim yol, bende olmayan zaman veya erişim gerektiriyor.",fallbackHint:"İşe yarayan cümleyi sesle yazdır",observationHint:"Kesinti oldu mu, işe döndüm mü"},stopRule:"İstersen gözlerini açık tut. Panik, kendinden veya çevrenden kopma hissi ya da istemsiz anılar gelirse dur veya atla.",accessibleAlternative:"Canlandırmadan planla. Daha küçük bir iş, işe yarayan destek veya güvenli bir ara seç."},result:{question:"Gerektiğinde seçtiğin yolu gerçekten kullandın mı?",observationPrompt:"Beklediğin engel ortaya çıktı mı? O anda gerçekte ne yaptın?"},judgment:{primary:{id:"stoic-3-decision",scenario:"Kerem’in öğle portföy çalışması, cevaplaması gereken kısa bir aramayla sık bölünüyor. Öncesindeki zamanı bakım sorumluluğu dolduruyor. Arama sonrasında genellikle iki dakika kalıyor. Proje cümlesi bu akşam lazım.",question:"Bu öngörülebilir engele hangi yol uyuyor?",options:[{id:"restart-small",text:"Cevaplaması gereken aramayı alsın, bittikten sonra kalan zamanda işe yarar bir proje cümlesi yazsın.",feedback:"Bu seçim gerekli aramayı ve kalan zamanı hesaba katıyor. Seçtiği yol yapılabilir ve kaydedilebilir. Engel çıktı mı, sonrasında gerçekten işe döndü mü, bunu ayrı ayrı kaydetsin."},{id:"same-minimum-tomorrow",text:"Aramadan sonra öğle molasını boş bıraksın; aynı cümleyi yazmak için yarınki iki dakikalık zamanı kullansın.",feedback:"Zaman veya güç yetmiyorsa aynı küçük işi başka zamana almak dinlenmeyi koruyabilir. Burada iki dakika var ve cümle bu akşam lazım. Şimdi dene; gücün değişirse uyarla."},{id:"move-before-lunch",text:"Portföy çalışmasını öğle molasının öncesine alsın ve gerekli aramayı da o sırada cevaplayacak biçimde ayarlasın.",feedback:"Öncesi boş olsaydı zamanı değiştirmek kesintiyi önleyebilirdi. Ama orada bakım sorumluluğu var. Gerekli aramayı cevapla, sonra öğle molasında kalan zamanı işe yarar bir cümle için dene."}],bestOptionId:"restart-small"}},carry:{takeaway:"Gerektiğinde kullanabileceğin bir yol hazırla. Felaket sahnesini tekrar tekrar oynatman gerekmiyor.",followUp:{questionId:"stoic-3-return",question:"Beklediğin engel çıktı mı? Seçtiğin yolu o koşullarda kullanabildin mi?",observationPrompt:"Engeli, işe dönmek için kalan zamanı ve kullandığın yolu belirt. O yolu denemediysen bunu da yaz.",adjustmentPrompt:"Aynı yolu korumak, küçültmek veya ortamı değiştirmek mi gerekiyor?"}},goDeeper:{sections:[{heading:"Eski zorluk alıştırması, güncel planlama",paragraphs:["Stoic Week el kitabı zorluklar üzerine düşünmeyi bir uygulama olarak anlatır [S08]. Bu uygulayıcı rehberi, olumsuz canlandırmanın tek başına etkisini göstermez. Verdiği açıklama kanıtlanmış bir mekanizma gibi sunulamaz. Kendi başına maruz bırakma tedavisi yapma izni de değildir. ODA bunun yerine gündelik, hafif bir engel; isteğe bağlı canlandırma ve yapılabilir bir yol sunar. Bunlar uyarlamadır. Seni üzen bir anıya dönmeden, yalnızca sözcüklerle plan yapabilirsin. Engelini açıkça belirtmek için sahneyi gözünde canlandırman veya onun ne kadar kötü olabileceğini büyütmen gerekmiyor.","“Şu olursa bunu yaparım” planları, belirli bir durumu yapmak istediğin davranışla eşleştirir [S03]. Bu planları tek başına inceleyen araştırmalar da vardır. 2006 derlemesi 8.461 katılımcılı 94 bağımsız sınamayı içerdi ve farklı koşullarda hedefe ulaşmada ortalama faydalar buldu. Plan yazmanın yorgunluğu, engelliliği veya eksik imkânları aşacağını göstermedi. Seçtiğin yol daha küçük yararlı bir iş, sınır veya destek olabilir. Engel tehlikeyse nasıl dayanacağını değil, güvenliğini ele al. Canlandırma panik, dissosiyasyon yani kendinden veya çevrenden kopma hissi, ya da istemsiz anılar getirirse dur. Canlandırmasız plan seçeneği hâlâ açık."]},{heading:"Her engel senin içinde değildir",paragraphs:["Wang ve çalışma arkadaşları zihinsel karşılaştırmayla “şu olursa bunu yaparım” planlarını birleştiren yöntemi derledi [S04]. Sıra; yapılabilir istek, istenen sonuç, mevcut engel ve o durumda yapılacak davranıştır. 21 makalede 15.907 katılımcılı 24 bağımsız tahminde, hedefe ulaşma ortalama olarak mütevazı biçimde arttı: g = 0,336. Çalışmalar ve sunum biçimleri farklıydı. Çalışmalar arası ciddi farklılık ve değişen kalite vardı. Bulgular iki dakikanın en iyi süre olduğunu, olumsuz sahnenin tek başına etkisini veya bu ODA biçimini doğrulamıyor. Sonucu farklı bir alıştırmaya taşımak doğru olmaz.","Gerekli arama, olmayan ulaşım, bakım sorumluluğu veya kullanamadığın araç gerçek bir koşuldur. Yalnızca düşünce biçiminle ilgili bir sorun değildir. Doğru adlandır. Yardım isteyebilir, fırsatı değiştirebilir veya uygun olmayan planı bırakabilirsin. Birkaç yeni ritüel eklemek yerine tek bir koşulu sına. Hazırlığı ve kullanımı ayır: işe dönme planını yazmak geri döndüğünü göstermez. Kesinti çıkmazsa yedek yolu sınamamış olursun. Bu belirsizliği koru; o gün yaptığın normal işi de kendi koşullarıyla kaydet. Böylece sonraki plan, hayal ettiğin bir başarıya değil, gerçekte ne yaptığına dayanır."]}],sourceIds:["stoic-week-handbook","stoic-planning","stoic-mcii"]}},{schemaVersion:2,revision:2,id:"stoic-4",courseId:"stoic",locale:"tr",title:"Sert cevabın hazır. Peki işine yarayacak mı?",goal:"İstersen kendi adınla düşün. Sonra hedefin için bildiklerine dayanan bir yanıt kullan.",minutes:{learning:6,rehearsal:1,suggestedAction:2,review:2},direction:{hook:"Vereceğin sert yanıt hazır. On saniye geçtikten sonra hedefin için hangi yanıt işe yarayacak?",reason:{id:"stoic-4-reason",label:"Gerçeğe dayanan bir yanıt neyi korur veya ilerletir?",kind:"text",maxLength:160,optional:!0,suggestions:["İşe yarayan iş birliğini korumak","Yanlış bilgiyi düzeltmek","Açık bir sınırı korumak"]},why:{id:"stoic-4-why",label:"Gerçeğe dayanan bir yanıt neyi korur veya ilerletir?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kısa süre düşünürken kendi adını kullanmak, duruma biraz mesafeden bakmanı sağlayabilir. Deneyler bunu inceledi; daha geniş kanıtlarda ise etkiler mütevazı ve değişken. Sakinleşme garantisi yok. Uzaydan dünyaya bakmak veya on yıl sonrasını düşünmek başka alıştırmalar. Buradaki kaynaklar onların belirli bir faydasını göstermiyor.","Gergin bir an hedefinin önüne geçtiğinde bu aracı deneyebilirsin. İsteğe bağlı 60 saniyelik hazırlık: “Kerem, hangi bilgi yanlış? Hangi talep işe yarar?” Kendi adını koy veya atla. Ardından bildiklerine dayanan bir cümle, talep veya sınır kullan. Mesafe almak, zararı silmek değildir. Öfken sürse de kullandığın yanıtı kaydet; düşündüğünü değil, söylediğini belirt."],example:{title:"Kerem olanı netleştiriyor",text:"Perşembe günü güvenli bir proje görüşmesinde Kerem, kontrol listesinin gecikmeye yol açtığını duyuyor. Sert yanıt vermek istiyor. Kendi adını kullanarak işin ilerlemesine neyin yardım edeceğini soruyor. Sonra gerçek devir tarihini söyleyip hangi adımın değişmesi gerektiğini soruyor. İş arkadaşı hâlâ kızgın. Kerem anlaşmazlığı çözdüğünü iddia etmiyor; o gün gerçekten söylediği cümleyi ve ilettiği talebi kaydediyor."}},move:{invitation:"İşe yarıyorsa biraz mesafe al. Sonra bildiklerine dayanan bir iş yap.",instructions:["İstersen kendi adınla 60 saniye düşün. Bu hazırlıktır.","Gerçeğe dayanan bir cümle, talep veya güvenli bir sınır kullan."],prompts:[],suggestions:{action:["Bir yanlış bilgiyi düzelt ve talep ilet","Proje için açık bir sınır söyle","Bildiklerime dayanan bir açıklama sorusu sor"],minimum:["Gerçeğe dayanan bir cümle kullan","Güvenli ve belirli bir sınır söyle","Açık bir soru gönder"],cue:["Sıradaki gergin yanıtımdan önce","Yanlış suçlama tekrarlandığında","Sonraki güvenli proje görüşmemde"],place:["Her zamanki çalışma masamda","Güvenli bir mesajlaşmada","Güvenli görüşme yerinde"],minutes:[2,5],fallback:["Güvenli yazılı yanıtta olanı belirt","İletişime ara ver ve destek al","Başka güvenli bir fırsat seç"],observation:["Gerçekte kullandığım cümle","Talebim ve gerçekten gelen yanıt","Sınırı korumak için hâlâ destek gerekiyor mu"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Bir yanlış bilgiyi düzelt ve talep ilet",minimum:"Gerçeğe dayanan bir cümle kullan",minutes:2,cueHint:"Sıradaki gergin yanıtımdan önce",placeHint:"Her zamanki çalışma masamda",obstacleHint:"Karşılaşma güvenli değil veya bu ara sıkıntımı artırıyor.",fallbackHint:"Güvenli yazılı yanıtta olanı belirt",observationHint:"Gerçekte kullandığım cümle"},stopRule:"Gündelik bir durum seç. Panik, kendinden veya çevrenden kopma hissi ya da istemsiz anılar gelirse dur veya atla.",accessibleAlternative:"Gözlerini açık tutabilir, düşünme adımını atlayabilir, yanıtını yardımla verebilir veya destek alabilirsin."},result:{question:"Seçtiğin, gerçeğe dayanan yanıtı kullandın mı?",observationPrompt:"Ne söyledin veya hangi sınırı koydun? Sonra ne oldu?"},judgment:{primary:{id:"stoic-4-decision",scenario:"Güvenli bir görüşmede Kerem yine haksız yere suçlanıyor. Yanlış tarih, sıradaki iş devrini geciktiriyor; Kerem gerçek tarihi biliyor. Kısa bir aradan sonra işi ilerletmek ve bilgiyi düzeltmek istiyor.",question:"Hangi yanıt mesafe alırken sorundan kaçınmaz?",options:[{id:"let-pass",text:"Ekip bu anlaşmazlık yerine işi yetiştirmeye odaklanabilsin diye suçlamayı şu an yanıtsız bırakıp görüşmeyi sürdürsün.",feedback:"İşi ilerletmek önemli. Ama sessiz kalmak, iş için gerekli yanlış bilgiyi düzeltmeden bırakır. Devir tarihini söylesin, sıradaki adım için talep iletsin. Gerekirse sınır da koyabilir."},{id:"facts-request",text:"İşin devir tarihini söylesin, neyin değişmesi gerektiğini sorsun; suçlama sürerse buna açık bir sınır koysun.",feedback:"Bu seçim, kısa düşünme adımından sonra yararlı bir işe geçiyor. Doğru bilgiyi söylemek ve talep iletmek, sakinlik şartı koymadan işi korur. Örüntü sürerse sınır koyma seçeneği de açık kalır."},{id:"separate-follow-up",text:"Tekrarlayan suçlama için ayrı bir görüşme istesin, ama şu anki konuşmayı yanlış tarihi düzeltmeden sürdürsün.",feedback:"Ayrı görüşme tekrarlayan örüntüyü ele alabilir. Burada yanlış tarih şu anki işi de etkiliyor. Kısaca şimdi düzelt, daha geniş konuşma gerekiyorsa sonra ayrıca zaman ayarla."}],bestOptionId:"facts-request"}},carry:{takeaway:"Verdiğin kısa ara, işe yarayan bir yanıt seçmene yardım ettiğinde anlam kazanır.",followUp:{questionId:"stoic-4-return",question:"Kendi adınla düşünmek yardım etti mi, önüne mi geçti, yoksa gereksiz mi geldi?",observationPrompt:"Hangi aracı kullandın veya atladın? Ardından gerçeğe dayanan hangi yanıtı verdin?",adjustmentPrompt:"Aracı korumak, bırakmak veya desteği güçlendirmek mi gerekiyor?"}},goDeeper:{sections:[{heading:"Kendi adınla düşünme deneyinde ne yapıldı?",paragraphs:["Kross ve çalışma arkadaşları, 585 katılımcılı yedi çalışma bildirdi [S05]. 1a çalışmasındaki 56 üniversite öğrencisi, yakın zamanda yaşadıkları üzücü bir olayın nedenini 60 saniye düşündü. Birinci kişi yerine kendi adlarını ve birinci kişi dışındaki zamirleri kullandılar. Katılımcılar daha fazla mesafe aldıklarını bildirdi. Sonraki deneyler stresli sosyal görevleri ve performansı inceledi. Bunlar tek araştırma programında birbirini destekleyen deneylerdir. Yedi bağımsız klinik rastgele atamalı deney veya kendi adını kullanmanın kaygıyı tedavi ettiğinin kanıtı değildir. Bulguyu araştırılan düşünme biçimiyle sınırlı tutmak gerekir.","Bu ders, olayı hafif ve güncel bir durumla değiştirip sonrasına gerçeğe dayanan bir adım ekliyor. Bu ODA uyarlaması, özgün protokol değil. Acı veren bir anıyı bulmak, gözlerini kapatmak veya kendini uzaydan görmek zorunda değilsin. Cümle tuhaf geliyorsa ya da seni sarsıyorsa atla. İşi ilerletmek için ne gerektiğini doğrudan sorabilir, güvenli bir yazılı yanıt kullanabilir veya destek arayabilirsin. O anda yanıt vermek ayrı bir iştir. Düşünmek veya taslak yazmak tek başına hazırlık olarak kalır; mesajı kullandığın anı ayrıca kaydet."]},{heading:"Mütevazı etkiler, uyku vaadi yok",paragraphs:["Murdoch ve çalışma arkadaşları 17 makalede 2.397 yetişkinle yapılan 25 deneyi birleştirdi [S06]. Mesafeden düşünmenin genel etkisi mütevazıydı: g = 0,19, %95 güven aralığı 0,05 ile 0,33. Kanıt kalitesi belirsizdi. Katılımcılar çoğunlukla genç ve görünürde sağlıklıydı; sonuçlar ciddi ölçüde farklıydı. Tahmin aralığı sıfırı kapsıyordu. Dört deneyde nesnel sonuçlarda istatistiksel olarak anlamlı fark bulunmadı. Bunlar daha ağır sıkıntı yaşayanlarda üstün fayda veya uzaydan dünyaya bakma ya da on yıl sonrasını düşünme alıştırmalarının belirli etkisini göstermez. Birleşik ortalama, herkesin aynı sonucu alacağını söylemez.","Önceden kaydedilmiş bir düşünme çalışması, mesafe almayı uykuya yönelik bir müdahale olarak desteklemedi [S16]. Uyku kalitesindeki değişim olaya kendi gözünden bakan grubu destekledi. Uyku süresinde istatistiksel olarak anlamlı fark bulunmadı. Bir gruptan daha çok katılımcının çıkarılması yorumu zorlaştırdı. İyi oluş tablosuyla anlatımdaki işaretler çeliştiği için iyi oluşun hangi yönde değiştiği söylenemez. Bu aracı daha iyi uyku veya güvenilir rahatlama için değil, istersen bakış açını değiştirmek için seç. Konunun ciddiyetini koru. Gerçeğe dayanan bir adım atmana yardım edip etmediğine bak."]}],sourceIds:["stoic-kross-self-talk","stoic-kross-distancing","stoic-distancing-sleep"]}},{schemaVersion:2,revision:2,id:"stoic-5",courseId:"stoic",locale:"tr",title:"Kötü geçen bir deneme bütün karakterini anlatmaz.",goal:"Son denemene adilce bak. Seçtiğin somut düzeltmeyi sıradaki fırsatta kullan.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Ters giden şeyleri hâlâ zihninde başa mı sarıyorsun? Sıradaki denemede kullanabileceğin tek bir değişiklik bul.",reason:{id:"stoic-5-reason",label:"Tekrar düşünüp durmak yerine hangi somut koşulu değiştirmek gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek denemeden öğrenmek","İşe yarayan bir düzeltme yapmak","Bütün karakterimi yargılamayı bırakmak"]},why:{id:"stoic-5-why",label:"Tekrar düşünüp durmak yerine hangi somut koşulu değiştirmek gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Stoacı el kitabının akşam değerlendirmesi, neyin ters gittiğini, neyin iyi gittiğini ve neyin değişebileceğini sorar. Bu anlatılmış bir yöntemdir. Bağımsız biçimde kanıtlanmış tedavi veya uyku yardımı değildir. Somut olana bak. “Kararlaştırdığımız tarihi kaçırdım” düzeltilecek bir şey verir. “Ben işe yaramam” ise sonraki adımı göstermez.","Aynı denemenin son kaydını kullan. Amacına yarayan bir kısmı koru, yaramayan tek bir koşulu değiştir. Sonra bu düzeltmeyi sıradaki işte kullan. Değerlendirme öğrenme veya hazırlıktır; sonraki işi yaptığın anlamına gelmez. Ertesi gün dönüşün yeterliyse ayrı bir gece ritüeli ekleme. Bu kontrol, gerçekte ne yapacağına yol göstersin."],example:{title:"Kerem değerlendirmeyi kullanıyor",text:"Cuma öğle molasında Kerem masasında, perşembe görüşmesini yeniden değerlendiriyor. Tarihi düzeltti ama dayanak olan notu eklemedi. Tarihi düzeltmesini olumlu bir adım sayıyor. Tek bir değişiklik seçiyor: sonraki mesajına bunu destekleyen cümleyi eklemek. O öğleden sonra mesajı gönderiyor. Anlaşmazlık sürüyor. Kaydında olayı değerlendirmekle düzeltilmiş mesajı gerçekten göndermek ayrı duruyor. İlkini bitirmesi, ikincisini de yaptığı anlamına gelmiyor."}},move:{invitation:"Son kaydına bak. Bir düzeltme seç ve dene.",instructions:["İşe yarayan bir kısmı ve uymayan somut bir koşulu belirt.","Seçtiğin düzeltmeyi sıradaki işte kullan."],prompts:[],suggestions:{action:["Değerlendirme sonunda seçtiğim proje düzeltmesini uygula","Kaydıma uygun bir telafi yap","Yararlı işimi yeni başlama anında yap"],minimum:["Düzeltilmiş bir proje cümlesi gönder","Belirli bir telafi talebi ilet","Kullanabileceğim bir proje cümlesi yaz"],cue:["Sonraki proje mesajımda","Sonraki güvenli telafi fırsatında","Seçtiğim yeni başlama anında"],place:["Güvenli bir mesajlaşmada","Her zamanki çalışma masamda","Planımı rahatça yapabildiğim yerde"],minutes:[2,5],fallback:["Yanlış bilgiyi daha kısa düzelt","Başka güvenli bir fırsat seç","Başa sarmak yerine destek al"],observation:["Gerçekten uyguladığım düzeltme","Bu değişiklikle ne yapabildiğim","Talebim ve gerçekten gelen yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Değerlendirme sonunda seçtiğim proje düzeltmesini uygula",minimum:"Düzeltilmiş bir proje cümlesi gönder",minutes:2,cueHint:"Sonraki proje mesajımda",placeHint:"Güvenli bir mesajlaşmada",obstacleHint:"Değerlendirme tekrara dönüyor veya düzeltme güvenli değil.",fallbackHint:"Yanlış bilgiyi daha kısa düzelt",observationHint:"Gerçekten uyguladığım düzeltme"},stopRule:"Aynı düşünceleri tekrar tekrar aklına getiren veya uykunu bozan değerlendirmeyi bırak, kısalt ya da başka zamana al. Güvenliğini koru.",accessibleAlternative:"Kısaca konuşarak veya yardımla değerlendir. Yeni ritüel yerine kayıtlı dönüşünü ya da desteği kullan."},result:{question:"Seçtiğin somut düzeltmeyi sıradaki işinde kullandın mı?",observationPrompt:"Gerçekte yaptığın işte hangi kısmı değiştirdin?"},judgment:{primary:{id:"stoic-5-decision",scenario:"Bakım sorumluluğu geç bittiğinde Kerem’in akşam çalışma zamanı iki kez aksadı. Hâlâ projesini somut biçimde anlatmak istiyor. Öğle molasında masasında kullanabileceği güvenli iki dakika var.",question:"Değerlendirmeyi ne işe yarar hâle getirir?",options:[{id:"same-plan",text:"Bakım işinin geç bitmesini kaydetsin; daha düzenli olabilmek için aynı akşam zamanını yeniden denesin.",feedback:"Kayıt dürüst, ama aynı koşul tekrar tekrar işlemedi. Hedefi koru. Aynı zamanın yeniden işlemesini beklemek yerine öğle molasında yapılabilen en küçük işi sına; ne olduğuna bak."},{id:"make-up",text:"Kaçırdığı zamanı kaydetsin ve eksik işi telafi etmek için hafta sonuna daha uzun bir çalışma koysun.",feedback:"Daha uzun çalışma yapılabiliyorsa yararlı olabilir. Ama tekrarlayan başlama anı sorununu sınamaz. Telafi yükü eklemeden önce, mevcut kısa zamanı kullan. Sonraki planını gerçekten olanlara göre değiştir."},{id:"cue-change",text:"Üstlendiği bakım sorumluluğunu hesaba katsın ve tek proje cümlesini elindeki öğle molası zamanına taşısın.",feedback:"Bu seçim gerçek kısıtı adlandırıyor, yapılanı koruyor ve tek koşulu değiştiriyor. Değerlendirme sıradaki denemeden ayrı. Öğle molasında işin gerçekten yapılıp yapılmadığını ayrıca kaydet; planı uygulama sayma."}],bestOptionId:"cue-change"}},carry:{takeaway:"Denemene adilce bak, tek bir koşulu değiştir. Sonra bu değişikliği sıradaki gerçek işte dene.",followUp:{questionId:"stoic-5-return",question:"Değiştirdiğin koşulu sınadın mı? Bu değişiklikle ne yapabildin?",observationPrompt:"Düzeltmeyi ve yaptığın işi belirt; koşul sınanmadıysa bunu da açıkça söyle.",adjustmentPrompt:"Düzeltmeyi korumak, başlama anını değiştirmek veya destek almak mı gerekiyor?"}},goDeeper:{sections:[{heading:"Değerlendirme yol gösterir, hüküm vermez",paragraphs:["Stoic Week el kitabı, yatağa girmeden önce beş ile on dakikalık akşam değerlendirmesini anlatır [S08]. Üç soru neyin ters gittiğini, neyin iyi gittiğini ve neyin farklı olabileceğini sorar. Kendine bir arkadaşını değerlendireceğin kadar adil bakmanı önerir. Bu, anlatılmış bir uygulayıcı yöntemidir. Deneyle belirlenmiş en iyi süre veya değerlendirmenin tek başına sınandığı çalışma değildir. ODA dönüşünü kısaltmak ve değerlendirmeyi erkene almak uyarlamadır. El kitabındaki süre, herkesin her akşam yerine getirmek zorunda olduğu bir şart olarak alınmamalı.","Bütün karakterini yargılamak yerine seçtiğin denemeye bak. Gözlenebilen bir aksama, işe yarayan bir katkı ve somut bir değişiklik belirle. Affetmeyi, özrü veya sıcak bir duyguyu şart koşma. Zarar verdiğinde telafi uygun olabilir; sana zarar verildiğinde korunmak uygun olabilir. Değerlendirme cezaya, tekrara veya uyku sorununa dönüyorsa kısalt, başka zamana al ya da bırak. Burada amaç, uygulayabileceğin bir düzeltme bulmak. Rahatlamayı garanti etmek veya fazladan bir gece görevi eklemek değil. Sonraki kaydın bu düzeltmeyi gerçekten kullanıp kullanmadığını gösterebilir."]},{heading:"Stoacı eğitim araştırmaları var, sınırları da var",paragraphs:["Stoacı eğitim üzerine doğrudan kontrollü araştırmalar henüz başlangıç aşamasında. Maclellan ve Derakshan, çok kaygılanan 45 kişiyi sekiz oturumluk Stoacı eğitim, birleşik eğitim ve aktif kontrol gruplarına rastgele ayırdı [S13]. Özetleri tekrarlayan düşüncelerde ve kişinin yapabileceğine inancında değişimler bildirdi. Hangi parçanın yardımcı olduğunu veya akşam değerlendirmesinin tek başına tanı konmuş kaygıyı tedavi ettiğini göstermez. Küçük bir eğitim çalışması, bu değerlendirmeyi tekrar etmenin belirtilerini güvenilir biçimde değiştireceğini söyleyemez. Eğitim paketini burada kullandığın kısa alıştırmayla aynı saymamak gerekir.","King’in 2025 doktora tezinde klinik örneklem dışındaki 119 yetişkin, iki haftalık çevrim içi Stoacı eğitime veya bekleme listesine ayrıldı [S15]. Kurum özeti, bütün ölçümleri bulunan kişilerde bazı ruh sağlığı ölçümlerinde olumlu değişimler bildirdi. Bekleme listeli, yayımlanmamış tez erken kanıt sağlar; hakemli araştırmaların ortak sonucu değildir. İki çalışma da bu kısa ODA uyarlamasının eğitimi tekrarladığını göstermez. Sana uyuyorsa adil bir düzeltme dene ve olanı kaydet. Sıkıntı sürüyorsa veya günlük işlerini etkiliyorsa uzman desteği al. Kayıt gerçekten değişen koşulu ve denenen işi belirtmeli. Yeni plan tek başına düzeltmeyi sınamaz."]}],sourceIds:["stoic-week-handbook","stoic-training-trial","stoic-training-thesis"]}},{schemaVersion:2,revision:2,id:"stoic-6",courseId:"stoic",locale:"tr",title:"Hafta doluydu. Asıl işine sıra geldi mi?",goal:"Kayıtlarına bak. Gelecek hafta için yararlı bir işi ve ona uygun tek koşulu koru.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yoğun bir haftaydı. Kaydettiğin hangi iş hedefin için işe yaradı?",reason:{id:"stoic-6-reason",label:"Asıl işine sıra gelsin diye neye daha az zaman ayıracaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["İşe yarayan en küçük işi korumak","İşleyen başlama anını kullanmak","Yaramayan ek ritüelleri bırakmak"]},why:{id:"stoic-6-why",label:"Asıl işine sıra gelsin diye neye daha az zaman ayıracaksın?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kolay bir iş seçmekle hedefe yarayan bir iş seçmek farklıdır. Zihinsel karşılaştırma ve planlama araştırmaları, yapılabilir isteği, sonucunu, gerçek engeli ve belirli bir yanıtı birleştirir. Ortalama faydalar mütevazı ve değişkendir. Yöntem başarı garantisi vermez. Her engeli senin kusuruna da dönüştürmez.","Aynı denemeyi toparla. Fırsatın oluşmadığı günler ve aralar dâhil, gerçekte ne olduğunu anlatan kayıtları oku. Yararlı işi ve başlama anını koru; gerekirse tek bir koşulu değiştir. Sonra sıradaki en küçük işi dene. Yardım etmeyen araçları bırak. Sonuç hâlâ belirsiz olabilir, ama gelen bilgi planını değiştirebilir. Destek almak veya bırakmak hâlâ geçerli seçimlerdir; kursu bitirmek bunları ortadan kaldırmaz."],example:{title:"Kerem işleyeni koruyor",text:"Ertesi hafta pazartesi öğle molasında Kerem kayıtlarına bakıyor. Masadaki kısa zamanda iki kullanılabilir cümle yazmış. Başka bir deneme erişim olmadığı için durmuş. Aynı zamanı koruyor, eksik erişimi istiyor ve yeni bir proje cümlesi yazıyor. Fazladan canlandırmayı bırakıyor. Başvurusu hâlâ beklemede. Ama yeni planını hayal ettiği koşullara değil, kendi denemelerinde gördüğü koşullara göre düzenliyor."}},move:{invitation:"Hedefe yarayan işi koru. Sıradaki uygun fırsatını seç.",instructions:["Kayıtlarına bak; tek bir koşulu korumaya veya değiştirmeye karar ver.","İşe yarayan en küçük işi yap. Diğer araçlar isteğe bağlı kalsın."],prompts:[],suggestions:{action:["Projeyi anlatan yararlı işimi tekrarla","Durumu netleştiren sorumu yeniden kullan","Kaydımın gösterdiği desteği iste"],minimum:["Kullanabileceğim bir proje cümlesi yaz","Açık bir soru gönder","Belirli bir erişim talebi ilet"],cue:["Öğle molasından döndüğümde","Sonraki güvenli proje mesajımda","Sıradaki proje denememden önce"],place:["Her zamanki çalışma masamda","Güvenli bir mesajlaşmada","Planımı rahatça yapabildiğim yerde"],minutes:[2,5],fallback:["Denediğim daha küçük biçimini kullan","Sonraki erişilebilir fırsatı seç","Destek al veya bu uygunsuz planı bırak"],observation:["Hedefime yarayan cümlem","Seçtiğim başlama anının gelip gelmediği","Sınadığım koşulda ne yapabildiğim"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Projeyi anlatan yararlı işimi tekrarla",minimum:"Kullanabileceğim bir proje cümlesi yaz",minutes:2,cueHint:"Öğle molasından döndüğümde",placeHint:"Her zamanki çalışma masamda",obstacleHint:"Önceki küçük iş veya başlama anı artık koşullarıma uymuyor.",fallbackHint:"Denediğim daha küçük biçimini kullan",observationHint:"Hedefime yarayan cümlem"},stopRule:"Sürdürmekten önce güvenliğini ve gereken dinlenmeyi koru. Uygun olmayan planı değiştir, ara ver veya bırak.",accessibleAlternative:"Yapabildiğin bir işi sürdür, yardım al veya yalnızca desteği seç. Kurstaki her aracı kullanman gerekmiyor."},result:{question:"Sıradaki işe yarayan en küçük işi yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Hangi geri bildirim hâlâ önemli?"},judgment:{primary:{id:"stoic-6-decision",scenario:"Kerem, hangi proje örneklerinin işverenin şartlarına uyduğunu kontrol etti. Uygun bir örnekte hâlâ yaptığı işi anlatan cümle eksik. Kayıtları öğle molasında yazmanın işe yaradığını gösteriyor. Bugün on dakikası var.",question:"Hangi iş önceliğine en doğrudan hizmet eder?",options:[{id:"draft-relevant",text:"Denediği öğle molası anında uygun proje cümlesini yazsın; gerekirse kullanabileceği erişilebilir bir yedek yolu olsun.",feedback:"Bu seçim, hedefe yarayan işi ve kayıtların desteklediği koşulu koruyor. Kabul garantisi vermeden görülebilen bir parça oluşturuyor. Denemeyi kaydet; sonradan gelen bilgiyi yeni planında kullan."},{id:"advice-read",text:"On dakika başvuru önerileri okusun; daha fazla öneriyi değerlendirdikten sonra projeyi anlatacak hangi işi yapacağını seçsin.",feedback:"Eksik bilgi varsa öneriler yardımcı olur. Burada gereken örnek ve işleyen başlama anı biliniyor. Daha çok okumak, mevcut zamana sığan yararlı parçayı yazmayı erteliyor. Şimdi o parçayı dene."},{id:"check-relevance-again",text:"Önceki proje cümlelerini yeniden değerlendirsin ve işverenin şartlarına en çok uyan cümleyi bu zamanda seçsin.",feedback:"Şartlar veya uygunluk belirsizse kontrol yararlıdır. Kerem bunlara zaten baktı ve bu örnekte cümle eksik. Mevcut yazma zamanını kullan. Şartlar değişirse tekrar kontrol edebilirsin."}],bestOptionId:"draft-relevant"}},carry:{takeaway:"Yararlı işi ve uygun koşulu koru. Gelen yeni bilgi sıradaki denemeni geliştirsin.",followUp:{questionId:"stoic-6-return",question:"Seçtiğin koşul yardım etti mi, işlemedi mi, sınanmadı mı? Yoksa hâlâ emin değil misin?",observationPrompt:"Hangi koşul oluştu ve gerçekte hangi işi yapmayı denedin?",adjustmentPrompt:"Tekrarla, bir koşulu değiştir, destek al veya bırak: hangisi uygun?"}},goDeeper:{sections:[{heading:"Toparlarken hedefe yarayan kanıta bak",paragraphs:["Epiktetos’un ayrımı, çabayı yönlendiren felsefi bir öneridir [S09]. Yaptığın işin sonuçlarını görmezden gelmeni gerektirmez. Gelen yanıt, işlemeyen erişim yolu veya tekrarlayan anlaşmazlık, sırada neyi deneyeceğini gösterebilir. İşverenin kararını tek başına veremezsin. Yine de uygun geri bildirimden yararlanabilir ve yardım arayabilirsin. Kaydın yaptığın işi ve ilgili sonucu birlikte içersin. İkisinden birini bütün karakterin hakkında hükme dönüştürme. Sonuç istediğin gibi olmadığında da hangi kısmı yaptığını, hangi kısmı değiştirebileceğini ve nerede yardıma ihtiyaç duyduğunu görebilirsin.","“Şu olursa bunu yaparım” planları üzerine araştırmalar, farklı hedeflerde ve ortamlarda tanınabilir bir durumu seçilen davranışla eşleştirmeyi destekler [S03]. Bu biçim, yanıt yapılabilir ve hedefe uygunsa yararlıdır. “Öğle molasından sonra işe yarar bir proje cümlesi yaz” somut iştir. “Öğle molasından sonra işverene onaylat” dışarıdaki sonuçtur. Hazırlık veya öneri okumak uygun olabilir, ama doğru adlandır. Son ders yeni günlük ritüel eklemek yerine aynı denemeyi toparlar. Kursu tamamlamak, gerçek hayat uygulamasının kanıtı değildir. Sıradaki işi ayrı denemede kaydet; planı yapılmış sayma."]},{heading:"Bir istek, bir engel, yapılabilir bir yol",paragraphs:["Wang ve çalışma arkadaşları zihinsel karşılaştırmayla “şu olursa bunu yaparım” planlarını birleştiren yöntemi derledi [S04]. Sıra; yapılabilir istek, istenen sonuç, mevcut engel ve belirli bir yanıttır. 21 makalede 15.907 katılımcılı 24 bağımsız tahminde hedefe ulaşma ortalama olarak arttı: g = 0,336. %95 güven aralığı 0,229 ile 0,443’tü. Çalışmalar arası farklılık yüksekti: I² = %59,3. Kalite de değişiyordu. Bu, birleşik yöntemin güncel bir tahminidir; herkes için başarı oranı değildir. Ortalamayı kendine garanti veya son tarih gibi uygulama.","ODA’nın bu sıralamayı kısa kullanması ve haftalık kayıtlara bakması uyarlamadır. Herkese uyan süre veya bu akışın etkisi belirlenmedi. Kolay oyalanma işleri ya da kurstaki her alıştırma yerine, asıl önceliğe yarayan işi seç. Engel dışarıdaki tehlike, eksik imkân, hastalık veya bakım ihtiyacıysa yanıt destek, sınır, dinlenme ya da hedefi bırakmak olabilir. Sıradaki denemeyi planından ve değerlendirmenden ayrı kaydet. Duygunun değişmemesi veya dış sonucun belirsizliği, yaptığını bildirdiğin yararlı işi silmez. Bu kayıt sonraki fırsatta neyi koruyacağına veya değiştireceğine karar vermek için kullanılabilir."]}],sourceIds:["stoic-epictetus-iep","stoic-planning","stoic-mcii"]}}],f=[{id:"stoic-1",practice:["Bir hedef seç. Yapabileceğin işi, gereken desteği ve dışarıdaki sonuçları ayır.","Fark edebileceğin bir başlama anı ve işe yarayan en küçük iş belirle.","İşi yap. Hazırlık seçersen bunu belirt, sonraki kullanım fırsatını da seç."],correct:1,photo:{id:"1507525428034-b723cf961d3e",alt:"Berrak suyun kumla buluştuğu sakin kıyı"}},{id:"stoic-2",practice:["Bir olguyu henüz doğrulanmamış yorumundan ayır.","Gerçek zararı küçültmeden her iki taraftaki kanıta bak.","Bildiklerine dayanan bir soru sor, yanlış bilgiyi düzelt veya güvenli biçimde kendini koru."],correct:2,photo:{id:"1500534314209-a25ddb2bd429",alt:"Alacakaranlıkta puslu tepe sıraları"}},{id:"stoic-3",practice:["Aynı iş için gündelik ve gerçekçi bir engel seç. Canlandırma isteğe bağlı.","Yapabileceğin bir yol planla. Sıkıntın artarsa dur.","Gerekirse seçtiğin yolu kullan. Engel çıktı mı, kaydet."],correct:1,photo:{id:"1464822759023-fed622ff2c3b",alt:"Karlı dağların altında ormanlık vadiler"}},{id:"stoic-4",practice:["Gündelik, hafif bir durum seç. İstersen kendi adınla 60 saniye düşün.","Panik, kendinden veya çevrenden kopma hissi ya da istemsiz anılar gelirse dur veya atla.","Gerçeğe dayanan bir cümle söyle, talep ilet veya güvenli sınır koy ve kaydet."],correct:0,photo:{id:"1506905925346-21bda4d32df4",alt:"Bulut denizinin üstünden görülen dağ sıraları"}},{id:"stoic-5",practice:["Gerçek bir denemeye bak. Yararlı kısmı ve uymayan somut koşulu belirt.","Tek bir düzeltme seç. Cezaya dönen veya uykunu bozan değerlendirmeyi kısalt, başka zamana al ya da bırak.","Düzeltmeyi gerçek bir işte kullan. Değerlendirmeden ayrı kaydet."],correct:1,photo:{id:"1475924156734-496f6cac6ec1",alt:"Alacakaranlıkta kayalık kıyıya vuran dalgalar"}},{id:"stoic-6",practice:["Aynı hedef ve iş için gerçekten yaptığın denemeleri karşılaştır.","İşe yarayan en küçük işi koru, en fazla tek koşulu değiştir.","Hedefe yarayan sıradaki işi dene ve kaydet. Ek araçlar isteğe bağlı kalsın."],correct:2,photo:{id:"1502082553048-f009c37129b9",alt:"Açık arazide tek başına duran ağaç"}}];function S(a,t){const i=f[t],e=a.judgment.primary,l=e.options.find(r=>r.id===e.bestOptionId),n=e.options.filter(r=>r.id!==l.id).map(r=>r.text);return n.splice(i.correct,0,l.text),{...i,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:n,feedback:l.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}}const B={id:"stoic",title:"Yanıtı mı bekliyorsun? Yapabileceğin işe dön.",subtitle:"6 ders. Belirsizlikte harekete geç, yorumlarını kontrol et, işe yarayan denemeni gelecek haftaya taşı.",description:"Belirsizliğin geri plana ittiği bir hedef seç. Stoacı ayrımlar ve isteğe bağlı psikolojik araçlarla bildiklerine uygun bir iş yap, değerlendir ve uyarla.",scope:"Strese, aksamalara ve belirsizliğe daha dengeli karşılık vermek isteyen yetişkinler için. Burada Stoacılık duyguları bastırmak veya güçlü görünmek değildir. Duygularına yer var; uygulama sırada ne yaptığına bakar. Bu eğitim ve kişisel uygulamadır, terapi değildir; tedavinin yerini tutmaz. Kaygı, depresyon, travma veya istemsiz kaygılı düşünceler yaşıyorsan bazı alıştırmalar, özellikle aksama canlandırmak, sana uymayabilir. Lütfen bir uzmanla çalış. Krizdeysen veya kendine zarar vermeyi düşünüyorsan hemen bulunduğun yerdeki acil yardım numarasını ara.",outcome:"Hedefine bağlı bir deneme, gerçek işler, dürüst değerlendirmeler ve destekle sınırları içeren gelecek hafta planı.",photo:{id:"1439066615861-d1af74d74000",alt:"Durgun dağ gölünde ahşap iskele"},lang:"tr",lessons:y.map(S)},F=Object.freeze(Object.defineProperty({__proto__:null,COURSE:B,LESSONS_V2:y,SOURCES:v},Symbol.toStringTag,{value:"Module"})),A=[{id:"turning-day-commitment-contract",title:"Giné, Karlan & Zinman · 2010 · Sigarayı bırakmak için taahhüt sözleşmesi",url:"https://www.aeaweb.org/articles?id=10.1257%2Fapp.2.4.213",type:"research",finding:"Sigara içenlere bir tasarruf hesabı önerildi: altı ay boyunca para yatırıyor, ardından nikotin ve kotinin için idrar testine giriyorlardı. Testi geçenlerin parası geri veriliyor, geçemeyenlerinki bir hayır kurumuna gidiyordu. Hesap önerilenlerin %11’i katıldı. Hesap açma seçeneği rastgele sunulan sigara içenlerin altı aylık testi geçme olasılığı 3 yüzde puan daha yüksekti ve fark 12. aydaki sürpriz testlerde de sürdü.",limitation:"Yalnızca özet okundu. Tek bir davranış (sigara) için yapılan bir saha deneyidir; katılım düşüktü ve ortalama etki küçüktü. Bir taahhüt aracının bazı insanlara yardımcı olabileceğini gösterir, herkese uyduğunu değil."}],D={"turning-day-1":{deeper:[{heading:"Yeni bir başlangıç neden işe yarar?",paragraphs:["Dai, Milkman ve Riis etkiyi şöyle açıklıyor: yeni bir hafta, yıl ya da başlangıç saydığın bir gün, geçmişle bugün arasına bir sınır koyar. “Eski sen”in hataları biraz daha uzakta görünür. Yeniden denemek, aynı başarısızlığı tekrarlamak yerine yeni bir sayfa açmak gibi gelir. Deneylerinde aynı tarih, bir başlangıç olarak sunulduğunda daha fazla kişi o gün için hedef hatırlatıcısı seçti.","Aynı araştırma bu etkinin sınırını da gösteriyor: başlama isteği gerçekten artıyor ama kısa sürüyor. Bu isteği seni sürekli taşıyacak bir güçten çok, ilk adımı kolaylaştıran bir destek gibi düşün. Bu yüzden bugün enerjini küçük ve somut bir şeye ayırmanı, yarın da tekrarlamanı öneriyoruz."],visual:{kind:"compare",title:"Başlangıç gününü beklemek ya da seçmek",left:{label:"Pazartesiyi beklemek",items:["“Haftaya düzgünce başlayacağım.”","İstek birikir, kullanılmadan sönüp gider.","Bir günü kaçırmak, bir sonraki pazartesiyi beklemek demektir."]},right:{label:"Bugünü işaretlemek",items:["“Bugün başlangıç günüm.”","Başlama isteği, küçük ve gerçek bir adıma dönüşür.","Bir günü kaçırmak, yarın sabah yeniden başlamak demektir."]},note:"Deneylerde bir günü yeni başlangıç olarak sunmak başlama isteğini artırdı; ne kadar süreceği bundan sonra ne yaptığına bağlı."}},{heading:"Başlangıç gününde sık yapılan hatalar",paragraphs:["İlk hata, her şeyi aynı anda değiştirmeye çalışmak: aynı sabah yeni bir diyet, spor planı ve iş düzenine başlamak. Hepsi sınırlı enerjine ihtiyaç duyar. Biri aksayınca hepsi boşa gitmiş gibi gelebilir. Bir gün için tek alan yeter.","İkinci hata, senin için önemli olan yerine kulağa etkileyici gelen bir alan seçmek. Kendi nedenin, yorgun bir öğleden sonra seni daha iyi destekleyebilir: “Çocuklarımla yürüyüşte onlara yetişmek istiyorum.” Başkalarının beklentisinden gelen bir neden daha çabuk etkisini kaybedebilir: “Herkes yapmam gerektiğini söylüyor.” Nedenini sesli söylediğinde içine sinmiyorsa, biraz daha düşün."]}],example:{title:"Dana, 34, vardiyalı hemşire",text:"Dana aylardır “pazartesi başlıyorum” diyordu ama vardiyaları yüzünden pazartesi çoğu zaman gece nöbetine denk geliyordu. İzinli bir çarşamba günü defterine tarihi yazdı, yanına da “Başlangıç günüm” notunu düştü. Biraz tuhaf hissetti. Kafasındaki uzun listeden (uyku, yemek yapmak, para, kız kardeşini aramak) yalnızca birini seçti: hareket. Nedenini bulması birkaç deneme aldı: “Çünkü on iki saatlik vardiyadan sonra sırtımın ağrımasını istemiyorum.” Bu neden içine sindi. Bunu telefonuna günün tek kararı olarak ekledi ve başka büyük bir değişiklik yapmadı. Gün henüz bir dönüm noktası gibi gelmedi. Ama bir iş arkadaşı planlarını sorduğunda tek cümlede bir alan ve bir neden söyleyebildi; bu yeniydi."}},"turning-day-2":{deeper:[{heading:"Önceden plan yapmak neden yardımcı olur?",paragraphs:["Eğer-öyleyse planında, zor an gelmeden önce karar verirsin. Öğlen, sakin ve zihnin açıkken, akşam altıda yorgun olduğunda ne yapacağını belirlersin. Saat altı geldiğinde kendinle pazarlık etmen gerekmez. İşaret (“Yorgunum”), küçük bir eyleme (“Yalnızca on dakika”) önceden bağlanmıştır. Bu yüzden “eğer” kısmının somut olması işe yarar: belli bir saat, yer ya da fark edebileceğin bir duygu.","İyi bir plan, zor bir günde de yapabileceğin kadar küçüktür. “Yorgunsam yine de bütün antrenmanı yapacağım” sözü, yorgun hâlini pek hesaba katmaz. “Yorgunsam iki dakikalık hâlini yapacağım” ise o an gerçekten yapabileceğin bir plandır."]},{heading:"Sözünü tutmana yardımcı olacak düzenlemeler",paragraphs:["Taahhüt aracı, bugün yaptığın ve ileride vazgeçmeni zorlaştıran bir düzenlemedir. Bir arkadaşına söylemek kadar hafif olabilir. Para kaybetme ihtimali içermek gibi daha bağlayıcı da olabilir. Bir saha deneyinde sigara içenlere tasarruf hesabı açma seçeneği sunuldu. Altı ay para yatırıyor, sonra nikotin testine giriyorlardı. Testi geçenlere paraları geri veriliyor, geçemeyenlerin parası bir hayır kurumuna gidiyordu. Bu seçenek sunulanların yalnızca %11’i katıldı. Ama seçeneğin sunulduğu grupta testi geçme olasılığı 3 yüzde puan daha yüksekti. Fark, bir yıl sonraki sürpriz testlerde de sürdü.","Katılım düşük ve ortalama etki küçüktü. Sonuçları buna göre değerlendirmek gerekir: bu tür düzenlemeler bazı insanlara, bazı zamanlarda yardımcı olabilir. Yeni başlangıç araştırmasında, insanların bu tür sözleşmeler yaptığı stickK sitesindeki yeni taahhütler hafta başlarında arttı. Yıl başında artış daha da büyüktü. Bu fikir hoşuna gidiyorsa, sözünü tutmana yardımcı olacağını düşündüğün en hafif düzenlemeyle başla."],visual:{kind:"table",title:"Daha hafiften daha bağlayıcı düzenlemelere",columns:["Tür","Örnek","Vazgeçmenin bedeli"],rows:[["Söz","Destekleyici bir kişiye ne yapacağını ve ne zaman yapacağını söyle","Biraz mahcup edici bir konuşma"],["Erişimi zorlaştırma","Dikkatini dağıtan uygulamayı bir hafta boyunca telefonunun son ekranında bir klasöre koy","Birkaç fazladan dokunuş"],["Peşin ödeme","Bir derse önceden kaydolup ücretini öde","Ücreti kaybetmek"],["Sözleşme","Sözünü tutmazsan kaybedeceğin bir para","Depozitoyu kaybetmek"]],note:"Daha bağlayıcı olması, daha iyi olduğu anlamına gelmez. Seçtiğin düzenleme içine sinsin; sana ya da başka birine zarar vermesin."}}],example:{title:"Marcus, 41, depo sorumlusu",text:"Marcus o sabah sağlığı seçmişti: işten sonra kısa bir yürüyüş. Öğle arasında sandviççiye yürürken kendine onu gerçekten neyin durduracağını sordu. Dürüst cevap yağmur ya da zaman değildi. Kanepeydi ve “dinlenmeyi hak ettim” düşüncesiydi. Telefonuna şunu yazdı: “Yürüyüşten önce kanepeye oturursam, kalkıp yalnızca köşeye kadar gidip döneceğim.” Bir adım sayılmayacak kadar küçük geliyordu. Akşam 6.15’te gerçekten oturdu ve düşünce tam zamanında geldi. Notu hatırladı, söylenerek köşeye kadar yürüdü. Sonra devam etti ve on iki dakika yürüdü. Ertesi gün köşeyi geçmedi ve bunu da bir adım olarak kabul etti."},sources:["turning-day-commitment-contract","fresh-start-effect"]},"turning-day-3":{deeper:[{heading:"Küçük başarılar neden önemlidir?",paragraphs:["İki dakikalık bir adımı “Bu sayılmaz, bunu herkes yapar” diyerek küçümsemek kolay. Ama öz yeterlik, adımın ne kadar etkileyici göründüğünden doğmaz. Bir şeye karar verip onu yapmış olmandan güç alır. Her seferinde, “Ben başladığım işi sürdürmem” düşüncesine karşı küçük ve somut bir kanıtın olur.","Yaptığın adımı yazmak önemli, çünkü hafızan her şeyi aynı ölçüde hatırlamaz. Zor bir akşamda kötü gidenleri kolay hatırlar, iyi gidenleri unutabilirsin. Yazılı bir “Bugün … yaptım” cümlesini yok saymak daha zordur. Zamanla bu notlar, yapabileceğine dair inancını destekleyen bir kayıt oluşturur."],visual:{kind:"cycle",title:"Küçük kanıt döngüsü",center:"Öz yeterlik",nodes:[{label:"Küçük adım",text:"Bitirebileceğin iki dakikalık bir eylem."},{label:"Kanıt",text:"Ne yaptığını yazarsın."},{label:"İnanç",text:"“Bunu yapabilirim” inancı biraz büyür."},{label:"Sonraki adım",text:"Yarınki adım biraz daha hafif gelir."}],note:"Bandura’nın başarı deneyimi fikrini anlatır; ölçülmüş bir etkiyi göstermez."}},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hata, ilk adımı fazla büyük tutmaktır. Adım iyi bir ruh hâli, boş bir saat ya da mükemmel koşullar gerektiriyorsa henüz bir ilk adım değildir. Vazgeçmek zor gelecek kadar küçült.","Bir başka hata, iki dakika sınırını mutlaka durman gereken bir kural ya da mutlaka aşman gereken bir hedef sanmaktır. İkisi de sorun değil: devam etmek istiyorsan devam et, durmak istiyorsan dur. Tek görev başlamak ve başladığını fark etmek."]}],example:{title:"Priya, 27, genç grafik tasarımcı",text:"Priya öğrenmeyi seçmişti: elle harf çizimini geliştirmek istiyordu ama her düşündüğünde bitmiş bir afiş hayal edip kendini geride hissediyordu. Öğleden sonra üçte, müşteri dosyalarıyla ilgilenirken verdiği arada iki dakikalık bir zamanlayıcı kurdu ve bir kâğıt parçasına tek satır harf yazdı. Titrek çıkmışlardı. Zamanlayıcı çaldığında durdu ve not uygulamasına şunu yazdı: “Bugün iki dakika harf çizimi çalıştım.” Ekranda biraz komik göründü. Ama o akşam her zamanki düşünce geldiğinde (“sen hiçbir hobiyi sürdüremezsin”), ona verecek küçük ve somut bir cevabı vardı. Ertesi öğleden sonra başlamak biraz daha kolay geldi ve beş dakika çalıştı."}},"turning-day-4":{deeper:[{heading:"Çevren adımı nasıl kolaylaştırır?",paragraphs:["Uzun bir günün sonunda, aç, yorgun ya da keyifsizken iradene güvenmek zor olabilir. Çevren ise hep oradadır. Kapının yanındaki ayakkabılar gibi gözünün önündeki bir işaret, yapacağın şeyi sana hatırlatır. Hazırlığın bir kısmını önceden yaptıysan, başlamak için daha az enerji gerekir.","Aynı mantık tersine de işler. Çoğumuz bir saat boyunca telefonda gezinmeyi seçmeyiz; telefon yalnızca kitaptan daha yakındır. Bunu değiştirmek için başka biri olman gerekmez. Bu gece tek bir eşyayı yerinden oynatmak, yarın büyük bir karar vermekten çoğu zaman daha kolaydır."],visual:{kind:"steps",title:"Yarınki adımı bu gece hazırla",steps:[{label:"Anı seç",text:"Yarınki adım tam olarak ne zaman olacak? Kahveden sonra, işten sonra, yatmadan önce."},{label:"İşareti koy",text:"İhtiyacın olan eşyayı o anda gözünün önüne gelecek yere bırak."},{label:"Bir engeli kaldır",text:"Kıyafetleri hazırla, dosyayı aç, su şişesini doldur."},{label:"Dikkat dağıtanı uzaklaştır",text:"Seni genellikle işten uzaklaştıran şeyi bir oda öteye taşı."}],note:"Bu gece birkaç dakika ayırıp dört küçük hazırlık yapabilirsin. Böylece yarın başlamak daha kolay olur."}},{heading:"Kime söyleyeceğini seçmek",paragraphs:["Araştırma bulgusu ilerlemeyi bildirmekle ilgili, övgü beklemekle değil. En yararlı kişi, “Nasıl geçti?” diye soran ve sonuç ne olursa olsun dinleyen kişidir. Seninle dalga geçecek, seninle yarışacak ya da planını kendi projesine çevirecek bir arkadaş bu adım için uygun değildir.","Mesajı kısa ve net tut: ne yapıyorsun, ne zaman ve ne zaman haber vereceksin. “Bu hafta işten sonra on dakika yürüyorum; pazar günü nasıl geçtiğini sana anlatabilir miyim?” yeter. Şu anda gerçekten kimse yoksa, kendine yazdığın haftalık bir not da yazılı bir kayıt olur."]}],example:{title:"Tomás, 52, lise öğretmeni",text:"Tomás yatmadan önce telefonda gezinmek yerine kitap okumak istiyordu. Akşam beşte, ödev okumaya başlamadan önce romanı oturma odasındaki raftan alıp yastığının üzerine koydu. Telefon şarj aletini mutfağa taşıdı; bu ona beklenmedik ölçüde büyük bir değişiklik gibi geldi. Sonra planını bir yapışkan nota yazdı: “Dişlerimi fırçaladıktan sonra bir sayfa okuyacağım.” Son olarak, aynı kitabı bir zamanlar okumuş olan ağabeyine mesaj attı: “Bu hafta her gece bir sayfa okumaya çalışıyorum. Pazar günü nereye kadar geldiğimi sana söylerim.” Ağabeyi bir başparmak emojisiyle karşılık verdi ve başka bir şey yazmadı; tam olması gerektiği gibi. O gece kitap oradaydı, telefon değildi."}},"turning-day-5":{deeper:[{heading:"Yarın için gerçekçi bir ideal gün planlamak",paragraphs:["Franklin yalnızca sabah ve akşam sorularını sormuyordu. İş, yemek, okuma ve dinlenme için zaman ayırıp gününü saat saat planlıyordu. Bu kadar ayrıntılı bir programa ihtiyacın yok. Ama bu gece bir dakika ayırıp yarın için gerçekçi bir ideal gün hayal edebilirsin. Bu, adımına ne zaman yer açacağını ve neyin ona engel olabileceğini görmene yardım eder.","İşe yarar bir ideal günün birkaç sabit noktası yeterlidir: seçtiğin alanda bir adım, bir dinlenme anı ve biriyle bağ kuracağın kısa bir zaman. Geri kalanı esnek bırakabilirsin. Planın yalnızca hiçbir şey ters gitmediğinde işliyorsa, uygulamak zor olacaktır. Beklenmedik şeyler için yer bırak."],visual:{kind:"table",title:"Gerçekçi bir ideal gün: üç sabit nokta",columns:["Sabit nokta","Ne zaman","Örnek"],rows:[["Tek adımın","Zaten yaptığın bir şeye bağlı","Sabah kahvesinden sonra: 10 dakikalık yürüyüş"],["Dinlenme","Zaman ayırdığın bir mola","Öğle yemeğini ekrandan uzakta yemek"],["Bağ","Kısa ama gerçek bir temas","Akşam bir kişiye mesaj at ya da onu ara"]],note:"Üç sabit nokta ve bol esneklik. Bu bir planlama yardımcısı; gününün nasıl geçmesi gerektiğine dair bir kural değil."}},{heading:"Şefkat ve sorumluluk birlikte olabilir",paragraphs:["Bazı insanlar kendilerine şefkatli davranınca tembelleşeceklerinden korkar. Bu dersteki araştırma, temkinli yorumlamak kaydıyla, tersine işaret ediyor. Wohl’un çalışmasında kendini daha çok affeden öğrenciler, sonraki sefer daha az erteledi. Bu bağlantıyı, işe karşı olumsuz duyguların azalması açıklıyordu. Kendini eleştirmek işi daha itici hâle getirebilir. İtici gelen bir işten kaçınmak da daha kolaydır.","Şefkatli bir değerlendirmede ne olduğunu dürüstçe söylersin: “İşte geç saatlere kadar kaldığım için yürüyüşü atladım.” Sonra kendine anlayış gösterir ve bir adım seçersin: “Bu anlaşılır; yarın yalnızca köşeye kadar gidip döneceğim.” İlk kısmı söylemezsen olanı görmezden gelirsin. İkinciyi söylemezsen kendine sert davranmış olursun."]}],example:{title:"Aisha, 38, muhasebeci ve iki çocuk annesi",text:"Aisha öğle yemeğinden sonra on dakikalık bir esneme planlamıştı ama bir müşteri görüşmesi uzadı ve yatma saatine kadar unuttu. Dişlerini fırçalarken ilk düşüncesi “İlk gün ve şimdiden başarısız oldum” oldu. Bunun yerine defteriyle yatağın kenarına oturdu. “Bugün hangi iyiliği yaptım?” başlığının altına şunu yazdı: “Yoga matını masanın yanına koydum. Sam’e planımı anlattım.” “Ne zorlaştırdı?” başlığının altına: “Görüşme uzadı; öğleden sonra esnemem, günün programına bağlı.” Nazik cümlesi: “Yoğun bir günde aksaması çok normal; yine de hazırlığı yapmıştım.” Yarının adımı: “Sabah 7.30, çocuklar uyanmadan önce, matın üstünde üç dakika.” Defteri kapattı ve ışığı söndürdü."}},"turning-day-6":{deeper:[{heading:"Yeniden başlayabilirsin",paragraphs:["Yeni başlangıç araştırması, önündeki hafta için yararlı bir fikir sunuyor: başlangıç yapmak için takvimde özel bir gün beklemen gerekmez. 2015 deneylerinde sıradan bir güne başlangıç demek bile başlama isteğini artırdı. Bunu bilinçli kullanabilirsin. Bir günü kaçırırsan ertesi sabahı yeni başlangıç sayabilirsin. Yeni haftanın başı ya da zor bir projeyi bitirdiğin gün de olabilir.","Ama bir sonraki başlangıç gününü beklemek için gerekçe yapma. Çarşamba günü “pazartesi yeniden başlarım” dediğinde dört günü bekleyerek geçirirsin. “Yarın haftamın ikinci yarısının ilk günü” diyebilirsin. Eski ile yeni arasındaki sınırı, ihtiyacın olan yerde koyabilirsin."]},{heading:"7. gün değerlendirmesi",paragraphs:["7. günde kutulara kendine not vermeden bak. Dördünü işaretlediğin ve üçünü boş bıraktığın bir hafta, başarısız olduğun anlamına gelmez. Adımının hayatına ne zaman uyduğunu, ne zaman zor geldiğini gösterir. Aşağıdaki sorular için yaklaşık on dakika ayır. Mümkünse yanıtlarını yaz. İlerleme takibi araştırmasında, yazılı kayıt tutmak daha büyük yararla ilişkiliydi.","Sonra üç seçenekten birini seç: adımı olduğu gibi sürdür, küçült ya da onu bağladığın günlük alışkanlığı veya saati değiştir. Adımı büyütebilirsin de, ama ancak artık kolay geliyorsa. İkinci haftada da amaç aynı: tekrar edebileceğin kadar küçük bir adım."],visual:{kind:"table",title:"7. gün soruları",columns:["Soru","Sana ne söyler?"],rows:[["Hangi günlerde kolayca gerçekleşti?","Adımını destekleyen koşullar"],["Hangi günlerde aksadı ve neden?","Bir sonraki eğer-öyleyse planının hedef alması gereken engel"],["Kaçırılan günden sonra geri döndüm mü?","En küçük hâlinin yeterince kolay olup olmadığı"],["Sürdür, küçült ya da değiştir?","Önümüzdeki yedi gün için planın"]],note:"Bu değerlendirmeden öğrenebilirsin. Boş kalan günler de sana bilgi verir."}}],example:{title:"Jonah, 23, kurye ve yarı zamanlı öğrenci",text:"Jonah’ın adımı akşam yemeğinden sonra yirmi dakika muhasebe tekrarıydı. Bir zarfın arkasına yedi kutu çizdi ve buzdolabına yapıştırdı. Pazartesi ve salı işaretlendi. Çarşamba geç saatlere kadar çalıştı ve zarf boş kaldı; tanıdık “haftaya sıfırdan başlarım” dürtüsünü hissetti. Bunun yerine birinci gün yazdığı cümleye baktı: “Kaçırırsam beş bilgi kartıyla tekrar yaparım.” Perşembe günü beş kart çalıştı, sonra sekiz. Pazara kadar yedi kutunun beşi işaretliydi. Değerlendirmesinde iki boşluğun da geç vardiya günleri olduğunu fark etti; ikinci hafta için o günlerde adımı öğle molasına taşıdı."},sources:["fresh-start-framing"]}},V=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:D,SOURCES:A},Symbol.toStringTag,{value:"Module"})),K=[{id:"procrastination-pychyl-start",title:"Timothy A. Pychyl · 2008 · “Sadece başla” (Psychology Today, Don’t Delay blogu)",url:"https://www.psychologytoday.com/us/blog/dont-delay/200803/just-get-started",type:"guidance",finding:"Erteleme araştırmacısı Tim Pychyl, laboratuvarının deneyim örnekleme yöntemiyle topladığı verileri anlatıyor. İnsanların kaçınırken çok stresli ve rahatsız edici bulduğu işler, başladıktan sonra daha az itici geliyordu. İşin bir kısmına bile başlayanlar, ertesi gün kendilerini daha fazla kontrol sahibi ve daha umutlu hissetti. Pychyl, “Yarın daha çok canım isteyecek” düşüncesinin de nadiren gerçeğe dönüştüğünü belirtiyor.",limitation:"Yazarın kendi araştırmasını genel okuyucu için özetleyen bir blog yazısıdır, hakemli bir makale değildir; Pychyl de başlamayı tam bir çözüm olarak değil, ilk adım olarak sunar."},{id:"procrastination-pomodoro",title:"Francesco Cirillo · Pomodoro tekniği (resmî site)",url:"https://www.pomodorotechnique.com/francesco-cirillo/",type:"technique",finding:"Cirillo tekniği 1980’lerde üniversite derslerine odaklanmakta zorlanırken, domates şeklinde bir mutfak zamanlayıcısıyla geliştirdi (“pomodoro” İtalyanca domates demektir); ilk deneyi, yalnızca iki dakika kesintisiz çalışıp çalışamayacağını görmekti. Teknik yaygın olarak, kısa molalarla ayrılmış 25 dakikalık odaklanarak çalışma dönemleri olarak öğretilir. Cirillo, amacın pomodoro biriktirmek değil, çalışırken zihninde neler olduğunun farkına varmak olduğunu vurgular.",limitation:"Yaratıcısının kendi sitesidir, bağımsız bir değerlendirme değildir; teknik bir bütün olarak kontrollü denemelerde sınanmamıştır. Çalışma ve mola süreleri araştırma bulgusu değil, geleneksel uygulamadır."},{id:"procrastination-pomodoro-breaks",title:"Biwer ve ark. · 2023 · “Pomodoro” molaları ile kendi seçtiği molalar",url:"https://cris.maastrichtuniversity.nl/en/publications/understanding-effort-regulation-comparing-pomodoro-breaks-and-sel/",type:"research",finding:"87 Hollandalı üniversite öğrencisi ya kendi seçtikleri molalarla (n = 35), ya her 24 dakikadan sonra 6 dakikalık molalarla (“Pomodoro”, n = 25), ya da her 12 dakikadan sonra 3 dakikalık molalarla (n = 27) çalıştı. Kendi molasını seçen öğrenciler daha uzun aralıklarla çalışıp dinlendi ama daha çok yorgunluk ve dikkat dağınıklığı, daha az konsantrasyon ve motivasyon bildirdi. Görevin tamamlanması ve zihinsel çaba anlamlı biçimde farklılaşmadı; yazarlar sabit molaların ruh hâli açısından yararlı olduğu ve daha verimli göründüğü sonucuna varır.",limitation:"Yalnızca özet okundu. Üniversite öğrencileriyle tek oturumluk kendi kendine çalışmayı inceleyen küçük bir çalışmadır; erteleme değil mola düzenlerini sınadı ve gruplar küçüktü."}],H={"procrastination-1":{deeper:[{heading:"Tim Pychyl’in bakışı: ertelemenin ardındaki duygu",paragraphs:["Uzun yıllardır erteleme üzerine çalışan psikolog Tim Pychyl, bunu bir duygu düzenleme yolu olarak tanımlıyor. Ancak bu yol ters tepiyor. Bir iş seni kaygılandırabilir, sıkabilir, bunaltabilir ya da belirsizlik hissettirebilir. Erteleyince hızla rahatlarsın ve kaçınmak çözüm gibi görünmeye başlar. Ama iş ortadan kalkmaz. Daha sonra, çoğu zaman büyümüş hâlde, ek stres ve kendini suçlama duygusuyla geri döner.","Fuschia Sirois ile yazdığı derlemede Pychyl, şimdiki sen ile gelecekteki sen arasında bir bedel aktarımından söz ediyor: bugün rahatlarsın, bedelini sonra ödersin. Böyle bakınca yapılacaklar uygulaması ya da sıkı bir program ancak bir yere kadar yardımcı olur. Duyguyu fark etmeyi, bir süre ona katlanmayı ve yine de küçük bir adım atmayı öğrenmek daha çok işe yarar."],visual:{kind:"cycle",title:"Erteleme döngüsü",center:"Kısa vadeli rahatlama, uzun vadeli bedel",nodes:[{label:"İş",text:"Belirsiz, sıkıcı ya da gözünü korkutan bir iş."},{label:"Duygu",text:"Korku, kaygı ya da sıkıntı yükselir."},{label:"Kaçınma",text:"Daha kolay bir şeye geçersin."},{label:"Rahatlama",text:"Rahatsız edici duygu şimdilik hafifler."},{label:"Dönüş",text:"İş, artık ek baskı ve kendini suçlamayla geri gelir."}],note:"Sirois ve Pychyl’in, ertelemenin anlık rahatlama sağladığı görüşünü anlatıyor. Ölçümlerle sınanmış bir model değil. Döngüyü kırmanın ilk adımı çoğunlukla duyguyu fark etmektir."}},{heading:"Rakamlar ne söylüyor, ne söylemiyor?",paragraphs:["Piers Steel’in kapsamlı derlemesinde, erteleme bir işi itici bulmakla ve dürtüsellikle güçlü biçimde ilişkiliydi. Çalışma niyetiyle ise neredeyse hiçbir ilişkisi yoktu. Steel, yetişkinlerin yaklaşık %15–20’sinde ertelemenin sürekli bir sorun olduğunu tahmin ediyor. Bunlar bağlantıları gösterir; itici işlerin ertelemeye yol açtığını kanıtlamaz. Yine de hangi etkenlere bakabileceğimizi gösterir.","Bu bulgularda umut veren bir yan var. Sorun çalışmak istememek değil; “daha çok istemen” gerekmiyor. İşin uyandırdığı duyguyu ele alabilir, ilk adımı küçültebilir ve zorlandığın an için plan yapabilirsin. Sonraki derslerde bunları deneyeceğiz."]}],example:{title:"Sofia, 31, pazarlama koordinatörü",text:"Sofia masraf raporundan üç haftadır kaçıyordu. Genellikle kendine “idari işlerde kötüyüm” diyordu. Bir kahve molasında bunun yerine alıştırmayı denedi: rapor şablonunun bulunduğu e-postayı açtı ve ne olduğunu fark etmek için durdu. Aklına “korku” kelimesi geldi. Bunun altında da utanç vardı. Tetikleyen şey tablo değildi; çantasındaki buruşuk fişlerdi, bir kısmı büyük ihtimalle kaybolmuştu. Yapışkan bir nota şunu yazdı: “Kayıp fişler yüzünden korku + utanç.” O gün rapora başlamadı. Ama “idari işlerde kötüyüm” cümlesi, işin belli bir kısmıyla ilgili somut bir duyguya dönüşmüştü ve bu, üzerinde çalışılabilecek bir şey gibi geldi."},sources:["procrastination-pychyl-start"]},"procrastination-2":{deeper:[{heading:"Başlamak, hissettiklerini neden değiştirir?",paragraphs:["Tim Pychyl, laboratuvarındaki araştırmalarda görülen bir durumu anlatıyor. İnsanların kaçınırken çok stresli ve rahatsız edici bulduğu işler, başladıktan sonra daha az rahatsız edici geliyordu. İşin bir kısmına bile başlayanlar, ertesi gün kontrolün daha çok kendilerinde olduğunu hissetti ve daha umutluydu. Korku çoğu zaman başlamadan önceki bekleyişte büyüyor.","Pychyl yaygın bir tuzağa da dikkat çekiyor: “Yarın daha çok canım isteyecek.” Ertesi gün çoğu zaman daha istekli olmuyoruz. Küçük bir ilk adım atmak için doğru ruh hâlini beklemen gerekmez. Başlamak, işle ilgili başka bir deneyim sunarak ruh hâlini değiştirebilir."]},{heading:"Süre tutarak kısa aralıklarla çalışmak",paragraphs:["Francesco Cirillo, Pomodoro tekniğini 1980’lerde, odaklanmakta zorlanan bir öğrenciyken geliştirdi. İlk deneyi küçüktü: yalnızca iki dakika kesintisiz ders çalışabilir miydi? Bu denemeden, süre tutarak çalıştığı ve aralarda kısa molalar verdiği bir yöntem doğdu. Bugün genellikle 25 dakikalık çalışma süreleriyle öğretiliyor.","Küçük bir çalışma, 87 üniversite öğrencisinde mola düzenlerini karşılaştırdı. Sabit mola veren öğrenciler (her 24 dakikadan sonra 6, ya da her 12 dakikadan sonra 3 dakika) kendi molasını seçenlere göre daha az yorgunluk ve dikkat dağınıklığı, daha çok konsantrasyon ve motivasyon bildirdi ve benzer miktarda iş çıkardı. Tek oturumluk, küçük örneklemli bir çalışmaydı; bu yüzden bir kural değil, bir ipucu olarak al. Başlangıçta sana daha kısa bir çalışma süresi uygun olabilir."],visual:{kind:"table",title:"Mola vermenin üç yolu (Biwer ve ark. 2023)",columns:["Mola düzeni","Öğrenci","Bildirdikleri"],rows:[["Kendi seçtiği molalar","35","Daha uzun aralıklar; daha çok yorgunluk ve dikkat dağınıklığı, daha az konsantrasyon ve motivasyon"],["Her 24 dakikada 6 dakika","25","Ruh hâlinde daha iyi sonuçlar; benzer miktarda iş tamamlama"],["Her 12 dakikada 3 dakika","27","Ruh hâlinde daha iyi sonuçlar; benzer miktarda iş tamamlama"]],note:"Tek bir kendi kendine çalışma oturumunu inceleyen küçük bir çalışma. Doğrudan erteleme değil, mola düzenlerini sınadı."}}],example:{title:"Kevin, 45, serbest çevirmen",text:"Kevin’in çevirmesi gereken 20 sayfalık bir sözleşme vardı ve iki sabahını e-postalara yanıt vererek “hazırlanmakla” geçirmişti. Üçüncü sabah işi “sözleşmeyi çevir” diye yazdı, sonra parçalara böldü: baştan sona oku, bir sözlük oluştur, birinci bölümü çevir. “Baştan sona oku” bile ağır geldi, o yüzden küçülttü: dosyayı aç ve ilk sayfayı oku. 25 dakika fazla geldiği için mutfak zamanlayıcısını on dakikaya kurdu. Çaldığında üç sayfa okumuş ve dört zor terimi not etmişti. Beş dakika mola verdi, çay yaptı ve zamanlayıcıyı yeniden kurdu. Sözleşme hâlâ uzundu ama artık bir duvar değildi; sayfa sayfa ele alabileceği bir işti ve bir kısmına başlamıştı."},sources:["procrastination-pychyl-start","procrastination-pomodoro","procrastination-pomodoro-breaks"]},"procrastination-3":{deeper:[{heading:"Piers Steel’in zamansal motivasyon kuramı",paragraphs:["Piers Steel, erteleme araştırmalarını zamansal motivasyon kuramında bir araya getiriyor. Başarabileceğine inanıyorsan (beklenti) ve sonuç senin için önemliyse ya da ödül getiriyorsa (değer), işe daha çok yönelirsin. Ödül uzaktaysa (gecikme) ve anlık cazibelere kolay kapılıyorsan (dürtüsellik), işe yönelmen zorlaşır. Üç hafta sonra teslim edilecek bir rapor, hemen keyif veren bir video karşısında geri planda kalabilir.","Bu kuramın yararlı yanı, her etken için deneyebileceğin bir şey göstermesi. İşi küçülterek başarabileceğine dair beklentini artırabilirsin. Önemsediğin bir şeyle bağ kurarak işi daha değerli hâle getirebilirsin. Daha yakın kontrol tarihleri ve küçük ödüller, bekleme süresini kısaltabilir. Dikkat dağıtıcıları erişemeyeceğin yere koymak da anlık dürtülere kapılmanı azaltabilir. WOOP ve eğer-öyleyse planları özellikle son noktaya yardımcı olur: cazip bir şeyle karşılaştığında ne yapacağını önceden belirlersin."],visual:{kind:"table",title:"Zamansal motivasyon kuramında değiştirebileceğin dört etken",columns:["Etken","Ne demek?","Denenecek bir şey"],rows:[["Beklenti","Yapabileceğinden ne kadar emin hissettiğin","Başarabileceğine inanacağın kadar işi küçült"],["Değer","Senin için ne kadar önemli ya da ödüllendirici olduğu","Neden önemli olduğunu tek satırla yaz"],["Gecikme","Karşılığın ne kadar uzakta olduğu","Daha yakın bir kontrol tarihi ve küçük bir ödül belirle"],["Dürtüsellik","Anlık cazibelere ne kadar kolay kapıldığın","Bir eğer-öyleyse planı yap ve dikkat dağıtıcıyı uzaklaştır"]],note:"Korelasyonel bulgulara uyan Steel’in modeline dayanır; bir düşünme biçimidir, sınanmış bir tedavi değildir."}},{heading:"Eğer-öyleyse planlarında sık yapılan hatalar",paragraphs:["“Eğer” kısmı çoğu zaman fazla belirsizdir. “Canım istemezse” neredeyse her zaman doğrudur, bu yüzden net bir işaret olamaz. “Masama oturduktan sonra telefonumu elime alırsam” ise gerçekleştiğinde tanıyacağın bir andır.","“O zaman” kısmı çoğu zaman fazla büyüktür. “O zaman iki saat çalışacağım”, zaten zorlandığın kadar büyük bir çaba ister. “O zaman önce tek bir cümle yazacağım” ise duygu yoğunken bile yapabileceğin kadar küçüktür. En sık karşılaştığın engel için tek bir plan, hatırlamayacağın beş plandan iyidir."]}],example:{title:"Grace, 26, yüksek lisans öğrencisi",text:"Grace tezinin literatür taramasını bu hafta bitirmek istiyordu; bitirirse her hafta sonu suçluluk duymayı bırakabilirdi. Engeli ararken bunun zaman olmadığını gördü. Engel, belgeyi açtıktan sonra yeterince bilmediğini hissedip telefona uzandığı andı. Planı şuydu: “Belgeyi açtıktan sonra telefona uzanırsam, o zaman telefonu çekmeceye koyup ilk makale hakkında tek bir cümle yazacağım.” Bunu otobüste bir kez prova etti. Salı günü kendini telefon zaten elindeyken yakaladı, biraz güldü ve telefonu çekmeceye koydu. Yazdığı cümle pek düzgün değildi. Yine de bir tane daha yazdı."},sources:["task-aversiveness","oettingen-woop-method"]},"procrastination-4":{deeper:[{heading:"Kendini affetme çalışması ne buldu?",paragraphs:["Michael Wohl, Tim Pychyl ve Shannon Bennett, birinci sınıf öğrencilerini iki ara sınav boyunca izledi. İlk sınavdan sonra öğrenciler ne kadar ertelediklerini ve bu konuda kendilerini ne kadar affettiklerini bildirdi. Kendini daha çok affedenler, ikinci sınavdan önce daha az erteledi. Bu bağlantıyı, derse karşı olumsuz duyguların azalması açıklıyordu.","Çalışmanın önemli sınırları var: yalnızca ilişkileri inceledi, tek bir derste yapıldı ve başlayan 312 öğrenciden yalnızca 119’u son analize girdi. Bu yüzden affetmenin daha az ertelemeye yol açtığını kanıtlayamaz. Ama ertelemenin anlık rahatlama sağladığı görüşüyle uyuşuyor: erteleme kötü duygulardan kaçmanın bir yoluysa, kendini daha kötü hissettirmek pek yardımcı olmayabilir. Daha genel olarak öz şefkat araştırmaları stres ve kaygı için küçük ile orta düzeyde kısa vadeli yararlar gösteriyor."]},{heading:"Üç parçalı bir affetme metni",paragraphs:["Kendini affetmenin ne demek olduğunu anlamak zor olabilir. Bu yüzden hazır birkaç cümle işe yarar. Aşağıdaki üç bölüm, dürüst ve şefkatli kalmana yardım eder. İçinden söyle ya da yaz. Cümleleri kendi sözlerinle kurabilirsin.","Bunu yaparken sert ses geri gelirse bu normal. Onunla tartışman ya da onu susturman gerekmez. Sadece fark et (“işte eleştirmen yine geldi”) ve metne dön."],visual:{kind:"steps",title:"Affet, sonra geri dön",steps:[{label:"Adını koy",text:"“Raporu bu hafta yine erteledim.”"},{label:"Bunun insanın başına gelebileceğini hatırla",text:"“Belirsiz ve stresli geldi; birçok insan böyle işlerden kaçınır.”"},{label:"Sorumluluğu al",text:"“Yine de benim için önemli ve bir kısmını düzeltebilirim.”"},{label:"Sonraki adımı seç",text:"“Yarın saat 9’da dosyayı açıp ilk başlığı yazacağım.”"}],note:"Burada affetmek, kendine yüklenmeyi bırakıp işe geri dönebilmek demek."}}],example:{title:"Daniel, 36, proje yöneticisi",text:"Daniel ekibine cuma gününe kadar bir bütçe taslağı sözü vermişti ve cuma öğleden sonra önündeki sayfa hâlâ boştu. Eve dönerken her zamanki sesi duydu: “Hep böyle yapıyorsun. Herkes hiçbir şeyi yönetemediğini görecek.” Arabayı park ettiğinde bilgisayarını açacak gücü bile bulamıyordu. Arabada otururken metni denedi. “Taslağı yapmadım. Belirsiz geldi ve kaçınmaya devam ettim; insanların başına gelir. Yine de önemli ve bir kısmını düzeltebilirim.” Sonraki adımı şuydu: ekibine taslağın pazartesi öğlene kadar geleceğini yazan bir e-posta ve dosyayı 8.30’da açması için bir not. Pazartesi günü başlamak, kendisi hakkında verilecek bir hükümle yüzleşmek gibi gelmiyordu."}},"procrastination-5":{deeper:[{heading:"Zorlandığın yere uygun yöntemi seçmek",paragraphs:["Ertelemenin nedeni her seferinde aynı olmayabilir. Bu kurstaki yöntemler farklı durumlarda işe yarayabilir. Nereden başlayacağını bilemiyorsan işi küçültmeyi dene. Belli bir anda hep işten uzaklaşıyorsan, o an için bir eğer-öyleyse planı yap. Sonuç çok uzaktaysa daha yakın bir kontrol tarihi belirle. Steel’in modeli de bekleme süresini kısaltmanın yardımcı olabileceğini öngörüyor.","Bütün yöntemleri aynı anda kullanman gerekmez. Zorlandığın yere uyan bir ya da iki tanesini seç, bir hafta dene ve sonucu gözden geçir. Geniş bir meta-analizde, yapılanları basit bir işaretle bile olsa takip etmek hedeflerde daha iyi ilerlemeyle ilişkiliydi. Kayıt tutmak, haftalık değerlendirmende somut olarak neye bakacağını da gösterir."],visual:{kind:"table",title:"Hangi zorluk için hangi yöntem?",columns:["İş şöyle geliyorsa…","Dene","Hangi dersten"],rows:[["Ağır ve korkutucu","Hissin adını koy, sonra iki dakikalık bir ilk adım","1 ve 2"],["Belirsiz ya da çok büyük","Parçalara böl; ilk adımı somut bir fiille yaz","2"],["Belli bir ana kadar sorun yok","O an için bir eğer-öyleyse planı","3"],["Uzak ve göz ardı etmesi kolay","Küçük ödüllü, daha yakın bir kontrol noktası","5"],["Erteledikten sonra artık düzelmez gibi","Affetme metni, sonra tek bir adım","4"]],note:"Buradan sana uygun yöntemleri seçebilirsin. Bir hafta için bir ya da iki yöntem yeter."}},{heading:"Ne zaman daha fazla destek almalısın?",paragraphs:["Ertelemeye yönelik araştırmalarda en güçlü sonuçlar, eğitimli bir uzmanla yapılan bilişsel davranışçı terapiden geldi. Bazı erteleme sorunları, kısa bir kursun ele alamayacağı durumlarla iç içe olabilir. Uzun süren kaygı, depresyon ya da DEHB gibi dikkat güçlükleri bunlar arasında. Bu kurs eğitim ve kişisel çalışma içindir; tanı ya da tedavi sunmaz.","Erteleme işini, okul başarını, ilişkilerini ya da sağlığını olumsuz etkiliyorsa bir doktora ya da terapiste danışabilirsin. İşlerin uyandırdığı duygular çok yoğunsa veya sürekli devam ediyorsa da destek almak iyi olabilir. Birkaç yöntem denediğin hâlde değişim görmüyorsan yardım isteyebilirsin. Bu, iradenin zayıf olduğu anlamına gelmez. Daha zor bir sorun için daha güçlü bir destek seçmiş olursun."]}],example:{title:"Nadia, 29, okula başvuran veteriner teknisyeni",text:"Nadia’nın başvuru yazısı üç hafta sonra teslim edilecekti ve kendini tanıyordu: bir gece öncesinde başlayacaktı. Pazar günü planı doldurdu. İlk adım: bir belge açıp onu bu mesleği istemeye götüren üç anı sıralamak. Zaman ve yer: salı akşam 7, akşam yemeğinden sonra mutfak masası. Eğer-öyleyse: “Eski e-postaları yeniden okumaya başlarsam, önce tek bir cümle yazacağım.” Deneme olarak iki ara tarih koydu: bir sonraki pazara kadar ilk taslak ve ondan sonraki çarşamba günü bir arkadaşının okuması. Salı gayet iyi geçti. Perşembe günü hiç yapmadı. Pazar günkü iki dakikalık gözden geçirmede arkadaşının okuyacağı tarihin, kendi koyduğu tarihten daha çok harekete geçirdiğini not etti ve arkadaşının okumasını üç gün öne aldı."},sources:["task-aversiveness"]}},Z=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:H,SOURCES:K},Symbol.toStringTag,{value:"Module"})),Y=[{id:"sleep-cbti-overview",title:"Sleep Foundation · Newsom (Dimitriu, MD tarafından gözden geçirildi) · 2026 · Uykusuzluk için bilişsel davranışçı terapi (BDT-U) nasıl işler?",url:"https://www.sleepfoundation.org/insomnia/treatment/cognitive-behavioral-therapy-insomnia",type:"guidance",finding:"BDT-U’nun temel bölümlerini anlatır. Uyaran kontrolü, yatağı yalnızca uyku ve cinsellik için kullanmayı ve uyuyamadığında yataktan kalkmayı içerir. Bu sayfada yaklaşık 10 dakika önerilir. Amaç, yatak odasıyla uyanıklık arasındaki bağı azaltmaktır. Uyku kısıtlaması, uyku ihtiyacını artırmak için yatakta geçen süreyi sınırlar. Bipolar bozukluk ya da nöbet gibi uykusuzluğun ağırlaştırabileceği durumlarda önerilmez. Diğer bölümler uyku hijyeni, nefes egzersizleri ve aşamalı kas gevşetme gibi gevşeme yöntemleri ve bilişsel yeniden yapılandırmadır. Sayfa bir döngüyü de anlatır: kötü geçen geceler uyuyamama endişesi yaratır. Kişi uyumaya çalışarak yatakta daha uzun kalır ve uykuya dalmak daha da zorlaşır. BDT-U genellikle altı ila sekiz seans sürer. Dijital sürümleri de vardır.",limitation:"Bir araştırma değil, sağlık bilgi sitesinde tıbbi açıdan gözden geçirilmiş bir açıklamadır. Buradaki 10 dakika önerisi AASM’nin 20 dakika önerisinden farklıdır. Bu süreler kesin eşikler yerine uygulama önerileri olarak görülmelidir. Sayfadaki etkililik yüzdeleri adı verilen bir araştırmaya bağlanmadığı için bu kursta kullanılmaz."}],G={"sleep-1":{deeper:[{heading:"Önce neden kalkış saatini belirliyoruz?",paragraphs:["CDC ve AASM her gün aynı saatte kalkmanı önerir. AASM hafta sonlarını da özellikle belirtir. Ne zaman kalkacağını belirlemek, ne zaman uykuya dalacağını belirlemekten daha kolaydır. Bu yüzden sabit bir kalkış saati iyi bir başlangıçtır. Yatış saatini de buna göre planlayınca her gece farklı bir saatte yatmaktan kaçınabilirsin.","Yatağa girdiğin saatle kalktığın saat arasında kalan süre, uyumak için ayırdığın zamandır. Buna uyku penceresi denir. Kalkış saatinden geriye sayınca bu süreyi görebilirsin. 7 saatlik uykuya gerçekten yer ayırıp ayırmadığın da ortaya çıkar."],visual:{kind:"steps",title:"Kalkış saatinden geriye say",steps:[{label:"Kalkış saatini belirle",text:"Örneğin sabah 6.30; hafta içi ve hafta sonu aynı."},{label:"7 saat geriye say",text:"En geç 23.30’da uyumuş olman gerekir."},{label:"Uykuya dalma payı ekle",text:"Uykuya dalmak için de zaman ayır. Örneğin ışıkları 23.15 civarında kapat."},{label:"Bir hafta kontrol et",text:"Ne zaman yattığını ve kalktığını not et; gerekirse ayarla."}],note:"Bu bir planlama örneği, reçete değildir. En az 7 saat önerisi CDC ve AASM uzlaşısına dayanır. Uykuya dalma süresi kişiden kişiye değişir."}},{heading:"Bu sayılar neyi anlatıyor?",paragraphs:["7 saat önerisi, çok sayıda araştırmayı inceleyen uzmanların uzlaşısına dayanır. Araştırmaların büyük bölümü gözlemseldir. Bu, bir öneri için makul bir temeldir. Ama 6 saat 50 dakika uyumanın zararlı olduğunu ya da herkesin aynı miktarda uykuya ihtiyaç duyduğunu göstermez. CDC’nin önerdiği süreler de yaşa göre biraz değişir.","En çok haftalar boyunca nasıl uyuduğun önemlidir. Tek bir geceden sonuç çıkarma. Düzenli olarak önerilen sürenin epey altında kaldığını fark edersen bu bilgi işine yarar. Bu kurstaki adımlar, uyku düzeninin böyle yönlerini ele almana yardımcı olur."]}],example:{title:"Daniel, 41, depo amiri",text:"Daniel’in alarmı iş günlerinde 5.45’te çalıyordu. Hafta sonları ise 9’a kadar uyuyor, pazar gecesi geç saate kadar uyuyamıyordu. Vardiyası 7’de başladığı için her gün kalkabileceği saat olarak 6.15’i seçti. 7 saat geriye sayınca 23.15 çıktı. Uykuya dalmak için de zaman bırakıp ışıkları 23’te kapatmayı hedefledi. Bu iki saati dolap kapağının içine yapıştırdığı nota yazdı. Telefonunda da kısa bir kayıt tuttu. İlk cumartesi 6.15’te isteksizce kalktı, öğleden sonra kanepede kestirdi. İkinci hafta sonu daha kolay geçti. Pazar geceleri uyumak için artık o kadar uğraşmıyordu. Büyük bir değişiklik olmadı, ama haftaya başlamak biraz kolaylaştı."}},"sleep-2":{deeper:[{heading:"Rehberler ne öneriyor?",paragraphs:["Saygın üç kuruluşun önerdiği süreler biraz farklı. Bu fark, sürelerin kesin eşikler olmadığını hatırlatıyor. Ekranı 29 dakika önce kapatmak işe yaramaz, 31 dakika önce kapatmak işe yarar demiyorlar. Hepsinin önerisi aynı yönde: gündüz daha çok ışık almak, akşamın son bölümünde ışığı ve zihnini uyaran şeyleri azaltmak.","Ekrandan bir saat uzak kalmak zor geliyorsa 30 dakikayla başlayabilirsin. Bu süre de CDC ve AASM önerileriyle uyumlu. Fark görürsen daha sonra uzatabilirsin."],visual:{kind:"table",title:"Her rehberin önerisi",columns:["Rehber","Gündüz","Akşam"],rows:[["NSF","Sabah ya da öğleden sonra en az bir saat dışarıda","Işıkları kıs; ekranları yatmadan en az bir saat önce kapat"],["CDC","Belirtilmemiş","Ekranları yatmadan en az 30 dakika önce kapat"],["AASM","Belirtilmemiş","Ekranları yatmadan en az 30 dakika önce kapat"]],note:"NSF, CDC ve AASM’nin kamuya açık sayfalarından alındı. Bunlar uygulama önerileridir; araştırmada sınanmış kesin süre sınırları değildir."}},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hata, ya hep ya hiç diye düşünmek. İlk günden bir saat dışarı çıkmaya, bütün ekranları kapatmaya ve tüm akşam düzenini değiştirmeye çalışıp iki gün sonra vazgeçebilirsin. Sürdürebildiğin küçük bir değişiklik, yarım kalan kusursuz bir plandan daha yararlıdır.","Bir başka hata, telefonun yerine yapacak bir şey koymamak. Ekran çoğu zaman gerçek bir ihtiyacı karşılar: gevşemek, biriyle konuşmak ya da kaygılarından uzaklaşmak. Loş ışıkta kitap okumak, hafifçe esnemek ya da müzik dinlemek akşamını boş bırakmadan yeni bir düzen kurmana yardımcı olur."]}],example:{title:"Ana, 29, müşteri hizmetleri temsilcisi",text:"Ana bütün gün kapalı bir yerde çalışıyordu. Yatakta uykusu gelene kadar telefonunda gezinir, çoğu zaman gece yarısını geçirirdi. Her şeyi birden değiştirmedi. Hafta içi öğle molasının yaklaşık yirmi dakikasını ofisin dışındaki bir bankta geçirmeye başladı. Otobüs durağına kısa bir yürüyüş de ekledi. Akşam için 22.30’a, alıştığı yatış saatinden yarım saat öncesine bir hatırlatıcı kurdu. Telefonunu mutfakta şarja taktı. İlk birkaç gece huzursuz olduğu için komodinine bir roman ve küçük bir lamba koydu. Bazı akşamlar yine mesajlara baktı. İki hafta sonra telefon çoğu gece mutfakta kalıyordu. Uykuya dalmayı beklerken geçirdiği süre de biraz daha kolay geliyordu."}},"sleep-3":{deeper:[{heading:"Akşamını planla",paragraphs:["NHS, AASM ve CDC, bazı alışkanlıkları yatmadan ne kadar önce bırakmanı ve gevşemeye ne zaman başlamanı önerdiklerini belirtir. Bu önerileri tek bir çizelgede birleştirebilirsin. Birinci derste kalkış saatinden geriye saymıştın. Burada da yatış saatinden geriye sayarak akşamını planlıyorsun.","Aşağıdaki örnekte yatış saati 23.00. Sen başka saatte yatıyorsan bütün satırları aynı süre kadar kaydır. Her öneriyi aynı anda uygulaman gerekmez. Tek bir alışkanlık için net bir saat belirlemek iyi bir başlangıçtır."],visual:{kind:"table",title:"23.00’te yatacaksan akşam planın",columns:["Alışkanlık","Rehber","Saat"],rows:[["Çay, kahve, alkol, sigara","En az 6 saat önce (NHS)","17.00"],["Egzersiz","En az 4 saat önce (NHS)","19.00"],["Gevşemeye başlamak","En az 1 saat önce (NHS)","22.00"],["Ekranları kapatmak","En az 30 dakika önce (CDC, AASM)","22.30"]],note:"Süreler NHS uykusuzluk rehberiyle AASM ve CDC sayfalarından alındı. Saatler, bu önerilere göre hazırlanmış bir örnektir. Önerilen süreler araştırmada sınanmış kesin eşikler değildir."}},{heading:"Kendi izlenimin neden yanıltabilir?",paragraphs:["Drake çalışmasında insanların uykularına dair değerlendirmeleri ölçümlerle tam örtüşmedi. Öğleden sonra kahve içip rahatça uykuya dalabilirsin. Yine de kahve içmediğin bir geceye göre daha az uyumuş olabilirsin. Bu yüzden yalnızca izlenimine güvenmek yerine küçük bir deney yap. Bir hafta boyunca son kahveni daha erken iç ve sabah nasıl hissettiğine bak.","Kafein yalnızca kahvede bulunmaz. Siyah çay, yeşil çay, kola ve enerji içeceklerinde de farklı miktarlarda vardır. Bir gün boyunca içtiklerini yazmak şaşırtıcı olabilir. Birkaç küçük içecek, tek bir sert kahveden daha fazla kafein içerebilir."]}],example:{title:"Tom, 38, lise öğretmeni",text:"Tom, kafeinin kendisini etkilemediğini düşünüyordu. Kahvaltıda ve öğle yemeğinde kahve içiyordu. Saat 19.00 civarında sınav kâğıtlarını okurken de kola içiyordu. Bir gün boyunca kafein içeren bütün içeceklerini yazdı. Akşam içtiği kola onu şaşırttı. Yatış saati 23’tü. 6 saat geriye sayıp son kafein saatini 17.00 olarak belirledi. Akşam kolası yerine gazlı su içmeye başladı. Koşusunu da 20.00’den okul çıkışına aldı. İlk akşamlar kâğıt okurken kolanın verdiği kısa süreli canlılığı özledi. Yaklaşık on gün sonra biraz daha erken uykuya daldığını fark etti. Bazı geceler hâlâ huzursuzdu, ama değişikliği sürdürmeye değer buldu."},sources:["sleep-habits","cdc-sleep"]},"sleep-4":{deeper:[{heading:"Endişe–uyanıklık döngüsü",paragraphs:["Uykusuzluk için bilişsel davranışçı terapiyi (BDT-U) anlatan kaynaklar, tanıdık bir döngüden söz eder. Birkaç kötü gecenin ardından uyuyamamaktan endişelenirsin. Telafi etmek için yatakta daha uzun kalır, uykuya dalmaya daha çok çalışırsın. Ama bu çaba ve endişe seni uyanık tutar. Yatak da zamanla dinlendiğin bir yerden çok sıkıntı çektiğin bir yer hâline gelir. Sonraki gece uyumak daha da zorlaşır.","Yataktan kalkmak bu döngüden çıkmanın bir yoludur. Böylece uyumaya çalışırken yaşadığın sıkıntı yatakla eşleşmez. Zamanla yatak yeniden uykuyu hatırlatan bir yer olabilir. BDT-U’nun bu bölümüne uyaran kontrolü denir."],visual:{kind:"cycle",title:"Endişe–uyanıklık döngüsü",center:"Uyumak için daha çok çabalamak",nodes:[{label:"Kötü bir gece",text:"Bir kez ya da birkaç kez kötü uyursun."},{label:"Endişe",text:"“Bu gece uyuyamazsam yarın felaket olur.”"},{label:"Yatakta daha çok zaman",text:"Uykuyu zorlamak için erken yatar ya da yatakta daha uzun kalırsın."},{label:"Uyanık kalırsın",text:"Çaba ve hayal kırıklığı zihnini uyanık tutar."},{label:"Yatakla sıkıntı eşleşir",text:"Yatağı, uyanık kalıp uyumaya çalıştığın bir yer olarak görmeye başlarsın."}],note:"BDT-U kaynaklarında anlatılan döngüye dayanır. Uyuyamadığında yataktan kalkmak ve her gün aynı saatte kalkmak bu döngüyü kırmaya yardımcı olabilir."}},{heading:"Sakin köşende ne yapabilirsin?",paragraphs:["Amaç zamanını verimli geçirmek değil, uykunun yeniden gelmesini beklemek. İstediğin an bırakabileceğin sakin bir uğraş seç. BDT-U programlarında yavaş nefes alma ve aşamalı kas gevşetme gibi yöntemler de öğretilir. Kas gevşetmede kas gruplarını tek tek gerip bırakırsın. Bu yöntemler de burada uygun olabilir.","Farklı rehberler yaklaşık 10, 15 ya da 20 dakika sonra kalkmayı öneriyor. Sana uygun bir süre seç. Saati izlemek yerine ne kadar zaman geçtiğini yaklaşık olarak tahmin et."],visual:{kind:"compare",title:"Gece yataktan kalktığında",left:{label:"Yardımcı olabilecekler",items:["Loş ışık, sessiz bir yer","Sıkıcı bir kitap ya da dergi","Yavaş nefes ya da hafif esneme"]},right:{label:"Seni uyanık tutabilecekler",items:["Telefon, dizüstü bilgisayar ya da TV","Sürekli saate bakmak","Çalışmak ya da yarını ayrıntılı planlamak"]},note:"AASM önerileriyle BDT-U kaynaklarında anlatılan gevşeme yöntemlerine dayanır."}}],example:{title:"Nadia, 52, muhasebeci",text:"Vergi döneminde Nadia bir saat boyunca yatakta uyuyamıyordu. Aklı işteydi, sürekli saate bakıyordu. Oturma odasında sakin bir köşe hazırladı. Küçük bir lamba, battaniye ve biraz sıkıcı bulduğu eski bir gezi kitabı koydu. Salı gecesi uzun süredir uyanık olduğunu fark edince saate bakmadan kalktı. Birkaç sayfa okudu, yavaşça nefes aldı. Gözleri ağırlaşınca yatağa döndü. Uykuya dalmadan önce bir kez daha kalkması gerekti. Sabah yorgun olsa da planladığı gibi 6.45’te kalktı. Haftanın sonunda yatakta uyanık geçirdiği uzun süreler tamamen bitmemişti, ama kısalmıştı."},sources:["sleep-cbti-overview"]},"sleep-5":{deeper:[{heading:"BDT-U neleri içerir?",paragraphs:["BDT-U, genellikle bu alanda eğitimli bir uzmanla yaklaşık altı ila sekiz seans süren yapılandırılmış bir programdır. Dijital sürümleri de vardır. Birkaç bölümden oluşur. Uyaran kontrolü gibi bazı bölümleriyle bu kursta basitleştirilmiş biçimde karşılaştın.","Uyku kısıtlaması denen bölümde, uyku ihtiyacını artırmak için yatakta geçen süre bir süreliğine azaltılır. Uykusuzluğun ağırlaştırabileceği bipolar bozukluk ya da nöbet gibi durumlarda önerilmez. Bu nedenle uyku kısıtlaması kendi kendine yardım kursunda uygulanacak bir yöntem değildir; bir uzmanla ele alınmalıdır."],visual:{kind:"table",title:"BDT-U’nun ana bölümleri",columns:["Bölüm","Neleri içerir"],rows:[["Uyaran kontrolü","Yatak yalnızca uyku ve cinsellik için; uyuyamadığında kalk"],["Uyku kısıtlaması","Yatakta geçen süreyi geçici olarak sınırlamak; bir uzmanla yapmak en iyisidir"],["Gevşeme","Nefes egzersizleri, aşamalı kas gevşetme ve benzeri yöntemler"],["Bilişsel çalışma","Uykuya dair kaygıları ve gerçekçi olmayan beklentileri incelemek"],["Uyku hijyeni","Alışkanlıkların, beslenmenin, egzersizin ve yatak odasının uykuyu nasıl etkilediği"]],note:"Tıbbi açıdan gözden geçirilmiş bir BDT-U açıklamasından özetlendi. Bu kurs BDT-U değildir. Yalnızca kendi başına deneyebileceğin birkaç basit fikrinden yararlanır."}},{heading:"Ne zaman doktora başvurmalısın?",paragraphs:["Bazı uyku sorunları alışkanlıklarla ilgilidir. Bu kurstaki adımlar yardımcı olabilir. Bazıları ise uzman değerlendirmesi gerektirir. Uykusuzluğun uzun sürmesi, uyku apnesi işaretleri ya da günlük hayatı zorlaştıran gündüz uykululuğu varsa randevu al. Böyle bir durumda tek başına daha çok çabalamak yeterli olmayabilir.","Araba kullanırken uyanık kalmakta zorlanacak kadar uykuluysan araba kullanma. Kısa süre içinde doktora başvur. Yatış ve kalkış saatlerinle gece uyanmalarını iki hafta kaydetmen görüşmeyi kolaylaştırır. Doktorunun da durumunu daha iyi anlamasına yardımcı olur."],visual:{kind:"compare",title:"Ne zaman kendi başına deneyebilirsin, ne zaman yardım almalısın?",left:{label:"Kendi başına denemeye değer",items:["Düzensiz program ya da geç saatte ekran","Günün geç saatlerinde kafein","Stresli bir günün ardından ara sıra kötü geceler"]},right:{label:"Doktora başvur",items:["3 aydan uzun süredir haftada en az 3 gece uykusuzluk","Yüksek sesli horlama ve nefes duraklamaları, nefes nefese kalma ya da boğulma hissi","İşi, günlük yaşamı ya da araba kullanmayı etkileyen gündüz uykululuğu"]},note:"ACP rehberinden ve NHS uykusuzluk ile uyku apnesi sayfalarından. Bu bir tanı kontrol listesi değildir."}}],example:{title:"Karen, 58, okul kütüphanecisi",text:"Karen yılın büyük bölümünde iyi uyuyamamıştı. Öğleden sonranın başında bile bitkin hissediyordu. Kalkış saatini sabitlemiş, geç saatte çay içmeyi bırakmıştı. Bunlar biraz yardımcı oldu, ama yetmedi. Bir sabah eşi, bazen nefesinin bir an durduğunu, ardından horlama sesi çıkardığını söyledi. Karen bunu bilmiyordu. O hafta yatış ve kalkış saatleriyle kaç kez uyandığını kaydetti. Eşinden de fark ettiklerini yazmasını istedi. Doktorundan randevu aldı. İki notu da ilaçlarının listesiyle birlikte götürdü. Kendi başına hiçbir şeyi değiştirmedi. Doktor onu uyku değerlendirmesine yönlendirdi. Sırada ne yapacağını bildiği için görüşmeden rahatlamış çıktı."},sources:["sleep-cbti-overview"]}},W=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:G,SOURCES:Y},Symbol.toStringTag,{value:"Module"})),x=[],w={"suggestion-1":{deeper:[{heading:"Beklenti gerçektir ve sınırları vardır",paragraphs:["Grafikteki etki hayalî değil. Güvendiğin biri bir işlemin daha az acıtacağını söylediğinde, gerçekten daha az ağrı hissedebilirsin. Beklenti, dikkatini nereye verdiğini, bedeninin ne kadar gerildiğini ve bir duyumu nasıl yorumladığını etkiler. Bu gerçek bir etkidir ve yararlı olabilir.","Yine de çalışmaların neyi ölçtüğüne dikkat et: ağrıyı, yani kişinin hissettiği ve bildirdiği bir deneyimi. Beklentinin tümörü küçülttüğünü, kan şekerini düşürdüğünü ya da enfeksiyonu iyileştirdiğini göstermiyorlar. Coué’nin bedensel hastalıkları iyileştirme iddiaları da desteklenmiyor. Telkin, zor bir anı nasıl yaşadığını ve sonrasında ne yaptığını etkileyebilir. Ama tıbbi bakımın yerini tutmaz."],visual:{kind:"compare",title:"Telkin nerede yardımcı olabilir, nerede olamaz",left:{label:"Etkileyebilir",items:["Zor bir andan önce ne kadar gergin hissettiğini","Ağrı gibi bir duyumun ne kadar güçlü hissedildiğini","Dikkatinin nereye gittiğini","Bir sonraki küçük adımın ne olduğunu"]},right:{label:"Yerine geçemez",items:["İlacın ya da tıbbi tedavinin","Bir belirtinin tanısının","Başkalarının kararlarının","Alıştırma ve hazırlığın"]},note:"Ağrı çalışmalarında telkinleri araştırmacılar ya da klinisyenler verdi. Kendi kendine telkin ayrıca sınanmadı."}},{heading:"Coué’nin fark ettiği döngü",paragraphs:["Coué hastalarında bir döngü fark etti: gergin olmamak için kendilerini ne kadar zorlarlarsa o kadar geriliyorlardı. Uyumaya ya da yüzünün kızarmasını engellemeye çalışırken benzerini yaşamış olabilirsin. Çabaladıkça dikkatin, kurtulmak istediğin şeye yönelir. Bu dikkat de onu güçlendirebilir.","Coué bunu bir yasa saydı. Oysa sık karşılaşılan bir durumu anlatan gözlem olarak düşünmek daha doğru. Kanıtlanmış bir kural değil. Yine de cümleni kendini zorlamadan, sakince söyleyip sonra bırakmanı neden önerdiğimizi açıklıyor."],visual:{kind:"cycle",title:"Zorlama döngüsü",center:"Çok fazla çaba",nodes:[{label:"Gerilme",text:"Kendine sertçe “Gergin olma” dersin."},{label:"Gözleme",text:"Gerginlik belirtilerini aramaya başlarsın."},{label:"Bulma",text:"Kalbinin hızlı atması ya da ağzının kuruması bütün dikkatini çeker."},{label:"Endişe",text:"Bu işaretleri, çabanın işe yaramadığının kanıtı gibi görürsün."},{label:"Daha çok zorlama",text:"Daha da çok zorlarsın ve döngü yeniden başlar."}],note:"Coué’nin gözlemi, bizim sözlerimizle yeniden anlatıldı; deneysel olarak kanıtlanmış bir yasa değildir."}}],example:{title:"Leyla, 34, diş hijyenisti",text:"Leyla pazartesi ekip toplantılarından önce kendine sertçe “Bu sefer telaşlanma” derdi. Konuşma sırası geldiğinde yüzü ısınır, sözlerini aceleyle söylerdi. Pazar günü dersi denedi. Kendini zorladığı cümleyi yazıp yanına daha yumuşak bir cümle ekledi: “Acele etmeden konuşabilirim.” Toplantıdan önce omuzlarını gevşetti, üç yavaş nefes aldı. Yeni cümleyi sessizce söylerken söze başlamadan önce durduğunu hayal etti. Yüzü yine biraz ısındı. Ama konuşurken bir kez durduğunu ve sözlerini sırayla söylediğini fark etti. Sonra telefonuna tek satır yazdı: “Çenemi daha az sıktım.” Büyük bir değişim olmadı, ama toplantı biraz daha rahat geçti."}},"suggestion-2":{deeper:[{heading:"Sade bir cümle neden yine de işe yarayabilir",paragraphs:["Bu cümle bilerek sade tutulmuş. Sakin bir ses ve birkaç dakika dışında senden bir şey istemiyor. Bu yüzden tekrarlaması kolay. Lally ve arkadaşlarının alışkanlık çalışmasında, aynı ortamda tekrarlanan davranışlar giderek daha az düşünerek yapılır hâle geldi. Bunun süresi kişiden kişiye çok değişti. Arada bir günü kaçırmak ise süreci bozmadı.","Cümleyi uyanmaya ve yatmaya bağlayarak küçük, düzenli bir alışkanlık oluşturabilirsin. Ruh hâlini nasıl etkilediğini sen gözlemleyeceksin; araştırma bunun için bir sonuç vaat etmiyor. Bazı insanlar sakinleştirici bulur. Bazıları başta tuhaf bulur, birkaç gece sonra alışır."],visual:{kind:"cycle",title:"Aynı ana bağlanmış bir ritüel",center:"Aynı zaman, aynı yer",nodes:[{label:"İpucu",text:"Uyanırsın ya da gece yatağa uzanırsın."},{label:"Rutin",text:"Düğümler ya da boncuklarla sayılan yirmi sakin tekrar."},{label:"An",text:"Güne başlamadan ya da uykuya dalmadan kısa bir sakinlik molası."},{label:"Tekrar",text:"Yarın aynı ipucu, başlamayı kolaylaştırır."}],note:"Aynı bağlamda tekrar, bir davranışı zamanla daha otomatik hâle getirir (Lally ve ark., 2010). Formülün kendi etkisi sınanmadı."}},{heading:"Sık yapılan hatalar",paragraphs:["İnsanlar bu cümleyi bir sınav gibi görürse uygulama zorlaşabilir. Yüksek sesle söyler, her tekrardan sonra bir şey değişti mi diye kontrol eder ya da dikkati dağılınca kendine kızar. Coué bunların her birinin tersini önerdi."],visual:{kind:"table",title:"Sık yapılan hatalar ve daha nazik alternatifler",columns:["Hata","Daha nazik alternatif"],rows:[["Yüksek sesle ve zorlayarak söylemek","Alçak, aynı tonda bir ses, neredeyse mırıltı"],["Her tekrarda bir şey değişti mi diye bakmak","Sayımı düğümlere bırak; bir hafta sonra gözden geçir"],["Zihni dağılınca kendini azarlamak","Fark et ve cümleye geri dön"],["Hekime gitmek yerine kullanmak","İhtiyaç duyduğun tıbbi bakımın yanında uygula"]]}}],example:{title:"Sami, 42, otobüs şoförü",text:"Sami erken vardiya günlerinde sabah 4.30’da uyanıyor, hemen trafiği düşünmeye başlıyordu. Tespih çeken kız kardeşi ona yirmi boncuklu kısa bir tespih ödünç verdi. Salı gecesi yatağa uzandı. Cümleyi yirmi kez mırıldanırken her seferinde bir boncuk ilerletti. İki kez sayıyı karıştırdı, ama devam etti. Çarşamba sabahı yataktan kalkmadan yine denedi. Yaklaşık iki dakika sürdü. Büyük bir değişim hissetmedi. Ama aklına ilk gelen şey çevre yolu yerine sakin bir cümleydi. Yapışkan bir nota “Güne daha az telaşla başlamak” yazdı. Cuma bunu düşünmeden yapıyordu. Cumartesi ise tamamen unuttu ve bunu sorun etmemeye karar verdi."}},"suggestion-3":{deeper:[{heading:"İnanmadığın bir cümle neden ters tepebilir?",paragraphs:["Popüler öğütlerde sık sık, olumlu cümleyi inanana kadar tekrarlaman söylenir. Wood’un deneyleri bunun bir sınırı olabileceğini gösteriyor. Kendileri hakkında zaten iyi hissedenlere cümle uydu ve biraz iyi geldi. Böyle hissetmeyenlerde ise her tekrar, içten gelen bir “Bu doğru değil” itirazını uyandırmış gibiydi. Cümleyle kişinin kendini nasıl gördüğü arasındaki fark daha belirgin oldu.","Bu tek bir cümleydi ve öğrencilerle birkaç dakika boyunca denendi; yani tüm olumlamaların zararlı olduğunu göstermez. Ama basit bir kontrol öneriyor: bir cümle seni rahatsız ediyorsa, inanabileceğin kadar ölçülü hâle getir."],visual:{kind:"cycle",title:"İnanmadığın bir cümle nasıl ters tepebilir",center:"Aradaki fark",nodes:[{label:"İddialı cümle",text:"“Kendime tamamen güveniyorum.”"},{label:"İç itiraz",text:"İçinden “Bu doğru değil” diye geçirirsin."},{label:"Karşı kanıt",text:"Tersine dair anılar akla gelir."},{label:"Daha kötü ruh hâli",text:"Cümleyle kendin hakkındaki düşüncen arasındaki fark gözüne daha büyük görünür."}],note:"Araştırmacıların sunduğu olası bir açıklama; adım adım ölçtükleri bir şey değil. Etki, özsaygısı düşük kişilerde görüldü."}},{heading:"Değerler üzerine araştırma ne diyor",paragraphs:["Öz-onaylama, kendin hakkında güzel şeyler söylemekten farklıdır. Sende olmadığını düşündüğün bir özelliğe sahip olduğunu iddia etmezsin. Aile, dürüstlük ya da inanç gibi önemsediğin bir değer üzerine yazarsın. Neden önemli olduğunu anlatırsın. Amaç, eleştiri ya da korkutan bir sağlık mesajıyla karşılaştığında kendini yalnızca o tehditle tanımlamamak. Böylece kendine daha geniş açıdan bakabilirsin.","Etkiler küçük. Birçok deneyde, değerleri üzerine yazan kişiler sağlık mesajlarına biraz daha açık oldu. Sonrasında davranışlarını değiştirme olasılıkları da arttı; bu etki biraz daha belirgindi. Zamanlama önemliydi. Okullardaki bazı büyük denemelerde önceki sonuçlar tekrarlanmadı."],visual:{kind:"bars",title:"Öz-onaylama ve sağlık davranışı",bars:[{label:"Mesajı kabul etme (34 test)",value:.17,display:"d = 0,17"},{label:"Değişim niyeti (64 test)",value:.14,display:"d = 0,14"},{label:"Sonraki davranış (46 test)",value:.32,display:"d = 0,32"}],note:"Epton ve ark. (2015), 144 deneysel test. Küçük etkiler, çoğunlukla bir sağlık mesajıyla birlikte ölçüldü; tek başına değer yazısı ve bu kurs sınanmadı.",sourceId:"self-affirmation-health"}}],example:{title:"Pınar, 27, genç muhasebeci",text:"Pınar aynasına “İşimde harikayım” yazan bir not yapıştırmıştı. Her sabah okuduğunda içi biraz burkuluyordu. Çünkü geçen hafta bir raporda hata yapmıştı. Perşembe günü cümleye ne kadar inandığını puanladı: on üzerinden üç. Notu değiştirdi: “Bu işi öğreniyorum ve işimi kontrol ediyorum.” Yeni cümleye yedi puan verdi. En çok önemsediği değer olan dürüstlük üzerine de on dakika yazdı. Yakın zamanda yöneticisine bir hatasını açıkça anlattığı anı düşündü. Ertesi sabah yeni not ona kendini harika hissettirmedi. Ama artık içini burkmuyordu. Bir değerlendirme toplantısından önce dürüstlük üzerine yazısını yeniden okudu. Toplantıya kendinden biraz daha emin girdi."}},"suggestion-4":{deeper:[{heading:"Adını kullanmak neden mesafe sağlar?",paragraphs:["“Ben” diyerek düşündüğünde durumu içeriden yaşarsın. Duyumların ve korkuların sana çok yakındır. Adını kullandığında ise başkasına seslenirken kullandığın dili kullanırsın. Bir arkadaşının sorununa çoğu zaman daha geniş açıdan bakabiliriz. Kendi adını kullanmak, kendine de bu açıdan bakmanın kısa bir yoludur.","Kross bunu ve ilişkili birkaç aracı Chatter kitabında anlatıyor: olayı bir yıl sonra nasıl göreceğini hayal etmek, onun hakkında yazmak ya da güvendiğin biriyle konuşmak. Hepsinde, olaydan bir adım geri çekilip bakarsın. Farklı anlarda farklı yöntemler işe yarayabilir."],visual:{kind:"steps",title:"İki dakika ayırıp dışarıdan bak",steps:[{label:"Ad",text:"Kendine seslen: “Ali, şu an neler oluyor?”"},{label:"Betimle",text:"Olanı “ben” değil “sen” diyerek söyle."},{label:"Öğüt ver",text:"Aynı durumdaki bir arkadaşına ne söylerdin, onu söyle."},{label:"Uzaklaş",text:"Bunun bir yıl sonra sana nasıl görüneceğini sor."},{label:"Sonraki adım",text:"Bir sonraki dakika için tek bir somut eylemle bitir."}],note:"Ethan Kross’un araçlarından uyarlandı. Laboratuvar çalışmaları ad ya da “sen” kullanmayı sınadı; diğer adımlar birlikte sınanmadı."}},{heading:"Sert değil, şefkatli",paragraphs:["Kendine dışarıdan bakarken şefkatli olmak da yardımcı olur. “Ali, aptalın tekisin” demek adını içerir, ama kendini eleştirmeyi sürdürürsün. Onlarca denemeyi inceleyen bir derlemede, öz şefkat uygulamaları kısa vadede stresi ve kaygıyı küçük ile orta düzeyde azalttı. Öz şefkat, kendine bir arkadaşına göstereceğin nezaketle davranmaktır. Yine de denemelerin çoğunda zayıf yönler vardı.","Basit bir kontrol yapabilirsin: bu cümleyi, bu tonla, sevdiğin birine söyler miydin? Yanıtın hayırsa, sözcükleri değiştirmeden önce tonu değiştir."]}],example:{title:"Metin, 38, hemşire",text:"Metin, gözünü korkutan yeni sorumlu hemşireye kısa bir devir teslim yapacaktı. Servise yürürken aklından şu geçiyordu: “Bunu berbat edeceğim. Hep bir şeyi unutuyorum.” Malzeme odasında iki dakika durup dersi fısıltıyla denedi: “Metin, bunu doğru yapmak istediğin için gerginsin. Yüz kez devir teslim yaptın.” Sonra genç bir meslektaşına ne söyleyeceğini düşündü: “En ağır hastayla başla, sırayla git.” Bunu kendine de söyledi. Devir teslim kusursuz değildi. Bir tahlil sonucunu unutup sonunda ekledi. Genellikle sonrasında bir saat boyunca olanları tekrar tekrar düşünürdü. Bu kez böyle yapmadığını fark etti."}},"suggestion-5":{deeper:[{heading:"Yönlendirici mi, motive edici mi?",paragraphs:["İkisinin de yeri var. Yönlendirici ipuçları dikkatini tek bir ayrıntıya çeker. İş yeni ya da hassas olduğunda, dikkatin dağıldığında veya gerildiğinde işe yarayabilir. Motive edici ipuçlarıysa çabanı sürdürmene daha çok yardımcı olur. Koşunun son kısmında ya da öğleden sonra onuncu e-postanı yazarken bunları deneyebilirsin.","Şöyle seçebilirsin: işi öğreniyorsan ya da dikkatle yapman gerekiyorsa kısa bir talimat kullan. Ne yapacağını biliyor ama isteğin azalıyorsa cesaret veren bir cümle seç. Her iki durumda da ipucun tek nefeste söyleyebileceğin kadar kısa olsun."],visual:{kind:"table",title:"Gündelik işler için ipucu kelimeleri",columns:["İş","Yönlendirici ipucu","Motive edici ipucu"],rows:[["Rapor yazmak","Önce taslak","Devam et"],["Toplantıda konuşmak","Yavaş ve net","Hazırsın"],["Araba kullanmayı öğrenmek","Ayna, sinyal","Sakin"],["Yeni bir yemek tarifi denemek","Tadına bak","Keyfini çıkar"]],note:"Bunlar yalnızca örnek. Spor ve hareket gerektiren görevleri kapsayan meta-analizde sınanmadılar."}},{heading:"Gallwey bunu nasıl yapıyor",paragraphs:["Tenis antrenörü Tim Gallwey, oyuncuların kendilerine uzun uzun öğüt verdiklerinde çoğu zaman daha kötü oynadığını fark etti. Yargılayan sese Benlik 1, öğrenen bedene Benlik 2 adını verdi. Daha fazla talimat yerine dikkati basit bir şeye yöneltmeyi önerdi: top yere değdiğinde “sekme”, raketle buluştuğunda “vuruş” demek. Sonra olanı iyi ya da kötü diye yargılamadan izlemek.","Araştırmalar Gallwey’nin yöntemini tek başına sınamadı. Ama yöntem, meta-analizde dikkati yönlendiren kısa ipuçlarına ilişkin bulgularla uyumlu. Hatalara da kendini azarlamadan bakmanı sağlar. Kendin hakkında bir yargıya varmak yerine bir dahaki sefere dikkat edeceğin tek bir şey seçersin."],visual:{kind:"compare",title:"Benlik 1 mi, basit bir ipucu mu?",left:{label:"Yargılayan ses (Benlik 1)",items:["“Bu berbattı.”","Aynı anda yapılacak beş düzeltme listesi","Gerginlik ve fazla düşünme"]},right:{label:"Basit ipucu",items:["Tek bir ana bağlanmış tek bir kelime","Olanı izlemek","Bir dahaki sefere fark edilecek tek şey"]},note:"Gallwey’nin anlatımı, bizim sözlerimizle. Yöntemin kendisi meta-analizlerde ayrıca sınanmadı."}},{heading:"İpucunu ihtiyaç duymadan önce dene",paragraphs:["Meta-analizde en açık sonuçlardan biri şuydu: iç konuşmayı önceden deneyen programlar, denemeyenlerden daha iyi işledi. İhtiyaç duyduğunda ipucu zaten tanıdıksa kullanman kolaylaşır. Önce kolay bir işte dene, sonra zorlandığın yerde kullan."]}],example:{title:"Aylin, 45, okul idari görevlisi",text:"Aylin işte yeni bir elektronik tablo sistemini öğreniyordu. Veri girerken küçük hatalar yapıyor, sonra kendini azarlıyordu. İki ipucu seçti: dikkatini yönlendirmek için “Sütunu kontrol et”, devam etmek için “Her seferinde bir satır”. Pazartesi gerçek işe başlamadan önce on kolay satırla denedi. Her yazışında önce “Sütunu kontrol et” dedi. Sonra asıl işe geçti. Elli satırda yine iki hata yaptı. Bu, her zamankinden azdı. Hataları görünce kendine dikkatsiz demedi. Defterine yalnızca “Tarihlere dikkat” yazdı. Çarşamba bunu yeni ipucu olarak ekledi. Küçük bir değişiklikti, ama öğleden sonra kendini sınavdaymış gibi daha az hissetti."}},"suggestion-6":{deeper:[{heading:"Uyku ne yapar, ne yapmaz",paragraphs:["Uyurken belleğin çalışmaya devam eder. Paller ve arkadaşlarının derlemesine göre, gün içinde oluşan anılar gece yeniden etkinleşir ve pekişir. Bu, sorun çözmeye ve duyguları düzenlemeye yardımcı olabilir. Yatmadan önceki kısa, sakin bir prova da gün içinde alıştırdığın son şeylerden biri olabilir.","Uyku sırasında gerçekten yeni bilgi öğrenmek, çok basit öğrenme türleriyle sınırlıdır. Derlemede, endişeleri tekrar tekrar düşünmenin zararlı olabileceği de belirtiliyor. Murphy’nin kitabında bilinçaltı, verilen her isteği yerine getiriyormuş gibi anlatılır. Araştırmalarda desteklenen ise alıştırmayla değişen alışkanlıklar, dikkat ve bellektir."],visual:{kind:"compare",title:"Uyku ve telkin: kanıtlarla uyumlu olanlar",left:{label:"Kanıtlarla uyumlu",items:["Yatmadan önce ilk adımı prova etmek","Kısa bir cümleyi sakince tekrarlamak","Gündüz alıştırdıklarının uykuda pekişmesi"]},right:{label:"Desteklenmiyor",items:["Bilinçaltının para ya da sağlık getirmesi","Uykuda karmaşık yeni beceriler öğrenmek","Düşüncenin hastalığı iyileştirmesi"]},note:"Uyku öncesi telkini doğrudan sınamayan Paller, Creery ve Schechtman (2021) derlemesine dayanır."}},{heading:"Engeli neden plana eklemelisin?",paragraphs:["Hoş bir hayal kurmak ilerleme gibi gelebilir. Kappes ve Oettingen’in deneylerinde, kusursuz bir geleceği hayal edenlerin sonrasında enerjisi daha düşüktü. Bir çalışmada sonraki hafta daha az iş yaptılar. Zihin, hedefe zaten ulaşılmış gibi rahatlıyor olabilir.","Çözüm hayal etmeyi bırakmak değil, iki adım eklemek. Sonucu gördükten sonra, sana engel olabilecek temel düşünce veya duyguyu belirle ve onu bir eğer-öyleyse planına bağla. 21 çalışmada bu birleşim, hedeflere ulaşmada küçük–orta bir ortalama etki gösterdi."],visual:{kind:"steps",title:"Akşam sahnesinden sabah planına",steps:[{label:"Dilek",text:"Uykun gelirken yavaşça tekrarlanan kısa bir cümle."},{label:"Sahne",text:"Bir arkadaşının seni tebrik etmesi gibi sonucun kısa bir görüntüsü."},{label:"Engel",text:"Sabah: hangi düşünce veya duygu sana engel olabilir?"},{label:"Plan",text:"“Eğer … olursa, … yapacağım.”"}],note:"İstenen geleceği engel ve bir eğer-öyleyse planıyla eşleştirmek, 21 çalışmada g = 0,336’lık bir ortalama etki gösterdi (Wang, Wang & Gai, 2021)."}},{heading:"Zihnin endişeye kayarsa",paragraphs:["Bazı geceler cümle, ters gidebilecek her şeyin listesine kayar. Bu, tekniğin başarısız olduğu anlamına gelmez. Sahneyi bırak, gerekirse endişeyi yatağın yanındaki bir not defterine yaz ve yavaş nefese dön. Uyku, alıştırmadan daha önemli. Endişe çoğu gece seni uyanık tutuyorsa, bir hekimle konuşabilirsin."]}],example:{title:"Tuna, 33, genç mimar",text:"Tuna’nın cuma günü bir tasarım değerlendirmesi vardı ve geceleri felaket senaryolarını prova edip duruyordu. Çarşamba günü dersi denedi. Dileğini “Değerlendirme sorunsuz geçti” cümlesine indirdi ve bir karta yazdı. Yatakta, uykusu gelirken bunu yavaşça tekrarladı ve meslektaşı İnci’nin “Vaziyet planında iyi iş çıkarmışsın” dediğini canlandırdı. Sahne bitmeden uyudu. Perşembe sabahı gerçek engeli yazdı: “Biri bana soru sorunca acele ediyorum.” Ve planı: “Biri bir ayrıntıya itiraz ederse durup soruyu tekrarlayacak ve bildiğim kısmı cevaplayacağım.” Cuma günü ortaklardan biri otopark yerleşimine gerçekten itiraz etti. Tuna biraz beceriksizce duraksadı ve cevap verdi. Değerlendirme kusursuz değildi, ama prova ettiği felaket de değildi."}},"suggestion-7":{deeper:[{heading:"Kartın parçaları birlikte nasıl çalışır?",paragraphs:["Kartın her parçasının ayrı bir görevi var. Cümle, kendine nasıl seslendiğini belirler. Görüntü ilk adımını gösterir. Plan, zorlandığın an için ne yapacağını hatırlatır. Belirlediğin saat de uygulamayı alışkanlık hâline getirmene yardım eder. Bunları bir hafta boyunca birlikte deneyip sonra ihtiyacına göre ayarlayabilirsin.","Araştırmalar bu döngünün her parçasını aynı ölçüde desteklemiyor. En açık destek, eğer-öyleyse planlarıyla ilerlemeyi izlemeye ait. Zihinsel provanın etkisi küçük. Cümle ise çoğunlukla kendi önüne engel koymanı azaltarak yardımcı oluyor."],visual:{kind:"cycle",title:"Haftalık bir döngü olarak telkin kartı",center:"Kartın",nodes:[{label:"Cümle",text:"İnanabileceğin, belki adınla başlayan bir cümle."},{label:"Görüntü",text:"İlk adımının kısa bir sahnesi."},{label:"Plan",text:"Engel çıkarsa ne yapacağını bilirsin."},{label:"Eylem",text:"O gün gerçekten attığın küçük adım."},{label:"Gözden geçirme",text:"7 gün sonra: koru, değiştir ya da küçült."}],note:"Döngü önceki derslerdeki araçları birleştirir; kartın bütünü tek bir yöntem olarak sınanmadı."}},{heading:"Ayna çalışması, nazikçe",paragraphs:["Louise Hay ayna çalışmasını yaygınlaştırdı. Aynada kendine bakıp nazik bir cümle söylersin. Bazı insanlar duygulanır, bazıları ise bunu dayanılmaz bulur. Her iki tepki de olağandır. Kimlere yardımcı olduğunu gösteren kontrollü bir araştırma yok.","Wood’un deneylerini düşünerek aynayı zorunlu bir görev yerine bir deneme olarak kullan. Kendi gözlerine bakınca cümle daha inandırıcı geliyorsa devam et. İçinden daha güçlü bir “Hayır” geliyorsa kâğıttan oku ya da önce cümleyi yumuşat."]},{heading:"Suçlamadan gözden geçirmek",paragraphs:["Gözden geçirme, uygulamayı kendine göre ayarlamana yardım eder. İnsanların ilerlemelerini daha sık kontrol etmesini sağlayan çalışmalarda, hedeflere ulaşmada ortalama olarak orta düzeyde yarar görüldü. İlerlemeyi kâğıda ya da ekrana kaydetmek, yalnızca akılda tutmaktan daha çok yardımcı oldu. Yanıtlarını kısa da olsa yaz."],visual:{kind:"table",title:"7 günlük gözden geçirme için sorular",columns:["Soru","Evetse","Yanıtın hayırsa"],rows:[["Kartı günlerin çoğunda okudum mu?","Saati olduğu gibi tut","Diş fırçalamak gibi daha sağlam bir ipucuna bağla"],["Cümleye inandım mı?","Tut","Daha küçük ve süreç odaklı yap"],["Engel geldiğinde plan devreye girdi mi?","Planı koru","“Eğer” kısmını daha belirgin yap"]],note:"İlerlemeyi izlemek, Harkin ve ark. (2016) çalışmasında ortalama olarak hedefe ulaşmayı destekledi (d = 0,40); bu belirli sorular sınanmadı."}}],example:{title:"Hande, 51, eczane teknisyeni",text:"Hande akşamları yürümek istiyor, ama kendini hep kanepede buluyordu. Küçük bir kartın önüne “Hande, on dakika yapabilirsin” yazdı. Altına kapının yanında ayakkabılarını bağladığı sahneyi ekledi. Arkasına bir plan yazdı: “Akşam yemeğinden sonra oturursam karar vermeden önce kalkıp ayakkabılarımı giyeceğim.” Kartı akşam saat 7’de, sofrayı topladıktan sonra okuyacaktı. Bir kez aynada denedi, kendini aptal gibi hissetti. Bu yüzden kartı eline alıp okumayı seçti. Yedi günde dört kez yürüdü. İkisinde yalnızca on dakika yürüdü. Gözden geçirirken cümleyi korudu. Hayal ettiği sahneyi, yemekten önce ayakkabılarını hazırlamak olarak değiştirdi. Okuma saatini de erkene aldı. Yedi günde dört kez yürümek, hiç yürümemekten iyiydi."}}},$=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:w,SOURCES:x},Symbol.toStringTag,{value:"Module"})),T=[{id:"P01",title:"Steel · 2007 · Correlates and theory of procrastination",url:"https://studypedia.au.dk/fileadmin/www.studiemetro.au.dk/Procrastination_2.pdf",type:"research",finding:"216 çalışmadan 691 korelasyon, ertelemeyi işin itici gelmesi, daha düşük öz denetim ve daha düşük öz yeterlikle ilişkilendirdi. Çalışma niyeti için r = -0,03’tü. Aralık sıfırı içeriyordu.",limitation:"Çoğunlukla öğrencilerle elde edilen ilişkisel kanıttır. Neden veya kişisel tanı değildir. Eski yaygınlık tahminleri bugünkü toplumu temsil eden güncel oranlar değildir."},{id:"P02",title:"Sirois & Pychyl · 2013 · Short-term mood regulation",url:"https://eprints.whiterose.ac.uk/91793/1/Compass%20Paper%20revision%20FINAL.pdf",type:"research",finding:"Kuramsal bir açıklamaya göre, işin yarattığı hoş olmayan duygulardan şimdi kaçmanın bedelini ileride ödersin.",limitation:"Bu, farklı araştırmaları ele alan bir anlatı derlemesidir. Yeni bir ortak etki büyüklüğü hesaplamaz. Her gecikmeyi açıklamaz, duyguyu adlandırmanın davranışı değiştirdiğini göstermez."},{id:"P03",title:"Gollwitzer & Sheeran · 2006 · If-then planning meta-analysis",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"94 bağımsız testte, belirli “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı. Bu eski derlemede standartlaştırılmış etki büyüklüğü d = 0,65’ti.",limitation:"Bulgular farklı hedeflerden ve eski çalışmalardan geliyor. Etki büyüklüğü, başarıda yüzde 65 artış demek değildir. Etki ertelemeye özgü de değildir. ODA’nın kısa iş alıştırması sınanmadı."},{id:"P04",title:"Wang, Wang & Gai · 2021 · Mental contrasting with planning",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"24 etki içeren 21 makalede, zihinsel karşılaştırmayı “şu olursa bunu yaparım” planıyla birleştirmek hedefe ulaşmada küçük ile orta arasında ortalama yarar gösterdi.",limitation:"Sonuçların farklılığı ve yayın yanlılığı işaretleri büyüklüğü sınırlar. Kısa ODA uyarlaması sınanmadı. Mümkün olmayan hedefleri bırakmak gerekebilir."},{id:"P05",title:"Rozental et al. · 2018 · Controlled procrastination interventions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2018.01588/full",type:"research",finding:"718 kişinin katıldığı 12 çalışmada, etkin müdahale almayan kontrollere göre kişinin bildirdiği ertelemede küçük bir ortalama azalma bulundu.",limitation:"Çoğunlukla öğrenciler, farklı yöntemler, kalite kaygıları ve her tedavide az çalışma vardı. Kesin olmayan bulgular ODA’nın etkisini veya evrensel bir tedavi sıralamasını göstermez."},{id:"P07",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and procrastination",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"İki ara sınavdan önce değerlendirilen 119 birinci sınıf öğrencisinde, daha fazla kendini affetmek ile sonraki sınav için daha az ertelemek ilişkiliydi.",limitation:"Tek bir dersteki öğrenci grubunu izleyen gözlemsel bir çalışmadır. Hazır cümlenin nedensel etkisi veya tamamlanmış düzeltme gösterilmedi. Başta katılan ve çalışmadan ayrılan kişi sayıları doğrulanmadı."},{id:"P08",title:"Han & Kim · 2023 · Self-compassion intervention review",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"56 rastgele kontrollü çalışmada, kendine şefkat uygulamalarının hemen sonrasında sıkıntı ölçülerinde küçük ile orta arasında yararlar görüldü. Bulguların sınırları vardı.",limitation:"Genel yanlılık riski yüksekti. Programlar farklı, etkin yöntemlerle karşılaştırmalar sınırlıydı. Tek bir cümlenin kaygıyı tedavi ettiğine veya ertelemeyi azalttığına dair burada kanıt yok."},{id:"P09",title:"Zhou et al. · 2026 · Planning and willingness to initiate",url:"https://pubmed.ncbi.nlm.nih.gov/41601124/",type:"research",finding:"81 lisans öğrencisiyle yapılan rastgele kontrollü çalışmada, olumlu düşünmeye göre MCII ile işin daha az itici geldiği ve harekete geçme isteğinin arttığı bildirildi.",limitation:"Çalışma Çin’de tek bir özel üniversitede yapıldı. Katılımcılar kısa süre izlendi. Özet, nesnel tamamlanmayı, günlük başlama yüzdelerini, ayrılan kişi sayısını veya ön kayıt durumunu doğrulamaz."},{id:"P10",title:"Oettingen et al. · 2015 · Time-management planning procedure",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"Akademik MCII alıştırmasında öğrenciler istedikleri sonucu, engeli ve ne yapacaklarını düşündü. Zaman ve yeri belirledi, prova yaptı, haftalık takvim hazırladı. Planlanan etkinlik saatleri ölçüldü.",limitation:"İlk çalışmada 84 Alman lisans öğrencisi rastgele gruplara ayrıldı. Tamamlanan iş değil, planlanan saatler ölçüldü. ODA bu alıştırmayı yetişkinlerin gündelik işleri için uyarlıyor."},{id:"P11",title:"Biwer et al. · 2023 · Fixed and self-regulated breaks",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"87 öğrenciyle yapılan çalışmada, kendi seçtikleri molalar 24/6 ve 12/3 düzenleriyle karşılaştırıldı. Sabit düzenlerde kişilerin bildirdiği yararlar vardı. İşin tamamlanmasında istatistiksel olarak anlamlı fark bildirilmedi.",limitation:"Küçük bir örneklem, kendi kendine çalışılan tek bir günde incelendi. Yalnızca özete erişildi. İstatistiksel olarak anlamlı fark bulunmaması, eşit iş çıkarıldığını, ertelemenin kalıcı olarak azaldığını veya en iyi sürenin 25/5 olduğunu kanıtlamaz."},{id:"P12",title:"Albulescu et al. · 2022 · Micro-breaks review",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0272460",type:"research",finding:"22 örneklemde kısa molaların yorgunluğu azaltma ve canlılığı artırma bakımından ortalama yararları, genel performans için bulunan yararlardan daha belirgindi.",limitation:"İşler ve mola etkinlikleri farklıydı. En iyi sürenin 25/5 olduğu veya zorlayıcı işlerde güvenilir performans artışı gösterilmedi."},{id:"P13",title:"Harkin et al. · 2016 · Progress monitoring meta-analysis",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 rastgele kontrollü çalışmada, izleme uygulamaları hedefe ulaşmayı ortalama olarak artırdı.",limitation:"Hedefler ve yöntemler farklıydı. Kayıt ve bildirim analizleri her biçimin nedensel etkisini kanıtlamaz. Herkese açık paylaşım ve iki dakikalık haftalık düzen gerekmez."},{id:"P15",title:"Psychological Science · 2026 · Deadline-paper retraction",url:"https://journals.sagepub.com/doi/full/10.1177/09567976261488042",type:"guidance",finding:"2 Eylül duyurusu, verilerin güvenilirliği ve gerçekliğiyle ilgili kaygılar nedeniyle Ariely ve Wertenbroch’un 2002 teslim tarihi makalesini geri çekiyor.",limitation:"Geri çekilen sonuçlar bir tekniği destekleyemez. Duyuru, her kişisel kontrol noktasının veya teslim tarihinin etkisiz olduğunu göstermez."},{id:"procrastination-pomodoro",title:"Cirillo · Pomodoro Technique provenance",url:"https://www.pomodorotechnique.com/francesco-cirillo/",type:"technique",finding:"Geliştiricinin anlatısı, genellikle 25 dakikalık çalışma aralıkları ve kısa molalarla öğretilen zamanlayıcı düzenini açıklar.",limitation:"Uygulamanın kaynağını gösterir, bağımsız etkililik kanıtı değildir. Geliştiricinin bu anlatısı tam süreleri veya ODA düzenini doğrulamaz."},{id:"if-then-plans",title:"Gollwitzer & Sheeran · 2006 · If-then planning meta-analysis",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"94 bağımsız testte, belirli “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı. Bu eski derlemede standartlaştırılmış etki büyüklüğü d = 0,65’ti.",limitation:"Bulgular farklı hedeflerden ve eski çalışmalardan geliyor. Etki büyüklüğü, başarıda yüzde 65 artış demek değildir. Etki ertelemeye özgü de değildir. ODA’nın kısa iş alıştırması sınanmadı."},{id:"self-forgiveness",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and procrastination",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"İki ara sınavdan önce değerlendirilen 119 birinci sınıf öğrencisinde, daha fazla kendini affetmek ile sonraki sınav için daha az ertelemek ilişkiliydi.",limitation:"Tek bir dersteki öğrenci grubunu izleyen gözlemsel bir çalışmadır. Hazır cümlenin nedensel etkisi veya tamamlanmış düzeltme gösterilmedi. Başta katılan ve çalışmadan ayrılan kişi sayıları doğrulanmadı."},{id:"procrastination-pomodoro-breaks",title:"Biwer et al. · 2023 · Fixed and self-regulated breaks",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"87 öğrenciyle yapılan çalışmada, kendi seçtikleri molalar 24/6 ve 12/3 düzenleriyle karşılaştırıldı. Sabit düzenlerde kişilerin bildirdiği yararlar vardı. İşin tamamlanmasında istatistiksel olarak anlamlı fark bildirilmedi.",limitation:"Küçük bir örneklem, kendi kendine çalışılan tek bir günde incelendi. Yalnızca özete erişildi. İstatistiksel olarak anlamlı fark bulunmaması, eşit iş çıkarıldığını, ertelemenin kalıcı olarak azaldığını veya en iyi sürenin 25/5 olduğunu kanıtlamaz."},{id:"P18",title:"Breines & Chen · 2012 · Compassionate writing and repair motivation",url:"https://self-compassion.org/wp-content/uploads/publications/selfimp.motivation.pdf",type:"research",finding:"İkinci deneyde, kendilerine anlayışla yazan lisans öğrencileri hatayı düzeltme ve tekrarlamama isteğinin arttığını bildirdi.",limitation:"100 kişi alındı, 91’i analiz edildi. Tamamlanmış düzeltme, kalıcı değişim veya ertelemede azalma ölçülmedi. ODA ayrı bir davranışla düzeltme adımı ekler."}],u=[{schemaVersion:2,revision:2,id:"procrastination-1",courseId:"procrastination",locale:"tr",title:"Ertelediğin işin bedeli birikiyor",goal:"Beklemek gerekli mi, kontrol et. Ardından ertelediğin işte işe yarayan küçük bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Masraf raporu hâlâ bekliyor. Bir kez daha ertelemek sana neye mal olacak?",reason:{id:"procrastination-1-delay-cost-reason",label:"Son ertelemenin bedeli neydi, o anda beklemen gerçekten gerekli miydi?",kind:"text",maxLength:160,optional:!0,suggestions:["Gereken bilgiye o anda ulaşamıyordum","Fişi girmedim, yapılacak iş daha da birikti","Dinlenme veya acil bakım sorumluluğu önce geldi"]},why:{id:"procrastination-1-why",label:"Bu iş neye yarıyor, ertelemek hangi bedeli getiriyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Erteleme, beklemenin işleri kötüleştireceğini düşündüğün hâlde yapmayı istediğin işi geciktirmektir. Ama dinlenmek, daha öncelikli bir sorumluluk veya eksik kaynaklar beklemeyi gerekli kılabilir. Kendine tembel demeden önce hangi durumda olduğuna bak. Her gecikme kaçınma değildir. O anda gerçekten yapabileceğin bir şey var mı, yoksa önce başka bir ihtiyaç mı karşılanmalı?","Bir açıklamaya göre, hoş gelmeyen işten kaçınca şimdi rahatlarsın, bedeli sonra ödersin. Bu bir model. Her gecikmeyi açıklamaz. Hissettiğin duyguyu veya somut engeli adlandır. Güvenli ve işe yarayan bir adım mümkünse rahatsızlık sürerken küçük bir işi yap. Rahatlamak şart değil. Burada sınadığın şey işe yarayan adımdır."],example:{title:"Selin elindeki bir fişi giriyor",text:"Saat 15.00. Selin iki fişi eksik olduğu için masraf raporunu erteliyor. Eksik fiş kuralını kontrol edip elindeki bir fişi giriyor. Utancı geçmiyor. Girdiği fişi ve yanıtsız kalan soruyu kaydediyor. Rapor henüz bitmedi. Ama artık her kısmı durmuş gibi davranmıyor. Eksik fişler hâlâ çözüm beklerken elindeki bir bilgi rapora girmiş oluyor."}},move:{invitation:"Ertelediğin işe uygun bir kayıt, bir cümle veya bilgi sorusu seç.",instructions:["Beklemek gerçek bir ihtiyacını koruyor mu, önce buna bak.","Örneği ancak kendi işine uyuyorsa seç."],prompts:[{id:"procrastination-1-0",label:"İşin hangi kısmı rahatsız ediyor, hangi kısmı gerçekten durmuş durumda?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Masraf raporuma elimdeki bir fişi gir","Ertelediğim işe yarayacak bir cümle yaz","İşimi durduran bir kural hakkında soru sor"],minimum:["Elimdeki bir fişi rapora gir","İşe yarayan bir cümle yaz","Kuralla ilgili tek bir net soru gönder"],cue:["İşte sonraki molam bitince","Akşam yemeğinden sonra tabağımı kaldırınca","Anlamadığım bir kural işimi durdurunca"],place:["İşteki çalışma masamda","Evde, mutfak masamda","İlgili kişiyle güvenli mesajlaşma kanalında"],minutes:[2,5,1],fallback:["Önce elimde olan bir fişi kullan","Taslak bir cümle yaz, belirsiz kısmı işaretle","Gerekirse ulaşabildiğim başka bir ilgili kişiye sor"],observation:["Rapora girdiğim fiş","Yazdığım cümle ve belirsiz kısmı","Gönderdiğim kural sorusu ve varsa yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",cue:"İşte sonraki molam bitince",place:"İşteki çalışma masamda",fallback:"Önce elimde olan bir fişi kullan",observation:"Rapora girdiğim fiş",minutes:2},{action:"Ertelediğim işe yarayacak bir cümle yaz",minimum:"İşe yarayan bir cümle yaz",cue:"Akşam yemeğinden sonra tabağımı kaldırınca",place:"Evde, mutfak masamda",fallback:"Taslak bir cümle yaz, belirsiz kısmı işaretle",observation:"Yazdığım cümle ve belirsiz kısmı",minutes:2},{action:"İşimi durduran bir kural hakkında soru sor",minimum:"Kuralla ilgili tek bir net soru gönder",cue:"Anlamadığım bir kural işimi durdurunca",place:"İlgili kişiyle güvenli mesajlaşma kanalında",fallback:"Gerekirse ulaşabildiğim başka bir ilgili kişiye sor",observation:"Gönderdiğim kural sorusu ve varsa yanıt",minutes:2,kind:"support"}]},suggested:{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",minutes:2,cueHint:"İşte sonraki molam bitince",placeHint:"İşteki çalışma masamda",obstacleHint:"Eksik bilgi veya işi bırakma isteği",fallbackHint:"Önce elimde olan bir fişi kullan",observationHint:"Rapora girdiğim fiş",requiresChoice:!0},stopRule:"Bu deneme için acil sağlık, güvenlik veya sözleşme yükümlülüklerini geciktirme.",accessibleAlternative:"Sana uygun yardımcı araçları kullan veya gereken bilgiyi sor. İş durmuşsa destek almayı seç."},result:{question:"Seçtiğin işe yarayan küçük adımı gerçekten attın mı?",observationPrompt:"Tam olarak ne yaptın? Hangi kısımda hâlâ ilerleyemiyorsun?"},judgment:{primary:{id:"procrastination-1-decision",scenario:"Selin’in iki boş dakikası ve rapor şablonu var. İki fiş eksik. Ama kurallar, elindeki fişleri girmesine izin veriyor.",question:"Hangi adım Selin’in ertelediği işe başlamasına yardımcı olur?",options:[{id:"procrastination-1-sort",text:"Sonra raporu daha kolay hazırlamak için elindeki bütün fişleri önce tarih sırasına göre tek tek dizsin.",feedback:"Fişleri sıralamak sonra işe yarayabilir. Ama burada eldeki kayıtlar şimdiden girilebilir. Bütün düzenleme bitene kadar bekleme. Bir fişi şimdi gir, eksik fişler için gereken kuralı da öğren."},{id:"procrastination-1-enter",text:"Eksik fiş kuralını kontrol etsin. Utancı devam etse de elindeki tek bir fişi hemen rapora girsin.",feedback:"Bu adım, belirsiz olan kurala bakıp eldeki zamanda işin bir parçasını tamamlamayı sağlar. Utancın sürmesi, girilen fişi yok etmez. Ne değiştiğini ve hangi bilginin hâlâ gerektiğini kaydet."},{id:"procrastination-1-wait",text:"Raporun tamamını tek oturuşta bitirebilmek için yarına daha uzun ve kesintisiz bir çalışma zamanı ayırsın.",feedback:"Bitirmek için uzun zaman gerekebilir. Ama bu, bugünkü başlangıç fırsatını değerlendirmiyor. Şimdiki zamanı bir fiş için kullan. Sonra kalan iş için ayrıca uygun bir zaman ayır."}],bestOptionId:"procrastination-1-enter"}},carry:{takeaway:"Engeli adlandır, gerçek ihtiyaca bak. Sonra işe yarayan küçük bir adım at.",followUp:{questionId:"procrastination-1-return",question:"Seni durduran rahatsızlık mıydı, yoksa gereken bir şeye hâlâ ulaşamıyor muydun?",observationPrompt:"Tam olarak ne yaptın? Hangi kısımda hâlâ ilerleyemiyorsun?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Gecikme, kişiliğin hakkında bir hüküm değil",paragraphs:["Steel’in 2007 derlemesi, 216 çalışmadan 691 korelasyonu bir araya getirdi. İşin hoş gelmemesi, daha düşük öz denetim ve işi yapabileceğine daha az güvenmek ertelemeyle ilişkiliydi. Bu ilişkiler, senin gecikmene neyin neden olduğunu göstermez. Araştırmaların çoğunda öğrenciler vardı. Eski yaygınlık tahminleri de bugünkü toplumu temsil eden güncel oranlar değildir. Bunları kendine tanı koymak veya herkesin durumunu açıklamak için kullanma. [P01]","Çalışma niyetiyle ilişki negatif 0,03’tü. Belirsizlik aralığı sıfırı da içeriyordu. Bu sıfıra yakın ortalama, herkesin yeterli isteği, zamanı, desteği veya kaynağı olduğunu göstermez. Onun yerine kendi işine bak: yapılabilir bir adım var mı? Önce gelen bir sorumluluk, sana uygun düzenleme ihtiyacı veya durman için bir neden var mı? Sıradaki adımı bu gerçeklerden seç. Kişiliğine taktığın bir etiketle karar verme."]},{heading:"Şimdi rahatlamak, sonra bedel ödemek",paragraphs:["Sirois ve Pychyl bir duygu düzenleme açıklaması sunar: hoş gelmeyen iş kaçınmayı tetikleyebilir. Kaçınmak anlık rahatlama sağlayabilir. Gelecekteki sen ise bitmemiş işi üstlenir. 2013 tarihli makale kuramsal bir anlatı derlemesidir. Bu döngüyü veya bir tedaviyi rastgele gruplarla sınayan deney değildir. Duyguyu fark etmenin somut planlamadan daha iyi olduğunu da göstermez. Bu, bazı ertelemelere bakmak için bir açıklamadır. [P02]","Duyguyu adlandırıp küçük bir iş yapmak ODA’nın uyarlamasıdır. İtiraf yazman veya sonra daha sakin hissetmen gerekmez. Denemeni gündelik, güvenli bir işte tut. Bilgi eksikse net bir soru sormak faydalı adım olabilir. Dinlenme, korunma veya acil sorumluluk önce geliyorsa o seçimi dürüstçe kaydet. Sonraki dersler, gerçek denemelerine göre aynı planı geliştirir. Her gün yeni bir başarısızlık bulmanı istemez. Buradaki kayıt, kendi durumunu daha açık görmen içindir."]}],sourceIds:["P01","P02"]}},{schemaVersion:2,revision:2,id:"procrastination-2",courseId:"procrastination",locale:"tr",title:"Hazırlık yeter. İşe yarayan bir parça çıkar",goal:"Aynı işin kullanabileceğin küçük bir kısmını yap. Elindeki zamana göre nerede duracağını belirle.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yine bütün zamanı hazırlanarak mı geçirdin? İşin kullanılabilir bir parçası elinde kalsın.",reason:{id:"procrastination-2-preparation-output-reason",label:"Son hazırlığından ne çıktı, işin hangi yararlı parçası hâlâ eksik?",kind:"text",maxLength:160,optional:!0,suggestions:["Malzemeler hazır ama henüz cümle yazmadım","Gerçekten eksik olan bir yönerge var","Bir fiş girdim, sıradaki hâlâ bekliyor"]},why:{id:"procrastination-2-why",label:"Kullanılabilir tek bir parça hangi işini kolaylaştırır?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin işi koru. Yapacağın işi ve elinde ne kalacağını söyle: bir fiş gir, bir cümle çevir veya gereken bir soruyu yanıtla. Dosyayı açmak hazırlıktır. Kullanılabilir bir parça eklemek işi yapmaktır. Hazırlık gerekli olabilir. O anki adımın buysa ona dürüstçe hazırlık de. Hazırladığın dosya ile içine eklediğin cümle aynı şey değil.","Belirli bir plan, uygun başlama anı geldiğinde ne yapacağını söyler. Araştırma bu genel yolu destekliyor. Tam iki dakikanın özel bir etkisi olduğunu göstermiyor. Elindeki zamana sığan büyüklüğü seç. Gerekirse orada dur. Başladıktan sonra da iş sana rahatsız edici gelebilir. Daha iyi hissetmeyi şart koşma. Ortaya çıkan işi kaydet."],example:{title:"Selin rapora bir fiş daha ekliyor",text:"Salı günü çay molasının ardından Selin’in aynı rapor için beş dakikası var. Fiş klasörlerini yeniden düzenlemeyi düşünüyor. Onun yerine bir fiş daha giriyor. Kategori belirsiz kalınca sormak için işaretliyor. Seçtiği süre dolduğunda duruyor. Artık iki fiş girilmiş durumda. Rapor henüz bitmiş değil. Hazırlığı büyütmek yerine mevcut zamana sığan bir kayıt ekledi."}},move:{invitation:"Kaydettiğin işi ve küçük adımı koru. Elindeki sürede işin kullanabileceğin bir kısmını tamamla.",instructions:["İşi koru. Başka bir küçük parça seçersen en küçük adımını değiştir.","“Engelle karşılaşınca” ve “Neye bakacaksın?” alanlarını seçtiğin işe göre düzenle."],prompts:[],suggestions:{action:["Masraf raporuma elimdeki bir fişi gir","Belgemden tek bir cümle çevir","İş için gereken bir soruyu yanıtla"],minimum:["Elimdeki bir fişi rapora gir","Tek bir cümlenin taslak çevirisini yap","İşe yarayan tek bir yanıt yaz"],cue:["İşte sonraki molam bitince","Bu işe ayırdığım sonraki zaman başlayınca","Akşam yemeğinden sonra tabağımı kaldırınca"],place:["İşteki çalışma masamda","Rahatça erişip kullanabildiğim çalışma masamda","Evde, mutfak masamda"],minutes:[2,5,10],fallback:["Klasörleri değiştirmeden sıradaki bir fişi rapora gir","Belirsiz terimi işaretle, cümleyi çevirip bitir","Bildiğim kısmı yaz, eksik bilgiyi birine sor"],observation:["Girdiğim fiş ve varsa belirsiz kalan kategori","Çevirdiğim cümle ve emin olmadığım terim","Yazdığım yanıt ve hâlâ eksik olan ayrıntı"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",cue:"İşte sonraki molam bitince",place:"İşteki çalışma masamda",fallback:"Klasörleri değiştirmeden sıradaki bir fişi rapora gir",observation:"Girdiğim fiş ve varsa belirsiz kalan kategori",minutes:2},{action:"Belgemden tek bir cümle çevir",minimum:"Tek bir cümlenin taslak çevirisini yap",cue:"Bu işe ayırdığım sonraki zaman başlayınca",place:"Rahatça erişip kullanabildiğim çalışma masamda",fallback:"Belirsiz terimi işaretle, cümleyi çevirip bitir",observation:"Çevirdiğim cümle ve emin olmadığım terim",minutes:2},{action:"İş için gereken bir soruyu yanıtla",minimum:"İşe yarayan tek bir yanıt yaz",cue:"Akşam yemeğinden sonra tabağımı kaldırınca",place:"Evde, mutfak masamda",fallback:"Bildiğim kısmı yaz, eksik bilgiyi birine sor",observation:"Yazdığım yanıt ve hâlâ eksik olan ayrıntı",minutes:2}]},suggested:{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",minutes:2,cueHint:"İşte sonraki molam bitince",placeHint:"İşteki çalışma masamda",obstacleHint:"İşi yapmak yerine hazırlığını düzeltip duruyorum",fallbackHint:"Klasörleri değiştirmeden sıradaki bir fişi rapora gir",observationHint:"Girdiğim fiş ve varsa belirsiz kalan kategori"},stopRule:"Acil sorumluluklar veya güvensiz bir iş varsa dur. Gerekli iletişim ulaşılabilir kalsın.",accessibleAlternative:"Sesle yazdır, yaz, yardımcı araçlarını kullan veya eksik olan belirli bir kaynağı iste."},result:{question:"Seçtiğin kullanılabilir küçük parçayı gerçekten ortaya çıkardın mı?",observationPrompt:"Şimdi elinde hangi iş var, hangi kısmı yalnızca hazırlıktı?"},judgment:{primary:{id:"procrastination-2-decision",scenario:"Kerem’in randevusuna iki dakika var. Sözleşme dosyası hazır. Birinci bölümün hangi cümleyle başladığını biliyor.",question:"Hangi başlangıç eldeki iki dakikayı kullanır?",options:[{id:"procrastination-2-timer",text:"Sözleşmenin bütün çevirisini destekleyebilecek iki farklı zamanlayıcı ayarını karşılaştırıp daha sonra kullanacağı ayarı seçsin.",feedback:"Zamanlayıcı, sonraki çalışmayı düzenlemeye yardımcı olabilir. Ama ayar karşılaştırmak burada çeviri üretmez. Dosya ve ilk cümle hazır. Bu kısa fırsatı tek bir cümlenin taslak çevirisi için kullan."},{id:"procrastination-2-outline",text:"Sonraki çalışma daha az karışık gelsin diye sözleşmenin tamamını hangi sırayla çevireceğini ayrıntılı olarak planlasın.",feedback:"Nereden ilerleyeceğini bilmiyorsan plan gerekir. Kerem ise sıradaki cümleyi zaten biliyor. Bütün sırayı planlarsa şu an yapabileceği küçük işi erteler, hazırlığı uzatır."},{id:"procrastination-2-unit",text:"İlk cümleyi çevirsin, emin olmadığı bir terimi işaretlesin ve randevusuna yetişmek için zamanında çalışmayı bıraksın.",feedback:"Bu adım kullanılabilir bir taslak çıkarır ve belirsizliği gösterir. Sözleşmeyi bitirmiş gibi davranmaz. Kerem zamanında durabilir. İşaretlediği terimi sonraki çalışma zamanında ele almak için kaydında tutar."}],bestOptionId:"procrastination-2-unit"}},carry:{takeaway:"İşe yarayan bir parça üreten küçük başlangıç, işte gerçek ilerleme sağlar.",followUp:{questionId:"procrastination-2-return",question:"En küçük adımından yararlı bir parça çıktı mı, yoksa yerine hazırlık mı yaptın?",observationPrompt:"Şimdi elinde hangi iş var, hangi kısmı yalnızca hazırlıktı?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Başlangıç anını belirle. İki dakika şart değil",paragraphs:["Gollwitzer ve Sheeran’ın 2006 meta-analizi, “şu olursa bunu yaparım” planlarına dair 94 bağımsız testi birleştirdi. Bu planlar, tanınabilir bir durum ile önceden seçilmiş yanıtı belirtir. Farklı ortamlarda hedefe ulaşma ortalama olarak arttı. Tarihsel standartlaştırılmış etki 0,65’ti. Bu, başarıda yüzde 65 artış değildir. Senin sonucunu da önceden söylemez. Genel plan biçiminin desteğini, belirli bir kişiye verilmiş sonuç sözü gibi okumamak gerekir. [P03]","Bu ders, gündelik bir iş için başlama anı geldiğinde ne yapacağını önceden seçme yolunu kullanıyor. Kısa süre ve tek parça hedefi tasarım seçimleridir. Araştırmayla en iyi bulunmuş doz değildir. Küçük parça yine işe hizmet etmeli. Amacın yazmaksa yönerge okumak hazırlık, taslak cümle yazmak ise yazma işidir. İkisi de uygun olabilir. Adlarını ayrı tut. Gerçekten sahip olduğun süre dolunca dur. Daha sonra büyütüp büyütmemeye çıkan işe, erişime ve sorumluluklarına göre bak. Başlangıcın kolay hissettirmesi şart değil."]},{heading:"Süre tutmak isteğe bağlıdır",paragraphs:["Biwer ve arkadaşları, kişinin kendi seçtiği molaları iki düzenle karşılaştırdı: 24 dakika çalışma ve altı dakika mola; 12 dakika çalışma ve üç dakika mola. 87 öğrenci, tek bir kendi kendine çalışma gününde incelendi. Sabit düzenlerde daha az yorgunluk ve dikkat dağınıklığı gibi öznel yararlar vardı. İşin tamamlanmasında istatistiksel olarak anlamlı fark bildirilmedi. Bu, iki grubun eşit iş çıkardığını kanıtlamaz. [P11]","En fazla on dakikalık molaları inceleyen daha geniş derlemede, yorgunluk ve canlılık için yararlar genel performansa göre daha açıktı. En iyi düzenin 25/5 olduğunu göstermedi. [P12] Zamanlayıcı seçersen koşullarına uyan bir süre kullan. Gerçek işi yorgunluğunla birlikte değerlendir. Zamanlayıcının çalışması, işin yapılması değildir. Acil ve erişim için gereken iletişim açık kalsın. İhtiyaç duyduğun molaları ver. Bu dersi denemek için özel zamanlayıcı, satın alma veya bütün Pomodoro düzeni gerekmez."]}],sourceIds:["P03","P11","P12"]}},{schemaVersion:2,revision:2,id:"procrastination-3",courseId:"procrastination",locale:"tr",title:"İşten koptuğun o anı yakala",goal:"Aynı işte karşılaştığın engeli aşmak için seçtiğin adımı dene. Bu adıma ihtiyaç duyup duymadığını kaydet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dosyayı açar açmaz elin telefona mı gidiyor? Tam o an için plan yap.",reason:{id:"procrastination-3-switch-cost-reason",label:"Son kez işten uzaklaşınca ne kazandın, bunun bedeli ne oldu?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerekli bir arama veya mesaj işi böldü","Kısaca rahatladım ama cümle yine yazılmadı","Eksik bir ayrıntı için bilgi sormam gerekiyordu"]},why:{id:"procrastination-3-why",label:"Bu işte kalmak senin için neyi korur?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Son iş kaydını kullan. İşten başka bir şeye geçtiğin anı bul: raporu açınca telefona uzanmak veya belirsiz bir kayıtta durmak gibi. O anda ne yapacağını belirlemek, “daha çok uğraşacağım” sözünden daha kolay sınanır. Daha önce seçtiğin küçük işi o anda yapmayı planla. Burada yeni bir iş aramıyoruz. Koptuğun belirli ana bakıyoruz.","İstenen sonucu bir engel ve “şu olursa bunu yaparım” yanıtıyla birleştiren araştırmalarda küçük ortalama yararlar var. Bu, uygulayacağını garanti etmez. Engel için uygun bir adım seç. Dikkat dağılması ortam değişikliği isteyebilir. Eksik bilgi için soru gerekir. Bakım sorumlulukları, hastalık veya güvensiz çalışma ise koşullarını uyarlamayı ya da destek almayı gerektirir."],example:{title:"Selin elinin telefona gittiğini fark ediyor",text:"Çarşamba rapor zamanı geldiğinde Selin dosyayı açıp telefona uzanıyor. Planı, telefonu ters çevirip önce bir fiş girmek. Bunu yapıyor. Ardından yanıtlaması gereken mesaja dönüyor. Bir fiş girdiğini ve engelin çıktığını kaydediyor. Aynı çalışma sırasında telefon daha sonra dikkatini yine dağıtıyor. O anda planını uygulaması, bütün dikkat sorununu çözdüğü anlamına gelmiyor."}},move:{invitation:"Kaydettiğin işi ve en küçük adımı koru. Karşılaştığın engel için seçtiğin adımı dene.",instructions:["“Engelle karşılaşınca” alanını, karşılaştığın engele göre değiştir.","Henüz kaydın yoksa tanıyabileceğin bir uzaklaşma veya eksik bilgi anını seç."],prompts:[],suggestions:{action:["Mesajlara bakmadan önce rapora bir fiş gir","Başka sekmeye geçmeden önce bir cümle yaz","Eksik bir ayrıntıyı öğrenmek için soru sor"],minimum:["Elimdeki bir fişi rapora gir","İşe yarayan bir cümle yaz","Tek bir konu hakkında net soru gönder"],cue:["Çalışırken elim telefona gidince","Başka sekmeye geçmek isteyince","Belirsiz bir kayıt ilerlememi durdurunca"],place:["İşteki çalışma masamda","Rahatça erişip kullanabildiğim çalışma masamda","İlgili kişiyle güvenli mesajlaşma kanalında"],minutes:[2,5,1],fallback:["Telefonu ters çevir, acil iletişimi açık tut","Ek sekmeleri kapalı tut, cümlenin taslağını yaz","Soruyu kullanabildiğim başka bir iletişim yoluyla gönder"],observation:["Engel çıktı mı, ne yaptım, hangi fişi girdim?","Sekmeye geçme isteğim, yaptığım adım ve yazdığım cümle","Belirsiz ayrıntı ve gerçekten gönderdiğim soru"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Mesajlara bakmadan önce rapora bir fiş gir",minimum:"Elimdeki bir fişi rapora gir",cue:"Çalışırken elim telefona gidince",place:"İşteki çalışma masamda",fallback:"Telefonu ters çevir, acil iletişimi açık tut",observation:"Engel çıktı mı, ne yaptım, hangi fişi girdim?",minutes:2},{action:"Başka sekmeye geçmeden önce bir cümle yaz",minimum:"İşe yarayan bir cümle yaz",cue:"Başka sekmeye geçmek isteyince",place:"Rahatça erişip kullanabildiğim çalışma masamda",fallback:"Ek sekmeleri kapalı tut, cümlenin taslağını yaz",observation:"Sekmeye geçme isteğim, yaptığım adım ve yazdığım cümle",minutes:2},{action:"Eksik bir ayrıntıyı öğrenmek için soru sor",minimum:"Tek bir konu hakkında net soru gönder",cue:"Belirsiz bir kayıt ilerlememi durdurunca",place:"İlgili kişiyle güvenli mesajlaşma kanalında",fallback:"Soruyu kullanabildiğim başka bir iletişim yoluyla gönder",observation:"Belirsiz ayrıntı ve gerçekten gönderdiğim soru",minutes:2}]},suggested:{action:"Mesajlara bakmadan önce rapora bir fiş gir",minimum:"Elimdeki bir fişi rapora gir",minutes:2,cueHint:"Çalışırken elim telefona gidince",placeHint:"İşteki çalışma masamda",obstacleHint:"Çalışırken acil olmayan mesajlara bakmak için uzanıyorum",fallbackHint:"Telefonu ters çevir, acil iletişimi açık tut",observationHint:"Engel çıktı mı, ne yaptım, hangi fişi girdim?"},stopRule:"Acil iletişim ve erişim için gereken arama ve mesajları ulaşılabilir tut. Güvensiz veya erişilemeyen koşullarda destek seç.",accessibleAlternative:"Sana uygun bir hatırlatma kullan, gereken kaynağı iste veya açıkça hazırlık olarak kaydedeceğin bir prova yap."},result:{question:"Seçtiğin yanıtı kullanıp en küçük adımını gerçekten attın mı?",observationPrompt:"Engel çıktı mı, çıktığında tam olarak ne yaptın?"},judgment:{primary:{id:"procrastination-3-decision",scenario:"Ece tez dosyasını açınca telefona uzanıyor. İlk makale elinde. En küçük adımı taslak bir cümle yazmak. Acil bir arama veya mesaj beklemiyor.",question:"Bu engele hangi yanıt daha uygun?",options:[{id:"procrastination-3-response",text:"Telefonu kenara koysun. Makale hakkında taslak bir cümle yazsın. Ardından bakması gereken mesajları kontrol etsin.",feedback:"Bu plan, telefona uzandığı anda daha önce seçtiği küçük işi yapmasını sağlıyor. Sonrasında gerekli iletişime dönmesine izin veriyor. Başlangıç anını yakalayıp yakalamadığını ve gerçekten yazdığı cümleyi kaydetsin."},{id:"procrastination-3-later",text:"Hafta sonuna daha uzun bir çalışma ayırsın. Böylece bugünkü dikkat dağılması tez bölümünü daha az etkilesin.",feedback:"Hafta sonunda daha çok zaman genel olarak yardımcı olabilir. Ama şu an işten kopmasına yol açan anı değiştirmiyor. Daha büyük bir çalışma eklemeden önce bu anda uygulanabilir bir yanıtı dene."},{id:"procrastination-3-inspire",text:"Ne yazacağını seçmeden önce tez hedefini tekrar okusun ve bitmiş bölümün nasıl görüneceğini gözünde canlandırsın.",feedback:"Hedefi hatırlamak yön verebilir. Ece’nin ayrıca telefona uzandığı an için bir plana ve gerçekten yazacağı bir cümleye ihtiyacı var. Sadece düşünmek, o yanıtı bugün kullanıp kullanamadığını sınamaz. Somut deneme hâlâ bekler."}],bestOptionId:"procrastination-3-response"}},carry:{takeaway:"Engel çıktığında yapabileceğin bir adım seç. İşe yarayan bir sonuç veriyor mu, dene.",followUp:{questionId:"procrastination-3-return",question:"Engeli zamanında fark ettin mi, seçtiğin yanıtı o anda gerçekten kullanabilir miydin?",observationPrompt:"Engel çıktı mı, çıktığında tam olarak ne yaptın?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Engel için plan yapmak ne ekler?",paragraphs:["“Şu olursa bunu yaparım” planıyla birlikte zihinsel karşılaştırma, istediğin sonucu bir engel ve önceden planlanmış yanıtla birleştirir. Wang ve arkadaşları, 24 bağımsız etki içeren 21 makaleyi bir araya getirdi. Hedefe ulaşmada küçük ile orta arasında ortalama yarar buldular. Sonuçlar değişiyordu. Yayın yanlılığına işaret eden bulgular da vardı. Bu yaklaşım, mümkün olmayan bir hedefi bırakmaya da yardım edebilir. Her engeli aşma zorunluluğu değildir. [P04]","Oettingen ve arkadaşlarının 2015 akademik alıştırmasında öğrenciler önemli bir konuyu seçti. Sonucu ve engeli hayal etti, yanıt belirledi, zaman ve yer ekledi, prova yaptı, haftalık takvim hazırladı. Ölçülen şey tamamlanmış iş değil, planlanan çalışma saatleriydi. [P10] Gündelik bir iş için yaptığın kısa plan, bu uygulamayı değiştiriyor. Burada senden işin hangi kısmını yaptığını söylemen isteniyor. Hayal etmek, prova yapmak, planlamak ve işi yapmak birbirinin yerine geçmez. Bir planın beş plandan daha iyi olduğunun kanıtlandığını da varsayma."]},{heading:"Başlama isteği, başlanmış işin kanıtı değildir",paragraphs:["Zhou ve arkadaşlarının yakın tarihli rastgele kontrollü çalışması, Çin’de tek bir özel üniversitedeki 81 lisans öğrencisini kapsadı. Erişilebilir özette, planlama yönteminden sonra yalnızca olumlu düşünmeye göre işin daha az itici geldiği ve harekete geçme isteğinin arttığı bildiriliyor. Deney başlama isteğini ölçtü. Doğrulanmış iş başlangıçlarını veya tamamlanmayı değil. İstemeyi yapmakla aynı sayma. Bu ayrım, kendi kaydını okurken de geçerli. [P09]","Olumlu düşünceler kendiliğinden işe yaramaz sayılmaz. Engel de içindeki bir kusur olmak zorunda değil. Bu deneme, bildirdiğin işten uzaklaşma anından veya somut engelden başlar. İyi plan, bulunduğun ortamda ne zaman başlayacağını fark edip uygulayabildiğin plandır. Engel hiç çıkmadıysa yanıt sınanmamıştır. Başarısız sayılmaz. Engel çıkıp yanıt mümkün olmadıysa ortamı, büyüklüğü veya desteği değiştir. Aynı işi ve yönü koruyup kaydının gösterdiği koşulu değiştirmen yeterli."]}],sourceIds:["P04","P10","P09"]}},{schemaVersion:2,revision:2,id:"procrastination-4",courseId:"procrastination",locale:"tr",title:"Teslim tarihi geçti mi? Düzeltebildiğin yerden dön",goal:"Tutamayacağın bir söz vermeden uygun bir düzeltme, işe dönüş veya destek adımı seç.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Teslim günü geçti mi? Dürüst bir mesaj, bekleyen kişiye bundan sonra ne olacağını söyler.",reason:{id:"procrastination-4-owed-repair-reason",label:"Hangi kısmı düzeltmek senin sorumluluğun, yine susmanın veya söz vermenin bedeli ne olur?",kind:"text",maxLength:160,optional:!0,suggestions:["Bekleyen kişiye durum bilgisi vermem gerekiyor","Bilgi vermem gerekmiyor, işe geri döneyim","İletişim güvenli değil, önce destek isteyeyim"]},why:{id:"procrastination-4-why",label:"Şimdi hangi sorumluluğuna veya sınırına dikkat etmen gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İş kaydını dürüst tut. Biri bekliyorsa ona bilgi vermen veya bir şeyi düzeltmen gerekip gerekmediğine bak. Neyin bitmediğini, neyi yapabileceğini açıkça söyle. Kendine anlayış göstermek teslim tarihini değiştirmez. Gecikmenin sonuçlarını silmez. Gücünün ötesinde söz vermeyi de haklı çıkarmaz. Dürüst bir mesaj, bekleyen kişinin şu anki durumu bilmesini sağlar.","Bir deneyde, anlayışlı yazmak kişilerin hatayı düzeltmek için bildirdiği isteği artırdı. Düzeltmenin yapılıp yapılmadığı ölçülmedi. Burada bu ayrımı kullan: kendine adil bir cümle söylemek hazırlıktır. Durumu bildirmek veya işin bir parçasını yapmak eylemdir. En küçük adımın tek bir iş olsun. Ek işleri ayrı kaydet. Kendini affetmiş hissetmen şart değil."],example:{title:"Selin neyin eksik olduğunu açıkça bildiriyor",text:"Perşembe sabahı Selin’in raporu gecikti. “Erteledim. Üzerime düşen kısmıyla ilgilenebilirim” diye yazıyor. Tek düzeltme adımı seçiyor: muhasebeye eksik fiş sorusunu ve kalan işi dürüstçe bildiren mesaj göndermek. Henüz yanıt gelmedi. Gönderdiği mesajı kaydediyor. Fiş girmek ayrı bir sonraki adım. Mesaj göndermiş olması, rapora fiş girdiği anlamına gelmiyor. Kaydı sadece yaptığı adımı anlatıyor."}},move:{invitation:"Aynı işin içinde kal. Sorumlu olduğun bir düzeltme, işe dönüş veya güvenli destek adımı seç.",instructions:["Adımı seçmeden önce hangi kısmı düzeltmenin gerçekten senin sorumluluğun olduğunu kontrol et.","En küçük adım olarak tek bir iş seç. Ek yaptıklarını ayrı kaydet."],prompts:[],suggestions:{action:["İşin yeni kapsamını ve uygun zamanını bildir","İşimde kullanabileceğim küçük bir parçayı yaz","Ertelediğim işi bölmek için yardım iste"],minimum:["İşin kapsamını ve zamanını dürüstçe bildiren mesaj gönder","İşimde kullanabileceğim tek bir cümle yaz","İşi bölmek için bir yardım isteği gönder"],cue:["İşte güvenle ara verebildiğim sonraki anda","Bu işe ayırdığım sonraki zaman başlayınca","Kararlaştırdığımız sonraki destek görüşmesi başlayınca"],place:["İşe uygun mesajlaşma kanalında","Rahatça erişip kullanabildiğim çalışma masamda","Güvenli destek mesajlaşma kanalında"],minutes:[5,2,10],fallback:["Belirsiz zaman için söz vermeden mevcut durumu bildir","Bildiğim kısmı yaz, eksik bir ayrıntıyı işaretle","Ulaşamıyorsam güvendiğim başka bir kişiden yardım iste"],observation:["Gönderdiğim durum bilgisi ve varsa gelen yanıt","İşim için yazdığım işe yarayan cümle","İşi bölmek için istediğim yardım ve varsa yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"İşin yeni kapsamını ve uygun zamanını bildir",minimum:"İşin kapsamını ve zamanını dürüstçe bildiren mesaj gönder",cue:"İşte güvenle ara verebildiğim sonraki anda",place:"İşe uygun mesajlaşma kanalında",fallback:"Belirsiz zaman için söz vermeden mevcut durumu bildir",observation:"Gönderdiğim durum bilgisi ve varsa gelen yanıt",minutes:5},{action:"İşimde kullanabileceğim küçük bir parçayı yaz",minimum:"İşimde kullanabileceğim tek bir cümle yaz",cue:"Bu işe ayırdığım sonraki zaman başlayınca",place:"Rahatça erişip kullanabildiğim çalışma masamda",fallback:"Bildiğim kısmı yaz, eksik bir ayrıntıyı işaretle",observation:"İşim için yazdığım işe yarayan cümle",minutes:2},{action:"Ertelediğim işi bölmek için yardım iste",minimum:"İşi bölmek için bir yardım isteği gönder",cue:"Kararlaştırdığımız sonraki destek görüşmesi başlayınca",place:"Güvenli destek mesajlaşma kanalında",fallback:"Ulaşamıyorsam güvendiğim başka bir kişiden yardım iste",observation:"İşi bölmek için istediğim yardım ve varsa yanıt",minutes:2,kind:"support"}]},suggested:{action:"İşin yeni kapsamını ve uygun zamanını bildir",minimum:"İşin kapsamını ve zamanını dürüstçe bildiren mesaj gönder",minutes:5,cueHint:"İşte güvenle ara verebildiğim sonraki anda",placeHint:"İşe uygun mesajlaşma kanalında",obstacleHint:"Sessiz kalmak veya tutamayacağım sözler vermek istiyorum",fallbackHint:"Belirsiz zaman için söz vermeden mevcut durumu bildir",observationHint:"Gönderdiğim durum bilgisi ve varsa gelen yanıt",requiresChoice:!0},stopRule:"Gündelik bir aksama seç. Başkasının verdiği zarar için kendini suçlama. İletişim güvenli değilse ara ver ve destek al.",accessibleAlternative:"Güvensiz iletişim yerine güvenli mesaj, yardımcı iletişim yöntemi veya destek seç."},result:{question:"Seçtiğin tek düzeltme veya işe dönüş adımını gerçekten attın mı?",observationPrompt:"Hangi tek adımı attın, işin hangi kısmı hâlâ bitmedi?"},judgment:{primary:{id:"procrastination-4-capacity-repair-decision",scenario:"Deniz söz verdiği taslağı yetiştiremedi. Ekibin durum bilgisine ihtiyacı var. Bugün tek bölüm verebilir. Bütün taslak için daha fazla zaman gerekiyor.",question:"Şu anki gücüne hangi yanıt uyar?",options:[{id:"procrastination-4-finish",text:"Önce yapabildiği bölümü bitirsin. Taslak güven verecek duruma gelene kadar ekibe bilgi vermek için beklesin.",feedback:"Bölümü hazırlamak önemli. Ama ekip zaten bekliyor ve güncel bilgiye ihtiyaç duyuyor. İşin kapsamını ve zamanını şimdi dürüstçe bildir. Ardından yapabildiğin bölümü hazırla. İkisini ayrı işler olarak kaydet."},{id:"procrastination-4-revise-first",text:"Şimdi bütün taslak için yeni tarih istesin. Bu tarih kabul edilene kadar yapabildiği bölümü de ertelesin.",feedback:"Yeni tarih konuşmak gerekli olabilir. Ama ekip bugün hem güncel bilgi hem kullanılabilir bölüm alabilir. Kalan iş için gerçekçi bir süre önerirken mevcut parçayı hazırla. Ekibin ihtiyacı beklemeyi gerektiriyorsa buna göre davran."},{id:"procrastination-4-repair",text:"Söz verdiği taslağı yetiştiremediğini söylesin. Yapabileceği kapsamı ve zamanı önersin. Sonra bugün verebileceği tek bölümü hazırlasın.",feedback:"Bu adım tutamayacağı yeni bir söz vermeden gecikmenin sonuçlarıyla ilgileniyor. Bilgi vermek ve bölüm hazırlamak somut işler. Kabul etmek hâlâ ekibin seçimi. Gelen yanıtı da dürüstçe kaydet."}],bestOptionId:"procrastination-4-repair"}},carry:{takeaway:"Kendine adil bir cümle söylemek düzeltmeyi destekler. Düzeltme, gerçekten yaptığın somut davranıştır.",followUp:{questionId:"procrastination-4-chosen-act-return",question:"Seçtiğin düzeltme, işe dönüş veya destek adımı o anki gücüne gerçekten uydu mu?",observationPrompt:"Gerçekte ne yaptın, hangi konuya hâlâ yanıt vermen gerekiyor?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Kendine anlayış göstermek ve hatayı düzeltmek ayrı şeyler",paragraphs:["Breines ve Chen’in 2012 deneyinde lisans öğrencileri, yakın zamanda yanlış buldukları bir davranışı anlattı. Ardından kendilerine anlayışla ve sıcak bir dille yazdı. Çalışmaya alınan 100 kişiden 91’i analize girdi. Anlayışlı yazan grup, karşılaştırma gruplarına göre telafi etme ve tekrardan kaçınma isteğini daha fazla bildirdi. Deney, özürlerin veya düzeltmelerin gerçekten yapıldığını göstermedi. Zamanla ertelemenin azaldığını da ölçmedi. İstek ile davranış ayrı sonuçlar olarak kalıyor. [P18]","Bu ders gündelik bir gecikme için daha kısa, adil bir cümle kullanıyor. Buna ayrıca seçilmiş bir davranış ekliyor. Bu, ODA uyarlamasıdır. Sınanan alıştırma değildir. Güvenli bir mesaj, hata düzeltme, kararlaştırılmış küçük iş, sana uygun düzenleme isteği veya uymayan planı durdurma seçebilirsin. Gerçek kayda hangi işin yapıldığını yaz. Sorumluluğun, gerçekten yaptığınla orantılı kalsın. Sana zarar verildiği için iletişim kurmak, barışmak veya özür dilemek zorunda değilsin."]},{heading:"Kendini affetmeyle ilgili bulgu neyi garanti etmez?",paragraphs:["Wohl, Pychyl ve Bennett, tek bir psikoloji dersindeki 119 birinci sınıf öğrencisini inceledi. Öğrenciler iki ara sınavın her birinden hemen önce değerlendirildi. Kendini daha fazla affetmek, ikinci sınavdan önce daha az ertelemeyle ilişkiliydi. Bu gözlemsel ilişki, değişime affetmenin neden olduğunu kanıtlamaz. Belirli bir hazır cümlenin birini işe döndürdüğünü de göstermez. Buradan senin nasıl hissedeceğini veya davranacağını önceden çıkaramayız. [P07]","Kendini affetmek ve kendine şefkat göstermek birbiriyle ilgili ama ayrı kavramlardır. Han ve Kim’in 56 rastgele kontrollü çalışmayı birleştiren derlemesinde sıkıntı ölçülerinde sınırlı yararlar bulundu. Genel yanlılık riski yüksekti. Tek bir cümleyi tedavi olarak doğrulamaz. Sonraki işe başlamanı kolaylaştırdığını da göstermez. [P08] Pişmanlık veya öfke sürerken adil bir anlatımı deneyebilirsin. Sınadığın şey, sonraki sözünün gerçeğe uyup uymadığı ve düzeltmenin veya işe dönüşün gerçekten olup olmadığıdır. Bunun için duygularının değişmesi gerekmiyor."]}],sourceIds:["P18","P07","P08"]}},{schemaVersion:2,revision:2,id:"procrastination-5",courseId:"procrastination",locale:"tr",title:"Başlamak yine aksadı mı? Haftaya uygun bir zaman seç.",goal:"İşe yarayan planını koru. Gördüğün tek engeli değiştir ve sıradaki uygun denemeyi planla.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bazı günler işe başladın, bazı günler başlayamadın mı? Gelecek haftanın planını kayıtlarına göre seç.",reason:{id:"procrastination-5-reason",label:"Bu iş hâlâ bu hafta ayıracağın zamana ve güce değer mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Verdiğim sözü yerine getirmeye devam etmek","Tekrar tekrar aksayan planın bir kısmını değiştirmek","Sürekli karşılaştığım bir sorun için destek istemek"]},why:{id:"procrastination-5-why",label:"Bu iş hâlâ bu hafta ayıracağın zamana ve güce değer mi?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kaydettiğin işi, seçtiğin yönü, en küçük adımı ve denemeleri kullan. İlerlemeyi kontrol etmek hedeflere ulaşmayı ortalama olarak destekleyebilir. Planı, denemeyi ve kullanılabilir işi ayır. Kayıt yoksa ne olduğunu bilmiyoruz demektir. Ne başarısızlık ne başarıdır. Kayda yazmadığın bir gün için kendiliğinden sonuç çıkarma. Önce ne olduğunu söyle.","Yardımcı olanı koru, seni durduran tek bir koşulu değiştir. Kendi koyduğun kontrol noktası deneme olarak kalabilir. Başkasına söz verdiğin teslimi değiştirmek için konuşmak ve anlaşmak gerekir. Sıradaki küçük işi kaydet. ODA ertesi gün dönüşünü planlar. İşe yarayan bir başlangıç anı bilmiyorsan ilk uygun denemeyi seç. Gecikme kalıcı zarar veriyorsa denemeyle birlikte destek al."],example:{title:"Selin gelecek haftayı kaydına göre seçiyor",text:"Cuma günü Selin aynı rapora bakıyor: üç fiş girmiş, bir soru yanıtsız, ayırdığı bir zamanı kullanmamış. İşteki molalar uygundu. Geç akşamlar uymadı. Pazartesi moladan sonra sıradaki fiş için zaman seçiyor. Kime hâlâ bilgi vermesi gerektiğini kontrol ediyor. Rapor bitmedi. Yeni planını yaptıklarına ve yapamadıklarına göre kuruyor. Boşluğu başarı gibi yazmıyor."}},move:{invitation:"Kaydettiğin işi ve işe yarayan başlangıcı koru. İşi durduran koşulu değiştir.",instructions:["İşe yarayan başlangıç kaydın yoksa ilk uygun fırsatı belirle.","Sıradaki küçük işi kaydet. ODA ertesi gün dönüşünü planlar."],prompts:[],suggestions:{action:["Masraf raporuma elimdeki bir fişi gir","İşimde kullanabileceğim küçük bir parçayı yaz","Uymayan çalışma zamanını değiştirmek için yardım iste"],minimum:["Elimdeki bir fişi rapora gir","İşimde kullanabileceğim tek bir cümle yaz","Zamanı ayarlamak için yardım isteği gönder"],cue:["İşte sonraki uygun molam bitince","Yazmaya ayırdığım bir sonraki zaman başladığında","Çalışma zamanını konuşmak için kararlaştırdığımız görüşme başlayınca"],place:["İşteki çalışma masamda","Rahatça erişip kullanabildiğim çalışma masamda","Güvenli destek mesajlaşma kanalında"],minutes:[2,5,10],fallback:["Bunun yerine yarınki uygun iş molasında dene","Bunun yerine yarın yazmaya ayırdığım zamanda dene","Ulaşamıyorsam güvendiğim başka bir kişiye sor"],observation:["Girdiğim fiş ve çalışma koşullarının işe uyup uymadığı","Yazdığım cümle ve zamanın işe uyup uymadığı","Zaman ayarlama isteğim ve varsa gelen yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",cue:"İşte sonraki uygun molam bitince",place:"İşteki çalışma masamda",fallback:"Bunun yerine yarınki uygun iş molasında dene",observation:"Girdiğim fiş ve çalışma koşullarının işe uyup uymadığı",minutes:2},{action:"İşimde kullanabileceğim küçük bir parçayı yaz",minimum:"İşimde kullanabileceğim tek bir cümle yaz",cue:"Yazmaya ayırdığım bir sonraki zaman başladığında",place:"Rahatça erişip kullanabildiğim çalışma masamda",fallback:"Bunun yerine yarın yazmaya ayırdığım zamanda dene",observation:"Yazdığım cümle ve zamanın işe uyup uymadığı",minutes:2},{action:"Uymayan çalışma zamanını değiştirmek için yardım iste",minimum:"Zamanı ayarlamak için yardım isteği gönder",cue:"Çalışma zamanını konuşmak için kararlaştırdığımız görüşme başlayınca",place:"Güvenli destek mesajlaşma kanalında",fallback:"Ulaşamıyorsam güvendiğim başka bir kişiye sor",observation:"Zaman ayarlama isteğim ve varsa gelen yanıt",minutes:2,kind:"support"}]},suggested:{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",minutes:2,cueHint:"İşte sonraki uygun molam bitince",placeHint:"İşteki çalışma masamda",obstacleHint:"Seçtiğim çalışma zamanı bana uygun olmayabilir",fallbackHint:"Bunun yerine yarınki uygun iş molasında dene",observationHint:"Girdiğim fiş ve çalışma koşullarının işe uyup uymadığı"},stopRule:"Gecikme hayatına zarar veriyorsa şimdi destek al. Acil sorumluluklar uygun ve zamanında adım gerektirir.",accessibleAlternative:"Yardımla çalışmayı, destek isteğini, uygulanabilir bir sınırı veya ara vermeyi seçebilirsin."},result:{question:"Seçtiğin bir sonraki küçük işi gerçekten yaptın mı?",observationPrompt:"Ne yaptın veya destek almak için ne istedin?"},judgment:{primary:{id:"procrastination-5-decision",scenario:"Nazan salı başvuru yazısına cümleler ekledi. Perşembe için ayırdığı zaman uygun değildi, çalışamadı. Önceden anlaştıkları gibi arkadaşının yazıyı okuyup yorum yapması işe yaradı. Başvurunun son tarihi değişmiyor.",question:"Gelecek hafta neyi korusun, neyi değiştirsin?",options:[{id:"procrastination-5-more",text:"Her planlı başlangıç için günlük bir kontrol zamanı ve net bir hedef belirlesin. Sonuçlarıyla daha erken yüzleşsin.",feedback:"Daha fazla kontrol noktası düzen katabilir. Ama kayıt, perşembe zamanının uygun olmadığını gösteriyor. Arkadaşının yazıyı okuyup yorum yapmasını sürdür. Her güne baskı eklemeden önce uygun olmayan zamanı değiştir."},{id:"procrastination-5-adjust",text:"Arkadaşının yazıyı okuyup yorum yapmasını sürdürsün. Perşembe işe başlayacağı anı değiştirsin. Gelecek hafta gerçek denemelerini ve yazdıklarını karşılaştırsın.",feedback:"Bu seçim işe yarayan koşulu korur. Başvurunun son tarihini de gözden kaçırmaz. Yeni kayıt hem denemeleri hem işe yarayan yazıyı göstermeli. Başkalarıyla kararlaştırdığın bir şey değişiyorsa onlarla konuş."},{id:"procrastination-5-remove",text:"Teslim tarihleri hakkındaki kanıt belirsizken kişisel kontrol noktalarını kaldırsın. Sadece başvurunun son tarihine göre çalışsın.",feedback:"Genel kanıt belirsiz olsa da Nazan, arkadaşının yorumlarının işe yaradığını gördü. Bu desteği kanıtlanmış bir çare saymadan denemeye devam et. Zaman sorununu doğrudan ele al."}],bestOptionId:"procrastination-5-adjust"}},carry:{takeaway:"İşe yarayan koşulu koru, aksayanı değiştir. Sıradaki denemeden gerçekten çıkan işi dürüstçe kaydet.",followUp:{questionId:"procrastination-5-work-or-support-return",question:"Sıradaki iş veya destek adımını seçtiğin uygun başlangıç anında gerçekten attın mı?",observationPrompt:"Hangi işi yaptın veya hangi desteği istedin? Seçtiğin başlangıç anı uygun muydu?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Yöntem biriktirmek yerine kaydını kullan",paragraphs:["Harkin ve arkadaşları, farklı hedeflerde ilerlemeyi izlemeye dair 138 rastgele kontrollü çalışmayı birleştirdi. İzlemeyi artıran uygulamalar hedefe ulaşmayı ortalama olarak artırdı. Ek analizlerde kayıt ve bildirim daha büyük etkilerle ilişkiliydi. Ama bu ilişkiler, her paylaşım biçiminin iyileşmeye neden olduğunu kanıtlamaz. Herkese açık paylaşım gerekmez. Bu planla ODA ertesi gün denemene bakman için tek bir zaman ayırır. İstersen kendi takviminde haftalık karşılaştırma için de zaman seçebilirsin. Burada ikinci bir randevu kaydedilmez. [P13]","Tarihini kaydettiğin denemelere bak. Seçtiğin başlama anı, küçük adım ve engel için yaptığın plan işi yapmana yardımcı oldu mu? Tek parçanın bitmesi bütün işin bitmesi değildir. Hiç çıkmayan engelin yanıtı henüz sınanmamıştır. Geçmişteki boşluklar görünür kalsın. Gelecek hafta sana uyan koşulu koru. Denemelerinde sorun çıkaran koşulu değiştir. İş artık sorumluluklarına veya seçtiğin yola hizmet etmiyorsa yeni teknik eklemek yerine konuşup yeniden anlaşmayı, ara vermeyi veya durmayı düşün."]},{heading:"Destek ve teslim tarihlerinde sınırları açık tut",paragraphs:["Rozental ve arkadaşlarının kontrollü derlemesi, çoğu öğrenci olan 718 kişinin katıldığı 12 çalışmayı kapsadı. Psikolojik uygulamalar, etkin müdahale almayan kontrol gruplarına göre kişinin bildirdiği ertelemeyi ortalama olarak azalttı. Ama kalite sorunları, farklı yöntemler ve her tedavi için az çalışma olması bulguları kesinleştirmiyor. Sonuçlar ODA’nın işe yaradığını veya her biçimin uzmanla uygulanması gerektiğini göstermez. Ertelemenin hayatındaki etkisi destek gerektiriyorsa bu denemeyle birlikte değerlendirme veya yardım alabilirsin. [P05]","Ariely ve Wertenbroch’un kişisel teslim tarihleriyle ilgili sık anılan makalesi, verilerin güvenilirliği ve gerçekliğiyle ilgili kaygılar nedeniyle Eylül 2026’da geri çekildi. Sonuçları bir tekniği doğrulayamaz. Duyuru, her kontrol noktasının işe yaramadığını da söylemez. [P15] Kendi koyduğun hatırlatmayı istersen deneyebilirsin. İşverene, müşteriye veya okula söz verdiğin teslim tarihi ise bağlayıcıdır. Değiştirmeden önce konuş ve anlaşma iste. Acil sağlık, güvenlik, yasal veya sözleşme sorumluluklarının yerine kendine koyduğun baskıyı geçirme."]}],sourceIds:["P13","P05","P15"]}}],O=[{id:"1552360708-ebcdf76845ac",alt:"Pencere kenarında düşünceli oturan kadın"},{id:"1448387473223-5c37445527e7",alt:"İlk basamağa adım atan bir ayak"},{id:"1553044020-8c90843adf96",alt:"Sarı yapışkan not kâğıtları ve bir kalem"},{id:"1778958619388-b529cc4e78e8",alt:"Pencere kenarında çay içen genç kadın"},{id:"1506784983877-45594efa4cbe",alt:"Açık planlama defterinin üzerinde duran kahve fincanı"}],d=[1,2,0,2,1],E=[3,3,3,3,3],j={id:"procrastination",title:"Yine mi erteledin? İşe yarayan bir parça çıkar",subtitle:"Ertelediğin tek iş. Beş derste işe başla, engelle ilgilen ve dürüst bir planla geri dön.",description:"Ertelediğin iş yüzünden kendini yargılamayı bırak. İşin kullanabileceğin küçük bir kısmını tamamla, önüne çıkan engeli kaydet. Haftanın ihtiyacına göre üzerine düşeni düzelt veya planını değiştir.",scope:"Gündelik erteleme için beceri eğitimi. Terapi değildir. Erteleme yoğun kaygı, uzun süren çökkünlük veya dikkat güçlükleriyle birlikte sürüyor ve hayatını belirgin biçimde etkiliyorsa bir uzmandan destek alabilirsin.",outcome:"İşe yarayan küçük bir parça, engel çıktığında ne yapacağın ve sıradaki uygun tarih.",photo:{id:"1758598304525-c2bc7aada66d",alt:"Bitkilerle çevrili bir masada dizüstü bilgisayarıyla çalışan kadın"},lang:"tr",lessons:u.map((a,t)=>{const i=a.judgment.primary,e=i.options.find(n=>n.id===i.bestOptionId),l=i.options.filter(n=>n.id!==i.bestOptionId);return l.splice(d[t],0,e),{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,practice:[...a.move.instructions,"Buraya dönüp gerçekte ne olduğunu kaydet."].slice(0,E[t]),reflection:a.direction.reason.label,question:`${i.scenario} ${i.question}`,options:l.map(n=>n.text),correct:d[t],feedback:e.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,deeper:a.goDeeper.sections,example:a.idea.example,photo:O[t]}})},J=Object.freeze(Object.defineProperty({__proto__:null,COURSE:j,LESSONS_V2:u,SOURCES:T},Symbol.toStringTag,{value:"Module"})),P=[{id:"S01",title:"Trauer ve arkadaşları · 2015 · Kronik uykusuzlukta BDT-I",url:"https://doi.org/10.7326/M14-2841",type:"research",finding:"1.162 yetişkinin katıldığı 20 çalışmada, yüz yüze ve birden fazla bileşen içeren BDT-I, günlüklerde bildirilen uykuya dalma süresini 19,03 dakika, gece uyanık kalma süresini 26,00 dakika azalttı. Toplam uyku 7,61 dakika arttı; güven aralığı hiç fark olmamasını da kapsıyordu.",limitation:"Çalışmanın özetine erişildi. Dar katılım ölçütleri ve aktif olmayan karşılaştırmalar, bulgunun başka koşullara aktarılmasını sınırlar. Bunlar tedavi sonundaki ortalamalar, ODA için tahminler değil. Toplam uykudaki belirsiz fark, uykunun daha az bölünmesindeki yararı geçersiz kılmaz."},{id:"S03",title:"Furukawa ve arkadaşları · 2024 · BDT-I bileşenleri",url:"https://jamanetwork.com/journals/jamapsychiatry/fullarticle/2814164?resultClick=1",type:"research",finding:"31.452 yetişkinin katıldığı 241 çalışmanın bileşen ağ analizinde, uyaran kontrolü ve uyku kısıtlama, uykusuzluğun düzelmesiyle ilişkili bulundu. Tek başına uyku hijyeninin ek katkısı için odds oranı 1,01 idi (%95 güven aralığı 0,77–1,32).",limitation:"Model, bileşenlerin etkilerinin toplanabileceğini varsayar. Her bileşenin ayrı ayrı rastgele atamayla sınanması değildir. Gevşemenin güven aralığı 1'i içerdiği için gevşemenin uykuya zarar verdiğini göstermez. ODA, BDT-I tedavisi değildir."},{id:"S04",title:"Edinger ve arkadaşları · 2021 · AASM uykusuzluk tedavi kılavuzu",url:"https://doi.org/10.5664/jcsm.8986",type:"guidance",finding:"Kronik uykusuzluk için birden fazla bileşenden oluşan BDT-I tedavisini güçlü biçimde önerir. Uyku hijyeninin tek tedavi olmasına karşı koşullu öneri verir. Bazı bileşenlerin tek başına kullanımı için de koşullu öneriler vardır.",limitation:"Yayıncının önerilerine erişildi. Bu, alışkanlık eğitiminin destek olarak yararsız olduğu veya bir uygulamanın uyku kısıtlama programı verebileceği anlamına gelmez."},{id:"S05",title:"American College of Physicians · 2016 · Uykusuzlukta ilk tedavi",url:"https://www.acponline.org/acp-newsroom/acp-recommends-cognitive-behavioral-therapy-as-initial-treatment-for-chronic-insomnia",type:"guidance",finding:"Yetişkinlerin kronik uykusuzluğunda ilk tedavi olarak BDT-I önerilir. Bireysel veya grup görüşmeleri, telefon ya da internet modülleri ve yapılandırılmış kendi kendine yardım seçenekleri kullanılabilir. İlaçla ilgili kararlar bir hekimle konuşularak verilmelidir.",limitation:"Bu, bir deney değil, resmî kılavuz özetidir. Kronik uykusuzluğun tanımındaki süre, değerlendirme için bekleme koşulu değildir. Her dijital ürünün doğrulanmış BDT-I olduğu da söylenemez."},{id:"S06",title:"NIH/NHLBI · 2022 · Uykusuzluk tedavisi",url:"https://www.nhlbi.nih.gov/health/insomnia/treatment",type:"guidance",finding:"BDT-I, genellikle altı ila sekiz haftalık, birden fazla bileşen içeren bir tedavi olarak anlatılır. Yüz yüze, telefonla ve internet üzerinden sunulabilir. Uyaran kontrolü, uykun gelince yatmayı ve uyuyamadığında yataktan çıkmayı içerir.",limitation:"Bu, hastalar için rehberdir; bir deney veya kendi kendine uyku kısıtlama izni değildir. ODA'nın beş dersi, anlatılan tedaviyi uygulamış sayılmaz."},{id:"S07",title:"Watson ve arkadaşları · 2015 · Yetişkinlerde uyku süresi uzlaşısı",url:"https://www.aasm.org/resources/pdf/adultsleepdurationconsensus.pdf",type:"guidance",finding:"18–60 yaş arasındaki yetişkinlere düzenli olarak en az yedi saat uyku önerilir. İhtiyaç kişiden kişiye değişir. Hastalıkta veya toparlanma döneminde daha uzun uyku uygun olabilir.",limitation:"Uzlaşı metninin tamamına ve yöntemlerine erişildi. Bu, genel nüfus için öneridir; kişisel hedefini tam olarak belirlemez. Yatakta geçen süre ile uyku aynı değildir. Sağlıkla ilgili ilişkiler, tek bir kişide neden sonuç bağı kurmaz."},{id:"S08",title:"CDC · 2024 · Uyku hakkında",url:"https://www.cdc.gov/sleep/about/index.html",type:"guidance",finding:"Uykunun hem süresi hem kalitesi önemlidir. Öneriler yaşa göre değişir. Düzenli uyku sorunları veya uyku bozukluğu belirtileri sağlık desteği gerektirir. İstersen bir günlükte uyku, uyanma, kestirme, madde kullanımı ve ilaçlarını kaydedebilirsin.",limitation:"Bu, halka yönelik rehberdir. Hekimle görüşmeden önce günlük doldurman gerekmez. Önerilen süre kadar uyuman, uyku bozukluğu olmadığını göstermez."},{id:"S09",title:"Gardiner ve arkadaşları · 2023 · Kafeinin sonraki uykuya etkisi",url:"https://www.colegiomedico.cl/wp-content/uploads/2023/07/cafe-y-sueno.pdf",type:"research",finding:"24 çalışmada kafein, sonraki uykuyu ortalama olarak olumsuz etkiledi. Nesnel ölçülen toplam uyku 45,3 dakika daha kısaydı (%95 güven aralığı: 29,0–61,5 dakika daha kısa). Alınan miktar ve saat, sonuçları etkiliyordu.",limitation:"Derlemenin tamamına erişildi. Bu, sıradan bir içeceğin sende yaratacağı etki için tahmin değildir. Modelle bulunan saat sınırları, kanıtlanmış kişisel güvenlik sınırları değildir. Duyarlılık ve düzenli kullanım kişiden kişiye değişir."},{id:"S10",title:"FDA · Ne kadar kafein fazladır?",url:"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much",type:"guidance",finding:"Çoğu yetişkinde günde 400 mg kafein genellikle olumsuz etkilerle ilişkili değildir; duyarlılık değişir. Ürünlerin ve porsiyonların gerçek miktarları farklıdır. Kademeli azaltmak, kafeini azaltmaya bağlı yoksunluk belirtilerini sınırlayabilir.",limitation:"Tüketici rehberidir; uykuyu etkilemeyen bir izin veya tüketim hedefi değildir. Gebelik, emzirme, ilaç ve sağlık durumuyla ilgili sorular için uzman görüşü gerekir. Kafeinsiz ürünler de kafein içerebilir. Güncelleme tarihi doğrulanmadı."},{id:"S11",title:"NHS · 2024 · Uykusuzluk",url:"https://www.nhs.uk/conditions/insomnia/",type:"guidance",finding:"Değişiklikler yardımcı olmadıysa veya uyku sorunu günlük hayatını sürdürmeni zorlaştırıyorsa sağlık desteği al. Uykun geldiğinde yat. Uykuluyken araç kullanma. Vardiya, hastalık ve ilaçlar da uyku sorununa katkıda bulunabilir.",limitation:"Üç ay, sorunun ne kadar süredir devam ettiğini tanımlar; yardım için bekleme koşulu değildir. Alışkanlıklarla ilgili genel süreler birer öneridir, kişiye özel güvenlik sınırı değildir. Bu bir rehber, tanı değil."},{id:"S12",title:"NHS · 2026 · Uyku apnesi",url:"https://www.nhs.uk/conditions/sleep-apnoea/",type:"guidance",finding:"Uykuda nefesin kesilmesi, nefes nefese veya boğulur gibi uyanmak ve gündüz aşırı uykululuk, tıbbi değerlendirme nedenidir. Sık uyanma, yüksek sesle horlama, baş ağrısı ve dikkat güçlüğü de belirtiler arasında olabilir.",limitation:"Belirti listesiyle apne tanısı konmaz. Yalnız yaşaman veya seni uyurken gören birinin olmaması, değerlendirme istemene engel değildir. Gevşeme, tıkalı solunumu tedavi etmez."},{id:"S13",title:"Drake ve arkadaşları · 2013 · Yüksek doz kafeinin saati",url:"https://doi.org/10.5664/jcsm.3170",type:"research",finding:"Sağlıklı uyuyan 12 kişide, yatmadan sıfır, üç ve altı saat önce alınan tek 400 mg doz, plaseboya göre uykuyu bozdu. AASM özeti, altı saat önce alındığında ölçülen uykunun bir saatten fazla azaldığını bildirir.",limitation:"Birincil makale özetine ve resmî AASM özetine erişildi. Küçük ve yüksek dozlu bir deneydir. Herkes için altı saat sınırı koymaz, çayın etkisini tahmin etmez. Etkinin kesin güven aralığına erişilemedi."},{id:"S14",title:"Chang ve arkadaşları · 2015 · Akşam e-okuyucu kullanımı",url:"https://doi.org/10.1073/pnas.1418490112",type:"research",finding:"Sağlıklı 12 genç yetişkin, her koşulda beş akşam boyunca dört saat iPad veya basılı metin okudu. E-okuyucu, uykuya dalmayı ve melatonin zamanlamasını geciktirdi. Ayrılan uyku süresi içinde toplam uyku farklı değildi.",limitation:"Yayımlanan çalışmanın tamamına erişildi. Uzun ve kontrollü kullanım, telefona kısaca bakmakla aynı değildir. Bu deney, ekranı 30 dakika önce kapatma sınırını test etmedi."},{id:"S15",title:"He ve arkadaşları · 2020 · Yatmadan önce telefon kullanımı pilotu",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0228756",type:"research",finding:"Gönüllü 38 üniversite katılımcısıyla yapılan rastgele kontrollü pilotta, yatmadan 30 dakika önce telefon kullanmamak denendi. Kısıtlamalar, hatırlatmalar ve her gece kontroller vardı. Katılımcıların bildirdiği sonuçlar uygulama grubunun lehineydi.",limitation:"Küçük, körleme yapılmamış bir pilot. Bazı katılımcılar dışlandı; uygulamayı sürdürmek için aktif destek vardı. Sonuçlar dört haftayı anlatırken Yöntem bölümü belirsiz biçimde bir haftadan söz eder. Uykuya dalma süresindeki yaklaşık 12 dakikalık iyileşme, rastgele atanmış gruplar arasındaki fark değil, grubun kendi içindeki değişimdir."},{id:"S17",title:"National Sleep Foundation · 2025 · Işık ve uyku",url:"https://www.thensf.org/good-light-bad-light-and-better-sleep/",type:"guidance",finding:"Gündüz dışarıda ışık almayı ve akşam daha loş ışık kullanmayı önerir. Dışarıda ve ekransız geçirilecek birer saat gibi pratik öneriler de içerir.",limitation:"Bu, en az etkili süreyi deneyle belirlemeyen halka yönelik eğitimdir. Pencere kenarında oturmanın dışarıda olmakla eşdeğer olduğu gösterilmemiştir. Vardiya, erişim, görme, hareket ve gerekli iletişime göre uyarlamak gerekir."},{id:"S19",title:"Stutz ve arkadaşları · 2019 · Akşam egzersizi ve uyku",url:"https://doi.org/10.1007/s40279-018-1015-0",type:"research",finding:"Sağlıklı yetişkinlerle yapılan 23 çalışmada akşam egzersizi genel olarak uykuyu kötüleştirmedi. Yatmadan bir saat içinde biten çok yoğun egzersizin etkisi farklı olabilir.",limitation:"Çalışmanın özetine erişildi. Sonucu değiştiren koşullarla ilgili bulgular, tek bir çalışmaya duyarlıydı. Her geç egzersizin zararsız olduğunu göstermez; uykusuzluk yaşayan kişilere doğrudan aktarılamaz. Herkese akşam egzersizi yasağı çıkarılamaz."},{id:"S20",title:"Schutte-Rodin ve arkadaşları · 2008 · Uyaran kontrolü rehberi",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Uyaran kontrolü, kişinin uzun süredir uyanık olduğunu fark etmesine göre ilerler. Sessiz bir etkinliği, uykun gelince geri dönmeyi ve saate bakmamayı önerir. Yorgunluk ile uykululuk ayrı şeylerdir.",limitation:"İlgili protokolün tamamına erişildi. Yaklaşık dakikalar biyolojik bir eşik değildir. Eski tanı ve ilaç önerileri burada kullanılmaz. Gece hareket etmek erişim veya güvenlik sorunu yaratıyorsa bir hekimle birlikte uyarlamak gerekir."},{id:"sleep-duration",title:"Watson ve arkadaşları · 2015 · Yetişkinlerde uyku süresi uzlaşısı",url:"https://www.aasm.org/resources/pdf/adultsleepdurationconsensus.pdf",type:"guidance",finding:"18–60 yaş arasındaki yetişkinlere düzenli olarak en az yedi saat uyku önerilir. İhtiyaç kişiden kişiye değişir. Hastalıkta veya toparlanma döneminde daha uzun uyku uygun olabilir.",limitation:"Uzlaşı metninin tamamına ve yöntemlerine erişildi. Bu, genel nüfus için öneridir; kişisel hedefini tam olarak belirlemez. Yatakta geçen süre ile uyku aynı değildir. Sağlıkla ilgili ilişkiler, tek bir kişide neden sonuç bağı kurmaz."},{id:"cdc-sleep",title:"CDC · 2024 · Uyku hakkında",url:"https://www.cdc.gov/sleep/about/index.html",type:"guidance",finding:"Uykunun hem süresi hem kalitesi önemlidir. Öneriler yaşa göre değişir. Düzenli uyku sorunları veya uyku bozukluğu belirtileri sağlık desteği gerektirir. İstersen bir günlükte uyku, uyanma, kestirme, madde kullanımı ve ilaçlarını kaydedebilirsin.",limitation:"Bu, halka yönelik rehberdir. Hekimle görüşmeden önce günlük doldurman gerekmez. Önerilen süre kadar uyuman, uyku bozukluğu olmadığını göstermez."},{id:"sleep-light",title:"National Sleep Foundation · 2025 · Işık ve uyku",url:"https://www.thensf.org/good-light-bad-light-and-better-sleep/",type:"guidance",finding:"Gündüz dışarıda ışık almayı ve akşam daha loş ışık kullanmayı önerir. Dışarıda ve ekransız geçirilecek birer saat gibi pratik öneriler de içerir.",limitation:"Bu, en az etkili süreyi deneyle belirlemeyen halka yönelik eğitimdir. Pencere kenarında oturmanın dışarıda olmakla eşdeğer olduğu gösterilmemiştir. Vardiya, erişim, görme, hareket ve gerekli iletişime göre uyarlamak gerekir."},{id:"sleep-habits",title:"Schutte-Rodin ve arkadaşları · 2008 · Uyaran kontrolü rehberi",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Uyaran kontrolü, kişinin uzun süredir uyanık olduğunu fark etmesine göre ilerler. Sessiz bir etkinliği, uykun gelince geri dönmeyi ve saate bakmamayı önerir. Yorgunluk ile uykululuk ayrı şeylerdir.",limitation:"İlgili protokolün tamamına erişildi. Yaklaşık dakikalar biyolojik bir eşik değildir. Eski tanı ve ilaç önerileri burada kullanılmaz. Gece hareket etmek erişim veya güvenlik sorunu yaratıyorsa bir hekimle birlikte uyarlamak gerekir."},{id:"caffeine-timing",title:"Drake ve arkadaşları · 2013 · Yüksek doz kafeinin saati",url:"https://doi.org/10.5664/jcsm.3170",type:"research",finding:"Sağlıklı uyuyan 12 kişide, yatmadan sıfır, üç ve altı saat önce alınan tek 400 mg doz, plaseboya göre uykuyu bozdu. AASM özeti, altı saat önce alındığında ölçülen uykunun bir saatten fazla azaldığını bildirir.",limitation:"Birincil makale özetine ve resmî AASM özetine erişildi. Küçük ve yüksek dozlu bir deneydir. Herkes için altı saat sınırı koymaz, çayın etkisini tahmin etmez. Etkinin kesin güven aralığına erişilemedi."},{id:"caffeine-amounts",title:"FDA · Ne kadar kafein fazladır?",url:"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much",type:"guidance",finding:"Çoğu yetişkinde günde 400 mg kafein genellikle olumsuz etkilerle ilişkili değildir; duyarlılık değişir. Ürünlerin ve porsiyonların gerçek miktarları farklıdır. Kademeli azaltmak, kafeini azaltmaya bağlı yoksunluk belirtilerini sınırlayabilir.",limitation:"Tüketici rehberidir; uykuyu etkilemeyen bir izin veya tüketim hedefi değildir. Gebelik, emzirme, ilaç ve sağlık durumuyla ilgili sorular için uzman görüşü gerekir. Kafeinsiz ürünler de kafein içerebilir. Güncelleme tarihi doğrulanmadı."},{id:"nhs-insomnia",title:"NHS · 2024 · Uykusuzluk",url:"https://www.nhs.uk/conditions/insomnia/",type:"guidance",finding:"Değişiklikler yardımcı olmadıysa veya uyku sorunu günlük hayatını sürdürmeni zorlaştırıyorsa sağlık desteği al. Uykun geldiğinde yat. Uykuluyken araç kullanma. Vardiya, hastalık ve ilaçlar da uyku sorununa katkıda bulunabilir.",limitation:"Üç ay, sorunun ne kadar süredir devam ettiğini tanımlar; yardım için bekleme koşulu değildir. Alışkanlıklarla ilgili genel süreler birer öneridir, kişiye özel güvenlik sınırı değildir. Bu bir rehber, tanı değil."},{id:"insomnia-self-help",title:"Schutte-Rodin ve arkadaşları · 2008 · Uyaran kontrolü rehberi",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Uyaran kontrolü, kişinin uzun süredir uyanık olduğunu fark etmesine göre ilerler. Sessiz bir etkinliği, uykun gelince geri dönmeyi ve saate bakmamayı önerir. Yorgunluk ile uykululuk ayrı şeylerdir.",limitation:"İlgili protokolün tamamına erişildi. Yaklaşık dakikalar biyolojik bir eşik değildir. Eski tanı ve ilaç önerileri burada kullanılmaz. Gece hareket etmek erişim veya güvenlik sorunu yaratıyorsa bir hekimle birlikte uyarlamak gerekir."},{id:"insomnia-guideline",title:"American College of Physicians · 2016 · Uykusuzlukta ilk tedavi",url:"https://www.acponline.org/acp-newsroom/acp-recommends-cognitive-behavioral-therapy-as-initial-treatment-for-chronic-insomnia",type:"guidance",finding:"Yetişkinlerin kronik uykusuzluğunda ilk tedavi olarak BDT-I önerilir. Bireysel veya grup görüşmeleri, telefon ya da internet modülleri ve yapılandırılmış kendi kendine yardım seçenekleri kullanılabilir. İlaçla ilgili kararlar bir hekimle konuşularak verilmelidir.",limitation:"Bu, bir deney değil, resmî kılavuz özetidir. Kronik uykusuzluğun tanımındaki süre, değerlendirme için bekleme koşulu değildir. Her dijital ürünün doğrulanmış BDT-I olduğu da söylenemez."},{id:"cbti-insomnia",title:"Trauer ve arkadaşları · 2015 · Kronik uykusuzlukta BDT-I",url:"https://doi.org/10.7326/M14-2841",type:"research",finding:"1.162 yetişkinin katıldığı 20 çalışmada, yüz yüze ve birden fazla bileşen içeren BDT-I, günlüklerde bildirilen uykuya dalma süresini 19,03 dakika, gece uyanık kalma süresini 26,00 dakika azalttı. Toplam uyku 7,61 dakika arttı; güven aralığı hiç fark olmamasını da kapsıyordu.",limitation:"Çalışmanın özetine erişildi. Dar katılım ölçütleri ve aktif olmayan karşılaştırmalar, bulgunun başka koşullara aktarılmasını sınırlar. Bunlar tedavi sonundaki ortalamalar, ODA için tahminler değil. Toplam uykudaki belirsiz fark, uykunun daha az bölünmesindeki yararı geçersiz kılmaz."},{id:"sleep-apnea",title:"NHS · 2026 · Uyku apnesi",url:"https://www.nhs.uk/conditions/sleep-apnoea/",type:"guidance",finding:"Uykuda nefesin kesilmesi, nefes nefese veya boğulur gibi uyanmak ve gündüz aşırı uykululuk, tıbbi değerlendirme nedenidir. Sık uyanma, yüksek sesle horlama, baş ağrısı ve dikkat güçlüğü de belirtiler arasında olabilir.",limitation:"Belirti listesiyle apne tanısı konmaz. Yalnız yaşaman veya seni uyurken gören birinin olmaması, değerlendirme istemene engel değildir. Gevşeme, tıkalı solunumu tedavi etmez."},{id:"sleep-cbti-overview",title:"NIH/NHLBI · 2022 · Uykusuzluk tedavisi",url:"https://www.nhlbi.nih.gov/health/insomnia/treatment",type:"guidance",finding:"BDT-I, genellikle altı ila sekiz haftalık, birden fazla bileşen içeren bir tedavi olarak anlatılır. Yüz yüze, telefonla ve internet üzerinden sunulabilir. Uyaran kontrolü, uykun gelince yatmayı ve uyuyamadığında yataktan çıkmayı içerir.",limitation:"Bu, hastalar için rehberdir; bir deney veya kendi kendine uyku kısıtlama izni değildir. ODA'nın beş dersi, anlatılan tedaviyi uygulamış sayılmaz."}],U={id:"sleep",title:"Sabah yine yorgun musun? Bu akşam dinlenmeye yer aç",subtitle:"Beş ders. Akşamını uzatan bir işi bitir, gerekli aramaları açık tut ve denemenin neyi değiştirdiğine bak.",description:"Dinlenmek için hayatına uyan bir zaman ayır. Önüne çıkan bir engeli değiştir. Kayıtlarına göre gelecek haftayı planla veya gecikmeden sağlık desteği al.",scope:"Yetişkinler için uyku alışkanlıkları eğitimi. Tanı veya tedavi değildir. Düzenli uyku sorunu günlük hayatını sürdürmeni zorlaştırıyorsa, değişiklikler işe yaramıyorsa, nefes nefese uyanıyor, uykuda nefesin kesiliyor veya gündüz uykululuğun sürüyorsa sağlık desteği al. Yalnız yaşamak veya notların eksik olması değerlendirmeyi geciktirmesin. Uykuluyken araç kullanma veya tehlikeli iş yapma. İlaçlarını değiştirme. Kendi kendine uyku kısıtlama uygulama. Planını vardiyana, bakım sorumluluklarına, engelliliğe ve gerekli iletişime göre uyarla. Yoğun sıkıntı veya kendine zarar verme düşünceleri için uygun acil uzman desteğine ya da kriz desteğine başvur. Güvenliğini koruyamıyorsan veya yakın tehlike varsa bulunduğun yerdeki acil yardım hizmetlerine ulaş.",outcome:"Tekrarlayabileceğin bir dinlenme adımı, olanları dürüstçe anlatan kayıtlar ve çözülmeyen güçlük için gelecek hafta planı veya sağlık desteği.",photo:{id:"1606796913825-2b02883605e9",alt:"Yeşil bir bitkinin yanında beyaz çarşaflı yatak"},lessons:[{id:"sleep-1",schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"sleep-1",courseId:"sleep",locale:"tr",title:"Bir video daha derken gece yarısı mı oldu?",goal:"Erteleyebileceğin bir etkinliği bitir. Dinlenmek için sana uyan bir zaman ayır.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Sen “Bir tane daha” derken yarın yaklaşıyor. Dinlenmeye zaman kalmadan, bu akşam hangi etkinliği bitireceğini seç.",reason:{id:"sleep-1-reason",label:"Yarın neye gücün gerekecek? Bu akşam neyi erken bitirebilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Kahvaltıda sabır; videolar bitebilir","Yarınki vardiya; zorunlu olmayan e-postalar bekleyebilir","Önce bakım; güvenle bırakabileceğim bir iş yok"]},why:{id:"sleep-1-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["18 ile 60 yaş arasındaki yetişkinler için yedi saat, önerilen en az uyku süresidir. Herkesin tam yedi saate ihtiyacı olduğu anlamına gelmez. Yatakta yedi saat geçirmek de yedi saat uyumak değildir. Yatma saatini yeni bir son teslim saatine çevirmeden, kendi ihtiyacına yer aç.","Dinleneceğin zamandan önce, erteleyebileceğin bir etkinliği bitirmeyi seç. Önce günü yavaşça kapat, uykun gelince yat. Burada denediğin şey, senin elinde olan bu geçiş. Onu uykundan ve sabahki enerjinden ayrı kaydet. Vardiyana, bakım sorumluluklarına ve gerekli aramalara göre uyarla. Yeterince dinlenmek sürekli mümkün olmuyorsa, bu koşulları değiştirmek için yardım iste."],example:{title:"Deniz videoyu nerede bırakıyor?",text:"Deniz, kızıyla birlikte yaptığı kahvaltıda sabırlı olmak istiyor. Saat 21.30'da izlediği program tekrarını bitirip dizüstü bilgisayarını kapatıyor. Erken vardiyasından önce dinlenmeye yer açıyor. Uykusu gelince yatıyor. Bakım için gelen bir arama akşamını bölüyor. Sabah bilgisayarı kapattığını ve aramayı ayrı ayrı kaydediyor. Hâlâ yorgun hissediyor."}},move:{invitation:"Bitirmek için seçtiğin an sana uyuyorsa koru. İlk planınsa bu video örneğinde etkinliği ve zamanı kendine göre yaz.",instructions:["Dinleneceğin zamanı ve dinlenmeye geçmeni hatırlatacak, gününde zaten olan bir anı belirle.","O an geldiğinde seçtiğin etkinliği bitir. Uykun gelince yatağa git."],prompts:[],suggestions:{action:["Akşam toparlandıktan sonra zorunlu olmayan videoları kapat","Akşam yemeğinden sonra ertelenebilir işi bırak","İyi geceler mesajından sonra grup sohbetini bitir"],minimum:["İzlediğim zorunlu olmayan videoları kapat","Erteleyebileceğim bir işi kenara bırak","İyi geceler de, grup sohbetini bitir"],cue:["Bu akşam ortalığı toparladıktan sonra","Son zorunlu işimi bitirdikten sonra","Planladığım iyi geceler mesajından sonra"],place:["Salondaki koltuğumda","Dizüstü bilgisayarımın yanında","Rahatça erişebildiğim dinlenme yerinde"],minutes:[2,1,5],fallback:["Gerekli bakımı bitir, sonra zorunlu olmayan videoları kapat","Gerekli aramalar için ulaşılabilir kal","Dinlenmeye yer açmak için yardım iste"],observation:["Seçtiğim anda bitirdiğim etkinlik","Bakımın planımı değiştirip değiştirmediği","Sabahki enerjim, ayrı bir not"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Akşam toparlandıktan sonra zorunlu olmayan videoları kapat",minimum:"İzlediğim zorunlu olmayan videoları kapat",minutes:2,cueHint:"Bu akşam ortalığı toparladıktan sonra",placeHint:"Salondaki koltuğumda",obstacleHint:"Zorunlu bir iş veya bakım ihtiyacı, seçtiğim anı bölüyor",fallbackHint:"Gerekli bakımı bitir, sonra zorunlu olmayan videoları kapat",observationHint:"Seçtiğim anda bitirdiğim etkinlik"},stopRule:"Uykuluyken araç kullanma. Uyku sorunu günlük hayatını sürdürmeni zorlaştırıyorsa sağlık desteği al.",accessibleAlternative:"Başlayacağın anı vardiyana, engelliliğe veya bakım sorumluluğuna göre uyarla. Gerekli iletişimi açık tut."},result:{question:"Bitirmeyi seçtiğin etkinliği bitirdin mi?",observationPrompt:"Neyi bitirdin? Dinlenmek için ayırabildiğin zamanı hangi durum değiştirdi?"},judgment:{primary:{id:"sleep-1-decision",scenario:"Deniz sabah 6'da kalkıyor. Genellikle yedi saatten fazla uykuya ihtiyacı var. İzlemesi gerekmeyen videolar yüzünden gece yarısından sonra yatıyor.",question:"Hangi plan ona dinlenmek için yeterli zaman bırakır?",options:[{id:"sleep-1-short-window",text:"Videoları saat on birden hemen önce bitirsin. Yedi saat ayırsın ve yarın nasıl hissettiğine baksın.",feedback:"Bu, biraz zaman kazandırır. Ama yedi saat genel bir alt sınır, Deniz'in kişisel hedefi değil. Kendi ihtiyacı için dinlenmeye daha erken geçmeli. Kendini uyumaya zorlaması gerekmez."},{id:"sleep-1-earlier-transition",text:"Zorunlu olmayan videoları daha erken bitirsin. Dinlenmeye geçsin. Bu geçişi uyku kalitesinden ayrı kaydetsin.",feedback:"Deniz bu seçenekte kendi elindeki şeyi değiştirir ve bildiği ihtiyacına yer açar. Uykusu gelince yatmak, saati “Şimdi uyumalısın” emrine dönüştürmesini önler."},{id:"sleep-1-weekend-recovery",text:"Bu akşam videoları izlesin. Hafta sonu daha çok dinlenmeyi ayarlasın. Yoğun hafta bitince düzenine yeniden baksın.",feedback:"Fazladan dinlenmek işe yarayabilir. Ama bu akşam önleyebileceği zaman kaybı aynı kalır. Deniz, daha geniş programını ve sorumluluklarını düzenlerken bu akşamki geçişi de koruyabilir."}],bestOptionId:"sleep-1-earlier-transition"}},carry:{takeaway:"Dinlenmeye yer aç. Günü kapatmak için yaptığını ve nasıl uyuduğunu ayrı ayrı anlat.",followUp:{questionId:"sleep-1-return",question:"Etkinliği seçtiğin anda bitirmek, dinlenmen için yeterli zaman bıraktı mı?",observationPrompt:"Seçtiğin başlangıç anı geldiğinde ne oldu?",adjustmentPrompt:"Neyi tekrarlamalı, değiştirmeli veya hangi konuda yardım istemelisin?"}},goDeeper:{sections:[{heading:"En az süre, senin kişisel hedefin değil",paragraphs:["AASM ve Sleep Research Society uzlaşısı, 18 ile 60 yaş arasındaki yetişkinlere düzenli olarak en az yedi saat uyku önerir [S07]. Uzmanlar araştırmaları inceleyerek bu öneriyi geliştirdi. Herkese yedi saatlik gece verip denemediler. Sağlıkla ilgili verilerin çoğu gözleme dayanır. Kısa uyku ile hastalık arasında ilişki bulunması, tek bir kötü gecenin sağlık sorununa neden olduğunu göstermez.","CDC, daha ileri yaşlar için farklı aralıklar verir: 61 ile 64 yaşta yedi ila dokuz saat, 65 yaş ve üzerinde yedi ila sekiz saat [S08]. Bunlar da genel nüfus için önerilerdir. Sürenin yanında uyku kalitesi, gün içindeki işlevin, hastalık ve toparlanma ihtiyacın önemlidir. Ayırdığın zaman kendi ihtiyacını ve uykuya geçişi karşılamalı. Bilgisayarı kapattığını kaydetmen o işi yaptığını gösterir. Ne kadar uyuduğunu veya neden hâlâ yorgun olduğunu belirleyemez."]},{heading:"Uyumaya zorlamadan yer aç",paragraphs:["NHS rehberi, uykun geldiğinde yatmanı ve uyku güçlüğü günlük hayatını sürdürmeni zorlaştırdığında sağlık desteği almanı önerir [S11]. Planladığın saat, ertelenebilir bir etkinliği bitirip dinlenmeye geçmenin başlangıcı olabilir. Hesapladığın yatma saati geldi diye yatakta uyanık kalman gerektiğini söylemez. Düzenli bir program yardımcı olabilir. Yine de vardiya, bakım, engellilik ve ev koşulları sana özel bir düzen gerektirebilir.","Bu kursta aynı denemeyi sürdüreceksin: dinlenmeye uygun zaman ayır, kendi elindeki adımı kaydet ve önüne gerçekten çıkan koşulu değiştir. Sonraki dersler, kayıtlarında ekran kullanımı, kafein veya uyumakta zorlanmak öne çıkıyorsa değişiklik önerir. Her geceye yeni bir ritüel eklemeni istemez. Sorumlulukların yeterince dinlenmene sürekli engel oluyorsa, pratik yardım veya bir hekimle görüşmek başka bir hatırlatmadan daha yararlı olabilir. Not yazmak sana kalır. Destek istemeden önce not tutman gerekmez."]}],sourceIds:["S07","S08","S11"]}},title:"Bir video daha derken gece yarısı mı oldu?",minutes:6,goal:"Erteleyebileceğin bir etkinliği bitir. Dinlenmek için sana uyan bir zaman ayır.",reading:["18 ile 60 yaş arasındaki yetişkinler için yedi saat, önerilen en az uyku süresidir. Herkesin tam yedi saate ihtiyacı olduğu anlamına gelmez. Yatakta yedi saat geçirmek de yedi saat uyumak değildir. Yatma saatini yeni bir son teslim saatine çevirmeden, kendi ihtiyacına yer aç.","Dinleneceğin zamandan önce, erteleyebileceğin bir etkinliği bitirmeyi seç. Önce günü yavaşça kapat, uykun gelince yat. Burada denediğin şey, senin elinde olan bu geçiş. Onu uykundan ve sabahki enerjinden ayrı kaydet. Vardiyana, bakım sorumluluklarına ve gerekli aramalara göre uyarla. Yeterince dinlenmek sürekli mümkün olmuyorsa, bu koşulları değiştirmek için yardım iste."],practice:["Sana uyan bir uyanma düzeni seç. Vardiyaya, bakım sorumluluklarına ve yeterli uykuya yer açacak şekilde uyarla.","Kendi uyku ihtiyacın ve uykuya geçiş için yeterli zaman ayır. Dinlenmeye geç; kendini uyumaya zorlama.","Önümüzdeki yedi gün boyunca ne zaman yatıp ne zaman kalktığına dair kısa bir not yaz."],reflection:"Seçtiğin kalkma saatini korumanı ne zorlaştırabilir?",question:"Yetişkinler için uyku önerisi nasıl anlaşılmalı?",options:["Herkes tam 8 saat uyumalı.","En az 7 saat, çoğu gece ulaşmayı hedeflediğin alt sınırdır.","Bir gece kötü uyursan sağlığın kesinlikle bozulur."],correct:1,feedback:"Öneri bir alt sınır verir ve düzenli alışkanlıklarla ilgilidir. Tek bir kötü gece, uzun süre devam eden bir sorunla aynı değildir.",takeaway:"Dinlenmeye yer aç. Günü kapatmak için yaptığını ve nasıl uyuduğunu ayrı ayrı anlat.",sources:["S07","S08","S11"],deeper:[{heading:"En az süre, senin kişisel hedefin değil",paragraphs:["AASM ve Sleep Research Society uzlaşısı, 18 ile 60 yaş arasındaki yetişkinlere düzenli olarak en az yedi saat uyku önerir [S07]. Uzmanlar araştırmaları inceleyerek bu öneriyi geliştirdi. Herkese yedi saatlik gece verip denemediler. Sağlıkla ilgili verilerin çoğu gözleme dayanır. Kısa uyku ile hastalık arasında ilişki bulunması, tek bir kötü gecenin sağlık sorununa neden olduğunu göstermez.","CDC, daha ileri yaşlar için farklı aralıklar verir: 61 ile 64 yaşta yedi ila dokuz saat, 65 yaş ve üzerinde yedi ila sekiz saat [S08]. Bunlar da genel nüfus için önerilerdir. Sürenin yanında uyku kalitesi, gün içindeki işlevin, hastalık ve toparlanma ihtiyacın önemlidir. Ayırdığın zaman kendi ihtiyacını ve uykuya geçişi karşılamalı. Bilgisayarı kapattığını kaydetmen o işi yaptığını gösterir. Ne kadar uyuduğunu veya neden hâlâ yorgun olduğunu belirleyemez."]},{heading:"Uyumaya zorlamadan yer aç",paragraphs:["NHS rehberi, uykun geldiğinde yatmanı ve uyku güçlüğü günlük hayatını sürdürmeni zorlaştırdığında sağlık desteği almanı önerir [S11]. Planladığın saat, ertelenebilir bir etkinliği bitirip dinlenmeye geçmenin başlangıcı olabilir. Hesapladığın yatma saati geldi diye yatakta uyanık kalman gerektiğini söylemez. Düzenli bir program yardımcı olabilir. Yine de vardiya, bakım, engellilik ve ev koşulları sana özel bir düzen gerektirebilir.","Bu kursta aynı denemeyi sürdüreceksin: dinlenmeye uygun zaman ayır, kendi elindeki adımı kaydet ve önüne gerçekten çıkan koşulu değiştir. Sonraki dersler, kayıtlarında ekran kullanımı, kafein veya uyumakta zorlanmak öne çıkıyorsa değişiklik önerir. Her geceye yeni bir ritüel eklemeni istemez. Sorumlulukların yeterince dinlenmene sürekli engel oluyorsa, pratik yardım veya bir hekimle görüşmek başka bir hatırlatmadan daha yararlı olabilir. Not yazmak sana kalır. Destek istemeden önce not tutman gerekmez."]}],example:{title:"Kurgusal örnek: Deniz videoyu nerede bırakıyor?",text:"Deniz, kızıyla birlikte yaptığı kahvaltıda sabırlı olmak istiyor. Saat 21.30'da izlediği program tekrarını bitirip dizüstü bilgisayarını kapatıyor. Erken vardiyasından önce dinlenmeye yer açıyor. Uykusu gelince yatıyor. Bakım için gelen bir arama akşamını bölüyor. Sabah bilgisayarı kapattığını ve aramayı ayrı ayrı kaydediyor. Hâlâ yorgun hissediyor."},photo:{id:"1767443522987-a83deb358199",alt:"Ahşap zeminde klasik çalar saat"}},{id:"sleep-2",schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"sleep-2",courseId:"sleep",locale:"tr",title:"Telefonu bırakıyorsun. Peki yerine ne koyuyorsun?",goal:"Ekransız bir ara dene. Ekranın karşıladığı ihtiyacı ve gerekli iletişimi koru.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Telefonu bıraktın, sonra yine eline aldın. Günü kapatırken hangi ihtiyacın karşılanmadan kaldı?",reason:{id:"sleep-2-reason",label:"Ekran hangi ihtiyacını karşılıyor? Ona hâlâ ihtiyacın var mı?",kind:"text",maxLength:160,optional:!0,suggestions:["Arkadaşlarımla konuşmak","Kullanabildiğim bir sesli kitap","Gece bakım için gelen aramalar","İhtiyaç yok; yine ekranda gezinmeye başladım"]},why:{id:"sleep-2-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Küçük bir laboratuvar çalışması, akşam dört saat e-okuyucu kullanımını test etti. Telefona kısaca bakmayı değil. Uyku zamanlaması değişti, ama tek bakışın sana neye mal olduğunu söyleyemez. Yatmadan önce telefon kullanımıyla ilgili başka bir pilotta hatırlatmalar ve gece kontrolleri vardı. Sadece telefonu sessize almak, araştırmada denenen program değildi.","Dinlenmeye zaman ayırmak için tuttuğun kayda bak. Zorunlu olmayan ekran kullanımı günü kapatmanı geciktirdiyse aynı ihtiyacı başka şekilde karşıla: daha erken konuşmak, kullanabildiğin bir ses kaydı veya basılı kitap. Beş ekransız dakika, daha küçük bir kişisel deneme olabilir. Çalışmadaki etkiyi sağlayacağını söylemez. Gerekli aramalar ulaşabilsin. Ekran engel olmadıysa seçtiğin adımı sürdür."],example:{title:"Deniz arkadaşlarıyla bağı koparmıyor",text:"Deniz'in notları, geç gelen grup mesajlarıyla akşamın tekrar uzadığını gösteriyor. Günü kapatmak için seçtiği an geldiğinde kısa bir iyi geceler mesajı gönderiyor. Beş dakika çevrimdışı ses kaydı dinliyor. Bakım için gereken aramaların sesi açık. Bir mesaj yine aklını çeliyor. Ekransız süreyi kaydediyor; bütün akşama ekransız demiyor, daha iyi uyuduğunu iddia etmiyor."}},move:{invitation:"İşe yarayan alternatifini koru. İlk planınsa bu çevrimdışı dinleme örneğini, günü kapatırken ihtiyacını karşılayacak şekilde düzenle.",instructions:["Ekran kullanımı seçtiğin adımı engellediyse o süreyi değiştir.","Kaydetmeden önce alternatifi, bırakacağın anı ve gerekli aramalar için ulaşılabilir yolu belirle."],prompts:[],suggestions:{action:["Sohbeti bitir, indirdiğim ses kaydını dinle","İyi geceler mesajından sonra basılı kitap oku","Akşam toparlandıktan sonra zorunlu olmayan videoları kapat"],minimum:["İndirdiğim ses kaydını beş dakika dinle","Beş dakika basılı kitap oku","İzlediğim zorunlu olmayan videoları kapat"],cue:["Bu akşam planladığım iyi geceler mesajından sonra","Konuşmak için ayırdığım zamanın ardından","Akşam toparlandıktan sonra, yeni video açmadan"],place:["Koltuğumda, bakım için gelen aramaların sesi açıkken","Ulaşılabilir telefonumun yakınında","Dinlenmeye geçtiğim her zamanki yerde"],minutes:[5,2,10],fallback:["Sohbeti bitir; gerekli aramalar ve ses kaydı kalsın","Kullanabildiğim çevrimdışı ses kaydını dinle","Yerine elimdeki basılı kitabı oku"],observation:["Dinlediğim kayıt, süre ve gerekli erişim","Gerekli iletişimin açık kalıp kalmadığı","Zorunlu olmayan ekran kullanımını yeniden başlatan şey"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sohbeti bitir, indirdiğim ses kaydını dinle",minimum:"İndirdiğim ses kaydını beş dakika dinle",minutes:5,cueHint:"Bu akşam planladığım iyi geceler mesajından sonra",placeHint:"Koltuğumda, bakım için gelen aramaların sesi açıkken",obstacleHint:"Telefonum bakım için açıkken zorunlu olmayan sohbete geri dönüyorum",fallbackHint:"Sohbeti bitir; gerekli aramalar ve ses kaydı kalsın",observationHint:"Dinlediğim kayıt, süre ve gerekli erişim"},stopRule:"Gerekli iletişimi ve güvenli aydınlatmayı koru. Bakımı aksatan değişikliği durdur.",accessibleAlternative:"Kullanabildiğin ses kaydını veya başka alternatifi seç. Gereken ekran araçları kalabilir."},result:{question:"Ekranın yerine seçtiğin etkinliği gerçekten yaptın mı?",observationPrompt:"Ekranın yerine ne koydun? Gerekli hangi erişimi açık tuttun?"},judgment:{primary:{id:"sleep-2-decision",scenario:"Deniz'in gece bakım için gelen aramaları alması gerekiyor. Dün grup sohbeti etkinliği bırakmasını geciktirdi. Basılı kitap ve indirilmiş ses kaydı hazır. Yakındaki telefonunda bakım için gereken aramaların sesi açık.",question:"Hangi değişiklik iki ihtiyacına da uyar?",options:[{id:"sleep-2-dim-only",text:"Ekran parlaklığını azaltıp yatakta sohbete devam etsin. Hem ulaşılabilir kalsın hem alıştığı akşam sohbetini sürdürsün.",feedback:"Parlaklığı azaltmak bir özelliği değiştirir. Ama devam eden sohbet, Deniz'in günü kapatmasını yine geciktirir. Gerekli aramalar açık kalırken sohbeti bitireceği anı ve yerine yapacağını seçmesi gerekir."},{id:"sleep-2-remove-phone",text:"Bakım için gereken aramaları alabileceği telefonun yanında basılı kitap okusun. Sayfa aralarında yanıtları tamamlamak için grup sohbetini açık bıraksın.",feedback:"Bakım için ulaşılabilir kalır ve okumayı ekrandan kitaba taşır. Ama sohbet açıkken bitirmeyi geciktiren etkinlik sürer. Alternatife geçmeden zorunlu olmayan yanıtları bitirsin. Bakım aramalarının sesi açık kalsın."},{id:"sleep-2-planned-handover",text:"Seçtiği anda sohbeti bitirsin. Bakım aramalarının sesi açık kalsın. Ekran yerine çevrimdışı seçeneğini kullansın.",feedback:"Bu seçim, gerekli iletişimi korurken dinlenmeyi geciktiren zorunlu olmayan etkinliği değiştirir. Beş ekransız dakika, planın uygulanabilirliğini sınar. Daha kapsamlı araştırma programının etkilerini sağlayacağını söylemez."}],bestOptionId:"sleep-2-planned-handover"}},carry:{takeaway:"Ekrana sınır koyarken ihtiyacını koru. O ihtiyacı başka bir yoldan karşılamayı dene.",followUp:{questionId:"sleep-2-return",question:"Alternatifin ihtiyacını karşıladı mı? Zorunlu olmayan ekran kullanımına geri döndün mü?",observationPrompt:"Seçtiğin başlangıç anı geldiğinde ne oldu?",adjustmentPrompt:"Neyi tekrarlamalı, değiştirmeli veya hangi konuda yardım istemelisin?"}},goDeeper:{sections:[{heading:"Cihaz çalışmaları neyi test etti?",paragraphs:["Chang ve arkadaşları, sağlıklı 12 genç yetişkinle hastanede kontrollü, çapraz bir deney yaptı [S14]. Katılımcılar her koşulda beş akşam, kısa bir mola vererek saat 18.00 ile 22.00 arasında iPad veya basılı metin okudu. E-okuyucu, uykuya dalmayı ve melatonin zamanlamasını geciktirdi. Planlanan sekiz saatlik fırsat içinde toplam uyku farklı değildi. Bu uzun süreli kullanımdır. Telefona her bakışın belirli bir uyku kaybı yarattığını göstermez.","He ve arkadaşları, uykusunu kötü olarak bildiren gönüllü 38 üniversite katılımcısını rastgele gruplara ayırdı [S15]. Telefon kısıtlamasında hatırlatmalar, cihaz kısıtlamaları veya kapatma ve her gece kontroller vardı. Sonuçlar dört haftayı anlatırken Yöntem bölümü belirsiz biçimde bir haftadan söz eder. Çalışma küçük ve körleme yapılmamıştı. Yaklaşık 12 dakikalık uykuya dalma iyileşmesi, rastgele atanmış gruplar arasındaki fark değil, grubun kendi içindeki değişimdi. ODA'nın isteğe bağlı ekran alternatifi, gerekli iletişim istisnası ve beş dakikalık en küçük adımı bunlarla eşdeğer olarak test edilmedi."]},{heading:"Işık önerisi hayatına uymalı",paragraphs:["National Sleep Foundation, gündüz dışarıda ışık almayı, akşam daha loş ışık kullanmayı önerir [S17]. Dışarıda veya ekransız geçirilecek birer saat, halka yönelik önerilerdir. Etkili olduğu doğrulanmış en az süreler değildir. Pencere kenarında oturmak sana uygun olabilir. Ama bu rehber, dışarıda ışık almakla eşdeğer olduğunu göstermez. Gece vardiyası, hava, görme, hareket ve bakım ihtiyaçları da hangi düzenin uygulanabileceğini etkiler.","Dinlenme denemene uyan tek değişiklik seç. Ekran kullanımı günü kapatmanı geciktirmiyorsa yeni bir saat sınırı eklemek yerine mevcut adımını koruyabilirsin. Sorun ışıkla ilgiliyse güvenli aydınlatma veya gündüz erişebileceğin bir fırsat seç. Yolu, hareket etmeyi tehlikeli hâle getirecek kadar karartma. Neyi değiştirdiğini, alternatifin amacına ulaşıp ulaşmadığını ve erişim sorunlarını kaydet. Bir sabah daha iyi veya kötü hissetmek, nedenin hangi değişiklik olduğunu tek başına göstermez."]}],sourceIds:["S14","S15","S17"]}},title:"Telefonu bırakıyorsun. Peki yerine ne koyuyorsun?",minutes:6,goal:"Ekransız bir ara dene. Ekranın karşıladığı ihtiyacı ve gerekli iletişimi koru.",reading:["Küçük bir laboratuvar çalışması, akşam dört saat e-okuyucu kullanımını test etti. Telefona kısaca bakmayı değil. Uyku zamanlaması değişti, ama tek bakışın sana neye mal olduğunu söyleyemez. Yatmadan önce telefon kullanımıyla ilgili başka bir pilotta hatırlatmalar ve gece kontrolleri vardı. Sadece telefonu sessize almak, araştırmada denenen program değildi.","Dinlenmeye zaman ayırmak için tuttuğun kayda bak. Zorunlu olmayan ekran kullanımı günü kapatmanı geciktirdiyse aynı ihtiyacı başka şekilde karşıla: daha erken konuşmak, kullanabildiğin bir ses kaydı veya basılı kitap. Beş ekransız dakika, daha küçük bir kişisel deneme olabilir. Çalışmadaki etkiyi sağlayacağını söylemez. Gerekli aramalar ulaşabilsin. Ekran engel olmadıysa seçtiğin adımı sürdür."],practice:["Gündüz ışık alabileceğin bir zaman seç. İçerideki alternatifin dışarıdaki ışıkla eşdeğer olduğu gösterilmedi.","Dinlenmeden önce seçtiğin ekran alternatifini dene. Pratik süreler birer öneridir; gerekli iletişim açık kalsın.","Ekran yerine loş ışıkta sakin bir etkinlik seç: kitap, hafif esneme veya müzik."],reflection:"Akşam hangi saatte ekranı bırakmak sana daha zor geliyor?",question:"Akşam ekran kullanımı için hangi adım resmî önerilere uyar?",options:["Yatağa girene kadar ekran kullanmak.","Ekranla ve bütün ışıklar açıkken dinlenmeye geçmek.","Yatmadan en az 30 dakika önce ekranları bırakmak."],correct:2,feedback:"CDC'nin 30 dakika önerisi pratik bir rehberdir; kesin eşik değildir. Sana uyan ekransız süreyi ve alternatifi seç. Gerekli iletişim açık kalsın.",takeaway:"Ekrana sınır koyarken ihtiyacını koru. O ihtiyacı başka bir yoldan karşılamayı dene.",sources:["S14","S15","S17","S08"],deeper:[{heading:"Cihaz çalışmaları neyi test etti?",paragraphs:["Chang ve arkadaşları, sağlıklı 12 genç yetişkinle hastanede kontrollü, çapraz bir deney yaptı [S14]. Katılımcılar her koşulda beş akşam, kısa bir mola vererek saat 18.00 ile 22.00 arasında iPad veya basılı metin okudu. E-okuyucu, uykuya dalmayı ve melatonin zamanlamasını geciktirdi. Planlanan sekiz saatlik fırsat içinde toplam uyku farklı değildi. Bu uzun süreli kullanımdır. Telefona her bakışın belirli bir uyku kaybı yarattığını göstermez.","He ve arkadaşları, uykusunu kötü olarak bildiren gönüllü 38 üniversite katılımcısını rastgele gruplara ayırdı [S15]. Telefon kısıtlamasında hatırlatmalar, cihaz kısıtlamaları veya kapatma ve her gece kontroller vardı. Sonuçlar dört haftayı anlatırken Yöntem bölümü belirsiz biçimde bir haftadan söz eder. Çalışma küçük ve körleme yapılmamıştı. Yaklaşık 12 dakikalık uykuya dalma iyileşmesi, rastgele atanmış gruplar arasındaki fark değil, grubun kendi içindeki değişimdi. ODA'nın isteğe bağlı ekran alternatifi, gerekli iletişim istisnası ve beş dakikalık en küçük adımı bunlarla eşdeğer olarak test edilmedi."]},{heading:"Işık önerisi hayatına uymalı",paragraphs:["National Sleep Foundation, gündüz dışarıda ışık almayı, akşam daha loş ışık kullanmayı önerir [S17]. Dışarıda veya ekransız geçirilecek birer saat, halka yönelik önerilerdir. Etkili olduğu doğrulanmış en az süreler değildir. Pencere kenarında oturmak sana uygun olabilir. Ama bu rehber, dışarıda ışık almakla eşdeğer olduğunu göstermez. Gece vardiyası, hava, görme, hareket ve bakım ihtiyaçları da hangi düzenin uygulanabileceğini etkiler.","Dinlenme denemene uyan tek değişiklik seç. Ekran kullanımı günü kapatmanı geciktirmiyorsa yeni bir saat sınırı eklemek yerine mevcut adımını koruyabilirsin. Sorun ışıkla ilgiliyse güvenli aydınlatma veya gündüz erişebileceğin bir fırsat seç. Yolu, hareket etmeyi tehlikeli hâle getirecek kadar karartma. Neyi değiştirdiğini, alternatifin amacına ulaşıp ulaşmadığını ve erişim sorunlarını kaydet. Bir sabah daha iyi veya kötü hissetmek, nedenin hangi değişiklik olduğunu tek başına göstermez."]}],example:{title:"Kurgusal örnek: Deniz arkadaşlarıyla bağı koparmıyor",text:"Deniz'in notları, geç gelen grup mesajlarıyla akşamın tekrar uzadığını gösteriyor. Günü kapatmak için seçtiği an geldiğinde kısa bir iyi geceler mesajı gönderiyor. Beş dakika çevrimdışı ses kaydı dinliyor. Bakım için gereken aramaların sesi açık. Bir mesaj yine aklını çeliyor. Ekransız süreyi kaydediyor; bütün akşama ekransız demiyor, daha iyi uyuduğunu iddia etmiyor."},photo:{id:"1527377761-f99968ed8a7f",alt:"Pencereden zemine düşen güneş ışığı"}},{id:"sleep-3",schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"sleep-3",courseId:"sleep",locale:"tr",title:"Akşamki kahve gece de peşini bırakmıyor mu?",goal:"Kaydında geç saatte içtiğin kafein dikkat çekiyorsa tek porsiyonu değiştir veya daha erken iç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kahveden sonra uykuya dalabilmen, geç saatte içmenin uykuna neye mal olduğunu tek başına açıklamaz.",reason:{id:"sleep-3-reason",label:"Geç saatte içtiğin bu içecek, olası etkisine rağmen sana ne sağlıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Zorunlu işi bitirmeme yardım ediyor","Uyuyorum; uyku kalitesi belirsiz","İçtiğim ve içmediğim gecelerin sabahlarını karşılaştırmadım","Deneyeceğim geç saat içeceği yok"]},why:{id:"sleep-3-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kafeinin etkisi miktara, saate ve kişisel duyarlılığa bağlı. Küçük bir deneyde tek 400 miligram doz, yatmadan altı saat önce alındığında bile uykuyu bozdu. Bu yüksek bir dozdu. Sıradan bir fincanın etkisini tahmin etmez. Altı saatin güvenli sınır olduğunu da göstermez.","Dinlenme kaydın geç saatteki bir içeceği işaret ediyorsa sadece onu değiştir. Daha erken iç, yerine başka içecek koy veya kademeli azalt. Gerçekte hangi ürünü ne zaman içtiğini yaz. Diğer önemli alışkanlıkların mümkün olduğunca aynı kalsın. Kayıt, sonraki seçimine yardımcı olabilir; neden sonuç ilişkisini kanıtlamaz. Kafein bu denemeyle ilgili değilse mevcut dinlenme adımını sürdür."],example:{title:"Deniz tek bir içeceği deniyor",text:"Deniz, not tuttuğu iki akşamda bilgisayarının yanında geç saatte büyük bir kahve olduğunu fark ediyor. Bugün zorunlu işini bitirirken onun yerine alıştığı kafeinsiz içeceği içiyor. Sabah kahvesini değiştirmiyor. Kahvenin verdiği canlılığı özlüyor; ertesi gün hâlâ yorgun. Tekrar denemeye karar vermeden önce değişikliği ve saatini kaydediyor."}},move:{invitation:"Hangi içeceği değiştireceğin belliyse seçimini koru. İlk planınsa bu kahve yerine su içme örneğini kendi içeceğine göre düzenle.",instructions:["Örneği kaydetmeden önce gerçek ürünü, porsiyonu, içme zamanını ve alternatifi belirle.","Yalnızca o porsiyonu değiştir. Ani değişiklik uygun değilse kademeli azaltmayı seç."],prompts:[],suggestions:{action:["Geç saatteki kahvem yerine su iç","Bir kafeinli içeceği daha erken iç","Düzenli içtiğim bir porsiyonu kademeli azalt"],minimum:["Geç saatte kahve yerine su iç","Bir porsiyonu daha erken iç","Seçtiğim daha küçük porsiyonu kullan"],cue:["Akşam kahveme uzandığımda","Her zamanki geç molamdan önce","Her zamanki içeceğimi aldığımda"],place:["Mutfak tezgâhımın başında","Her zamanki içeceğimi aldığım yerde","Çalışma masamın yanında"],minutes:[2,1,5],fallback:["Geç saatteki kahve yerine elimdeki suyu iç","Bana uygun bir dinlenme molası ver","Kademeli azaltmak için görüş al"],observation:["Ürün, porsiyon ve içtiğim saat","Planladığım porsiyonun değişip değişmediği","Sabah işlerimi yapabilmem, ayrı bir not"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Geç saatteki kahvem yerine su iç",minimum:"Geç saatte kahve yerine su iç",minutes:2,cueHint:"Akşam kahveme uzandığımda",placeHint:"Mutfak tezgâhımın başında",obstacleHint:"Tercih ettiğim kafeinsiz içecek elimde yok",fallbackHint:"Geç saatteki kahve yerine elimdeki suyu iç",observationHint:"Ürün, porsiyon ve içtiğim saat"},stopRule:"Uykuluyken araç kullanma. İlaçlarını değiştirme. Gebelik, emzirme veya sağlık kaygın varsa bir hekime danış.",accessibleAlternative:"Kademeli değiştir. Kafein bu denemeyle ilgili değilse mevcut adımını sürdür."},result:{question:"Değiştirmeyi seçtiğin tek porsiyonu değiştirdin mi?",observationPrompt:"Hangi içeceği, ne kadar ve hangi saatte içtin?"},judgment:{primary:{id:"sleep-3-decision",scenario:"Deniz'in geç saatteki kahvesi denemeye değer görünüyor. Bu hafta öğünlerini, ekran kullanımını ve egzersizini de değiştirmek istiyor.",question:"İlk denemede hangisinin sonucunu anlamak daha kolay?",options:[{id:"sleep-3-one-serving",text:"Geç saatte içtiği o kahveyi değiştirsin. Saatini yazsın. Diğer önemli alışkanlıklarını mümkün olduğunca aynı tutsun.",feedback:"Tek bir değişiklik, kaydı anlamayı kolaylaştırır; yine de neden sonuç ilişkisini kanıtlamaz. Deniz, aynı denemeye başka değişiklik eklemeden önce uygulanabilirliği ve sabah işlerini nasıl yaptığını değerlendirebilir."},{id:"sleep-3-under-limit",text:"Toplamı genel günlük sınırın altında olduğu için kahvesi kalsın. Ne kadar uyuduğunu kaydetsin.",feedback:"Genel günlük sınır, uykunun etkilenmeyeceğini garanti etmez. Miktar, saat ve duyarlılık hâlâ önemlidir. Belirlediği içeceği değiştirmeden uykuyu kaydetmesi, Deniz'in seçtiği soruyu test etmez."},{id:"sleep-3-whole-overhaul",text:"Kafeini bıraksın. Öğün, egzersiz ve ekran saatlerini birlikte değiştirsin. Sonra yararlı görünenleri korusun.",feedback:"Bütün düzeni değiştirmek, aynı anda birkaç şeyi değiştirir ve sürdürmesi zor olabilir. Deniz hangi değişikliğin ilgili olduğunu bilemez. Kafeini birden azaltmak da ayrıca uyarlama gerektirebilir."}],bestOptionId:"sleep-3-one-serving"}},carry:{takeaway:"İlgili tek porsiyonu değiştir. Genel günlük sınırın altında kalmak uykunun etkilenmeyeceği anlamına gelmez.",followUp:{questionId:"sleep-3-return",question:"Seçtiğin porsiyon değişti mi? Bu tek değişikliği tekrar yapmak hayatına uyar mı?",observationPrompt:"Seçtiğin başlangıç anı geldiğinde ne oldu?",adjustmentPrompt:"Neyi tekrarlamalı, değiştirmeli veya hangi konuda yardım istemelisin?"}},goDeeper:{sections:[{heading:"Saat bilgisi güvenli sınır koymaz",paragraphs:["Sık anılan Drake deneyinde, sağlıklı uyuyan 12 kişiye kafein aldıkları gün tek 400 miligram doz verildi [S13]. Yatmadan sıfır, üç veya altı saat önce alınması plaseboyla karşılaştırıldı. Her gün üç yüksek doz verilmedi. Resmî AASM özeti, altı saat önce alındığında ölçülen uykunun bir saatten fazla azaldığını bildirir. Erişilen birincil makale özetinde etkinin kesin güven aralıkları yoktu.","Bu, sağlıklı uyuyan küçük bir grupta denenmiş tek yüksek dozdu. Senin sıradan kahvenin etkisini tahmin edemez. Herkes için altı saati güvenli sınır ilan edemez. İşe yarayan soru şu: gerçekte içtiğin hangi porsiyonu değiştirmeye değer ve değişiklik o içeceğin sana sağladığı şeyle uyumlu mu? Ürünü, miktarı ve saati sabah gözleminle birlikte kaydet. Tek bir içeceği değiştirmek pratik bir denemedir. Tedavi veya neden sonuç kanıtı değildir. Mümkün olduğunda diğer önemli alışkanlıkların aynı kalsın."]},{heading:"Hedef sayıdan önce içtiğin porsiyona bak",paragraphs:["FDA'nın genel 400 miligram bilgisi bir hedef değildir. Uykunun bozulmayacağını garanti etmez [S10]. Ürün miktarları ve porsiyon büyüklükleri değişir. Çay, gazlı içecek, enerji içeceği ve bazı kafeinsiz ürünler de kafein ekleyebilir. Evdeki her fincanı aynı saymak yerine kullandığın ürünü, etiketini veya alıştığın porsiyonu yaz. Kişisel duyarlılık ve sağlık durumun, bir uzmana danışmanı gerektirebilir.","Bu kursta bir içeceği değiştirmek pratik bir denemedir. Araştırmada denenmiş dozun tekrarı değildir. Düzenli kafein kullanıyorsan bütün porsiyonları birden bırakmak yerine kademeli değişiklik daha uygulanabilir olabilir. FDA, yoksunluk belirtilerini sınırlamak için kademeli azaltmayı önerir [S10]. Amacın, mevcut dinlenme fırsatını desteklemek olsun. Sonraki gece aynı geçse bile içecekle ilgili yaptığını anlat. Uyku sorunu günlük hayatını sürdürmeni zorlaştırıyorsa kusursuz günlük beklemeden sağlık desteği al. Uykuluyken araç kullanma [S11]."]}],sourceIds:["S10","S13","S11"]}},title:"Akşamki kahve gece de peşini bırakmıyor mu?",minutes:6,goal:"Kaydında geç saatte içtiğin kafein dikkat çekiyorsa tek porsiyonu değiştir veya daha erken iç.",reading:["Kafeinin etkisi miktara, saate ve kişisel duyarlılığa bağlı. Küçük bir deneyde tek 400 miligram doz, yatmadan altı saat önce alındığında bile uykuyu bozdu. Bu yüksek bir dozdu. Sıradan bir fincanın etkisini tahmin etmez. Altı saatin güvenli sınır olduğunu da göstermez.","Dinlenme kaydın geç saatteki bir içeceği işaret ediyorsa sadece onu değiştir. Daha erken iç, yerine başka içecek koy veya kademeli azalt. Gerçekte hangi ürünü ne zaman içtiğini yaz. Diğer önemli alışkanlıkların mümkün olduğunca aynı kalsın. Kayıt, sonraki seçimine yardımcı olabilir; neden sonuç ilişkisini kanıtlamaz. Kafein bu denemeyle ilgili değilse mevcut dinlenme adımını sürdür."],practice:["Geç saatteki tek kafeinli porsiyonu seç. Daha erken iç, değiştir veya kademeli azalt. Hiçbir sabit saat sınırı uyku garantisi vermez.","Bir gün boyunca içtiğin bütün kafeinli içecekleri kısaca yaz.","Önce ilgili tek alışkanlığı değiştir. Herkes için geçerli bir akşam egzersizi yasağı koyma. Reçeteli ilaçlarını değiştirme."],reflection:"Akşam alışkanlıklarından hangisini değiştirmek sana daha kolay geliyor?",question:"Drake'in 2013 deneyinden hangi sonuç çıkarılabilir?",options:["Yatmadan 6 saat önce alınan yüksek doz kafein, uykuyu yine kısaltabilir.","Kafein yalnızca hemen yatmadan önce alınırsa uykuyu etkiler.","Kafein hiç kimsenin uykusunu etkilemez."],correct:0,feedback:"Küçük çalışma, tek seferlik 400 mg gibi yüksek bir dozu denedi. Yatmadan altı saat önce bile uykuyu bozdu. Herkes için güvenli saat sınırı koymaz; daha küçük porsiyonun etkisini tahmin etmez.",takeaway:"İlgili tek porsiyonu değiştir. Genel günlük sınırın altında kalmak uykunun etkilenmeyeceği anlamına gelmez.",sources:["S10","S13","S11"],deeper:[{heading:"Saat bilgisi güvenli sınır koymaz",paragraphs:["Sık anılan Drake deneyinde, sağlıklı uyuyan 12 kişiye kafein aldıkları gün tek 400 miligram doz verildi [S13]. Yatmadan sıfır, üç veya altı saat önce alınması plaseboyla karşılaştırıldı. Her gün üç yüksek doz verilmedi. Resmî AASM özeti, altı saat önce alındığında ölçülen uykunun bir saatten fazla azaldığını bildirir. Erişilen birincil makale özetinde etkinin kesin güven aralıkları yoktu.","Bu, sağlıklı uyuyan küçük bir grupta denenmiş tek yüksek dozdu. Senin sıradan kahvenin etkisini tahmin edemez. Herkes için altı saati güvenli sınır ilan edemez. İşe yarayan soru şu: gerçekte içtiğin hangi porsiyonu değiştirmeye değer ve değişiklik o içeceğin sana sağladığı şeyle uyumlu mu? Ürünü, miktarı ve saati sabah gözleminle birlikte kaydet. Tek bir içeceği değiştirmek pratik bir denemedir. Tedavi veya neden sonuç kanıtı değildir. Mümkün olduğunda diğer önemli alışkanlıkların aynı kalsın."]},{heading:"Hedef sayıdan önce içtiğin porsiyona bak",paragraphs:["FDA'nın genel 400 miligram bilgisi bir hedef değildir. Uykunun bozulmayacağını garanti etmez [S10]. Ürün miktarları ve porsiyon büyüklükleri değişir. Çay, gazlı içecek, enerji içeceği ve bazı kafeinsiz ürünler de kafein ekleyebilir. Evdeki her fincanı aynı saymak yerine kullandığın ürünü, etiketini veya alıştığın porsiyonu yaz. Kişisel duyarlılık ve sağlık durumun, bir uzmana danışmanı gerektirebilir.","Bu kursta bir içeceği değiştirmek pratik bir denemedir. Araştırmada denenmiş dozun tekrarı değildir. Düzenli kafein kullanıyorsan bütün porsiyonları birden bırakmak yerine kademeli değişiklik daha uygulanabilir olabilir. FDA, yoksunluk belirtilerini sınırlamak için kademeli azaltmayı önerir [S10]. Amacın, mevcut dinlenme fırsatını desteklemek olsun. Sonraki gece aynı geçse bile içecekle ilgili yaptığını anlat. Uyku sorunu günlük hayatını sürdürmeni zorlaştırıyorsa kusursuz günlük beklemeden sağlık desteği al. Uykuluyken araç kullanma [S11]."]}],example:{title:"Kurgusal örnek: Deniz tek bir içeceği deniyor",text:"Deniz, not tuttuğu iki akşamda bilgisayarının yanında geç saatte büyük bir kahve olduğunu fark ediyor. Bugün zorunlu işini bitirirken onun yerine alıştığı kafeinsiz içeceği içiyor. Sabah kahvesini değiştirmiyor. Kahvenin verdiği canlılığı özlüyor; ertesi gün hâlâ yorgun. Tekrar denemeye karar vermeden önce değişikliği ve saatini kaydediyor."},photo:{id:"1743689374053-be49ca407b7c",alt:"Pencere kenarında bir fincan kahve"}},{id:"sleep-4",schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"sleep-4",courseId:"sleep",locale:"tr",title:"Yatakta saatle yarışıyorsan bu yarışı bırak",goal:"Uzun süre uyanık kalmakla boğuşuyorsan saate bakmadan güvenli, sessiz bir etkinlik seç.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Yine saate baktın, yine hesap yaptın. Uykuyu zorlamak yerine uzun süre uyanık kaldığında ne yapacağını güvenli biçimde hazırla.",reason:{id:"sleep-4-reason",label:"Uyanık kalmak seni zorlamaya başladığında ne yapıyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Tekrar tekrar saate bakıyorum","Yataktan yarını planlıyorum","Uyumaya kendimi zorluyorum","Yakın zamanda böyle bir durum olmadı"]},why:{id:"sleep-4-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bitkin hissetmekle uykunun gelmesi aynı şey değil. Uykululuk, uykuya dalabilecek hâlde olmandır. Klinik rehber şunu önerir: uykun gelince yat. Uzun süre uyanık kalmakla boğuşuyorsan sessiz bir etkinlik seç. Saati izleme. Yirmi dakika, vücudunun uyması gereken bir sınır değil.","Mevcut dinlenme denemeni kullan. Uyanık kalmakla boğuştuysan güvenli ve sessiz bir etkinlik hazırla. Gerektiğinde onu yap, uykun gelince geri dön. Kalkmak tehlikeli veya uygulanamazsa bir hekime danış. Bu durumun hiç oluşmaması da geçerli bir sonuçtur. Senin elinde olan, yaptığın şeydir. Uykunun ne kadar çabuk geldiği değil."],example:{title:"Deniz saat hesabını bırakıyor",text:"Deniz, dinlenmeye geçmeden önce salondaki koltuğun yanına kitap koyuyor. Lambayı ve oraya giden yolu kontrol ediyor. Gece, uzun süredir uyanık olduğunu ve saate bakıp durduğunu fark ediyor. Güvenle koltuğa geçip okuyor. Uykusu gelince geri dönüyor. Hazırlığı, gece yaptığından ayrı kaydediyor. Uykusu yine bölündü; sağlık desteği almayı düşünüyor."}},move:{invitation:"Hazırlığın varsa seçtiğin etkinlikle devam et. Yoksa “Bunu uyarla”, ardından “Hazırlık” seç. Bu okuma örneğini düzenle. Güvenliğini bugün kontrol et.",instructions:["Hazırlık örneği: sessiz bir etkinlik ve yer seç. Kaydetmeden önce yolu kontrol et.","Hazırlığı gece kullanmaktan ayrı tut. Hazırladığını yalnızca ihtiyaç olursa kullan.","Hareket etmek tehlikeliyse ara ver. Yeniden denemeden önce sana özel öneri al."],prompts:[],suggestions:{action:["Basılı kitabı hazırla; koltuğa giden yolu kontrol et","Sakin ses kaydını hazırla; güvenli oturabildiğini kontrol et","Lambayı ve okuma koltuğuna giden yolu kontrol et"],minimum:["Kitabı koy, koltuğa giden yolu kontrol et","Ses kaydını hazırla, oturacağın yerin güvenliğini kontrol et","Güvenli aydınlatmayı, koltuğa giden açık yolu kontrol et"],cue:["Akşam ortalığı toparladıktan sonra","Son zorunlu akşam işimden sonra","Dinleneceğim yere yerleşmeden önce"],place:["Salondaki okuma koltuğumun yanında","Akşam rahatça erişebildiğim koltukta","Okuma koltuğuma giden yol üzerinde"],minutes:[5,2,10],fallback:["Ara ver; bana özel öneri iste","Yolun güvenliğini kontrol etmek için yardım iste","Önceden kararlaştırılan, bana uygun seçeneği kullan"],observation:["Hazırladığım etkinlik ve yolun güvenliğini kontrol edip etmediğim","Saate bakmayı bırakıp bırakmadığım","Yaptığım şey ve uykum, ayrı notlar"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Basılı kitabı hazırla; koltuğa giden yolu kontrol et",minimum:"Kitabı koy, koltuğa giden yolu kontrol et",minutes:5,cueHint:"Akşam ortalığı toparladıktan sonra",placeHint:"Salondaki okuma koltuğumun yanında",obstacleHint:"Koltuk veya gece kullanacağım yol güvenli değil ya da kullanılamıyor",fallbackHint:"Ara ver; bana özel öneri iste",observationHint:"Hazırladığım etkinlik ve yolun güvenliğini kontrol edip etmediğim",kind:"preparation"},stopRule:"Uykuluyken araç kullanma. Hareket etmek tehlikeliyse bu adıma ara ver ve sana özel öneri iste.",accessibleAlternative:"Hekiminle gerçekten kararlaştırdığın uyarlamayı koru. Böyle bir plan yoksa öneri iste. Gece güvenli olmayan bir hareketi kendin uydurma."},result:{question:"Güvenli yeri hazırladın mı, yoksa seçtiğin etkinliği ihtiyaç olduğunda yaptın mı?",observationPrompt:"Neyi hazırladın, kontrol ettin veya kullandın? Güvenli olmayan bir şey var mıydı?"},judgment:{primary:{id:"sleep-4-decision",scenario:"Deniz uzun süredir uyanık ve saate bakıp duruyor. Sessiz bir yerdeki koltuğunu önceden hazırladı; oraya güvenle ulaşabiliyor.",question:"Hangi seçenek onun hazırladığı plana uyar?",options:[{id:"sleep-4-timed-checks",text:"Ne zaman kalkacağını belirlemek için yirmi dakikalık hatırlatmalar kursun. İlk denemeden sonra onları kapatsın.",feedback:"Zamanlayıcı kesin görünür, ama uyanık olduğunu fark etmek yerine saati izlemeye yöneltir. Rehber bunu önermez. Deniz, uzun süren boğuşmayı fark edip dakika hesabı yapmadan güvenli seçeneğe geçebilir."},{id:"sleep-4-safe-alternative",text:"Saate bakmayı bıraksın. Uyuyamamak onu zorlamaya devam ederse sessiz bir yerdeki koltuğuna geçsin. Uykusu geldiğinde yatağa geri dönsün.",feedback:"Bu, kronometre yerine duruma göre hareket etmektir. Deniz, hazırladığını kullanıp kullanmadığını ve erişim sorununu anlatabilir. Denemeyi tamamlamanın koşulu çabucak uykuya dalmak değildir."},{id:"sleep-4-push-through",text:"Önce yatakta planladığı gevşeme çalışmasını yapsın. Sabah, planın işe yarayıp yaramadığına karar versin.",feedback:"Gevşemek rahat gelebilir. Ama uyanık kalmakla boğuşma sürüyorsa güvenli seçeneği şimdi kullan. Harekete geçmek için sabahki değerlendirmeyi bekleme. Hangi yolu seçersen seç, saati izlemeyi bırak."}],bestOptionId:"sleep-4-safe-alternative"}},carry:{takeaway:"Uyanık kalmak seni zorladığında yapacağını seç. Uykuya dalmak, bitirip işaretleyebileceğin bir görev değildir.",followUp:{questionId:"sleep-4-return",question:"Saate bakmadan güvenli yeri hazırladın mı? İhtiyaç olduğunda orayı kullandın mı?",observationPrompt:"Hangi kısmı yaptın? Güvenli olmayan veya ulaşamadığın bir şey var mıydı?",adjustmentPrompt:"Neyi tekrarlamalı, değiştirmeli veya hangi konuda yardım istemelisin?"}},goDeeper:{sections:[{heading:"Saati değil, uyanık kaldığını fark et",paragraphs:["AASM'nin eski klinik kılavuzu uyaran kontrolünü anlatır ve saate bakmaktan kaçınmayı açıkça önerir [S20]. Yaklaşık yirmi dakika ifadesi, kişinin uyanık olduğunu fark etmesiyle ilgilidir. Ölçülmüş biyolojik bir eşik değildir. Aynı kılavuz, gücün azaldığını hissetmek anlamındaki yorgunluğu, uykuya dalma eğilimi olan uykululuktan ayırır. Bu ayrımlar, bitkin birinin yalnızca saat geldi diye kendini yatağa girmeye zorlamasının neden gerekmediğini açıklar.","NIH'nin genel anlatımı, uykun gelince yatmayı, uyuyamadığında kalkmayı ve yatağı yeniden uyku için kullanmayı içerir [S06]. Bunlar daha kapsamlı bir klinik yaklaşımın parçalarıdır. Her zor gecenin kaygıdan veya yatakla uyku arasındaki zayıf bağdan kaynaklandığını göstermez. ODA'nın sessiz etkinlik seçeneği, pratik uyarlamalar içeren eğitimdir; tam bir tedavi değildir. Kaydında, bu duruma bağlı seçeneğin gerekip gerekmediğini ve kullanılıp kullanılmadığını değerlendirirsin. Durum oluşmadıysa bunu da açıkça bildirebilirsin."]},{heading:"Katı düzenden önce güvenliğini koru",paragraphs:["Sessiz etkinlik için o yere güvenle ulaşabilmen gerekir. Hareket kısıtlılığı, düşme riski, tek odalı ev, bakım sorumluluğu ve vardiyalar yataktan kalkmayı uygunsuz kılabilir. Sana uymayan talimatı kopyalamak yerine hekimle sana özel plan yapmak daha iyidir. Güvenli aydınlatma, yolu çok loş yapmaktan daha önemlidir. Bu kurs daha kısa bir uyku süresi vermez, güvenlik için gereken kestirmeyi yasaklamaz veya ilaçlarını değiştirmeni istemez.","NHS rehberi, uykuluyken araç kullanmamanı ve uyku güçlüğü günlük hayatını sürdürmeni zorlaştırıyorsa sağlık desteği almanı söyler [S11]. Düzenli programı yeterli uyku fırsatı ve o anki güvenliğinle birlikte düşün. Gece kötü geçtiyse, erken kalkmayı sürdürmen uykuluyken araç kullanmayı güvenli hâle getirmez. Yaşadığın güçlüğü bir hekime anlat veya pratik destek iste. Sessiz yeri hazırlamak bir hazırlıktır. İhtiyaç olduğunda kullanmak ayrı bir denemedir. İkisi de tek başına uykunun iyileştiğini göstermez."]}],sourceIds:["S06","S11","S20"]}},title:"Yatakta saatle yarışıyorsan bu yarışı bırak",minutes:6,goal:"Uzun süre uyanık kalmakla boğuşuyorsan saate bakmadan güvenli, sessiz bir etkinlik seç.",reading:["Bitkin hissetmekle uykunun gelmesi aynı şey değil. Uykululuk, uykuya dalabilecek hâlde olmandır. Klinik rehber şunu önerir: uykun gelince yat. Uzun süre uyanık kalmakla boğuşuyorsan sessiz bir etkinlik seç. Saati izleme. Yirmi dakika, vücudunun uyması gereken bir sınır değil.","Mevcut dinlenme denemeni kullan. Uyanık kalmakla boğuştuysan güvenli ve sessiz bir etkinlik hazırla. Gerektiğinde onu yap, uykun gelince geri dön. Kalkmak tehlikeli veya uygulanamazsa bir hekime danış. Bu durumun hiç oluşmaması da geçerli bir sonuçtur. Senin elinde olan, yaptığın şeydir. Uykunun ne kadar çabuk geldiği değil."],practice:["Uzun süre uyanık kaldığında güvenli, sessiz bir etkinlik seç. Kalkmak tehlikeliyse sana uygun uyarlama için yardım iste.","Orada sana uygun sessiz bir etkinlik seç. Rahat nefese odaklanmak isteğe bağlıdır; gerekli erişim açık kalsın.","Saati izlemeden dinlenmeye geçmek ve gerekirse gece yapacağın etkinlik için hazırlık yap. Uykuluyken araç kullanma."],reflection:"Uyuyamadığın bir gecede kendine ne söylemek istersin?",question:"Uyaran kontrolü rehberi, uzun süren uyanıklıkta saate bakmadan ne yapmanı önerir?",options:["Uyumak için kendini daha fazla zorla.","Yatakta telefona bakıp ekranda gezinmeye başla.","Kalk, güvenli ve loş ışıkta sessiz bir şey yap. Uykun gelince geri dön."],correct:2,feedback:"Güvenli, sessiz bir etkinlik seç; uykun gelince geri dön. Verilen yaklaşık süreler biyolojik bir sınır değildir. Erişim ve bakım ihtiyaçlarına göre uyarla. Uykuluyken araç kullanma.",takeaway:"Uyanık kalmak seni zorladığında yapacağını seç. Uykuya dalmak, bitirip işaretleyebileceğin bir görev değildir.",sources:["S06","S11","S20"],deeper:[{heading:"Saati değil, uyanık kaldığını fark et",paragraphs:["AASM'nin eski klinik kılavuzu uyaran kontrolünü anlatır ve saate bakmaktan kaçınmayı açıkça önerir [S20]. Yaklaşık yirmi dakika ifadesi, kişinin uyanık olduğunu fark etmesiyle ilgilidir. Ölçülmüş biyolojik bir eşik değildir. Aynı kılavuz, gücün azaldığını hissetmek anlamındaki yorgunluğu, uykuya dalma eğilimi olan uykululuktan ayırır. Bu ayrımlar, bitkin birinin yalnızca saat geldi diye kendini yatağa girmeye zorlamasının neden gerekmediğini açıklar.","NIH'nin genel anlatımı, uykun gelince yatmayı, uyuyamadığında kalkmayı ve yatağı yeniden uyku için kullanmayı içerir [S06]. Bunlar daha kapsamlı bir klinik yaklaşımın parçalarıdır. Her zor gecenin kaygıdan veya yatakla uyku arasındaki zayıf bağdan kaynaklandığını göstermez. ODA'nın sessiz etkinlik seçeneği, pratik uyarlamalar içeren eğitimdir; tam bir tedavi değildir. Kaydında, bu duruma bağlı seçeneğin gerekip gerekmediğini ve kullanılıp kullanılmadığını değerlendirirsin. Durum oluşmadıysa bunu da açıkça bildirebilirsin."]},{heading:"Katı düzenden önce güvenliğini koru",paragraphs:["Sessiz etkinlik için o yere güvenle ulaşabilmen gerekir. Hareket kısıtlılığı, düşme riski, tek odalı ev, bakım sorumluluğu ve vardiyalar yataktan kalkmayı uygunsuz kılabilir. Sana uymayan talimatı kopyalamak yerine hekimle sana özel plan yapmak daha iyidir. Güvenli aydınlatma, yolu çok loş yapmaktan daha önemlidir. Bu kurs daha kısa bir uyku süresi vermez, güvenlik için gereken kestirmeyi yasaklamaz veya ilaçlarını değiştirmeni istemez.","NHS rehberi, uykuluyken araç kullanmamanı ve uyku güçlüğü günlük hayatını sürdürmeni zorlaştırıyorsa sağlık desteği almanı söyler [S11]. Düzenli programı yeterli uyku fırsatı ve o anki güvenliğinle birlikte düşün. Gece kötü geçtiyse, erken kalkmayı sürdürmen uykuluyken araç kullanmayı güvenli hâle getirmez. Yaşadığın güçlüğü bir hekime anlat veya pratik destek iste. Sessiz yeri hazırlamak bir hazırlıktır. İhtiyaç olduğunda kullanmak ayrı bir denemedir. İkisi de tek başına uykunun iyileştiğini göstermez."]}],example:{title:"Kurgusal örnek: Deniz saat hesabını bırakıyor",text:"Deniz, dinlenmeye geçmeden önce salondaki koltuğun yanına kitap koyuyor. Lambayı ve oraya giden yolu kontrol ediyor. Gece, uzun süredir uyanık olduğunu ve saate bakıp durduğunu fark ediyor. Güvenle koltuğa geçip okuyor. Uykusu gelince geri dönüyor. Hazırlığı, gece yaptığından ayrı kaydediyor. Uykusu yine bölündü; sağlık desteği almayı düşünüyor."},photo:{id:"1789930445611-3b13fd7d6de4",alt:"Küçük masa lambasının ışığında kitap okuyan kişi"}},{id:"sleep-5",schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"sleep-5",courseId:"sleep",locale:"tr",title:"Kötü geceler gün içinde yapabildiklerini de kısıtlıyor mu?",goal:"Dinlenme denemeni değerlendir. Sana uyan bir adımı sürdür veya ihtiyaç duyduğun sağlık desteğini iste.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kötü geceler hâlâ gününü etkiliyor mu? Elindeki kayıtlarla gelecek haftayı planla veya şimdi sağlık desteği iste.",reason:{id:"sleep-5-reason",label:"Uyku sorunu hafta boyunca şimdiden neleri zorlaştırıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Güvenle yolculuk edemeyecek kadar uykuluyum","Günlük işlerimi yapmak zor","Sevdiklerimle geçireceğim zamanı kaçırıyorum","Henüz bildiğim bir etkisi yok"]},why:{id:"sleep-5-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Yardım istemek için uyku sorununun üç ay sürmesi gerekmez. Günlük hayatı sürdürmekte zorlanmak, işe yaramayan alışkanlık değişiklikleri, nefes nefese uyanmak, nefesin kesilmesi veya gündüz süren uykululuk değerlendirme nedenidir. Yalnız yaşaman veya notlarının eksik olması, iletişimi geciktirmesin.","Henüz denemediğin plan dahil, mevcut dinlenme denemenin kayıtlarına bak. Yapabileceğin bir dinlenme adımını koru veya şimdi sağlık desteği iste. Hiç denemedin mi? İlk kez denemek için sana uygun fırsatı seç. ODA yapılandırılmış uykusuzluk tedavisi değildir. Kendi kendine yatakta geçirdiğin süreyi azaltma veya ilaçlarını değiştirme."],example:{title:"Deniz bütün düzenini değiştirmeden yardım istiyor",text:"Deniz'in kayıtları üç gece ertelenebilir işi bitirdiğini gösteriyor. Yine de gündüz uykululuğu işe gidip gelmesini tehlikeli kılıyor. Gündüz uykululuğunun etkisini anlatarak sağlık merkezine bir değerlendirme talebi gönderiyor. İş arkadaşından kendisini götürmesini istiyor. Akşama kadar merkezden yanıt gelmiyor. Talebini kaydediyor. Yedek planı olarak merkeze yeniden ulaşabileceği ilk zamanı seçiyor."}},move:{invitation:"Kaygı veren belirti veya günlük hayatta zorlanma varsa “Bunu uyarla”, ardından “Destek” seç. Bu sağlık desteği örneğini ilk uygun zamana göre düzenle. Diğer durumda dinlenme adımını koru.",instructions:["Kaydetmeden önce sağlık merkezini, ulaşabileceğin gerçek günü ve özel görüşebileceğin yeri yaz.","Yanıt yoksa şimdi başka iletişim yolu seç. Bir dinlenme denemesini daha bekleme.","Kaygı veren belirti yoksa dinlenme adımını koru veya “Bunu uyarla” içinde “Uygulama” seç."],prompts:[],suggestions:{action:["Uyku değerlendirmesi için aile hekimimi ara","Sağlık merkezime değerlendirme talebi gönder","Güvendiğim birinden iletişimi ayarlamasını iste"],minimum:["Sağlık merkezine bir kez ulaşmayı dene","Bir değerlendirme talebi gönder","İletişim kurmak için yardım iste"],cue:["Aile hekimime ulaşabileceğim ilk zamanda","Öğle yemeğinden sonra, sağlık merkezim açıkken","Ulaşabildiğim randevu hattı açıldığında"],place:["Mutfak masamda, telefonum hazırken","Özel görüşebildiğim, erişebildiğim bir yerde","Mesaj gönderebildiğim cihazın yanında"],minutes:[2,5,10],fallback:["Güvendiğim birinden iletişimi ayarlamasını iste","Kamu sağlık hizmetinin randevu hattını ara","Sağlık merkezim açıldığında yeniden ulaşmayı dene"],observation:["Ulaşma denemesi; yanıt veya yanıtsızlık","Önerilen randevu ve sonraki ulaşma adımı","İstediğim yardım ve gelen yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Uyku değerlendirmesi için aile hekimimi ara",minimum:"Sağlık merkezine bir kez ulaşmayı dene",minutes:2,cueHint:"Aile hekimime ulaşabileceğim ilk zamanda",placeHint:"Mutfak masamda, telefonum hazırken",obstacleHint:"Sağlık merkezime ulaşılamıyor veya henüz yanıt vermedi",fallbackHint:"Güvendiğim birinden iletişimi ayarlamasını iste",observationHint:"Ulaşma denemesi; yanıt veya yanıtsızlık",kind:"support"},stopRule:"Nefes nefese uyanma veya gündüz uykululuğu için değerlendirme iste. Uykuluyken araç kullanma. Kendi kendine uyku kısıtlama uygulama.",accessibleAlternative:"Telefon, mesaj veya birinin yardımıyla ulaş. Kaydetmeden önce, ilk yol olmazsa ulaşabileceğin kişiyi veya kamu hizmetini belirle."},result:{question:"Kendin için seçtiğin sonraki adımı gerçekten attın mı?",observationPrompt:"Hangi adımı attın veya hangi sağlık desteğini istedin? Ne hâlâ çözülmedi?"},judgment:{primary:{id:"sleep-5-decision",scenario:"Deniz dinlenme düzenini değiştirdi. Ama gündüz süren uykululuğu işe gidip gelmesini hâlâ tehlikeli kılıyor. Sağlık merkezi şimdi açık. Kamu randevu hattı yarın açılıyor.",question:"Kayıtlarına göre hangi sonraki adım ona uyar?",options:[{id:"sleep-5-more-records",text:"Şimdi güvenli ulaşım seçsin. Ablasından bu akşam, yarına randevu ayarlaması için yardım istesin.",feedback:"Bu seçim yolculuğu güvenli kılar ve pratik yardım sağlar. Ama Deniz açık sağlık merkezine şimdi ulaşabilir. Akşamki yardım, bu talebi geciktirmesin. Ablasından ayrıca yardım isteyebilir."},{id:"sleep-5-continue-changes",text:"Şimdi güvenli ulaşım kullansın. Ulaşabileceği bir hekim bulmak için yarın kamu randevu hattını arasın.",feedback:"Sağlık merkezi yardımcı olamazsa bu yararlı bir yoldur. Merkez şimdi açık olduğundan ilk değerlendirme talebini bugün iletebilir. Yarınki yolu ilkinden yanıt alamazsa kullanabilir."},{id:"sleep-5-contact-now",text:"Gündüz yaşadığı güçlüğü şimdi sağlık merkezine anlatsın. Not tutmak isteğe bağlı kalsın. Güvenli ulaşım ayarlasın.",feedback:"Bu seçim, güvenliği koruyarak yaşadığı etkiye yanıt verir. Deniz uygun değerlendirmeyi istemek ve sonraki adımları konuşmak için üç ay beklemek, bir tanık bulmak veya günlüğünü bitirmek zorunda değildir."}],bestOptionId:"sleep-5-contact-now"}},carry:{takeaway:"İşe yarayan adımı koru. O adımın çözmediği güçlük için sağlık desteği al.",followUp:{questionId:"sleep-5-return",question:"Dinlenmek için seçtiğin adımda veya sağlık desteği talebinde ne oldu? Yanıt bekliyor musun, iletişim kurmak için sonraki adımın ne?",observationPrompt:"Neyi denedin? Ne hâlâ yanıt veya çözüm bekliyor?",adjustmentPrompt:"Neyi tekrarlamalı, değiştirmeli veya hangi konuda yardım istemelisin?"}},goDeeper:{sections:[{heading:"Sağlık desteği kursu veya günlüğü beklemez",paragraphs:["NHS uykusuzluk rehberi, günlük hayatı sürdürmekte zorlanmayı ve yardımcı olmayan alışkanlık değişikliklerini sağlık desteğine başvurma nedenleri arasında sayar [S11]. Üç ay, sorunun devam süresiyle ilgili bir kategoriyi ayırır. Beklemeni söylemez. İş düzeni, sağlık, ilaçlar ve başka koşullar uykuyu etkileyebilir. Bu kurs, senin durumunda hangi açıklamanın geçerli olduğuna karar veremez. Bir hekim sorunu ve uygun tedaviyi değerlendirebilir.","Nefesin kesilmesi, nefes nefese veya boğulur gibi uyanmak ve gündüz aşırı uykululuk, olası uyku apnesi veya başka nedenler için değerlendirme gerektirir [S12]. Yüksek sesle horlamak tek başına tanı değildir. Yalnız yaşaman, değerlendirme istemene engel olmaz. Gün içinde yaşadığın güçlüğü veya gece fark ettiklerini anlatabilirsin. Yararlıysa mevcut kayıtlarını götür. Ama belirli sayıda geceyi kaydetmek için randevuyu geciktirme. Uygun yardımı ayarlarken uykuluyken araç kullanma veya tehlikeli iş yapma."]},{heading:"Yapılandırılmış tedavi ne sunabilir?",paragraphs:["ACP, kronik uykusuzlukta ilk tedavi olarak uykusuzluk için bilişsel davranışçı terapiyi (BDT-I) önerir [S05]. Bireysel veya grup görüşmeleri, telefon ya da internet modülleri ve yapılandırılmış kendi kendine yardım seçenekleri olabilir. Bu, her dijital uyku ürününün doğrulanmış tedavi olduğu anlamına gelmez. İlaç kararlarını bir hekimle konuşmalısın. ODA, alışkanlık eğitimi ve kendi elindeki adımların kaydını sunar. Bunlar görüşmeyi destekleyebilir, ama sağlık hizmetinin yerini tutmaz.","Son adımın, her geceye yeni bir çalışma eklemek değil, elindekileri toparlamak. Planlarına ve denemelerine bak: günü kapatmanın hangi yolu uygulanabildi, ne engelledi, hangi güçlük kaldı? Deneme kaydı yoksa sonucu bilmiyoruz. İlk uygun fırsatı veya desteği seç. Önümüzdeki haftaya yararlı bir adım ya da sağlık desteğine ulaşma planını taşı. Yanıt gelmeyen talep de gerçek bir iletişim denemesidir. Sonrasında hangi yoldan ulaşacağını seçebilirsin. Günlük tutmak, kursu bitirmek veya karar sorusunu doğru yanıtlamak, iyi uyuduğunu kanıtlamaz. Değerlendirme veya pratik yardım ararken denemene ara verebilirsin."]}],sourceIds:["S05","S11","S12"]}},title:"Kötü geceler gün içinde yapabildiklerini de kısıtlıyor mu?",minutes:6,goal:"Dinlenme denemeni değerlendir. Sana uyan bir adımı sürdür veya ihtiyaç duyduğun sağlık desteğini iste.",reading:["Yardım istemek için uyku sorununun üç ay sürmesi gerekmez. Günlük hayatı sürdürmekte zorlanmak, işe yaramayan alışkanlık değişiklikleri, nefes nefese uyanmak, nefesin kesilmesi veya gündüz süren uykululuk değerlendirme nedenidir. Yalnız yaşaman veya notlarının eksik olması, iletişimi geciktirmesin.","Henüz denemediğin plan dahil, mevcut dinlenme denemenin kayıtlarına bak. Yapabileceğin bir dinlenme adımını koru veya şimdi sağlık desteği iste. Hiç denemedin mi? İlk kez denemek için sana uygun fırsatı seç. ODA yapılandırılmış uykusuzluk tedavisi değildir. Kendi kendine yatakta geçirdiğin süreyi azaltma veya ilaçlarını değiştirme."],practice:["Uyku güçlüğüne ve günlük etkisine bak. Değerlendirme istemek için üç ay beklemen gerekmez.","Varsa başka birinin gözlemleri yardımcı olabilir. Yalnız yaşamak, sağlık desteği istemene engel değildir.","Gerektiğinde sağlık desteğine ulaş. İsteğe bağlı notlarını randevuya götürebilirsin. İki haftalık günlük için iletişimi geciktirme."],reflection:"Uykunu bir uzmanla konuşmak sana ne kazandırabilir?",question:"Kronik uykusuzluk için önerilen hangi tedaviyi bir hekimle konuşabilirsin?",options:["Kendi kendine uyku ilacına başla.","Bir uzmanla görüş ve BDT-I gibi seçenekleri konuş.","Bu kursu tekrar etmenin yeterli olacağını varsay."],correct:1,feedback:"ACP, farklı sunum seçenekleri olan BDT-I tedavisini kronik uykusuzlukta ilk tedavi olarak önerir. Günlük hayatta zorlanma veya apne şüphesi gecikmeden sağlık desteği gerektirir. Bu kurs değerlendirme veya tedavinin yerini tutmaz.",takeaway:"İşe yarayan adımı koru. O adımın çözmediği güçlük için sağlık desteği al.",sources:["S05","S11","S12"],deeper:[{heading:"Sağlık desteği kursu veya günlüğü beklemez",paragraphs:["NHS uykusuzluk rehberi, günlük hayatı sürdürmekte zorlanmayı ve yardımcı olmayan alışkanlık değişikliklerini sağlık desteğine başvurma nedenleri arasında sayar [S11]. Üç ay, sorunun devam süresiyle ilgili bir kategoriyi ayırır. Beklemeni söylemez. İş düzeni, sağlık, ilaçlar ve başka koşullar uykuyu etkileyebilir. Bu kurs, senin durumunda hangi açıklamanın geçerli olduğuna karar veremez. Bir hekim sorunu ve uygun tedaviyi değerlendirebilir.","Nefesin kesilmesi, nefes nefese veya boğulur gibi uyanmak ve gündüz aşırı uykululuk, olası uyku apnesi veya başka nedenler için değerlendirme gerektirir [S12]. Yüksek sesle horlamak tek başına tanı değildir. Yalnız yaşaman, değerlendirme istemene engel olmaz. Gün içinde yaşadığın güçlüğü veya gece fark ettiklerini anlatabilirsin. Yararlıysa mevcut kayıtlarını götür. Ama belirli sayıda geceyi kaydetmek için randevuyu geciktirme. Uygun yardımı ayarlarken uykuluyken araç kullanma veya tehlikeli iş yapma."]},{heading:"Yapılandırılmış tedavi ne sunabilir?",paragraphs:["ACP, kronik uykusuzlukta ilk tedavi olarak uykusuzluk için bilişsel davranışçı terapiyi (BDT-I) önerir [S05]. Bireysel veya grup görüşmeleri, telefon ya da internet modülleri ve yapılandırılmış kendi kendine yardım seçenekleri olabilir. Bu, her dijital uyku ürününün doğrulanmış tedavi olduğu anlamına gelmez. İlaç kararlarını bir hekimle konuşmalısın. ODA, alışkanlık eğitimi ve kendi elindeki adımların kaydını sunar. Bunlar görüşmeyi destekleyebilir, ama sağlık hizmetinin yerini tutmaz.","Son adımın, her geceye yeni bir çalışma eklemek değil, elindekileri toparlamak. Planlarına ve denemelerine bak: günü kapatmanın hangi yolu uygulanabildi, ne engelledi, hangi güçlük kaldı? Deneme kaydı yoksa sonucu bilmiyoruz. İlk uygun fırsatı veya desteği seç. Önümüzdeki haftaya yararlı bir adım ya da sağlık desteğine ulaşma planını taşı. Yanıt gelmeyen talep de gerçek bir iletişim denemesidir. Sonrasında hangi yoldan ulaşacağını seçebilirsin. Günlük tutmak, kursu bitirmek veya karar sorusunu doğru yanıtlamak, iyi uyuduğunu kanıtlamaz. Değerlendirme veya pratik yardım ararken denemene ara verebilirsin."]}],example:{title:"Kurgusal örnek: Deniz bütün düzenini değiştirmeden yardım istiyor",text:"Deniz'in kayıtları üç gece ertelenebilir işi bitirdiğini gösteriyor. Yine de gündüz uykululuğu işe gidip gelmesini tehlikeli kılıyor. Gündüz uykululuğunun etkisini anlatarak sağlık merkezine bir değerlendirme talebi gönderiyor. İş arkadaşından kendisini götürmesini istiyor. Akşama kadar merkezden yanıt gelmiyor. Talebini kaydediyor. Yedek planı olarak merkeze yeniden ulaşabileceği ilk zamanı seçiyor."},photo:{id:"1653656120968-accae8452c9e",alt:"Kanepede oturup başka bir kadınla konuşan kadın"}}],lang:"tr"},X=Object.freeze(Object.defineProperty({__proto__:null,COURSE:U,SOURCES:P},Symbol.toStringTag,{value:"Module"})),I=[{id:"suggestion-S01",title:"Peerdeman ve arkadaşları · 2016 · Hastalarda ağrı beklentisini ele alan uygulamalar",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"Seçilmiş 1.256 hastayı içeren, birleştirilmiş 27 çalışmada beklenti uygulamalarından sonra bildirilen ağrı azaldı: g=0,61, %95 güven aralığı 0,42 ile 0,79. Yanlılık düzeltmesi 0,43, aralık 0,24 ile 0,62.",limitation:"Klinik uygulamalar, kendi yazdığın cümleden farklıdır. Sonuçlar oldukça değişkendi. Ağrının azalması, ağrıya yol açan sorunun iyileştiğini göstermez. Aykırı değer çıkarılınca kaygıya ilişkin duyarlılık analizinde etki tahmini 0,03, güven aralığı −0,21 ile 0,26 oldu."},{id:"suggestion-S02",title:"Epton ve arkadaşları · 2015 · Kişisel değerler ve sağlık davranışı",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Değerleri hatırlamakla sağlık bilgisini birleştiren 144 sonuç testinde bilgiyi kabul etme, niyet ve davranışta küçük ortalama farklar vardı. Davranış: d=0,32, %95 güven aralığı 0,19 ile 0,44.",limitation:"144 test mutlaka ayrı çalışmalar değildir. Sonuçlardaki katılımcı sayıları örtüşür. Yalnızca değerler hakkında yazmanın, olumlu söz tekrarlamanın veya ODA’nın kısa yetişkin alıştırmasının etkisi gösterilmedi."},{id:"suggestion-S03",title:"Kross ve arkadaşları · 2014 · Kendine dışarıdan bakarak konuşma deneyleri",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Yedi kısa deneyde 585 kişi vardı. İkinci çalışmada sosyal görüşmeden önce üç dakika adını veya “ben” dışındaki ifadeleri kullanarak düşünmek, gözlemci puanlarına göre daha iyi performans verdi.",limitation:"Çoğunlukla öğrenciler ve sosyal değerlendirme ortamları incelendi. İkinci çalışmada görüşme öncesi kaygı anlamlı ölçüde azalmadı; sonrasında toparlanma daha açıktı. ODA’nın kısa tavsiye ve davranış uyarlaması tedavi veya garanti değil."},{id:"suggestion-S04",title:"Hatzigeorgiadis ve arkadaşları · 2011 · Kendi kendine konuşma ve spor performansı",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 çalışma, 62 etki ve 2.741 katılımcıda spor becerilerinde ortalama performans yararı bulundu: d+=0,48, %95 güven aralığı 0,38 ile 0,58. Yapılan görev ve antrenmana göre alt grup tahminleri farklıydı.",limitation:"Bazı çalışmalarda kontrol grubu yoktu. Çalışmalar arası karşılaştırmalar en iyi miktarı veya yönergenin evrensel üstünlüğünü göstermez. Masa başı işine aktarım ve Gallwey’nin bütün yaklaşımı sınanmadı."},{id:"suggestion-S05",title:"Zhang ve arkadaşları · 2025 · Değerleri hatırlamak ve iyi oluş",url:"https://hub.hku.hk/handle/10722/366517",type:"research",finding:"Üniversite özeti, klinik olmayan gruplarda 67 makale ve 129 bağımsız test bildiriyor. Kendine bakış ve iyi oluşta küçük ortalama yararlar vardı.",limitation:"Tam yöntemler, toplam katılımcı, güven aralıkları, kesin etki ölçüsü ve izlem sürelerine erişilemedi. Her olumlama metni veya adı verilen ritüel doğrulanmış değil."},{id:"suggestion-S06",title:"Wang, Wang ve Gai · 2021 · Sonuç, engel ve karşılık planları",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makale, 24 bağımsız etki, 15.907 katılımcı: zihinsel karşılaştırma ve “şu olursa bunu yaparım” planlarında hedefe ulaşmaya ortalama yarar, g=0,336, güven aralığı 0,229 ile 0,443. Yanlılık düzeltmesi 0,242, 0,143 ile 0,342.",limitation:"Yöntemler ve kontroller farklıydı. ODA’nın birleşik kartı, olumlu sözlerin etken parça olduğu veya yatakta hayalle ertesi sabah planını ayırmanın yararı doğrulanmadı."},{id:"suggestion-S07",title:"Wood, Perunovic ve Lee · 2009 · Kendine olumlu cümleler söylemek",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Özet, çok olumlu bir cümleyi tekrarlayan, kendine verdiği değer düşük bazı kişilerde hemen sonrasında daha kötü tepkiler bildiriyor. Kendine verdiği değer yüksek kişilerde yararlar sınırlıydı.",limitation:"İlk katılımcı sayıları, tekrar sayısı ve sayısal etkiler doğrulanmadı. Sonraki iki çalışma örüntüyü tekrarlamadı. Klinik eşik veya herkes için geçerli bir uyumsuzluk mekanizması gösterilmedi."},{id:"suggestion-S08",title:"Flynn ve Bordieri · 2020 · Olumlamayı yeniden sınayan çalışmalar",url:"https://doi.org/10.1016/j.jcbs.2020.03.003",type:"research",finding:"Üniversitede gündelik koşulları modelleyen iki çalışmada yaklaşık 225 ve 237 katılımcı vardı. Beklenen ruh hâli ve anlık özsaygı değişimleriyle özsaygının kalıcı düzeyinin sonucu değiştirmesi örüntüsü tekrarlanmadı.",limitation:"Yalnızca yazarların özetine erişildi. Sayısal etkiler, güven aralıkları ve ölçüm kesinliği yoktu. Anlamlı sonuç bulunmaması, her durumda yararı veya zararsızlığı göstermez."},{id:"suggestion-S09",title:"Lally ve arkadaşları · 2010 · Günlük hayatta alışkanlıklar",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 gönüllü 84 gün boyunca tekrarlanan koşullarda yemek, içmek veya hareket davranışlarını tekrarladı. Uygun 39 modelde kendiliğinden yapmaya ulaşmak için tahmin edilen süreler oldukça farklıydı.",limitation:"Gözlemsel çalışma, olumlama deneyi değil. Ortanca 66 gün son tarih değildir. Bazı tahminler gözlem süresini aşar. Cumaya kadar kendiliğinden yapma veya kalıcı 21 günlük değişim gösterilmedi."},{id:"suggestion-S10",title:"Paller, Creery ve Schechtman · 2021 · Bellek ve uyku",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"Derleme, önceden öğrenilmiş bilginin uykuda yeniden etkinleşmesini ve sınırlı, basit çağrışım öğrenmesini ele alır.",limitation:"Anlatı derlemesi, birleşik etki yok. Bellek işlemleri uykuluyken kişisel gelişim komutlarına açıklığı, Murphy ritüelini, kayıtlarla yüklenen karmaşık becerileri veya düşüncelerin dış sonuçları yönettiğini göstermez."},{id:"suggestion-S11",title:"Cohen ve arkadaşları · 2006 · Bir okulda değerler hakkında yazmak",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/cohen_et_al._2006_-_reducing_the_racial_achievement_gap.pdf",type:"research",finding:"Bir ABD okulundaki 243 yedinci sınıf öğrencisiyle iki rastgele kontrollü saha deneyi yapıldı. Yaklaşık on beş dakikalık değer yazısı, o ortamda Siyah öğrencilerin hedef dersteki notlarını iyileştirdi.",limitation:"Beyaz öğrencilerde anlamlı etki yoktu. Sonraki büyük tekrar çalışmasında anlamlı yarar bulunmadı. Herkese akademik kazanç, yetişkin güveni veya hemen ruh hâli etkisi gösterilmedi."},{id:"suggestion-S12",title:"Hanselman ve arkadaşları · 2017 · Değer çalışmasını büyük ölçekte tekrar sınamak",url:"https://files.eric.ed.gov/fulltext/ED578033.pdf",type:"research",finding:"Ortaokullardaki yeni öğrenci grubunda hedeflenen not ortalaması için anlamlı yarar bulunmadı. Ölçüm kesinliği en az 0,10 standart sapmalık yararları dışlayabiliyordu.",limitation:"Okul koşulları ve sonuç önemlidir. Bütün değer çalışmalarının yararsızlığını göstermez, sağlık bilgisi bulgularını çürütmez. Bağlantı kabul edilmiş yazar metnine gider."},{id:"suggestion-S13",title:"Toth ve arkadaşları · 2020 · Zihinsel prova ve performans",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"Üniversite özeti, 37 iş ve beceri çalışması bildiriyor. Yayın yanlılığı için düzeltilen performans ilişkisi küçüktü: r=0,131.",limitation:"Tam yöntemler, toplam katılımcı sayısı ve güven aralığı yoktu. İş provası, yatma telkinini, markalı ritüeli veya herkes için geçerli prova miktarını doğrulamaz."},{id:"suggestion-S15",title:"Émile Coué · 1922 İngilizce baskı · Bilinçli kendi kendine telkin",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"Tarihsel metin, uyanınca ve yatmadan önce alçak sesle yirmi tekrar önerir. Gözler kapalıdır, zorlamadan söylenir ve düğümlerle sayılır.",limitation:"Anılar ve kişisel başarı anlatıları kontrollü kanıt değildir. Yirmi tekrar tarihsel sayı, kanıtlanmış miktar değil. Evrensel hayal gücü kuralları ve hastalıkları iyileştirme iddiaları desteklenmiyor."},{id:"suggestion-S16",title:"Joseph Murphy · Bilinçaltının Gücü · Yayıncı özeti",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Özet kitabın kökenini, inanç ve hayal gücünü öne çıkaran yaklaşımını tanımlar.",limitation:"Deney kanıtı yok. Yatma cümlesi, tebrik sahnesi ve minnet bölümü tam metinden doğrulanmadı. Uyku ve bellek bulguları, uykululuğun üstünlüğünü, bilinçaltıyla bir şey çekmeyi veya iyileşmeyi doğrulamaz."},{id:"suggestion-S17",title:"Oettingen ve arkadaşları · 2015 · Zihinsel karşılaştırma ve zaman yönetimi",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Birinci çalışmada tek oturumda istenen sonuç, engel ve karşılık seçildi. Olağan zaman ve yerle “şu olursa bunu yaparım” planı eklendi. Sonra hafta planlandı.",limitation:"Alman lisans öğrencileri incelendi. Sonuç tamamlanan iş değil, planlanan saatlerdi. Sabit bir dakika miktarı veya özel yatma zamanı gösterilmedi."},{id:"suggestion-S18",title:"Louise Hay · Ayna çalışması nedir?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"Yazarın sayfası, aynada yüksek sesle söylenen olumlu cümleleri ve 21 günlük programı anlatır.",limitation:"Yöntemin kökeni, etkililik kanıtı değil. Dosya taramasında bütün düzen için kontrollü çalışma bulunmadı. Bu, taramanın sınırıdır. Aynanın üstünlüğü veya 21 günlük alışkanlık son tarihi gösterilmedi."},{id:"suggestion-S19",title:"Joe Dispenza · Kendin Olma Alışkanlığını Kırmak · Yayıncının baskı bilgisi",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/9781401938093/",type:"technique",finding:"Yayıncı, karton kapaklı baskıyı Şubat 2013 olarak tarihler. E-kitap ilk kez 2012’de yayımlandı.",limitation:"Tanıtım özeti, kontrollü kanıt değil. On dakikalık düzen, minnet sırası ve değişim işareti tam metinden doğrulanmadı. Kuantumla çekim, genlere komut veya iyileşme gösterilmedi."},{id:"suggestion-S20",title:"NIMH · Ruh sağlığı sorunlarında yardım almak",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Resmî rehber, uzman ruh sağlığı ve kriz desteğine ulaşma yollarını anlatır. Süren sıkıntı, ciddi günlük hayat aksaması ve kendine zarar verme düşünceleri uygun yardım gerektirir.",limitation:"ODA tanı veya tedavi değildir. ABD dışında yerel hizmetleri kullan. Kaygı veren fiziksel belirtiler tıbbi değerlendirme gerektirir. Kendine söylediğin sözler, kötü muameleyi veya gerçek tehlikeyi güvenli diye anlatmamalı."},{id:"murphy-subconscious",title:"Joseph Murphy · Bilinçaltının Gücü · Yayıncı özeti",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Özet kitabın kökenini, inanç ve hayal gücünü öne çıkaran yaklaşımını tanımlar.",limitation:"Deney kanıtı yok. Yatma cümlesi, tebrik sahnesi ve minnet bölümü tam metinden doğrulanmadı. Uyku ve bellek bulguları, uykululuğun üstünlüğünü, bilinçaltıyla bir şey çekmeyi veya iyileşmeyi doğrulamaz."},{id:"expectation-suggestion",title:"Peerdeman ve arkadaşları · 2016 · Hastalarda ağrı beklentisini ele alan uygulamalar",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"Seçilmiş 1.256 hastayı içeren, birleştirilmiş 27 çalışmada beklenti uygulamalarından sonra bildirilen ağrı azaldı: g=0,61, %95 güven aralığı 0,42 ile 0,79. Yanlılık düzeltmesi 0,43, aralık 0,24 ile 0,62.",limitation:"Klinik uygulamalar, kendi yazdığın cümleden farklıdır. Sonuçlar oldukça değişkendi. Ağrının azalması, ağrıya yol açan sorunun iyileştiğini göstermez. Aykırı değer çıkarılınca kaygıya ilişkin duyarlılık analizinde etki tahmini 0,03, güven aralığı −0,21 ile 0,26 oldu."},{id:"positive-self-statements",title:"Wood, Perunovic ve Lee · 2009 · Kendine olumlu cümleler söylemek",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Özet, çok olumlu bir cümleyi tekrarlayan, kendine verdiği değer düşük bazı kişilerde hemen sonrasında daha kötü tepkiler bildiriyor. Kendine verdiği değer yüksek kişilerde yararlar sınırlıydı.",limitation:"İlk katılımcı sayıları, tekrar sayısı ve sayısal etkiler doğrulanmadı. Sonraki iki çalışma örüntüyü tekrarlamadı. Klinik eşik veya herkes için geçerli bir uyumsuzluk mekanizması gösterilmedi."},{id:"self-affirmation-health",title:"Epton ve arkadaşları · 2015 · Kişisel değerler ve sağlık davranışı",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Değerleri hatırlamakla sağlık bilgisini birleştiren 144 sonuç testinde bilgiyi kabul etme, niyet ve davranışta küçük ortalama farklar vardı. Davranış: d=0,32, %95 güven aralığı 0,19 ile 0,44.",limitation:"144 test mutlaka ayrı çalışmalar değildir. Sonuçlardaki katılımcı sayıları örtüşür. Yalnızca değerler hakkında yazmanın, olumlu söz tekrarlamanın veya ODA’nın kısa yetişkin alıştırmasının etkisi gösterilmedi."},{id:"distanced-self-talk",title:"Kross ve arkadaşları · 2014 · Kendine dışarıdan bakarak konuşma deneyleri",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Yedi kısa deneyde 585 kişi vardı. İkinci çalışmada sosyal görüşmeden önce üç dakika adını veya “ben” dışındaki ifadeleri kullanarak düşünmek, gözlemci puanlarına göre daha iyi performans verdi.",limitation:"Çoğunlukla öğrenciler ve sosyal değerlendirme ortamları incelendi. İkinci çalışmada görüşme öncesi kaygı anlamlı ölçüde azalmadı; sonrasında toparlanma daha açıktı. ODA’nın kısa tavsiye ve davranış uyarlaması tedavi veya garanti değil."},{id:"sport-self-talk",title:"Hatzigeorgiadis ve arkadaşları · 2011 · Kendi kendine konuşma ve spor performansı",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 çalışma, 62 etki ve 2.741 katılımcıda spor becerilerinde ortalama performans yararı bulundu: d+=0,48, %95 güven aralığı 0,38 ile 0,58. Yapılan görev ve antrenmana göre alt grup tahminleri farklıydı.",limitation:"Bazı çalışmalarda kontrol grubu yoktu. Çalışmalar arası karşılaştırmalar en iyi miktarı veya yönergenin evrensel üstünlüğünü göstermez. Masa başı işine aktarım ve Gallwey’nin bütün yaklaşımı sınanmadı."},{id:"sleep-memory-reactivation",title:"Paller, Creery ve Schechtman · 2021 · Bellek ve uyku",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"Derleme, önceden öğrenilmiş bilginin uykuda yeniden etkinleşmesini ve sınırlı, basit çağrışım öğrenmesini ele alır.",limitation:"Anlatı derlemesi, birleşik etki yok. Bellek işlemleri uykuluyken kişisel gelişim komutlarına açıklığı, Murphy ritüelini, kayıtlarla yüklenen karmaşık becerileri veya düşüncelerin dış sonuçları yönettiğini göstermez."},{id:"coue-autosuggestion",title:"Émile Coué · 1922 İngilizce baskı · Bilinçli kendi kendine telkin",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"Tarihsel metin, uyanınca ve yatmadan önce alçak sesle yirmi tekrar önerir. Gözler kapalıdır, zorlamadan söylenir ve düğümlerle sayılır.",limitation:"Anılar ve kişisel başarı anlatıları kontrollü kanıt değildir. Yirmi tekrar tarihsel sayı, kanıtlanmış miktar değil. Evrensel hayal gücü kuralları ve hastalıkları iyileştirme iddiaları desteklenmiyor."},{id:"hay-mirror-work",title:"Louise Hay · Ayna çalışması nedir?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"Yazarın sayfası, aynada yüksek sesle söylenen olumlu cümleleri ve 21 günlük programı anlatır.",limitation:"Yöntemin kökeni, etkililik kanıtı değil. Dosya taramasında bütün düzen için kontrollü çalışma bulunmadı. Bu, taramanın sınırıdır. Aynanın üstünlüğü veya 21 günlük alışkanlık son tarihi gösterilmedi."}],M={id:"suggestion",title:"İçindeki eleştiri seni durduruyor mu? Şimdi yapacağın işi söyle.",subtitle:"Yedi kısa ders. İnandırıcı sözlerle işe yarayan tek bir adım at. Ardından gerçekte olana göre düzenle.",description:"Anlamlı tek bir iş seç. İçine sinen cümleyi işi yaparken dene. İşareti iyileştir, yorumları kullan, gördüğün engeli ele al ve aynı denemeyi gelecek hafta sürdür.",scope:"Yetişkinler için kendi kendine telkin ve kendinle konuşma kursu. Hipnoterapi, tanı veya tedavi değildir. Telkin, ilaçlarının veya aldığın tedavinin yerini tutmaz. Doktorunla konuşmadan ilaç veya tedaviyi bırakma. Bazı kitapların hastalıkları iyileştirme ve para çekme iddiaları araştırmayla desteklenmiyor. İçindeki olumsuz sözler çok yoğunsa veya uzun süredir çökkün hissediyorsan bir ruh sağlığı uzmanına başvur. Kendine zarar verme düşüncelerin varsa veya acil tehlikedeysen yerel acil yardım numarasını ara.",outcome:"Yapacağın işe uygun, inandırıcı bir cümle; ne yaptığını gösteren dürüst kayıt ve gününden öğrendiklerine göre sonraki deneme.",photo:{id:"1779922811108-245a9403ef44",alt:"Gün doğumunda tepe üzerinde duran birinin silueti"},lessons:[{id:"suggestion-1",practice:["Bu hafta farklı yaklaşmak istediğin gündelik bir durum belirt.","Tanıdık eleştiri cümlesiyle inanılır, nötr yönergeyi karşılaştır. Görüntü ve cesaret veren sözler isteğe bağlı.","Yönergeyle işe yarayan küçük bir işi dene. Gerçek davranışı ve varsa baskıyı ayrı not et."],reflection:"Kendine en sık hangi cümleyi söylüyorsun? Seni nasıl etkiliyor?",question:"Bu kursta telkin nasıl tanımlanıyor?",options:["Bilinçaltına gönderilen, tek başına her şeyi değiştiren gizli komut.","Seçilen bir cümleyi, görüntüyü ve küçük davranışı birlikte tekrarlamak.","İlaç veya tedavinin yerini tutabilecek düşünme tekniği."],correct:1,feedback:"Kurs, sınanmamış bir yönerge ve davranış denemesi kullanır. Görüntü isteğe bağlıdır. Klinik beklenti çalışmaları birleşik düzeni doğrulamaz. Telkin tedavinin yerini tutmaz, dış sonuçları garanti etmez.",photo:{id:"1461468611824-46457c0e11fd",alt:"Oturup denize bakan bir kadın"},schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"suggestion-1",courseId:"suggestion",locale:"tr",title:"Kendini eleştirip duruyorsun. Şimdi yapacağın işi söyle.",goal:"İçine sinen bir yönerge seç. Asıl işinde yararlı tek bir adım için kullan.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kendine beceriksiz deyip taslağı boş mu bıraktın? O cümle şimdi ne yapacağını söylesin.",reason:{id:"suggestion-1-reason",label:"Kendini eleştirmek neye mal oldu? Şimdi hangi iş önemli?",kind:"text",maxLength:160,optional:!0,suggestions:["Başvuru boş kaldı; ilk bilgiyi yaz","Düzeltmeyi erteledim; tarihi kontrol et","Henüz gördüğüm bir bedel yok"]},why:{id:"suggestion-1-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İşe yarayan cümle ne yapacağını söyler. “İlk bilgiyi yaz” gibi. Seni öven bir cümle ise nasıl biri olduğunu söyler. Çok olumlu cümleler hakkında kanıtlar karışık. İlk çalışma bazı kişilerde hemen sonrasında daha kötü tepkiler bildirdi. Sonraki iki çalışma bu durumu tekrarlamadı. Nötr bir cümle seçmek sana tanı koymaz.","Önemsediğin amaç için işe yarayacak gerçek bir iş bul. Kendine etiket takmak yerine yapacağın işi söyleyen bir cümle kur. Ardından işe yarayan tek kısmı yap. Spor araştırması masa başı işine yararı kanıtlamaz. Yaptığını kaydet. Cümle yardım mı etti, baskı mı yarattı, etkisiz mi kaldı?"],example:{title:"Selin ilk bilgiyi yazıyor",text:"Saat 14.00. Selin başvuru taslağının başında. “Ben beceriksizim” tanıdık, “Harikayım” ise inandırıcı değil. “İlk bilgiyi yaz” cümlesini deniyor. Deneyimi hakkında kullanabileceği bir cümle yazıyor. Başvuruya ilişkin kuşkusu sürüyor. Cümleyi ve değişmeyen kuşkusunu kaydediyor. Övgüye inanana kadar tekrar etmek yerine başka küçük bir deneme planlıyor. İlk yazdığı cümle, başvurunun bitmesi veya kabul edilmesi demek değil."}},move:{invitation:"İşini ve ne yapacağını söyleyen cümleyi belirt. Öneriler Selin’in başvurusundan örnekler.",instructions:["Kaydetmeden önce gerçekten kullanacağın belgeyi, soruyu veya işi belirt.","Yönergeyi bir kez oku. Ardından ona uyan, işe yarayan küçük kısmı yap."],prompts:[],suggestions:{action:["“İlk bilgiyi yaz” diyerek bir başvuru cümlesi yaz","Başvurudaki iş deneyimi sorusunu yanıtla"],minimum:["İş deneyimimle ilgili bir bilgiyi anlatan cümleyi kaydet","İş deneyimi sorusuna yazdığım yanıtı kaydet"],cue:["Öğle yemeği bitince","Akşam yemeğinin sofrası toplandıktan sonra"],place:["Mutfak masamda","Başvuru taslağımda"],minutes:[2,1,3],fallback:["Kendini yargılama; başvuruya doğru bilgi içeren cümle yaz","Metni okuyana hangi iş ayrıntısının gerektiğini sor"],observation:["Başvuruda kaydettiğim gerçek cümle","Sözlerin yardım etmesi veya baskı yaratması"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"“İlk bilgiyi yaz” diyerek bir başvuru cümlesi yaz",minimum:"İş deneyimimle ilgili bir bilgiyi anlatan cümleyi kaydet",minutes:2,cueHint:"Öğle yemeği bitince",placeHint:"Mutfak masamda",obstacleHint:"Cümlem yine kendime etiket takmaya dönüşüyor",fallbackHint:"Kendini yargılama; başvuruya doğru bilgi içeren cümle yaz",observationHint:"Başvuruda kaydettiğim gerçek cümle"},stopRule:"Sıkıntını artıran sözleri bırak. Sıkıntı sürüyorsa destek al. Kaygı veren belirtiler için sağlık hizmetine başvur.",accessibleAlternative:"Yazabilir, sesle yazdırabilir veya yardım alabilirsin. Yalnızca yapılacak işi söylemek yeterli."},result:{question:"Seçtiğin işe yarayan küçük kısmı ortaya çıkardın mı?",observationPrompt:"Gerçekte hangi işi yaptın? O fırsatta önünü hangi koşul kesti?"},judgment:{primary:{id:"suggestion-1-decision",scenario:"Selin’in iki dakikası ve başvuruda yazacağı bir cümle için bilgileri var. Övgü inandırıcı gelmiyor. Taslak hâlâ boş.",question:"Bu denemeye hangi adım daha iyi uyar?",options:[{id:"suggestion-1-praise",text:"Yazmaya başlayıp başlayamayacağına karar vermeden önce daha sıcak ve olumlu bir cümle kullanmak.",feedback:"Sıcak sözler tercih olabilir. Ama Selin bugün onlara inanmadığını zaten biliyor. Nötr bir iş yönergesi dene. Önce övgüye inanmayı şart koşmadan, kullanabileceğin küçük bir kısmı yap."},{id:"suggestion-1-fact",text:"“İlk bilgiyi yaz” demek, sonra başvuruda kullanabileceği bir cümleyi gerçekten yazmak.",feedback:"Bu seçim, kontrolündeki bir işi belirtir ve hemen sınar. Cümle yardımcı olabilir, etkisiz kalabilir veya baskı yaratabilir. Ortaya çıkan gerçek işi ve yaşadığını ayrı ayrı kaydedebilir."},{id:"suggestion-1-picture",text:"Başvurusunun başarıyla değerlendirildiğini canlandırmak, sonra yazmaya hazır hissedip hissetmediğine bakmak.",feedback:"Görüntü kurmak hoş bir hazırlık olabilir. Ama seçilen küçük işi ortaya çıkarmaz. Bilgiler hazır. Ne yapacağını söyleyen bir cümle kullan ve o küçük işi dene. Hazır hissetmen gerekmiyor."}],bestOptionId:"suggestion-1-fact"}},carry:{takeaway:"Cümle ne yapacağını söylesin. İşe yarayıp yaramadığına, gerçekte yaptığınla birlikte bak.",followUp:{questionId:"suggestion-1-return",question:"Seçtiğin işi yapınca ne oldu? Cümle yardımcı mı oldu, baskı mı yarattı?",observationPrompt:"Kaydın, hangi işi yaptığını veya hangi isteği ilettiğini gösteriyor?",adjustmentPrompt:"Sonraki işaret geldiğinde neyi koruyacak veya değiştireceksin?"}},goDeeper:{sections:[{heading:"Sözlerin inandırıcı gelmesi bir tercih. Ulaşman gereken bir puan yok.",paragraphs:["Wood ve arkadaşlarının erişilebilen özeti, çok olumlu bir cümleyi tekrarlayan, kendine verdiği değer düşük bazı kişilerde hemen sonrasında daha kötü tepkiler bildiriyordu. Özet, belirli bir tekrar sayısı önermek veya bir kişinin tepkisini tahmin etmek için yeterli ayrıntı vermiyor. Flynn ve Bordieri’nin üniversite ortamında, gündelik durumları modelleyen sonraki iki çalışması beklenen örüntüyü tekrarlamadı. Bu yüzden kanıtlar belirsizlik içeriyor. Olumlu sözlerin belli türdeki kişilere zarar verdiğine dair yerleşmiş bir kural sunmuyor. Bu bulguyla kendine bir etiket veya tanı koyma. (suggestion-S07; suggestion-S08)","Yine de kendi tercihin kullanılabilir bir bilgi. “Harikayım” yanlış geliyorsa “İlk bilgiyi yaz” diyebilirsin. Sözleri değiştirebilir, tekrarlamayabilir veya bırakabilirsin. Kendine sakladığın bir inandırıcılık puanı, sözleri seçmene yardım edebilir. Ama burada hiçbir puan doğrulanmış klinik sınır değildir. ODA o puandan kendine verdiğin değeri çıkarmaz. Kendini motive eden sözler söylemeni de şart koşmaz. Gerçek işinden başla ki cümlenin belirli bir amacı olsun. İnanılır gelmesi, o işe yardım ettiği anlamına kendiliğinden gelmez."]},{heading:"Farklı sözler farklı araştırmalarda sınandı",paragraphs:["Hatzigeorgiadis ve arkadaşları, spor ve hareket becerilerinde kendi kendine konuşmayla ilgili otuz iki çalışmadan altmış iki etkiyi birleştirdi. Birinci tabloda 2.741 katılımcı bildirildi. Performansa ortalama yarar, başvuru yazarken, ilişkilerde veya kaygıda aynı yararın olacağını göstermez. Bazı çalışmalarda kontrol grubu yoktu. Alt grup karşılaştırmaları da yapacağın işi söyleyen sözlerle motive eden sözler arasında herkes için geçerli bir sıralama kanıtlamıyor. Spor ortamındaki bulguyu başka bir alana doğrudan taşıyamayız. (suggestion-S04)","Bugünkü nötr yönerge ve küçük yazı işi, spor araştırmasının dışına taşınan bir ODA uyarlaması. Kursun birleşik düzeni bir paket olarak sınanmadı. Ne söylediğini, gerçekte ne yaptığını ve varsa hissettiğin baskıyı ayrı kaydet. Bir cümle inanılır gelebilir ama iş yapmana yardım etmeyebilir. Başlamayı kolaylaştırıp kuşkunu azaltmayabilir. Bu ayrımlar, cümleyi korumak, düzenlemek veya bırakmak için gerekçe verir. Her tekrarı, seçtiğin hayata doğru ilerlemişsin gibi sayman gerekmez. Sonraki kararını cümlenin güzel görünmesine değil, işinle birlikte nasıl kullanıldığına göre verebilirsin."]}],sourceIds:["suggestion-S07","suggestion-S08","suggestion-S04"]}},title:"Kendini eleştirip duruyorsun. Şimdi yapacağın işi söyle.",goal:"İçine sinen bir yönerge seç. Asıl işinde yararlı tek bir adım için kullan.",minutes:6,reading:["İşe yarayan cümle ne yapacağını söyler. “İlk bilgiyi yaz” gibi. Seni öven bir cümle ise nasıl biri olduğunu söyler. Çok olumlu cümleler hakkında kanıtlar karışık. İlk çalışma bazı kişilerde hemen sonrasında daha kötü tepkiler bildirdi. Sonraki iki çalışma bu durumu tekrarlamadı. Nötr bir cümle seçmek sana tanı koymaz.","Önemsediğin amaç için işe yarayacak gerçek bir iş bul. Kendine etiket takmak yerine yapacağın işi söyleyen bir cümle kur. Ardından işe yarayan tek kısmı yap. Spor araştırması masa başı işine yararı kanıtlamaz. Yaptığını kaydet. Cümle yardım mı etti, baskı mı yarattı, etkisiz mi kaldı?"],example:{title:"Selin ilk bilgiyi yazıyor",text:"Saat 14.00. Selin başvuru taslağının başında. “Ben beceriksizim” tanıdık, “Harikayım” ise inandırıcı değil. “İlk bilgiyi yaz” cümlesini deniyor. Deneyimi hakkında kullanabileceği bir cümle yazıyor. Başvuruya ilişkin kuşkusu sürüyor. Cümleyi ve değişmeyen kuşkusunu kaydediyor. Övgüye inanana kadar tekrar etmek yerine başka küçük bir deneme planlıyor. İlk yazdığı cümle, başvurunun bitmesi veya kabul edilmesi demek değil."},deeper:[{heading:"Sözlerin inandırıcı gelmesi bir tercih. Ulaşman gereken bir puan yok.",paragraphs:["Wood ve arkadaşlarının erişilebilen özeti, çok olumlu bir cümleyi tekrarlayan, kendine verdiği değer düşük bazı kişilerde hemen sonrasında daha kötü tepkiler bildiriyordu. Özet, belirli bir tekrar sayısı önermek veya bir kişinin tepkisini tahmin etmek için yeterli ayrıntı vermiyor. Flynn ve Bordieri’nin üniversite ortamında, gündelik durumları modelleyen sonraki iki çalışması beklenen örüntüyü tekrarlamadı. Bu yüzden kanıtlar belirsizlik içeriyor. Olumlu sözlerin belli türdeki kişilere zarar verdiğine dair yerleşmiş bir kural sunmuyor. Bu bulguyla kendine bir etiket veya tanı koyma. (suggestion-S07; suggestion-S08)","Yine de kendi tercihin kullanılabilir bir bilgi. “Harikayım” yanlış geliyorsa “İlk bilgiyi yaz” diyebilirsin. Sözleri değiştirebilir, tekrarlamayabilir veya bırakabilirsin. Kendine sakladığın bir inandırıcılık puanı, sözleri seçmene yardım edebilir. Ama burada hiçbir puan doğrulanmış klinik sınır değildir. ODA o puandan kendine verdiğin değeri çıkarmaz. Kendini motive eden sözler söylemeni de şart koşmaz. Gerçek işinden başla ki cümlenin belirli bir amacı olsun. İnanılır gelmesi, o işe yardım ettiği anlamına kendiliğinden gelmez."]},{heading:"Farklı sözler farklı araştırmalarda sınandı",paragraphs:["Hatzigeorgiadis ve arkadaşları, spor ve hareket becerilerinde kendi kendine konuşmayla ilgili otuz iki çalışmadan altmış iki etkiyi birleştirdi. Birinci tabloda 2.741 katılımcı bildirildi. Performansa ortalama yarar, başvuru yazarken, ilişkilerde veya kaygıda aynı yararın olacağını göstermez. Bazı çalışmalarda kontrol grubu yoktu. Alt grup karşılaştırmaları da yapacağın işi söyleyen sözlerle motive eden sözler arasında herkes için geçerli bir sıralama kanıtlamıyor. Spor ortamındaki bulguyu başka bir alana doğrudan taşıyamayız. (suggestion-S04)","Bugünkü nötr yönerge ve küçük yazı işi, spor araştırmasının dışına taşınan bir ODA uyarlaması. Kursun birleşik düzeni bir paket olarak sınanmadı. Ne söylediğini, gerçekte ne yaptığını ve varsa hissettiğin baskıyı ayrı kaydet. Bir cümle inanılır gelebilir ama iş yapmana yardım etmeyebilir. Başlamayı kolaylaştırıp kuşkunu azaltmayabilir. Bu ayrımlar, cümleyi korumak, düzenlemek veya bırakmak için gerekçe verir. Her tekrarı, seçtiğin hayata doğru ilerlemişsin gibi sayman gerekmez. Sonraki kararını cümlenin güzel görünmesine değil, işinle birlikte nasıl kullanıldığına göre verebilirsin."]}],sources:["suggestion-S07","suggestion-S08","suggestion-S04","suggestion-S20"],takeaway:"Cümle ne yapacağını söylesin. İşe yarayıp yaramadığına, gerçekte yaptığınla birlikte bak.",visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"İşaret",text:"Sana uyan bir fırsat seç."},{label:"Yap",text:"İşe yarayan en küçük adımı dene."},{label:"Dön",text:"Kaydet ve sonraki denemeyi seç."}]}},{id:"suggestion-2",practice:["Coué’nin tarihsel ritüelini incelemeyi seçersen sözlerin sana uyduğunu kontrol et. Sayma araçları isteğe bağlı.","1922 İngilizce metni yirmi sessiz tekrar anlatır. Bu tarihsel bilgi, kanıtlanmış miktar veya gerekli yatma alıştırması değil.","Sözleri kendi isteğinle denersen sıkıntı hissedince veya uyanık kalınca bırak. Okumayı gerçek iş davranışından ayrı tut."],reflection:"Zorlamadan söylemek nasıl geldi: rahatlatıcı, tuhaf, sıkıcı mı?",question:"Hangisi Coué’nin cümlesi için önerdiği tutuma uyar?",options:["Cümleyi dişlerini sıkarak, olabildiğince güçlü söylemek.","Rahat, alçak sesle söylemek; saymayı ipe veya boncuklara bırakmak.","Her tekrardan sonra bir şey değişti mi diye kontrol etmek."],correct:1,feedback:"Coué tarihsel anlatısında rahat tekrar önerdi. Anılar evrensel hayal gücü kuralını, etkili yirmi tekrar miktarını veya hastalıkları iyileştirmeyi göstermez. Açılan İngilizce baskı 1922 tarihlidir.",photo:{id:"1762328490563-9b9c300fba3e",alt:"Elinde boncuk dizisi tutan biri"},schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"suggestion-2",courseId:"suggestion",locale:"tr",title:"Hatırlatmayı okudun. Peki işe ne zaman başlayacaksın?",goal:"Aynı yararlı adımı, hayatında gerçekten karşılaştığın bir başlama anında dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hatırlatmayı tekrarladın, sayfa hâlâ boş mu? O işaret geldiğinde yalnızca okuma, işi yap.",reason:{id:"suggestion-2-reason",label:"İşi yapmadan hatırlatmayı tekrarladıysan bundan ne kazandın?",kind:"text",maxLength:160,optional:!0,suggestions:["Kısa süre rahatladım; taslak boş kaldı","İlk cümleyi seçmekten kaçındım","Daha önce yalnızca hatırlatma okuduğum deneme yok"],help:"Denemen yoksa bir kez daha hatırlatma okumak hangi işi erteler, düşün."},why:{id:"suggestion-2-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir sözü tekrarlamakla bir işi tekrarlamak ayrı denemelerdir. Alışkanlık araştırması, tekrarlanan olaylarda yemek, içmek ve hareket etmek gibi davranışları izledi. Bu davranışlar kişiden kişiye farklı hızlarda otomatikleşti. Olumlama cümleleri sınanmadı. Coué’nin yirmi tekrarı tarihsel bir talimat, kanıtlanmış uygulama miktarı değil.","İlk kaydına bak. Cümle içine sindi ama başlayamadın mı? İşi koru ve gerçekten oluşan bir olay seç. “Öğle yemeğinden sonra bir başvuru cümlesi yaz” işaretle işi birleştirir. İşine yarıyorsa yönergeni bir kez oku, ardından o kısmı yap. Malzemeleri hazırlamak hazırlıktır. Cümleyi yazmak ise işi denemektir."],example:{title:"Selin öğle yemeğinden sonra yazıyor",text:"Selin’in ilk yönergesi inandırıcıydı. Ama yoğun sabahında aklına gelmedi. Başvuru işini koruyup sonraki işaret olarak öğle yemeğinin bitişini seçiyor. Mutfak masasında “İlk bilgiyi yaz” cümlesini bir kez okuyor. Ardından kullanabileceği bir cümle yazıyor. Çalışma kısa sürüyor. İşareti ve yazdığını kaydediyor. Buna hemen kendiliğinden oluşmuş bir alışkanlık demiyor. Bir kez yapmış olması, her gün unutmayacağını da göstermiyor."}},move:{invitation:"Seçtiğin işi koru. Öneriler Selin’in öğle yemeğinden sonra yaptığı işten örnekler.",instructions:["İşi ve en küçük adımı koru. İşareti ancak kaydında sorun görünüyorsa değiştir.","İlk planında, kaydetmeden önce işe yarayan sonucu ve gerçek fırsatı belirt."],prompts:[],suggestions:{action:["Öğle yemeğinden sonra başvuruya deneyimini anlatan cümle yaz","Çaydan sonra başvurunun deneyim sorusunu yanıtla"],minimum:["Başvuruya doğru bilgi içeren tek cümle yazıp kaydet","İş deneyimi sorusuna yazdığım yanıtı kaydet"],cue:["Öğle yemeği bitince","Çayımı masaya bıraktığımda"],place:["Mutfak masamda","Başvuru taslağımda"],minutes:[2,1,3],fallback:["Akşam yemeğinden sonra iş deneyimini anlatan cümleyi yaz","Öğle yemeğinde başvuru cümlesini sesle yazdır"],observation:["İşaretin oluşması ve başvuru cümlesini yazmam","Hatırlatmayı okumakla ortaya çıkan işi ayrı tutmam"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Öğle yemeğinden sonra başvuruya deneyimini anlatan cümle yaz",minimum:"Başvuruya doğru bilgi içeren tek cümle yazıp kaydet",minutes:2,cueHint:"Öğle yemeği bitince",placeHint:"Mutfak masamda",obstacleHint:"Başka işler öğle yemeğinden sonra başlamamı engelliyor",fallbackHint:"Akşam yemeğinden sonra iş deneyimini anlatan cümleyi yaz",observationHint:"İşaretin oluşması ve başvuru cümlesini yazmam"},stopRule:"Sıkıntını artıran veya seni daha uyanık tutan tekrarları yapma. Bakım, dinlenme ve gerçek güvenlik ihtiyaçlarını koru.",accessibleAlternative:"Yazılı, sözlü veya sana uygun bir hatırlatıcı kullan. Boncuk veya sayma şart değil."},result:{question:"İşaret oluştu mu? Seçtiğin küçük işi yaptın mı?",observationPrompt:"Gerçekte hangi işi yaptın? O fırsatta önünü hangi koşul kesti?"},judgment:{primary:{id:"suggestion-2-decision",scenario:"Selin üç sabah inandırıcı hatırlatmasını okudu ama yazmadı. Taslağı ve deneyim bilgileri hazır. Öğle arasında bir cümleye düzenli olarak zaman var.",question:"Bu denemeye hangi adım daha iyi uyar?",options:[{id:"suggestion-2-count",text:"Sabah işaretini korumak ve taslağa başlamadan önce daha çok tekrar eklemek.",feedback:"Daha çok tekrar, sözü okumayı sınar. Eksik olan işe başlamayı değil. Kayıtları zamanın uygunluğuna işaret ediyor. Önündeki öğle fırsatında gerçek bir cümle yaz. Sonra ne olduğuna bak."},{id:"suggestion-2-cue",text:"İnandırıcı cümleyi korumak, öğle yemeği bitişini işaret seçmek ve bir cümle yazmak.",feedback:"Bu seçim, işe yarayan işi korurken başlamayı engelleyen koşulu değiştirir. İşaret oluştu mu ve cümle yazıldı mı, kaydet. Denemenin sayılması için davranışın kendiliğinden bir alışkanlığa dönüşmesi gerekmiyor."},{id:"suggestion-2-prepare",text:"Öğle arasını hatırlatmayı kusursuzlaştırmaya ve yarın kullanacağı bütün malzemeleri düzenlemeye ayırmak.",feedback:"Bir kaynak eksikse hazırlık işe yarar. Ama Selin’in malzemeleri ve yönergesi hazır. Yeni bir hazırlık çalışması, kullanabileceği aynı cümleyi yine yazılmamış bırakır. Şimdi küçük işi yapmayı dene."}],bestOptionId:"suggestion-2-cue"}},carry:{takeaway:"İşaret geldiğinde işe yarayan adımı at. Ondan önceki sözleri okumakla yetinme.",followUp:{questionId:"suggestion-2-return",question:"Seçtiğin işaretin ardından işi mi yaptın, isteğini mi ilettin, yoksa yalnızca hatırlatmayı mı okudun?",observationPrompt:"Kaydın, hangi işi yaptığını veya hangi isteği ilettiğini gösteriyor?",adjustmentPrompt:"Sonraki işaret geldiğinde neyi koruyacak veya değiştireceksin?"}},goDeeper:{sections:[{heading:"Coué’nin tekrar sayısı neyi gösterir?",paragraphs:["Coué’nin 1922 tarihli İngilizce metni, uyanınca ve yatmadan önce yirmi kez alçak sesle tekrar etmeyi anlatır. Gözler kapalıdır, saymak için düğümler kullanılır. Bunlar tarihsel talimatlardır. Metinde kontrollü müdahale kanıtı yerine anılar, gösteriler ve kişilerin anlattığı sonuçlar vardır. Yirmi tekrar ve günde iki zaman, bu nedenle yöntemin kökenine aittir. Etkili olduğu gösterilmiş miktarlar değildir. Geçmişte önerilen tekrarlar, bugünkü cümlenin seçtiğin işe yardım edip etmediğini söyleyemez. (suggestion-S15)","İnandırıcı bir iş yönergesini denemek için bu ritüeli yeniden kurman gerekmiyor. Hayal gücünün iradeye her zaman üstün geldiği veya hastalıkları iyileştirdiği iddiaları, anlatılan örneklerden çıkarılamaz. Önerilen tedavini sürdür. Yeni fiziksel belirtileri açıklamak için rahatlatıcı bir söz kullanma. Ana ders, seçtiğin işaretin işe yarayan bir davranışı destekleyip desteklemediğine bakıyor. Bir kez okumak isteğe bağlı hazırlıktır. İşe katkı veren, sonrasında gerçekten yaptığın davranıştır. Okumayı veya saymayı işi tamamladığınla karıştırmadan kaydet. Tarihsel açıklama, tedavi yerine geçmez."]},{heading:"Tekrarlanan bir an, hemen alışkanlık yaratmaz",paragraphs:["Lally ve arkadaşları, tekrarlanan bir olaya bağlı yemek, içmek veya hareket etmek davranışı seçen doksan altı gönüllüyü izledi. Seksen dört gün boyunca tekrarı ve kendiliğinden yapma düzeyini takip ettiler. Yeterli verisi olan seksen iki kişiden otuz dokuzunun modeli uygundu. Bu kişilerde, kendiliğinden yapmanın kişisel en yüksek düzeyine yaklaşma süreleri oldukça farklıydı. Bazı tahminler gözlem süresini aşıyordu. Ortanca altmış altı gün, her davranış için son tarih değildi. Herkesin aynı gün alışkanlık kazanacağı sonucu çıkarılamaz. (suggestion-S09)","Bu, gözlemsel bir alışkanlık çalışmasıydı. Coué’nin cümlesini, yatarken tekrarı veya başvuru yazma düzenini sınayan bir deney değildi. ODA’nın öğle işareti ve küçük adımı tasarım tercihleridir. Bir deneme, işaretin oluştuğunu ve küçük işi yapabildiğini gösterebilir. Cümlenin başarıya neden olduğunu veya rutinin cuma gününe kadar kendiliğinden işleyeceğini kanıtlamaz. Yarın kaydına bakarken hazırlığı, işaretin oluşmasını ve gerçek işin ortaya çıkmasını ayrı tut. Sonraki fırsatta hangi koşulu koruyacağını veya değiştireceğini bu ayrımdan seçebilirsin. Bir günün kaydı, bütün haftaya söz vermez."]}],sourceIds:["suggestion-S15","suggestion-S09"]}},title:"Hatırlatmayı okudun. Peki işe ne zaman başlayacaksın?",goal:"Aynı yararlı adımı, hayatında gerçekten karşılaştığın bir başlama anında dene.",minutes:6,reading:["Bir sözü tekrarlamakla bir işi tekrarlamak ayrı denemelerdir. Alışkanlık araştırması, tekrarlanan olaylarda yemek, içmek ve hareket etmek gibi davranışları izledi. Bu davranışlar kişiden kişiye farklı hızlarda otomatikleşti. Olumlama cümleleri sınanmadı. Coué’nin yirmi tekrarı tarihsel bir talimat, kanıtlanmış uygulama miktarı değil.","İlk kaydına bak. Cümle içine sindi ama başlayamadın mı? İşi koru ve gerçekten oluşan bir olay seç. “Öğle yemeğinden sonra bir başvuru cümlesi yaz” işaretle işi birleştirir. İşine yarıyorsa yönergeni bir kez oku, ardından o kısmı yap. Malzemeleri hazırlamak hazırlıktır. Cümleyi yazmak ise işi denemektir."],example:{title:"Selin öğle yemeğinden sonra yazıyor",text:"Selin’in ilk yönergesi inandırıcıydı. Ama yoğun sabahında aklına gelmedi. Başvuru işini koruyup sonraki işaret olarak öğle yemeğinin bitişini seçiyor. Mutfak masasında “İlk bilgiyi yaz” cümlesini bir kez okuyor. Ardından kullanabileceği bir cümle yazıyor. Çalışma kısa sürüyor. İşareti ve yazdığını kaydediyor. Buna hemen kendiliğinden oluşmuş bir alışkanlık demiyor. Bir kez yapmış olması, her gün unutmayacağını da göstermiyor."},deeper:[{heading:"Coué’nin tekrar sayısı neyi gösterir?",paragraphs:["Coué’nin 1922 tarihli İngilizce metni, uyanınca ve yatmadan önce yirmi kez alçak sesle tekrar etmeyi anlatır. Gözler kapalıdır, saymak için düğümler kullanılır. Bunlar tarihsel talimatlardır. Metinde kontrollü müdahale kanıtı yerine anılar, gösteriler ve kişilerin anlattığı sonuçlar vardır. Yirmi tekrar ve günde iki zaman, bu nedenle yöntemin kökenine aittir. Etkili olduğu gösterilmiş miktarlar değildir. Geçmişte önerilen tekrarlar, bugünkü cümlenin seçtiğin işe yardım edip etmediğini söyleyemez. (suggestion-S15)","İnandırıcı bir iş yönergesini denemek için bu ritüeli yeniden kurman gerekmiyor. Hayal gücünün iradeye her zaman üstün geldiği veya hastalıkları iyileştirdiği iddiaları, anlatılan örneklerden çıkarılamaz. Önerilen tedavini sürdür. Yeni fiziksel belirtileri açıklamak için rahatlatıcı bir söz kullanma. Ana ders, seçtiğin işaretin işe yarayan bir davranışı destekleyip desteklemediğine bakıyor. Bir kez okumak isteğe bağlı hazırlıktır. İşe katkı veren, sonrasında gerçekten yaptığın davranıştır. Okumayı veya saymayı işi tamamladığınla karıştırmadan kaydet. Tarihsel açıklama, tedavi yerine geçmez."]},{heading:"Tekrarlanan bir an, hemen alışkanlık yaratmaz",paragraphs:["Lally ve arkadaşları, tekrarlanan bir olaya bağlı yemek, içmek veya hareket etmek davranışı seçen doksan altı gönüllüyü izledi. Seksen dört gün boyunca tekrarı ve kendiliğinden yapma düzeyini takip ettiler. Yeterli verisi olan seksen iki kişiden otuz dokuzunun modeli uygundu. Bu kişilerde, kendiliğinden yapmanın kişisel en yüksek düzeyine yaklaşma süreleri oldukça farklıydı. Bazı tahminler gözlem süresini aşıyordu. Ortanca altmış altı gün, her davranış için son tarih değildi. Herkesin aynı gün alışkanlık kazanacağı sonucu çıkarılamaz. (suggestion-S09)","Bu, gözlemsel bir alışkanlık çalışmasıydı. Coué’nin cümlesini, yatarken tekrarı veya başvuru yazma düzenini sınayan bir deney değildi. ODA’nın öğle işareti ve küçük adımı tasarım tercihleridir. Bir deneme, işaretin oluştuğunu ve küçük işi yapabildiğini gösterebilir. Cümlenin başarıya neden olduğunu veya rutinin cuma gününe kadar kendiliğinden işleyeceğini kanıtlamaz. Yarın kaydına bakarken hazırlığı, işaretin oluşmasını ve gerçek işin ortaya çıkmasını ayrı tut. Sonraki fırsatta hangi koşulu koruyacağını veya değiştireceğini bu ayrımdan seçebilirsin. Bir günün kaydı, bütün haftaya söz vermez."]}],sources:["suggestion-S15","suggestion-S09","suggestion-S20"],takeaway:"İşaret geldiğinde işe yarayan adımı at. Ondan önceki sözleri okumakla yetinme.",visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"İşaret",text:"Sana uyan bir fırsat seç."},{label:"Yap",text:"İşe yarayan en küçük adımı dene."},{label:"Dön",text:"Kaydet ve sonraki denemeyi seç."}]}},{id:"suggestion-3",practice:["Sana uyan olumlu bir cümle veya nötr iş yönergesi seç.","İstersen inandırıcılığı puanla; bu puan klinik bir eşik değil. Sıkıntını artırıyorsa sözleri düzenle veya bırak.","İstersen önemli bir değeri düşün. Sonra o değere katkı veren somut bir iş seç."],reflection:"Hangi cümle “Evet, bu doğru olabilir” dedirtiyor?",question:"Olumlu cümlelere ilişkin karışık bulgularla hangi sözleri denemeyi seçebilirsin?",options:["İnanmasan da en iddialı cümleyi daha çok tekrarlamak.","İnanabileceğin, yapacağın süreci anlatan cümle seçmek.","Kendine hiçbir zaman olumlu bir cümle söylememek."],correct:1,feedback:"İlk ters tepme bulgusu sonraki iki çalışmada tekrarlanmadı. Nötr veya yapacağın işi anlatan sözler isteğe bağlıdır, kanıtlanmış daha güvenli tedavi değil. İnandırıcılık puanları, kendine verdiğin değeri ölçmez; tanı koymak için de kullanılamaz.",photo:{id:"1616628188467-8fb29f49bbe8",alt:"Beyaz kâğıda not yazan el"},schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"suggestion-3",courseId:"suggestion",locale:"tr",title:"Eleştiriyi kapatıp geçme. Bir ayrıntıyı düzelt.",goal:"Yorumlar işini durduruyorsa, seçtiğin bir değere uygun gerçek bir düzeltme yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kendine güvenini korumak için yorumları okumuyor musun? Önemsediğin bir değer, somut bir düzeltmeye yol göstersin.",reason:{id:"suggestion-3-reason",label:"Hangi işe yarayan yorumu kullanmak zor geliyor? Ertelemenin bedeli ne?",kind:"text",maxLength:160,optional:!0,suggestions:["Cümle belirsiz; okuyan hâlâ anlamıyor","Tarih eksik; başvuru tamamlanmıyor","Taslağı değiştirmeden önce açıklama gerekiyor","Henüz kullanabileceğim bir yorum yok"]},why:{id:"suggestion-3-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Değerlerini düşünmek, kendini övmekten farklıdır. Bunu sağlık bilgisiyle birleştiren araştırmalar, bilgiyi kabul etmede ve sonraki davranışta küçük ortalama yararlar buldu. Kısa bir değer notunun tek başına her işi veya ruh hâlini iyileştirdiği kanıtlanmış değil.","Kaydında yorumdan kaçındığını görüyorsan bu adımı kullan. Aynı işi koru. Öğrenmek gibi önemsediğin bir değer, tek düzeltmeyi seçmene yardım edebilir. “Bu bilgiyi kontrol et” de. Sonra düzelt veya açıklama iste. Birden çok nedenin ve aileden gelen sorumlulukların olabilir. Kusursuz bir gerekçe, her yoruma katılmak veya daha çok güven hissetmek gerekmiyor."],example:{title:"Selin yoruma göre bir cümleyi düzeltiyor",text:"Öğle yemeği bitince Selin, başvuru cümlesinin belirsiz olduğunu söyleyen yorumu görüyor. Öğrenmek onun için önemli. Yine de belgeyi kapatmak istiyor. “Somut bir örnek ekle” diyor. Cümleye gerçekten yaptığı bir işi ekliyor. Taslağın tamamında hâlâ eksikler var. Değeri sayesinde yeni bir güven kazandığını söylemek yerine yaptığı düzeltmeyi kaydediyor. Yorumun hepsine katıldığını da varsaymıyor."}},move:{invitation:"Seçtiğin işi koru. Öneriler Selin’in yorum üzerine yaptığı düzeltmeden örnekler.",instructions:["Kayıtlı işi ve işareti koru. Hangi yorum için neyi düzelteceğini belirt.","Bir değeri hatırlamak yardım edebilir. Gerçek adımın, düzeltmek veya açıklama istemek olsun."],prompts:[],suggestions:{action:["Başvuru cümlesine yaptığım işten bir örnek ekle","Okuyana hangi başvuru cümlesinde ayrıntı gerektiğini sor"],minimum:["Bir örnek eklediğin başvuru cümlesini kaydet","Eksik başvuru ayrıntısını soran mesajı gönder"],cue:["Öğle yemeği bitince","Metni okuyanın yorumu gelince"],place:["Mutfak masamda","Başvuru taslağımda"],minutes:[2,1,3],fallback:["Taslağı savunmadan bildiğin bir iş bilgisini ekle","Okuyana hangi ayrıntının açıklanması gerektiğini sor"],observation:["Düzelttiğim cümle veya gönderdiğim açıklama sorusu","İlgili yorumu kullanıp kullanmadığım"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Başvuru cümlesine yaptığım işten bir örnek ekle",minimum:"Bir örnek eklediğin başvuru cümlesini kaydet",minutes:2,cueHint:"Öğle yemeği bitince",placeHint:"Mutfak masamda",obstacleHint:"Düzeltmek yerine bütün taslağı savunmak istiyorum",fallbackHint:"Taslağı savunmadan bildiğin bir iş bilgisini ekle",observationHint:"Düzelttiğim cümle veya gönderdiğim açıklama sorusu"},stopRule:"Düşmanca veya güvenli olmayan yorumlarda sınırlarını koru. Gerekiyorsa korunmayı veya destek almayı seç.",accessibleAlternative:"Hangi değeri seçtiğini kendine saklayabilir, nötr bir yönergeyi veya yardım almayı seçebilirsin. Değer hakkında yazmak isteğe bağlı."},result:{question:"Düzeltmeyi yaptın mı veya seçtiğin soruyu sordun mu?",observationPrompt:"Gerçekte hangi işi yaptın? O fırsatta önünü hangi koşul kesti?"},judgment:{primary:{id:"suggestion-3-decision",scenario:"Selin’in güvenle yorum alabildiği kişi bir cümleyi belirsiz buluyor. Selin’in somut örneği hazır, öğrenmeye değer veriyor. Ama kendini savunmak istiyor.",question:"Bu denemeye hangi adım daha iyi uyar?",options:[{id:"suggestion-3-strengths",text:"Önce güçlü yönlerini sıralamak, eleştiriyi duymak daha kolay geldiğinde cümleye geri dönmek.",feedback:"Güçlü yönlerini düşünmeyi tercih edebilir. Ama kullanabileceği örnek şimdi hazır. Önce rahatlamayı şart koşmadan, önemsediği öğrenme değeriyle bir düzeltme yapabilir. Değer, gerçek bir seçime bu şekilde katılır."},{id:"suggestion-3-correct",text:"“Bir örnek ekle” demek ve elindeki gerçek bilgiyi cümleye yazarak düzeltmek.",feedback:"Bu seçim, aynı işte öğrenmeyi somut bir davranışa dönüştürür. Düzeltme gözlenebilir bir kanıttır. Ruh hâlinin iyileşmesi veya her yoruma katılması gerekmiyor. Kayda ekleyeceği şey, gerçekten değiştirdiği cümledir."},{id:"suggestion-3-reassure",text:"Belirli düzeltmeyi yapmadan önce metni okuyandan genel becerisini onaylamasını istemek.",feedback:"Onay almak iyi hissettirebilir. Ama eksik bilgi genel becerisi hakkında değil. Belirli yorumu ve hazır bilgiyi kullan. Ayrıntılar gerçekten belirsiz olduğunda açıklama iste. Düzeltmeye başlamak için övgü bekleme."}],bestOptionId:"suggestion-3-correct"}},carry:{takeaway:"Önemsediğin bir değer, gerçekten yaptığın bir seçime yol gösterdiğinde işine yarar.",followUp:{questionId:"suggestion-3-return",question:"Düzeltmeyi yaptın mı veya açıklama istedin mi? Hangi ayrıntı hâlâ belirsiz?",observationPrompt:"Kaydın, hangi işi yaptığını veya hangi isteği ilettiğini gösteriyor?",adjustmentPrompt:"Sonraki işaret geldiğinde neyi koruyacak veya değiştireceksin?"}},goDeeper:{sections:[{heading:"Değerleri düşünmenin kanıtı belirli koşullara bağlı",paragraphs:["Epton ve arkadaşları, kişisel değerleri hatırlamanın sağlık bilgisiyle birlikte kullanıldığı testleri birleştirdi. Bilgiyi kabul etmede, niyetlerde ve davranışta küçük ortalama etkiler buldular. 144 test farklı sonuçları kapsar. Bunlar mutlaka 144 ayrı çalışma değildir. Katılımcı sayıları farklı sonuçlarda örtüşebilir. Bu sayıları birbirinden ayrı kişiler gibi toplayamayız. O koşullarda değerleri düşünmek, övgü tekrarlamaktan veya yorumu okumadan kendine mükemmel demekten farklıdır. Bulguyu bu iki yaklaşım için aynı kanıt gibi kullanma. (suggestion-S02)","Zhang ve arkadaşlarının daha yeni derlemesi, klinik olmayan gruplarda altmış yedi makale ve 129 bağımsız testte iyi oluş için küçük yararlar bildirdi. Erişilebilen üniversite özeti genel bir açıklama verir. Kesin etki ölçüsünü, toplam katılımcı sayısını, güven aralıklarını veya izlem sürelerini değerlendirmek için gereken tam yöntemler yoktur. Bu bulgu, bağlamı sağlık bilgisinin ötesine genişletir. Ama bugünkü kısa değer ve düzeltme alıştırmasının ya da belli bir olumlama metninin yararını göstermez. Özetin vermediği ayrıntıları varsayımla dolduramayız. (suggestion-S05)"]},{heading:"Değerini kullan, herkese aynı sonuç sözü verme",paragraphs:["Hanselman ve arkadaşlarının büyük ortaokul tekrar çalışmasında, yeni öğrenci grubunun hedeflenen not ortalamasına istatistiksel olarak anlamlı yarar bulunmadı. Bildirilen ölçüm kesinliği, en az 0,10 standart sapmalık yararları dışlayabiliyordu. Bu sonuç, bütün değer çalışmalarının yararsız olduğunu söylemez. Sağlık bilgisiyle ilgili bulguları da çürütmez. Koşulların, grubun ve ölçülen sonucun önemli olduğunu gösterir. Okuldaki bir sonuç, yetişkinlere güven veya genel performans artışı sözü veremez. Araştırmanın neyi ölçtüğünü korumamız gerekiyor. (suggestion-S12)","ODA’nın pratik sorusu daha dar: Önemsediğin bir değeri hatırlamak, aynı işinde ilgili bir yorumu kullanmana yardım ediyor mu? Kısa, isteğe bağlı not ve bu belirli düzeltme uyarlamadır. Öğrenmeyi, ailene karşı sorumluluğunu veya işe girmeyi aynı anda birkaç nedenle önemseyebilirsin. Niyetinin tamamen saf olduğunu kanıtlaman gerekmez. Yararlı yorumla hakareti veya güvenli olmayan talepleri ayır. Daha olumlu bir öz tanım yerine gerçek düzeltmeyi ya da yardım isteğini kaydet. Sonraki denemeyi o kayda göre seçebilirsin. Her yoruma katılmak veya kendine güvenini artırmak şart değil."]}],sourceIds:["suggestion-S02","suggestion-S05","suggestion-S12"]}},title:"Eleştiriyi kapatıp geçme. Bir ayrıntıyı düzelt.",goal:"Yorumlar işini durduruyorsa, seçtiğin bir değere uygun gerçek bir düzeltme yap.",minutes:6,reading:["Değerlerini düşünmek, kendini övmekten farklıdır. Bunu sağlık bilgisiyle birleştiren araştırmalar, bilgiyi kabul etmede ve sonraki davranışta küçük ortalama yararlar buldu. Kısa bir değer notunun tek başına her işi veya ruh hâlini iyileştirdiği kanıtlanmış değil.","Kaydında yorumdan kaçındığını görüyorsan bu adımı kullan. Aynı işi koru. Öğrenmek gibi önemsediğin bir değer, tek düzeltmeyi seçmene yardım edebilir. “Bu bilgiyi kontrol et” de. Sonra düzelt veya açıklama iste. Birden çok nedenin ve aileden gelen sorumlulukların olabilir. Kusursuz bir gerekçe, her yoruma katılmak veya daha çok güven hissetmek gerekmiyor."],example:{title:"Selin yoruma göre bir cümleyi düzeltiyor",text:"Öğle yemeği bitince Selin, başvuru cümlesinin belirsiz olduğunu söyleyen yorumu görüyor. Öğrenmek onun için önemli. Yine de belgeyi kapatmak istiyor. “Somut bir örnek ekle” diyor. Cümleye gerçekten yaptığı bir işi ekliyor. Taslağın tamamında hâlâ eksikler var. Değeri sayesinde yeni bir güven kazandığını söylemek yerine yaptığı düzeltmeyi kaydediyor. Yorumun hepsine katıldığını da varsaymıyor."},deeper:[{heading:"Değerleri düşünmenin kanıtı belirli koşullara bağlı",paragraphs:["Epton ve arkadaşları, kişisel değerleri hatırlamanın sağlık bilgisiyle birlikte kullanıldığı testleri birleştirdi. Bilgiyi kabul etmede, niyetlerde ve davranışta küçük ortalama etkiler buldular. 144 test farklı sonuçları kapsar. Bunlar mutlaka 144 ayrı çalışma değildir. Katılımcı sayıları farklı sonuçlarda örtüşebilir. Bu sayıları birbirinden ayrı kişiler gibi toplayamayız. O koşullarda değerleri düşünmek, övgü tekrarlamaktan veya yorumu okumadan kendine mükemmel demekten farklıdır. Bulguyu bu iki yaklaşım için aynı kanıt gibi kullanma. (suggestion-S02)","Zhang ve arkadaşlarının daha yeni derlemesi, klinik olmayan gruplarda altmış yedi makale ve 129 bağımsız testte iyi oluş için küçük yararlar bildirdi. Erişilebilen üniversite özeti genel bir açıklama verir. Kesin etki ölçüsünü, toplam katılımcı sayısını, güven aralıklarını veya izlem sürelerini değerlendirmek için gereken tam yöntemler yoktur. Bu bulgu, bağlamı sağlık bilgisinin ötesine genişletir. Ama bugünkü kısa değer ve düzeltme alıştırmasının ya da belli bir olumlama metninin yararını göstermez. Özetin vermediği ayrıntıları varsayımla dolduramayız. (suggestion-S05)"]},{heading:"Değerini kullan, herkese aynı sonuç sözü verme",paragraphs:["Hanselman ve arkadaşlarının büyük ortaokul tekrar çalışmasında, yeni öğrenci grubunun hedeflenen not ortalamasına istatistiksel olarak anlamlı yarar bulunmadı. Bildirilen ölçüm kesinliği, en az 0,10 standart sapmalık yararları dışlayabiliyordu. Bu sonuç, bütün değer çalışmalarının yararsız olduğunu söylemez. Sağlık bilgisiyle ilgili bulguları da çürütmez. Koşulların, grubun ve ölçülen sonucun önemli olduğunu gösterir. Okuldaki bir sonuç, yetişkinlere güven veya genel performans artışı sözü veremez. Araştırmanın neyi ölçtüğünü korumamız gerekiyor. (suggestion-S12)","ODA’nın pratik sorusu daha dar: Önemsediğin bir değeri hatırlamak, aynı işinde ilgili bir yorumu kullanmana yardım ediyor mu? Kısa, isteğe bağlı not ve bu belirli düzeltme uyarlamadır. Öğrenmeyi, ailene karşı sorumluluğunu veya işe girmeyi aynı anda birkaç nedenle önemseyebilirsin. Niyetinin tamamen saf olduğunu kanıtlaman gerekmez. Yararlı yorumla hakareti veya güvenli olmayan talepleri ayır. Daha olumlu bir öz tanım yerine gerçek düzeltmeyi ya da yardım isteğini kaydet. Sonraki denemeyi o kayda göre seçebilirsin. Her yoruma katılmak veya kendine güvenini artırmak şart değil."]}],sources:["suggestion-S02","suggestion-S05","suggestion-S12","suggestion-S20","suggestion-S07","suggestion-S08"],takeaway:"Önemsediğin bir değer, gerçekten yaptığın bir seçime yol gösterdiğinde işine yarar.",visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"İşaret",text:"Sana uyan bir fırsat seç."},{label:"Yap",text:"İşe yarayan en küçük adımı dene."},{label:"Dön",text:"Kaydet ve sonraki denemeyi seç."}]}},{id:"suggestion-4",practice:["Bu hafta sana zor gelecek bir an seç. Zamanını not et.","O andan önce iki dakika ayır. Durumu kendine anlatırken adını kullan.","Sonra aynı durumda arkadaşına söyleyeceğin destekleyici cümleyi kendine söyle."],reflection:"Kendine adınla seslendiğinde ses tonun nasıl değişti?",question:"Kross’un 2014 deneylerinde sosyal stres altında hangi konuşma biçimi daha yararlıydı?",options:["Kendine adınla veya “sen” diye seslenmek.","Yalnızca “ben” diyerek durumu uzun uzun düşünmek.","Sert eleştiriyle kendini motive etmek."],correct:0,feedback:"Kısa sosyal stres deneylerinde ad veya “ben” dışındaki ifadeler, gözlemci puanlarına göre daha iyi performans verdi. İkinci çalışmada önceki kaygı anlamlı azalmadı; sonrasında toparlanma daha açıktı. Tedavi değildir.",photo:{id:"1641907173006-6b8930ae1191",alt:"Düşüncelere dalıp gökyüzüne bakan bir kadın"},schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"suggestion-4",courseId:"suggestion",locale:"tr",title:"Heyecanlı mısın? Kendine kullanabileceğin bir söz söyle.",goal:"Kendine odaklanan kaygı katılmanı engelliyorsa, adınla düşünmeyi dene. Hazır cümleni gerçek konuşmada kullan.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Ne söyleyeceğini biliyor, yine heyecanını mı düşünüp duruyorsun? Kendine bir kez seslen, sonra sözünü söyle.",reason:{id:"suggestion-4-reason",label:"Kendini daha çok incelemek ne verir? Hangi fırsatı kaçırmana yol açabilir?",kind:"text",maxLength:160,optional:!0,suggestions:["Cümle düzelir; sorumu sorma fırsatını kaçırırım","Kısa rahatlama; hazır soruyu ertelerim","Soru belirsiz; hâlâ hazırlanmak gerekiyor","Daha önce kaçırdığım bir fırsat yok"]},why:{id:"suggestion-4-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kısa sosyal stres deneylerinde kişiler, “ben” yerine adlarını veya “sen” gibi ifadeleri kullanarak düşündü. Bir çalışmada, konuşma öncesi kaygı anlamlı ölçüde azalmadan, gözlemcilerin değerlendirdiği performans daha iyiydi. Bakışını değiştirmek, heyecanını silen bir komut değil.","Kendine odaklanan kaygı işini durdurduysa gerçekleri aynı tut. “Hazırım ve heyecanlıyım” yerine “Selin, hazırsın ve heyecanlısın” de. Kullanabileceğin bir yönerge ekle. Ardından cümleni güvenli bir konuşmada kullan. Önceki yönergen işe yarıyorsa koru. Adınla düşünmek isteğe bağlı hazırlıktır. Konuşmaya gerçekten katılmak ise denemedir. Konuşmaya katılmadan önce sakinleşmiş olman gerekmiyor."],example:{title:"Selin metni okuyana soruyor",text:"Selin’in başvurusu hakkında sorusu hazır. Ama öğle arasındaki notu, konuşurken nasıl bir izlenim bırakacağını düşünüp durduğunu gösteriyor. Güvenle katılabileceği görüşmeden önce “Selin, hazırsın ve heyecanlısın. Örneği sor” diyor. Sorusunu soruyor. Metni okuyanın yanıt için zamana ihtiyacı var. Selin gerçekten konuştuğunu ve yanıtın beklendiğini kaydediyor. Adıyla konuşmanın kaygıyı sildiğini söylemiyor. Yaptığı şey soruyu kullanmak, karşı tarafın yanıtını yönetmek değil."}},move:{invitation:"Gerçekte yapacağın işi koru. Öneriler metni okuyana sorabileceğin sorudan örnekler.",instructions:["Seçtiğin işi ve işareti koru. Böyle düşünmek isteğe bağlı hazırlıktır.","İlk konuşmanda gerçek soruyu ve güvenli fırsatı belirt.","Hazır cümlenle sor veya anlat. Her zamanki “ben” ifadeni de kullanabilirsin."],prompts:[],suggestions:{action:["Okuyana başvuruda hangi iş örneğinin gerektiğini sor","Başvuru cümlesini metni okuyacak kişiyle paylaş"],minimum:["Hangi iş örneğinin eksik olduğunu sor","Başvuru cümlesini yorum için gönder"],cue:["Metni okuyan kişi sorum olup olmadığını sorunca","Öğle yemeği bitince"],place:["Kararlaştırdığımız başvuru görüşmesinde","Metni okuyacak kişiyle mesajlaşırken"],minutes:[2,1,3],fallback:["Şimdi “Hangi iş örneği eksik?” diye sor","İş örneği sorusunu okuyana mesajla gönder"],observation:["İş örneği sorusunu gerçekten sorup sormadığım","Gelen yanıt veya henüz yanıt beklemem"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Okuyana başvuruda hangi iş örneğinin gerektiğini sor",minimum:"Hangi iş örneğinin eksik olduğunu sor",minutes:2,cueHint:"Metni okuyan kişi sorum olup olmadığını sorunca",placeHint:"Kararlaştırdığımız başvuru görüşmesinde",obstacleHint:"Hazır soruyu sormak yerine kendimi inceleyip duruyorum",fallbackHint:"Şimdi “Hangi iş örneği eksik?” diye sor",observationHint:"İş örneği sorusunu gerçekten sorup sormadığım"},stopRule:"Güvenli olmayan konuşmalara ara ver. Sıkıntı sürüyorsa veya günlük hayatın ciddi aksıyorsa uzman desteği al.",accessibleAlternative:"Güvenli bir yazılı mesaj, işaret dili veya iletişimini kolaylaştıran bir araç kullan. Adınla düşünmek isteğe bağlı."},result:{question:"Seçtiğin hazır cümleni gerçek konuşmada kullandın mı?",observationPrompt:"Gerçekte hangi işi yaptın? O fırsatta önünü hangi koşul kesti?"},judgment:{primary:{id:"suggestion-4-decision",scenario:"Selin’in başvuru için soracağı soru net. Kararlaştırılan görüşme bitmeden, metni okuyan soruyu şimdi sorabileceğini söylüyor. Selin heyecanlı. Az önce kısa süre düşünüp hazırlandı.",question:"Bu denemeye hangi adım daha iyi uyar?",options:[{id:"suggestion-4-name",text:"Sözcüklerini düzeltmek için kendi kendine bir kez daha prova etmek, sonra bir sonraki davette sormak.",feedback:"Bir prova cümleyi düzeltebilir. Ama soru zaten açık ve görüşme bitiyor. Bu güvenli fırsatı kullan. Adınla düşünmek isteğe bağlı. “Ben” diyerek gerçeklere dayanan yönerge kullanmak da uygun."},{id:"suggestion-4-analyze",text:"Katılıp katılmayacağına karar vermeden önce heyecanının nedenini kendi kendine daha ayrıntılı açıklamak.",feedback:"Ayrıntılı düşünmek, başka bir soruya yanıt bulmana yardımcı olabilir. Burada ise hazırlığı uzatır. Şu anki sorun, güvenli fırsat varken hazır cümleyi kullanmak. Önce kendini tamamen çözmen veya rahatlaman gerekmiyor."},{id:"suggestion-4-use",text:"“Selin, hazırsın ve heyecanlısın” cümlesini kullanmak, ardından gerçek sorusunu şimdi sormak.",feedback:"Bu seçim gerçekleri korur ve hazırlığı katılımla bitirir. Laboratuvar bulgusu önceden daha az kaygı sözü vermez. Gerçekte kullandığın cümleyi ve gelen yanıtı kaydet. Yanıt beklemek de ayrı bir gözlemdir."}],bestOptionId:"suggestion-4-use"}},carry:{takeaway:"Kendine ne yapacağını söyle. Sonra hazır cümleni kullan. Yeniden kendini incelemeye dönme.",followUp:{questionId:"suggestion-4-return",question:"Kendine söylediklerin hazır cümleni kullanmana yardım etti mi, yoksa hazırlığı mı uzattı?",observationPrompt:"Kaydın, hangi işi yaptığını veya hangi isteği ilettiğini gösteriyor?",adjustmentPrompt:"Sonraki işaret geldiğinde neyi koruyacak veya değiştireceksin?"}},goDeeper:{sections:[{heading:"Gerçekleri koruyarak bakışını değiştir",paragraphs:["Kross ve arkadaşları, çoğunlukla öğrencilerle ve başkalarının değerlendirdiği sosyal ortamlarda 585 kişiyle yedi deney yaptı. İkinci çalışmada kişiler, tanımadıkları biriyle görüşmeden önce yalnız başlarına üç dakika düşündü. Deney grubundaki yönerge kendi adlarını ve “ben” dışındaki ifadeleri kullandırıyordu. Karşılaştırmada “ben” ve “bana” kullanıldı. Adını kullanan grubun gözlemci puanlarına göre konuşma performansı daha iyiydi. Konuşma öncesi kaygı anlamlı ölçüde azalmadı. Sonrasında toparlanma bulgusu daha açıktı. Bu iki sonucu birbirine karıştırmamak gerekir. (suggestion-S03)","Doğru bir örnek aynı içeriği korur. “Hazırım ve heyecanlıyım; ilk bilgiyle başla” ile “Selin, hazırsın ve heyecanlısın; ilk bilgiyle başla” cümlelerini karşılaştır. Sert bir “ben” eleştirisini sıcak, adınla verilen tavsiyeyle karşılaştırırsan sözlerin sıcaklığını da değiştirmiş olursun. O zaman yalnızca bakış açısını ayıramazsın. ODA’nın kısa tavsiye ve gerçek cümle biçimi bir uyarlama. Araştırmadaki üç dakikalık uygulama değil. Sosyal kaygı tedavisi de değil. Konuşmadan önce aynı gerçekleri farklı biçimde ele almayı, ardından hazır sözü kullanmayı seçebilirsin."]},{heading:"Açık tavsiye için de gerçek bir fırsat gerekir",paragraphs:["Kısa deneyler kalıcı yararı, gerekli tek bir zamiri veya her koşulda üstünlüğü göstermez. Her zamanki “ben” diye düşünmek kendi başına zararlı değil. “Soruyu sorabilirim” demeyi, nötr yönergeyi veya hiç bu hazırlığı yapmamayı tercih edebilirsin. Kurs boyunca sürdürdüğün deneme, belirli bir dilbilgisi biçiminde kendinle konuşmak hakkında değil. Seçtiğin işe yarayan iş hakkında. Adını kullanmak ancak bu iş için denemek istediğin bir hazırlık seçeneği olarak kalsın. Her konuşmada uygulanması gereken bir kural değil. (suggestion-S03)","Sonraki işin gerçek görüşmeyse onu eylem olarak kaydet. Yalnızca cümleyi hazırladıysan, konuşmuş gibi yazmak yerine hazırlığı kaydet. Fırsat oluşmadığında bunu fırsat yoktu diye bildirebilirsin. Süren sıkıntı, ciddi günlük hayat aksaması veya kendine zarar verme düşünceleri uzman desteği gerektirir. Adınla düşünmek onun yerini tutmaz. Güvenli olmayan durumda kendini koru ve uygun yerel desteği kullan. Zamiri değiştirmek kötü muameleyi güvenli yapmaz. Bakım veya sağlık desteği ihtiyacını da kaldırmaz. Denemeyi bitirmeden önce yardım istemek için izin beklemen gerekmiyor. (suggestion-S20)"]}],sourceIds:["suggestion-S03","suggestion-S20"]}},title:"Heyecanlı mısın? Kendine kullanabileceğin bir söz söyle.",goal:"Kendine odaklanan kaygı katılmanı engelliyorsa, adınla düşünmeyi dene. Hazır cümleni gerçek konuşmada kullan.",minutes:6,reading:["Kısa sosyal stres deneylerinde kişiler, “ben” yerine adlarını veya “sen” gibi ifadeleri kullanarak düşündü. Bir çalışmada, konuşma öncesi kaygı anlamlı ölçüde azalmadan, gözlemcilerin değerlendirdiği performans daha iyiydi. Bakışını değiştirmek, heyecanını silen bir komut değil.","Kendine odaklanan kaygı işini durdurduysa gerçekleri aynı tut. “Hazırım ve heyecanlıyım” yerine “Selin, hazırsın ve heyecanlısın” de. Kullanabileceğin bir yönerge ekle. Ardından cümleni güvenli bir konuşmada kullan. Önceki yönergen işe yarıyorsa koru. Adınla düşünmek isteğe bağlı hazırlıktır. Konuşmaya gerçekten katılmak ise denemedir. Konuşmaya katılmadan önce sakinleşmiş olman gerekmiyor."],example:{title:"Selin metni okuyana soruyor",text:"Selin’in başvurusu hakkında sorusu hazır. Ama öğle arasındaki notu, konuşurken nasıl bir izlenim bırakacağını düşünüp durduğunu gösteriyor. Güvenle katılabileceği görüşmeden önce “Selin, hazırsın ve heyecanlısın. Örneği sor” diyor. Sorusunu soruyor. Metni okuyanın yanıt için zamana ihtiyacı var. Selin gerçekten konuştuğunu ve yanıtın beklendiğini kaydediyor. Adıyla konuşmanın kaygıyı sildiğini söylemiyor. Yaptığı şey soruyu kullanmak, karşı tarafın yanıtını yönetmek değil."},deeper:[{heading:"Gerçekleri koruyarak bakışını değiştir",paragraphs:["Kross ve arkadaşları, çoğunlukla öğrencilerle ve başkalarının değerlendirdiği sosyal ortamlarda 585 kişiyle yedi deney yaptı. İkinci çalışmada kişiler, tanımadıkları biriyle görüşmeden önce yalnız başlarına üç dakika düşündü. Deney grubundaki yönerge kendi adlarını ve “ben” dışındaki ifadeleri kullandırıyordu. Karşılaştırmada “ben” ve “bana” kullanıldı. Adını kullanan grubun gözlemci puanlarına göre konuşma performansı daha iyiydi. Konuşma öncesi kaygı anlamlı ölçüde azalmadı. Sonrasında toparlanma bulgusu daha açıktı. Bu iki sonucu birbirine karıştırmamak gerekir. (suggestion-S03)","Doğru bir örnek aynı içeriği korur. “Hazırım ve heyecanlıyım; ilk bilgiyle başla” ile “Selin, hazırsın ve heyecanlısın; ilk bilgiyle başla” cümlelerini karşılaştır. Sert bir “ben” eleştirisini sıcak, adınla verilen tavsiyeyle karşılaştırırsan sözlerin sıcaklığını da değiştirmiş olursun. O zaman yalnızca bakış açısını ayıramazsın. ODA’nın kısa tavsiye ve gerçek cümle biçimi bir uyarlama. Araştırmadaki üç dakikalık uygulama değil. Sosyal kaygı tedavisi de değil. Konuşmadan önce aynı gerçekleri farklı biçimde ele almayı, ardından hazır sözü kullanmayı seçebilirsin."]},{heading:"Açık tavsiye için de gerçek bir fırsat gerekir",paragraphs:["Kısa deneyler kalıcı yararı, gerekli tek bir zamiri veya her koşulda üstünlüğü göstermez. Her zamanki “ben” diye düşünmek kendi başına zararlı değil. “Soruyu sorabilirim” demeyi, nötr yönergeyi veya hiç bu hazırlığı yapmamayı tercih edebilirsin. Kurs boyunca sürdürdüğün deneme, belirli bir dilbilgisi biçiminde kendinle konuşmak hakkında değil. Seçtiğin işe yarayan iş hakkında. Adını kullanmak ancak bu iş için denemek istediğin bir hazırlık seçeneği olarak kalsın. Her konuşmada uygulanması gereken bir kural değil. (suggestion-S03)","Sonraki işin gerçek görüşmeyse onu eylem olarak kaydet. Yalnızca cümleyi hazırladıysan, konuşmuş gibi yazmak yerine hazırlığı kaydet. Fırsat oluşmadığında bunu fırsat yoktu diye bildirebilirsin. Süren sıkıntı, ciddi günlük hayat aksaması veya kendine zarar verme düşünceleri uzman desteği gerektirir. Adınla düşünmek onun yerini tutmaz. Güvenli olmayan durumda kendini koru ve uygun yerel desteği kullan. Zamiri değiştirmek kötü muameleyi güvenli yapmaz. Bakım veya sağlık desteği ihtiyacını da kaldırmaz. Denemeyi bitirmeden önce yardım istemek için izin beklemen gerekmiyor. (suggestion-S20)"]}],sources:["suggestion-S03","suggestion-S20"],takeaway:"Kendine ne yapacağını söyle. Sonra hazır cümleni kullan. Yeniden kendini incelemeye dönme.",visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"İşaret",text:"Sana uyan bir fırsat seç."},{label:"Yap",text:"İşe yarayan en küçük adımı dene."},{label:"Dön",text:"Kaydet ve sonraki denemeyi seç."}]}},{id:"suggestion-5",practice:["Bu hafta öğrenmesi veya iyi yapması zor gelen bir iş seç.","İş için bir yönerge ve bir motivasyon sözü yaz.","İşi yaparken işareti kısa, sakin sesle söyle. Sonucu yargılamadan not et."],reflection:"Hangi işaret dikkatini gerçekten işe çekti?",question:"Meta-analize göre yönerge veren sözler özellikle nerede işe yaradı?",options:["İnce beceri ve dikkat isteyen işlerde.","Yalnızca çok iyi öğrenilmiş, kendiliğinden yapılan işlerde.","Hiç alıştırma yapmadan yalnızca ilk denemede."],correct:0,feedback:"Spor çalışmalarında yönergeler çoğunlukla hassas hareketlere veya yeni görevlere uydu. Bazı çalışmalarda kontrol yoktu. Görev ve antrenman alt grupları evrensel sıralama, en iyi miktar veya eşdeğer masa başı yararı kanıtlamaz.",photo:{id:"1523497804259-88c4c134ca90",alt:"Pistte koşmaya hazırlanan sporcu"},schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"suggestion-5",courseId:"suggestion",locale:"tr",title:"Yine hata mı? Şimdi düzelteceğin ayrıntıyı söyle.",goal:"İşinde bir hata tekrarlanıyorsa, belirli bir yönergeyi gerçek bir kayıt üzerinde dene.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Yine hata yaptın, yine kendine etiket mi taktın? Sonraki denemede tek bir somut iş söyle.",reason:{id:"suggestion-5-reason",label:"Son hatandan sonra kendine ne dedin? Bu, düzeltmeni nasıl geciktirdi?",kind:"text",maxLength:160,optional:!0,suggestions:["“Dikkatsizim” dedim; tarihi değiştirmedim","“Bu taslak olmaz” dedim; kontrolü bıraktım","Kendime söylediklerim düzeltmemi geciktirmedi","Önceki hata yok; kendime yüklenebilirim"],help:"Önceki hata yoksa sıradaki düzeltmeni geciktirebilecek bir öz eleştiri cümlesi belirt."},why:{id:"suggestion-5-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sporda kendi kendine konuşma çalışmaları, farklı görevler ve antrenman biçimlerinde ortalama performans yararı buldu. Yapılacak işi söylemek bazen hassas hareketlere daha iyi uydu. Ama karşılaştırmalar, motive eden sözlere her durumda üstün olduğunu veya masa başında aynı etkiyi verdiğini göstermez.","İş kaydına bak. Tekrarlanan ayrıntı için neyi kontrol edeceğini belirt. “Tarihi kontrol et” gibi. Gerekiyorsa kolay bir örnekte dene, ardından asıl işindeki bir kayıt üzerinde uygula. İkisini ayrı kaydet. Hatayı nasıl düzelteceğini bilmiyorsan anlatılmasını iste. Daha çok motive olmak eksik bilgiyi vermez. Düzeltmenin kendisini de tamamlamaz."],example:{title:"Selin tarihi kontrol ediyor",text:"Selin’in başvuru taslağında iki tarih birbiriyle tutmuyor. Öğle yemeği bitince “Tarihi kontrol et” diyor. Hazırlık için kopyaladığı bir örnek üzerinde deniyor. Sonra taslağındaki gerçek bir tarihi kontrol edip düzeltiyor. İkinci uyuşmazlık duruyor. Gerçek düzeltmeyi kaydediyor, belirsiz kaydı nasıl kontrol edeceğini soruyor. Yönergenin bütün taslağı çözdüğünü iddia etmiyor. Örnekte denemekle asıl tarihi düzeltmek ayrı işler olarak kalıyor."}},move:{invitation:"Aynı kayıt üzerinde, aynı başlama işaretiyle çalışmayı sürdür. Öneriler başvurudaki bir tarih düzeltmesinden örnekler.",instructions:["Kayıtlı işi ve fırsatı koru. O işte gerçekten hangi kontrolü yapacağını söyle.","Örnekte “Tarihi kontrol et” de ve başvurudaki bir kaydı düzelt.","Nasıl yapılacağını bilmiyorsan “Bunu uyarla” seç. Belirli bir yönerge iste."],prompts:[],suggestions:{action:["“Tarihi kontrol et” de, bir başvuru kaydını düzelt","Başvurudaki bir tarihi asıl kayıtla karşılaştır"],minimum:["Başvuruda düzelttiğin bir tarihi kaydet","Başvuru tarihinin asıl kayıtla uyuşup uyuşmadığını kaydet"],cue:["Öğle yemeği bitince","Başvurunun tarihler kısmına gelince"],place:["Mutfak masamda","Başvuru taslağımda"],minutes:[3,2,1],fallback:["Tarihi nasıl doğrulayabileceğini metni okuyana sor","Tarihin yazılı olduğu asıl iş kaydını kontrol et"],observation:["Başvuruda düzelttiğim tarih veya nasıl düzelteceğimi sormam","Deneme örneğiyle gerçek işi ayrı tutmam"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"“Tarihi kontrol et” de, bir başvuru kaydını düzelt",minimum:"Başvuruda düzelttiğin bir tarihi kaydet",minutes:3,cueHint:"Öğle yemeği bitince",placeHint:"Mutfak masamda",obstacleHint:"Doğru tarihi nasıl doğrulayacağımı bilmiyorum",fallbackHint:"Tarihi nasıl doğrulayabileceğini metni okuyana sor",observationHint:"Başvuruda düzelttiğim tarih veya nasıl düzelteceğimi sormam"},stopRule:"Yönerge mi gerekiyor? “Bunu uyarla”, sonra “Destek” seç. Önemli sonuçları olan işlerde uygun uzman yardımı al.",accessibleAlternative:"Yazılı işaret veya sana uygun örnek kullan. Sesle yazdırabilir ya da yardım alabilirsin."},result:{question:"Gerçek bir kaydı düzelttin mi veya nasıl yapılacağını sordun mu?",observationPrompt:"Gerçekte hangi işi yaptın? O fırsatta önünü hangi koşul kesti?"},judgment:{primary:{id:"suggestion-5-decision",scenario:"Selin tarihi nasıl kontrol edeceğini biliyor. Ama bu adımı tekrar tekrar atlıyor. Başvurudaki gerçek bir kaydın düzeltilmesi gerekiyor.",question:"Bu denemeye hangi adım daha iyi uyar?",options:[{id:"suggestion-5-drive",text:"Hızını korumak için kalan kayıtları tamamlayana kadar kendine “Devam et” demek.",feedback:"İlerlemek önemli. Ama kayıt, atlanan bir kontrolü gösteriyor. Aynı hatayı diğer kayıtlara taşımak yerine o ayrıntıyı belirt ve gerçek bir kayıtta dene. Sonucu bütün işin bitmesiyle karıştırma."},{id:"suggestion-5-detail",text:"Gerçek bir kayıtta “Tarihi kontrol et” yönergesini kullanmak, ardından o tarihi düzeltmek.",feedback:"Yönerge, gördüğü soruna uyuyor ve tarihi düzeltmesini sağlıyor. Bu kişisel deneme, koşullara uyum hakkında bilgi verir. Yönergenin değişime neden olduğunu kanıtlamaz. Kaydına gerçekten düzelttiğin tarihi yaz."},{id:"suggestion-5-all",text:"Başvuru kaydına dönmeden önce tarihler, etiketler ve biçim için kısa bir kontrol listesi yazmak.",feedback:"Kısa liste birkaç eksiği önleyebilir. Ama bu kayıt atlanan tek tarih kontrolünü gösteriyor. Selin nasıl yapacağını biliyor. Önce gerçek kaydı düzelt. Başka kontrolleri, gördüğün ihtiyaca karşılık verdiklerinde ekle."}],bestOptionId:"suggestion-5-detail"}},carry:{takeaway:"Düzeltebileceğin bir sonraki somut ayrıntıyı düzelt. Gereken beceri eksikse nasıl yapılacağını birine sor.",followUp:{questionId:"suggestion-5-return",question:"Düzeltmede veya yönerge isteğinde ne oldu? Hangi ayrıntı hâlâ kontrol edilmeli?",observationPrompt:"Kaydın, hangi işi yaptığını veya hangi isteği ilettiğini gösteriyor?",adjustmentPrompt:"Sonraki işaret geldiğinde neyi koruyacak veya değiştireceksin?"}},goDeeper:{sections:[{heading:"Spordaki ortalama, masa başına söz vermez",paragraphs:["Hatzigeorgiadis ve arkadaşlarının meta-analizi otuz iki çalışmadan altmış iki etkiyi birleştirdi. Asıl tabloda 2.741 katılımcı vardı. Düzeltilmiş genel standartlaştırılmış performans farkı 0,48, güven aralığı 0,38 ile 0,58 arasındaydı. Öğrenciler ve sporcular dâhil, spor ve hareket işleri incelendi. Bazı çalışmalarda kontrollü karşılaştırma yoktu. Spordaki birleşik sonuç, başvuru taslağında ne olacağını söyleyemez. Senin için doğru kontrol yönergesini de seçemez. Bu sayıyı iş yerindeki kişisel artış beklentin olarak kullanmak araştırmanın kapsamını aşar. (suggestion-S04)","Alt grup tahminleri, ince ve kaba motor beceriler, yapılacak işi söyleyen ve motive eden sözler, ayrıca önceden antrenman yapma açısından farklıydı. Bunlar rastgele gruplarla karşılaştırılmış uygulama miktarları veya herkes için geçerli teknik sıralaması değil. Tabloda, başvuruda veya konuşmada 0,48 yarar olacağını öngörmez. Bugünkü tek yönerge ve tek gerçek kayıt denemesi, ODA’nın başka alana taşıdığı bir deneme. İyi bir sonuçtan sınırlı bir çıkarım yap: yalnızca o kayıtta ne olduğunu gösterir. Bu değişime neyin yol açtığını veya sonraki her denemede ne olacağını göstermez. Önceden hazırlanmakla gerçek işi tamamlamak da ayrı kalsın."]},{heading:"Yönerge, kullanabileceğin bir ayrıntıyı söylesin",paragraphs:["Yönerge, kaydındaki gerçek soruna karşılık vermeli. “Tarihi kontrol et” bir adımı söyler. “Mükemmel ol” bir kaydı nasıl düzelteceğini anlatmaz. Kolay bir örnekle denemek yönergeyi hazırlayabilir. Ama gerçek kaydı tamamlamak değildir. Yöntemi bilmiyorsan, nasıl yapılacağını somut biçimde sormak kendi başına işe yarayan bir davranıştır. Spor derlemesi Gallwey’nin bütün yaklaşımını, beyinde gerçek anlamda iki ayrı benlik olduğunu veya doğrulanmamış tarihsel bir metni onaylamaz. Bu açıklamaları araştırmanın bulduğu mekanizmalar gibi kullanamayız. (suggestion-S04)","Uymadığını gördüğünde yönergeyi değiştirebilir, işe yarayan denemeden sonra koruyabilir veya baskı ekliyorsa kendine bu sözleri söylemeyi bırakabilirsin. Sırf plan daha etkileyici görünsün diye bir sürü yeni talimat ekleme. ODA’nın kaydı, nerede takıldığını görmek içindir. Kişiliğine verilen not değil. Süren veya yoğun sıkıntıda daha güçlü tekrarlar yerine uzman desteği gerekir. Sonraki küçük adımı bilinen ihtiyaca göre seç. Bilgi istemek için önce birçok başarısız deneme biriktirmen gerekmez. Yardım isteğinin gönderilmesi de ayrı ve gerçek bir iştir. (suggestion-S20)"]}],sourceIds:["suggestion-S04","suggestion-S20"]}},title:"Yine hata mı? Şimdi düzelteceğin ayrıntıyı söyle.",goal:"İşinde bir hata tekrarlanıyorsa, belirli bir yönergeyi gerçek bir kayıt üzerinde dene.",minutes:6,reading:["Sporda kendi kendine konuşma çalışmaları, farklı görevler ve antrenman biçimlerinde ortalama performans yararı buldu. Yapılacak işi söylemek bazen hassas hareketlere daha iyi uydu. Ama karşılaştırmalar, motive eden sözlere her durumda üstün olduğunu veya masa başında aynı etkiyi verdiğini göstermez.","İş kaydına bak. Tekrarlanan ayrıntı için neyi kontrol edeceğini belirt. “Tarihi kontrol et” gibi. Gerekiyorsa kolay bir örnekte dene, ardından asıl işindeki bir kayıt üzerinde uygula. İkisini ayrı kaydet. Hatayı nasıl düzelteceğini bilmiyorsan anlatılmasını iste. Daha çok motive olmak eksik bilgiyi vermez. Düzeltmenin kendisini de tamamlamaz."],example:{title:"Selin tarihi kontrol ediyor",text:"Selin’in başvuru taslağında iki tarih birbiriyle tutmuyor. Öğle yemeği bitince “Tarihi kontrol et” diyor. Hazırlık için kopyaladığı bir örnek üzerinde deniyor. Sonra taslağındaki gerçek bir tarihi kontrol edip düzeltiyor. İkinci uyuşmazlık duruyor. Gerçek düzeltmeyi kaydediyor, belirsiz kaydı nasıl kontrol edeceğini soruyor. Yönergenin bütün taslağı çözdüğünü iddia etmiyor. Örnekte denemekle asıl tarihi düzeltmek ayrı işler olarak kalıyor."},deeper:[{heading:"Spordaki ortalama, masa başına söz vermez",paragraphs:["Hatzigeorgiadis ve arkadaşlarının meta-analizi otuz iki çalışmadan altmış iki etkiyi birleştirdi. Asıl tabloda 2.741 katılımcı vardı. Düzeltilmiş genel standartlaştırılmış performans farkı 0,48, güven aralığı 0,38 ile 0,58 arasındaydı. Öğrenciler ve sporcular dâhil, spor ve hareket işleri incelendi. Bazı çalışmalarda kontrollü karşılaştırma yoktu. Spordaki birleşik sonuç, başvuru taslağında ne olacağını söyleyemez. Senin için doğru kontrol yönergesini de seçemez. Bu sayıyı iş yerindeki kişisel artış beklentin olarak kullanmak araştırmanın kapsamını aşar. (suggestion-S04)","Alt grup tahminleri, ince ve kaba motor beceriler, yapılacak işi söyleyen ve motive eden sözler, ayrıca önceden antrenman yapma açısından farklıydı. Bunlar rastgele gruplarla karşılaştırılmış uygulama miktarları veya herkes için geçerli teknik sıralaması değil. Tabloda, başvuruda veya konuşmada 0,48 yarar olacağını öngörmez. Bugünkü tek yönerge ve tek gerçek kayıt denemesi, ODA’nın başka alana taşıdığı bir deneme. İyi bir sonuçtan sınırlı bir çıkarım yap: yalnızca o kayıtta ne olduğunu gösterir. Bu değişime neyin yol açtığını veya sonraki her denemede ne olacağını göstermez. Önceden hazırlanmakla gerçek işi tamamlamak da ayrı kalsın."]},{heading:"Yönerge, kullanabileceğin bir ayrıntıyı söylesin",paragraphs:["Yönerge, kaydındaki gerçek soruna karşılık vermeli. “Tarihi kontrol et” bir adımı söyler. “Mükemmel ol” bir kaydı nasıl düzelteceğini anlatmaz. Kolay bir örnekle denemek yönergeyi hazırlayabilir. Ama gerçek kaydı tamamlamak değildir. Yöntemi bilmiyorsan, nasıl yapılacağını somut biçimde sormak kendi başına işe yarayan bir davranıştır. Spor derlemesi Gallwey’nin bütün yaklaşımını, beyinde gerçek anlamda iki ayrı benlik olduğunu veya doğrulanmamış tarihsel bir metni onaylamaz. Bu açıklamaları araştırmanın bulduğu mekanizmalar gibi kullanamayız. (suggestion-S04)","Uymadığını gördüğünde yönergeyi değiştirebilir, işe yarayan denemeden sonra koruyabilir veya baskı ekliyorsa kendine bu sözleri söylemeyi bırakabilirsin. Sırf plan daha etkileyici görünsün diye bir sürü yeni talimat ekleme. ODA’nın kaydı, nerede takıldığını görmek içindir. Kişiliğine verilen not değil. Süren veya yoğun sıkıntıda daha güçlü tekrarlar yerine uzman desteği gerekir. Sonraki küçük adımı bilinen ihtiyaca göre seç. Bilgi istemek için önce birçok başarısız deneme biriktirmen gerekmez. Yardım isteğinin gönderilmesi de ayrı ve gerçek bir iştir. (suggestion-S20)"]}],sources:["suggestion-S04","suggestion-S20"],takeaway:"Düzeltebileceğin bir sonraki somut ayrıntıyı düzelt. Gereken beceri eksikse nasıl yapılacağını birine sor.",visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"İşaret",text:"Sana uyan bir fırsat seç."},{label:"Yap",text:"İşe yarayan en küçük adımı dene."},{label:"Dön",text:"Kaydet ve sonraki denemeyi seç."}]}},{id:"suggestion-6",practice:["Günün daha erken saatinde uyanıkken, istediğin sonucu ve gerçek bir engeli birlikte belirt.","Engel çıkarsa ne yapabileceğini ve asıl işindeki yararlı küçük adımı seç. İsteğe bağlı görüntü hazırlık olarak kalır.","Gerçek işaretini kaydet. Sonraki denemeyi ayrı yaz. Yatarken planlama uyanıklığı artırıyorsa bırak."],reflection:"Uyumadan önce kurduğun sahne, sabah sana neyi hatırlattı?",question:"Hangi hazırlık telkin iddialarını kanıtın sınırında tutar?",options:["Sonucu hayal etmek, gerçek engeli ve “şu olursa bunu yaparım” planını eklemek.","Bilinçaltının uykuda kendiliğinden para ve sağlık çekmesini beklemek.","Yalnızca iyi sonucu hayal edip hiç plan yapmamak."],correct:0,feedback:"İstediğin sonucu, önündeki engeli ve o engel çıkarsa ne yapacağını birlikte planlamanın farklı hedeflerde araştırma desteği var. Uykuluyken yapılan özel ritüeli veya yatakta hayalle ertesi sabah planını ayırmayı doğrulamaz. Uykuyu koru. Sonraki iş ayrıdır.",photo:{id:"1757796859729-270d1e3ad4d5",alt:"Yanan lambanın altında komodinde açık kitap"},schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"suggestion-6",courseId:"suggestion",locale:"tr",title:"Yatakta planı bırak. Dinlenmeye yer aç.",goal:"Yarınki engel belirsizse planı daha erken yap. Gerçek işi deneyeceğin zamanı ayrıca kaydet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yatarken kendini motive etmeye çalışmak seni uyanık mı tutuyor? Yarın ne zaman başlayacağını gündüz seç.",reason:{id:"suggestion-6-reason",label:"Neyi planlaman gerekiyor? Neye ara verip dinlenmeye ihtiyacın var?",kind:"text",maxLength:160,optional:!0,suggestions:["Öğle arası yoğun; gündüz başka bir zaman seç","Plan hazır; yatarken kontrolü bırak","Henüz gördüğüm bir planlama sorunu yok"]},why:{id:"suggestion-6-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Uyku, bellekteki bilgileri işlemeye yardım eder. Bu, bilinçaltına komut vermek için özel bir zaman olduğunu göstermez. İstediğin sonucu, önündeki engeli ve o engel çıkarsa ne yapacağını birlikte planlamanın farklı hedeflerde araştırma desteği var. Ama araştırma yatakta hayal kurup ertesi sabah plan yapmayı doğrulamaz.","Ele almadığın engel için daha erken, uyanıkken plan yap. İstediğin sonucu, engeli ve o engel çıkarsa ne yapabileceğini birlikte belirt. Asıl işinde aynı yararlı kısmı yapmayı sürdür. Planlama hazırlıktır. Sonraki denemeyi ayrıca kaydet. Yatarken düşünmek seni daha uyanık tutuyorsa bırak. Planın geçerli olması için görüntü kurmak, minnet duymak veya cümle tekrarlamak gerekmez. Dinlenme alıştırmadan önce gelir."],example:{title:"Selin yemekten önce plan yapıyor",text:"Saat 18.30. Selin yarın bir başvuru cümlesi yazmak istiyor. Kahvaltının yoğun geçeceğini düşünüyor. Öğle yemeği bitişini seçiyor. Masa doluysa cümleyi sesle yazdıracak. Bu not hazırlık. Ertesi gün masa dolu oluyor, Selin kullanabileceği bir cümleyi sesle yazdırıyor. Gerçek yazıyı kaydediyor. Yatma vakti geldiğinde planı kurcalamıyor. Notu yazmış olmakla sonraki cümleyi gerçekten yazdırmak ayrı kalıyor."}},move:{invitation:"Seçtiğin işi koru. Öneriler Selin’in gündüz yaptığı başvuru yazısından örnekler.",instructions:["Bir engel için değişiklik gerekmiyorsa kayıtlı işi, en küçük adımı ve işareti koru.","Uyanıkken sonucu, engeli ve engel çıkarsa ne yapacağını birlikte planla. Sonraki gerçek işi ayrı kaydet."],prompts:[],suggestions:{action:["Öğle yemeğinden sonra başvuruya deneyimini anlatan cümle yaz","Öğle yemeğinden sonra deneyimini anlatan cümleyi sesle yazdır"],minimum:["Başvuruya doğru bilgi içeren tek cümle yazıp kaydet","İş deneyimini anlatan, sesle yazdırdığın bir cümleyi kaydet"],cue:["Öğle yemeği bitince","Sabah içeceğimi içtikten sonra"],place:["Mutfak masamda","Başvuru taslağımda"],minutes:[2,1,3],fallback:["Öğle yemeğinde başvuru cümlesini sesle yazdır","Akşam yemeğinden sonra iş deneyimini anlatan cümleyi yaz"],observation:["Masanın uygun olması ve yedek adımı kullanmam","Hazırlığın ardından yazdığım gerçek başvuru cümlesi"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Öğle yemeğinden sonra başvuruya deneyimini anlatan cümle yaz",minimum:"Başvuruya doğru bilgi içeren tek cümle yazıp kaydet",minutes:2,cueHint:"Öğle yemeği bitince",placeHint:"Mutfak masamda",obstacleHint:"Mutfak masam başkası tarafından kullanılıyor",fallbackHint:"Öğle yemeğinde başvuru cümlesini sesle yazdır",observationHint:"Masanın uygun olması ve yedek adımı kullanmam"},stopRule:"Yatarken plan yapmak seni daha uyanık tutuyorsa bırak. Dinlenmeyi koru. Kaygıların sürüyorsa uygun yardım al.",accessibleAlternative:"Uyanıkken yazarak, konuşarak veya yardımla plan yap. Görüntü kurmak isteğe bağlı."},result:{question:"İşaret geldiğinde gerçek küçük işi yaptın mı?",observationPrompt:"Gerçekte hangi işi yaptın? O fırsatta önünü hangi koşul kesti?"},judgment:{primary:{id:"suggestion-6-decision",scenario:"Selin öğle için yazılı bir plan yaptı. Yatakta yarını hayal etmek, kaygıyla tekrar tekrar kontrol etmeye dönüşüyor. Daha uyanık hissediyor.",question:"Bu denemeye hangi adım daha iyi uyar?",options:[{id:"suggestion-6-finish",text:"Yarınki planın tamamen netleştiğini hissedene kadar yatakta engel incelemesini bitirmek.",feedback:"Her şeyi tamamlamak cazip. Ama uygulanabilir plan zaten yazıldı ve kontrol etmek onu daha uyanık tutuyor. Şimdi bırak. Ayrıntıların değişmesi gerekiyorsa daha erken bir zamanda, uyanıkken değerlendir. Yatakta bitirmen gerekmiyor."},{id:"suggestion-6-stop",text:"Görüntü kurmayı bırakmak, yazılı işareti olduğu gibi tutmak ve dinlenmeye dönmek.",feedback:"Bu seçim, yarının yapılabilir işinden vazgeçmeden dinlenmeyi korur. Uyku ve bellek bulguları gerekli bir yatma ritüeli göstermez. Sonraki gerçek denemenin kendi kaydı olur. Planı yeniden düşünerek geçerli hâle getirmen gerekmiyor."},{id:"suggestion-6-replace",text:"Görüntü yerine, kontrol isteği dinene kadar olumlu bir cümleyi tekrar tekrar söylemek.",feedback:"Başka bir ritüel aynı uyanık kalma çabasını sürdürebilir. Planın geçerli olması için tekrar gerekmiyor. İşareti olduğu gibi bırak ve şimdi planlamayı durdur. Yarının işini, gerçekten yaptıktan sonra kaydedebilirsin."}],bestOptionId:"suggestion-6-stop"}},carry:{takeaway:"Planını daha erken, uyanıkken yap. Dinlenmeyle sonrasında yaptığın gerçek işin kayıtlarını ayrı tut.",followUp:{questionId:"suggestion-6-return",question:"Engel çıkınca yapmayı seçtiğin şey, yatakta planlamayı uzatmadan asıl işi yapmana yardım etti mi?",observationPrompt:"Kaydın, hangi işi yaptığını veya hangi isteği ilettiğini gösteriyor?",adjustmentPrompt:"Sonraki işaret geldiğinde neyi koruyacak veya değiştireceksin?"}},goDeeper:{sections:[{heading:"Uyku bilimi bir ritüeli doğrulamaz",paragraphs:["Paller, Creery ve Schechtman’ın derlemesi, önceden öğrenilmiş bilginin uyku sırasında yeniden etkinleşmesini ve sınırlı, basit çağrışım öğrenmesini ele alır. Bu bir anlatı derlemesidir. Kişisel gelişim telkini için birleştirilmiş etki vermez. Bellek işlemleri, uyku öncesinde her şeyi sorgusuz alan bir bilinçaltı olduğunu göstermez. Olumlamanın uykuluyken üstün olduğunu veya karmaşık becerilerin tek cümleyle yüklendiğini de göstermez. Bunlar birbirinden farklı iddialardır. Uyku ve bellek bilgisini bir komut ritüelinin kanıtı gibi kullanamayız. (suggestion-S10)","Murphy’nin yayıncı özeti kitabın kökenini gösterir, inanç ve hayal gücünü tanıtır. Bu özet, Murphy’nin yatma ritüelinin işe yaradığını göstermez. Adı verilen bütün düzen için kontrollü kanıt sunmaz. Belirli tekrar metnini de doğrulayamaz. Planlama seni daha uyanık yapıyorsa gereken planı gündüz daha erken bir fırsata taşı. Yatma vaktini dinlenmeye bırak. Gündüz istersen gözünde canlandırmak yine bir ODA tercihi. Bir şeyi çekmenin, iyileşmenin veya özel yatma mekanizmasının kanıtı değil. Hiç görüntü kurmadan da işini planlayıp gerçek denemeyi ayrıca yapabilirsin. (suggestion-S16)"]},{heading:"Sonucu, engeli ve engel çıkarsa yapacağını birlikte düşün",paragraphs:["Wang ve arkadaşlarının zihinsel karşılaştırma ve “şu olursa bunu yaparım” planları meta-analizi, yirmi bir makaleden yirmi dört bağımsız etkiyi ve 15.907 katılımcıyı içeriyordu. Hedefe ulaşmada ortalama yarar bulundu. Yayın yanlılığı için düzeltme yapıldığında tahmin küçüldü. Hedefler, yöntemler ve karşılaştırmalar farklıydı. Sonuç, olumlu bir cümleyi işe yarayan tek parça olarak ayırmaz. ODA’nın parçaları birleştiren telkin kartını da doğrulamaz. Birleşik kurs düzenini bu araştırmada sınanmış gibi sunamayız. (suggestion-S06)","Bu karşılaştırmayı somut planlama sorusu için kullan: Hangi sonuç önemli, hangi engel çıkabilir, o engel çıkarsa ne yapabilirsin? Bu parçaları birlikte düşün. Sonra gerçek küçük işi başlama işaretiyle kaydet. Yarın hakkında not almak bugünkü hazırlık. Yarının işinin tamamlanması değil. Engeli aşmak için imkâna, güvenliğe veya yardıma ihtiyacın varsa inancını suçlamak yerine buna uygun bir adım seç. Planı daha erkene almak dinlenme fırsatını korur. Araştırma, yatarken hayal kurmayı ertesi sabahki plandan ayıran düzeni sınamadı. Planın hem ne zaman kullanılacağı hem de gerçekte ne çıktığı ayrı kalmalı."]}],sourceIds:["suggestion-S10","suggestion-S16","suggestion-S06"]}},title:"Yatakta planı bırak. Dinlenmeye yer aç.",goal:"Yarınki engel belirsizse planı daha erken yap. Gerçek işi deneyeceğin zamanı ayrıca kaydet.",minutes:6,reading:["Uyku, bellekteki bilgileri işlemeye yardım eder. Bu, bilinçaltına komut vermek için özel bir zaman olduğunu göstermez. İstediğin sonucu, önündeki engeli ve o engel çıkarsa ne yapacağını birlikte planlamanın farklı hedeflerde araştırma desteği var. Ama araştırma yatakta hayal kurup ertesi sabah plan yapmayı doğrulamaz.","Ele almadığın engel için daha erken, uyanıkken plan yap. İstediğin sonucu, engeli ve o engel çıkarsa ne yapabileceğini birlikte belirt. Asıl işinde aynı yararlı kısmı yapmayı sürdür. Planlama hazırlıktır. Sonraki denemeyi ayrıca kaydet. Yatarken düşünmek seni daha uyanık tutuyorsa bırak. Planın geçerli olması için görüntü kurmak, minnet duymak veya cümle tekrarlamak gerekmez. Dinlenme alıştırmadan önce gelir."],example:{title:"Selin yemekten önce plan yapıyor",text:"Saat 18.30. Selin yarın bir başvuru cümlesi yazmak istiyor. Kahvaltının yoğun geçeceğini düşünüyor. Öğle yemeği bitişini seçiyor. Masa doluysa cümleyi sesle yazdıracak. Bu not hazırlık. Ertesi gün masa dolu oluyor, Selin kullanabileceği bir cümleyi sesle yazdırıyor. Gerçek yazıyı kaydediyor. Yatma vakti geldiğinde planı kurcalamıyor. Notu yazmış olmakla sonraki cümleyi gerçekten yazdırmak ayrı kalıyor."},deeper:[{heading:"Uyku bilimi bir ritüeli doğrulamaz",paragraphs:["Paller, Creery ve Schechtman’ın derlemesi, önceden öğrenilmiş bilginin uyku sırasında yeniden etkinleşmesini ve sınırlı, basit çağrışım öğrenmesini ele alır. Bu bir anlatı derlemesidir. Kişisel gelişim telkini için birleştirilmiş etki vermez. Bellek işlemleri, uyku öncesinde her şeyi sorgusuz alan bir bilinçaltı olduğunu göstermez. Olumlamanın uykuluyken üstün olduğunu veya karmaşık becerilerin tek cümleyle yüklendiğini de göstermez. Bunlar birbirinden farklı iddialardır. Uyku ve bellek bilgisini bir komut ritüelinin kanıtı gibi kullanamayız. (suggestion-S10)","Murphy’nin yayıncı özeti kitabın kökenini gösterir, inanç ve hayal gücünü tanıtır. Bu özet, Murphy’nin yatma ritüelinin işe yaradığını göstermez. Adı verilen bütün düzen için kontrollü kanıt sunmaz. Belirli tekrar metnini de doğrulayamaz. Planlama seni daha uyanık yapıyorsa gereken planı gündüz daha erken bir fırsata taşı. Yatma vaktini dinlenmeye bırak. Gündüz istersen gözünde canlandırmak yine bir ODA tercihi. Bir şeyi çekmenin, iyileşmenin veya özel yatma mekanizmasının kanıtı değil. Hiç görüntü kurmadan da işini planlayıp gerçek denemeyi ayrıca yapabilirsin. (suggestion-S16)"]},{heading:"Sonucu, engeli ve engel çıkarsa yapacağını birlikte düşün",paragraphs:["Wang ve arkadaşlarının zihinsel karşılaştırma ve “şu olursa bunu yaparım” planları meta-analizi, yirmi bir makaleden yirmi dört bağımsız etkiyi ve 15.907 katılımcıyı içeriyordu. Hedefe ulaşmada ortalama yarar bulundu. Yayın yanlılığı için düzeltme yapıldığında tahmin küçüldü. Hedefler, yöntemler ve karşılaştırmalar farklıydı. Sonuç, olumlu bir cümleyi işe yarayan tek parça olarak ayırmaz. ODA’nın parçaları birleştiren telkin kartını da doğrulamaz. Birleşik kurs düzenini bu araştırmada sınanmış gibi sunamayız. (suggestion-S06)","Bu karşılaştırmayı somut planlama sorusu için kullan: Hangi sonuç önemli, hangi engel çıkabilir, o engel çıkarsa ne yapabilirsin? Bu parçaları birlikte düşün. Sonra gerçek küçük işi başlama işaretiyle kaydet. Yarın hakkında not almak bugünkü hazırlık. Yarının işinin tamamlanması değil. Engeli aşmak için imkâna, güvenliğe veya yardıma ihtiyacın varsa inancını suçlamak yerine buna uygun bir adım seç. Planı daha erkene almak dinlenme fırsatını korur. Araştırma, yatarken hayal kurmayı ertesi sabahki plandan ayıran düzeni sınamadı. Planın hem ne zaman kullanılacağı hem de gerçekte ne çıktığı ayrı kalmalı."]}],sources:["suggestion-S10","suggestion-S16","suggestion-S06","suggestion-S20"],takeaway:"Planını daha erken, uyanıkken yap. Dinlenmeyle sonrasında yaptığın gerçek işin kayıtlarını ayrı tut.",visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"İşaret",text:"Sana uyan bir fırsat seç."},{label:"Yap",text:"İşe yarayan en küçük adımı dene."},{label:"Dön",text:"Kaydet ve sonraki denemeyi seç."}]}},{id:"suggestion-7",practice:["Kart işe yarıyorsa inanılır yönergeyi ve isteğe bağlı ilk adımı gözünde nasıl canlandırdığını yaz. Kendine saklayabileceğin, sana uygun bir biçim kullan.","İşe başlama işaretini ve engel çıkarsa yapabileceğin şeyi ekle. Kart okumak işi yapmak değildir.","Değerlendirme tarihi seç. Gerçek denemeleri oluştuktan sonra hazırlıkla karşılaştır. Bir hafta, etkisi doğrulanmış bir uygulama süresi değil."],reflection:"Yedi günün ardından kartında neyi aynen korur, neyi değiştirirsin?",question:"Yedi gün sonra telkin kartını değerlendirirken hangisi daha işe yarar?",options:["Hiçbir şey değişmediyse kendini suçlamak.","Neyin işe yaradığına bakıp cümleyi, görüntüyü veya planı düzenlemek.","Daha iddialı cümleyi daha yüksek sesle söylemeye başlamak."],correct:1,feedback:"Gerçek iş denemelerini kart okumalarından ayrı değerlendir. Birleşik kart sınanmadı. Yararlı sözleri koru, gördüğün sorunu değiştir. Ayna, daha güçlü inanç veya yeni ritüel şart değil.",photo:{id:"1484480974693-6ca0a78fb36b",alt:"Deftere kontrol listesi yazan el"},schemaVersion:2,v2:{schemaVersion:2,revision:2,id:"suggestion-7",courseId:"suggestion",locale:"tr",title:"Kartı kaç kez okudun? Asıl hangi işi yaptın?",goal:"Aynı işin kayıtlarını bir araya getir. Sonraki uygulanabilir yönerge ve gerçek iş denemesini seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hatırlatmayı okudun, iş yine duruyor mu? Gerçekten yaptığın kısımlara bak veya ilk denemeni seç.",reason:{id:"suggestion-7-reason",label:"Kayıtlarına göre neyi koruyacak, değiştirecek veya bırakacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Öğle arası işe yaradı; o zamanı koru","Sabah yoğundu; başlama anını değiştir","Tekrar baskı yarattı; tekrarlamayı bırak","Deneme kaydı yok; ilk işi seç"]},why:{id:"suggestion-7-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İnandırıcı bir cümle, başlama işareti ve engel çıkarsa yapacağın şey aynı kartta yer alabilir. Ama bu kart bir bütün olarak doğrulanmış değil. Planlama araştırması, kart okumanın davranışa neden olduğunu göstermez.","İşini değerlendir veya ilk denemeni seç. Hatırlatmayı okumayı, hazırlığı, gerçek davranışı ve dönüşlerini ayır. Sana uyan sözleri ve işe yarayan işareti koru. Gördüğün tek sorunu değiştir. Aynı işi ve en küçük adımı sonraki fırsata kaydet. Sonraki tarihler, yaptığını bildirene kadar plan kalır. Sözler baskı ekliyorsa sadeleştir veya bırak. Ayna, yeni ritüel veya daha güçlü inanç gerekmiyor."],example:{title:"Selin gelecek haftaya bakıyor",text:"Pazar günü Selin beş hatırlatma okuması ve başvuruda işe yarayan üç küçük iş görüyor. Kaçırdığı iki başlangıç yoğun sabahındaydı. Öğle zamanı iki kez uydu. “İlk bilgiyi yaz” cümlesini koruyor, ek görüntü kurmayı bırakıyor, pazartesi öğle denemesini planlıyor. Pazartesi yazdığı cümlede hâlâ düzeltme gerekiyor. Yaptığını kaydediyor. Gelecek haftanın diğer tarihlerini ise yapılmış iş gibi değil, plan olarak tutuyor."}},move:{invitation:"Seçtiğin işi ve en küçük adımı koru. Öneriler başvuru için örnekler.",instructions:["Gerçek işi, en küçük adımı, işareti ve yeri koru. Yalnızca gördüğün sorunu değiştir.","Kaydın yoksa kaydetmeden önce ilk işini ve ona uyan en küçük adımı belirt.","Destek isteği için “Bunu uyarla” kullan. Sonraki tarihler plan olarak kalır."],prompts:[],suggestions:{action:["“Tarihi kontrol et” de, bir başvuru kaydını düzelt","Başvurudaki bir tarihi asıl kayıtla karşılaştır"],minimum:["Başvuruda düzelttiğin bir tarihi kaydet","Başvuru tarihinin asıl kayıtla uyuşup uyuşmadığını kaydet"],cue:["Öğle yemeği bitince","Başvurunun tarihler kısmına gelince"],place:["Mutfak masamda","Metni okuyacak kişiyle mesajlaşırken"],minutes:[2,1,3],fallback:["Okumayı bırak, başvurudaki bir tarihi doğrula","Metni okuyana tarihi hangi kaynaktan kontrol edeceğini sor"],observation:["Gerçek düzeltmelerim ve kart okumalarım ayrı","Öğle fırsatının ve yönergenin uygunluğu"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"“Tarihi kontrol et” de, bir başvuru kaydını düzelt",minimum:"Başvuruda düzelttiğin bir tarihi kaydet",minutes:2,cueHint:"Öğle yemeği bitince",placeHint:"Mutfak masamda",obstacleHint:"Başvuru tarihini kontrol etmek yerine kartı okuyup duruyorum",fallbackHint:"Okumayı bırak, başvurudaki bir tarihi doğrula",observationHint:"Gerçek düzeltmelerim ve kart okumalarım ayrı"},stopRule:"Bu işi yaparken yardım için “Bunu uyarla”, sonra “Destek” seç. Sıkıntı veren sözleri bırak. Süren sıkıntı veya günlük hayatta aksamada uzman desteği al. Önerilen tedavini sürdür.",accessibleAlternative:"Notunu kendine saklayabilir, nötr sözler kullanabilir veya yardım alabilirsin. Ayna şart değil."},result:{question:"Sonraki küçük işi veya seçtiğin destek adımını attın mı?",observationPrompt:"Gerçekte hangi işi yaptın? O fırsatta önünü hangi koşul kesti?"},judgment:{primary:{id:"suggestion-7-decision",scenario:"Selin kartını her gün okudu. Ama yalnızca bir kez, öğle arasında yazdı. Sabahları yoğundu. Yönerge hâlâ içine siniyordu.",question:"Bu denemeye hangi adım daha iyi uyar?",options:[{id:"suggestion-7-repeat",text:"Kartı her gün okumak rutinin yerleştiğini gösterdiği için sabah planını aynen korumak.",feedback:"Her gün okumak gerçek bir süreç kaydıdır. Ama seçtiğin yazı işi değildir. İşaret nadiren işe götürdü. Bunun yerine öğle fırsatını dene. Kartın okunmasıyla cümlenin yazılmasını ayrı tut."},{id:"suggestion-7-increase",text:"İnandırıcı cümleyi daha kolay hatırlamak için akşam bir kart okuması daha eklemek.",feedback:"Hatırlamak önemli olabilir. Ama eldeki kayıtlar yoğun sabahlara işaret ediyor. Daha çok okumak tekrarı değiştirir, işin zamanını aynı bırakır. Önce gördüğün zaman engelini değiştir. Yeni okumalar sorunu kendiliğinden çözmez."},{id:"suggestion-7-revise",text:"İnandırıcı cümleyi korumak, öğle zamanını kullanmak ve gerçek bir küçük yazı işi planlamak.",feedback:"Bu seçim, sana uyan kısmı korur. Başlamayı kaçırdığın zamanları dikkate alıp başlama işaretini değiştirir. Sonraki küçük iş, yaptığını bildirene kadar plan kalır. Yarın döndüğünde gerçek denemeye bakarak yeni fırsatın sana uyup uymadığını değerlendir."}],bestOptionId:"suggestion-7-revise"}},carry:{takeaway:"Sana yararlı sözleri, yapılabilir bir iş, dürüst kayıt ve sonraki seçimle birlikte sürdür.",followUp:{questionId:"suggestion-7-return",question:"Seçtiğin işte veya destek isteğinde ne oldu? Hangi koşulun değişmesi gerekiyor?",observationPrompt:"Kaydın, hangi işi yaptığını veya hangi isteği ilettiğini gösteriyor?",adjustmentPrompt:"Sonraki işaret geldiğinde neyi koruyacak veya değiştireceksin?"}},goDeeper:{sections:[{heading:"Kartın parçalarını birleştirmek bir tasarım tercihi",paragraphs:["Kurs; inandırıcı sözü, tek başlama işaretini, asıl işindeki küçük adımı, engel çıkarsa yapacağını ve sonraki değerlendirmeyi birleştirir. Bu bir ODA tasarımıdır. Kontrollü olarak sınanmış bir müdahale paketi değil. Wang ve arkadaşlarının derlemesi farklı hedeflerde zihinsel karşılaştırmayla “şu olursa bunu yaparım” planlarını destekler. Ama kartın her parçasının yardım ettiğini veya kart okumanın tamamlanan bir işe neden olduğunu göstermez. Araştırmada sınanan plan biçimiyle uygulamanın birleştirdiği düzeni ayrı tutmak gerekir. (suggestion-S06)","Kartı yeni zorunluluk olarak değil, kaydettiğin planın kısa hatırlatması olarak kullan. Hazırlığı işe yarayan küçük kısımdan ayrı değerlendir. Kart okumayı dürüstçe bildirebilirsin. Onu yazmak, sormak veya düzeltmek sayma. Gördüğün tek soruna odaklan ki sonraki deneme belirli bir soruyu yanıtlasın. Olumlu kişisel kayıt, koşulların uyumuna ilişkin geri bildirimdir. Neden-sonuç kanıtı veya aynı planın her hafta çalışacağına garanti değil. Sonraki tarihe plan koyduğunda, o günü yapılmış iş olarak kayda geçirme. Gerçek sonuç bildirildiğinde kendi adıyla yer alsın."]},{heading:"Kurs sonunda yeni ritüel gerekmiyor",paragraphs:["Lally’nin gözlemsel alışkanlık çalışması, tekrarlanan olaylarda yapılan yemek, içmek ve hareket etmek davranışlarını inceledi. Olumlu cümleleri sınamadı. Kendiliğinden yapma için kesin bir son tarih vermedi. ODA’nın gelecek hafta fırsatları ve değerlendirme aralığı, denemeyi düzenlemek için tercihlerdir. Sınanmış uygulama miktarı veya hiç kesilmeyen seri zorunluluğu değil. Gerçek işi denemek, öğrenmeyi bitirmekten ayrı kalır. Kursu tamamladığın için sonraki işin yapılmış olduğu veya bir alışkanlığın yerleştiği sonucunu çıkaramayız. (suggestion-S09)","Hay’in kendi sayfası, aynaya konuşulan olumlu cümleleri ve yirmi bir günlük programı anlatır. Kanıt taramasında adı verilen bütün düzen için kontrollü çalışma bulunmadı. Bu, hiç incelenmediğini kanıtlamaz. Burada aynayla söylemenin üstünlüğü gösterilmedi. Yirmi bir gün de alışkanlık için son tarih değil. Tercihine göre özel not, sana uygun hatırlatıcı veya hiç kart kullanmamak uygun olabilir. Sonunda aynı işe yarayan işi sürdür. Kayıtlarına göre değiştir. Güvenliği, dinlenmeyi ve önerilen tedavini koru. Aynayı veya yeni bir ritüeli son denemenin şartı hâline getirme. (suggestion-S18)"]}],sourceIds:["suggestion-S06","suggestion-S09","suggestion-S18"]}},title:"Kartı kaç kez okudun? Asıl hangi işi yaptın?",goal:"Aynı işin kayıtlarını bir araya getir. Sonraki uygulanabilir yönerge ve gerçek iş denemesini seç.",minutes:6,reading:["İnandırıcı bir cümle, başlama işareti ve engel çıkarsa yapacağın şey aynı kartta yer alabilir. Ama bu kart bir bütün olarak doğrulanmış değil. Planlama araştırması, kart okumanın davranışa neden olduğunu göstermez.","İşini değerlendir veya ilk denemeni seç. Hatırlatmayı okumayı, hazırlığı, gerçek davranışı ve dönüşlerini ayır. Sana uyan sözleri ve işe yarayan işareti koru. Gördüğün tek sorunu değiştir. Aynı işi ve en küçük adımı sonraki fırsata kaydet. Sonraki tarihler, yaptığını bildirene kadar plan kalır. Sözler baskı ekliyorsa sadeleştir veya bırak. Ayna, yeni ritüel veya daha güçlü inanç gerekmiyor."],example:{title:"Selin gelecek haftaya bakıyor",text:"Pazar günü Selin beş hatırlatma okuması ve başvuruda işe yarayan üç küçük iş görüyor. Kaçırdığı iki başlangıç yoğun sabahındaydı. Öğle zamanı iki kez uydu. “İlk bilgiyi yaz” cümlesini koruyor, ek görüntü kurmayı bırakıyor, pazartesi öğle denemesini planlıyor. Pazartesi yazdığı cümlede hâlâ düzeltme gerekiyor. Yaptığını kaydediyor. Gelecek haftanın diğer tarihlerini ise yapılmış iş gibi değil, plan olarak tutuyor."},deeper:[{heading:"Kartın parçalarını birleştirmek bir tasarım tercihi",paragraphs:["Kurs; inandırıcı sözü, tek başlama işaretini, asıl işindeki küçük adımı, engel çıkarsa yapacağını ve sonraki değerlendirmeyi birleştirir. Bu bir ODA tasarımıdır. Kontrollü olarak sınanmış bir müdahale paketi değil. Wang ve arkadaşlarının derlemesi farklı hedeflerde zihinsel karşılaştırmayla “şu olursa bunu yaparım” planlarını destekler. Ama kartın her parçasının yardım ettiğini veya kart okumanın tamamlanan bir işe neden olduğunu göstermez. Araştırmada sınanan plan biçimiyle uygulamanın birleştirdiği düzeni ayrı tutmak gerekir. (suggestion-S06)","Kartı yeni zorunluluk olarak değil, kaydettiğin planın kısa hatırlatması olarak kullan. Hazırlığı işe yarayan küçük kısımdan ayrı değerlendir. Kart okumayı dürüstçe bildirebilirsin. Onu yazmak, sormak veya düzeltmek sayma. Gördüğün tek soruna odaklan ki sonraki deneme belirli bir soruyu yanıtlasın. Olumlu kişisel kayıt, koşulların uyumuna ilişkin geri bildirimdir. Neden-sonuç kanıtı veya aynı planın her hafta çalışacağına garanti değil. Sonraki tarihe plan koyduğunda, o günü yapılmış iş olarak kayda geçirme. Gerçek sonuç bildirildiğinde kendi adıyla yer alsın."]},{heading:"Kurs sonunda yeni ritüel gerekmiyor",paragraphs:["Lally’nin gözlemsel alışkanlık çalışması, tekrarlanan olaylarda yapılan yemek, içmek ve hareket etmek davranışlarını inceledi. Olumlu cümleleri sınamadı. Kendiliğinden yapma için kesin bir son tarih vermedi. ODA’nın gelecek hafta fırsatları ve değerlendirme aralığı, denemeyi düzenlemek için tercihlerdir. Sınanmış uygulama miktarı veya hiç kesilmeyen seri zorunluluğu değil. Gerçek işi denemek, öğrenmeyi bitirmekten ayrı kalır. Kursu tamamladığın için sonraki işin yapılmış olduğu veya bir alışkanlığın yerleştiği sonucunu çıkaramayız. (suggestion-S09)","Hay’in kendi sayfası, aynaya konuşulan olumlu cümleleri ve yirmi bir günlük programı anlatır. Kanıt taramasında adı verilen bütün düzen için kontrollü çalışma bulunmadı. Bu, hiç incelenmediğini kanıtlamaz. Burada aynayla söylemenin üstünlüğü gösterilmedi. Yirmi bir gün de alışkanlık için son tarih değil. Tercihine göre özel not, sana uygun hatırlatıcı veya hiç kart kullanmamak uygun olabilir. Sonunda aynı işe yarayan işi sürdür. Kayıtlarına göre değiştir. Güvenliği, dinlenmeyi ve önerilen tedavini koru. Aynayı veya yeni bir ritüeli son denemenin şartı hâline getirme. (suggestion-S18)"]}],sources:["suggestion-S06","suggestion-S09","suggestion-S18","suggestion-S20"],takeaway:"Sana yararlı sözleri, yapılabilir bir iş, dürüst kayıt ve sonraki seçimle birlikte sürdür.",visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"İşaret",text:"Sana uyan bir fırsat seç."},{label:"Yap",text:"İşe yarayan en küçük adımı dene."},{label:"Dön",text:"Kaydet ve sonraki denemeyi seç."}]}}],lang:"tr"},Q=Object.freeze(Object.defineProperty({__proto__:null,COURSE:M,SOURCES:I},Symbol.toStringTag,{value:"Module"})),q=[{id:"T01",title:"Dai, Milkman & Riis · 2014 · The fresh-start effect",url:"https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf",type:"research",finding:"Üç arşiv veri kümesinde, takvimde yeni dönemleri işaretleyen günlerin çevresinde hedefe başlama arttı. Ölçüler diyet aramaları, üniversite spor salonu ziyaretleri ve taahhüt sözleşmeleriydi.",limitation:"Gözlemsel başlama ölçüleri neden-sonuç, sürdürülen değişim veya rastgele bir güne başlangıç demenin etkisini göstermez."},{id:"T02",title:"Dai, Milkman & Riis · 2015 · Temporal landmarks and goal initiation",url:"https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf",type:"research",finding:"İnternetten katılan 165 yetişkinin %25,61’i, 20 Mart baharın başlangıcı olarak sunulunca o güne hatırlatma seçti. Tarih üçüncü perşembe olarak sunulunca oran %7,23’tü.",limitation:"Karşılaştırma, gerçek davranışı veya kalıcı değişimi değil hatırlatma seçimini ölçtü. Kendi başlangıç gününü ilan etmek ODA uyarlamasıdır."},{id:"T03",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 kişinin katıldığı 94 bağımsız testte, belirli “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı: d = 0,65, %95 güven aralığı [0,60; 0,70].",limitation:"Farklı ortamlar ve eski yöntemler genellemeyi sınırlar. Etki başarıda %65 artış değildir. ODA’nın bu kısa planı sınanmadı."},{id:"T04",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"15.907 kişinin katıldığı, 24 etki içeren 21 makalenin meta-analizinde hedefe ulaşmada küçük bir ortalama yarar bulundu: g = 0,336, %95 güven aralığı [0,229; 0,443].",limitation:"Sonuçlar farklıydı, yayın yanlılığı olasıydı. Katılımcı toplamında iki büyük çevrim içi örneklem baskın. Hayal etmek sonuçları çekmez. ODA alıştırması sınanmadı."},{id:"T05",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"19.951 kişinin katıldığı 138 rastgele kontrollü çalışmada ilerlemeyi izleme uygulamaları hedefe ulaşmayı ortalama olarak artırdı: d = 0,40, %95 güven aralığı [0,32; 0,48].",limitation:"Hedefler ve yöntemler farklıydı. Ek analizlerde fiziksel kayıt ve bildirim daha büyük etkilerle ilişkiliydi. Herkese açık paylaşım gerekmez. ODA’nın bu kayıt biçimi sınanmadı."},{id:"T06",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"84 günlük gözlemsel çalışma 96 gönüllüyü izledi. Verilere iyi uyan 39 eğride, otomatikliğin her kişideki üst sınırının %95’ine ulaşma süresi 18–254 gün olarak tahmin edildi. Ortanca 66 gündü.",limitation:"Bunlar model tahminleriydi, gözlenmiş bitiş tarihleri değil. Kişinin bildirdiği gündelik sağlık davranışları, herkese uyan süreyi veya iki fırsat kaçırma eşiğini göstermez."},{id:"T07",title:"Singh et al. · 2024 · Time to form a habit",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"2.601 kişinin katıldığı 20 sağlık davranışı çalışmasının derlemesinde, oluşma süresi tahminleri çok farklıydı. Yalnızca dört çalışma süre tahmini verdi. Bireysel tahminler 4 ile 335 gün arasındaydı.",limitation:"On bir çalışmada yanlılık riski yüksekti. Süre tanımları farklıydı. Öncesi ve sonrası arasındaki alışkanlık gücü farkı, kontrollü tedavi etkisi veya kişisel son tarih değildir."},{id:"T08",title:"Wood & Rünger · 2016 · Psychology of habit",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Derleme, benzer ortamlarda tekrarladığımız davranışları zamanla o ortamdaki işaretlerle yapmaya başlayabildiğimizi anlatır. Bilinçli hedefler ile alışkanlıklar birlikte işleyebilir.",limitation:"Farklı araştırmaları birleştiren anlatı derlemesidir. Yeni bir deney sunmaz, tek bir ortak etki büyüklüğü hesaplamaz. Nesnelerin yerinin isteği gereksiz kıldığını veya her karmaşık hedefin otomatikleştiğini göstermez."},{id:"T09",title:"Bandura · 1977 · Self-efficacy theory",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Bandura’nın kuramı; kendi başardıklarını, başkalarını izlemeyi, cesaretlendirilmeyi ve bedensel durumları belirli bir davranışı yapma beklentisinin kaynakları olarak tanımlar. Kişinin kendi başardığı işlere özellikle önem verir.",limitation:"Önceki araştırmaları birleştiren kuramdır, yeni deney değildir. Her küçük işin özgüveni artırdığını veya genel yeteneği kanıtladığını göstermez."},{id:"T11",title:"Scullin et al. · 2018 · Bedtime task-list writing",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/",type:"research",finding:"Bir laboratuvar gecesinde, 18–30 yaşındaki 57 sağlıklı yetişkin beş dakika kâğıda gelecek işleri veya tamamlanan işleri yazdı. Ortalama uykuya dalma süresi 15,82 ve 25,09 dakikaydı.",limitation:"Karşılaştırma başka bir yazma işiydi. Toplam uykuda istatistiksel olarak anlamlı artış veya uzun süreli uykusuzluk yararı gösterilmedi. Sözlü telkinler ve ODA’nın kısa değerlendirmesi sınanmadı."},{id:"T12",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and exam procrastination",url:"https://doi.org/10.1016/j.paid.2010.01.029",type:"research",finding:"119 birinci sınıf öğrencisinde, bir ara sınav öncesindeki erteleme için daha fazla kendini affetmek, sonraki sınav öncesinde daha az ertelemeyle ilişkiliydi.",limitation:"Tek bir dersteki gözlemsel ölçümler neden-sonuç göstermez. Özet bir etki katsayısını veya hazır cümlenin yararını doğrulamaz."},{id:"T15",title:"Oettingen et al. · 2015 · Mental contrasting and time management",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"İlk çalışmada 84 Alman lisans öğrencisi rastgele gruplara ayrıldı. Birleşik alıştırma grubu iki kontrol grubundan daha çok saat planladı. Önceden planlanan karşılaştırma istatistiksel olarak anlamlıydı. Genel koşul testinde p = 0,057 bulundu.",limitation:"Planlanan saatler niyet ölçüsüydü. Çalışılan saat veya biten proje değildi. Çalışma, ODA’nın kısa adımını ve ertesi gün değerlendirmesini doğrulamaz."},{id:"T17",title:"James Clear · The two-minute rule",url:"https://jamesclear.com/how-to-stop-procrastinating",type:"technique",finding:"Clear, yeni bir davranışa başlarken yapılacak kısa bir iş seçmeyi önerir. Bu, başlaması kolay bir adım seçmek için uygulamaya dönük bir öneridir.",limitation:"Tam iki dakikanın en iyi süre olduğu kontrollü araştırmayla gösterilmedi. Hazırlık ile hedeflenen davranışın işe yarayan bir parçasını tamamlamak aynı şey değildir."},{id:"bandura-self-efficacy",title:"Bandura · 1977 · Self-efficacy theory",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Bandura’nın kuramı; kendi başardıklarını, başkalarını izlemeyi, cesaretlendirilmeyi ve bedensel durumları belirli bir davranışı yapma beklentisinin kaynakları olarak tanımlar. Kişinin kendi başardığı işlere özellikle önem verir.",limitation:"Önceki araştırmaları birleştiren kuramdır, yeni deney değildir. Her küçük işin özgüveni artırdığını veya genel yeteneği kanıtladığını göstermez."},{id:"habits",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"84 günlük gözlemsel çalışma 96 gönüllüyü izledi. Verilere iyi uyan 39 eğride, otomatikliğin her kişideki üst sınırının %95’ine ulaşma süresi 18–254 gün olarak tahmin edildi. Ortanca 66 gündü.",limitation:"Bunlar model tahminleriydi, gözlenmiş bitiş tarihleri değil. Kişinin bildirdiği gündelik sağlık davranışları, herkese uyan süreyi veya iki fırsat kaçırma eşiğini göstermez."},{id:"oettingen-woop-method",title:"Gabriele Oettingen · WOOP",url:"https://woopmylife.org/en/home",type:"technique",finding:"WOOP; bir isteği, arzulanan sonucu, iç engeli ve “şu olursa bunu yaparım” planını birleştirir. İlgili araştırmalar planlamayı ortalama olarak destekler, sonuçlar değişir.",limitation:"Geliştiricinin sitesi bağımsız değerlendirme değildir. MCII bulguları yöntemin her biçimini doğrulamaz. Dış koşulları düşünce biçiminin kusuru hâline getirmez."}],o=[{schemaVersion:2,revision:2,id:"turning-day-1",courseId:"turning-day",locale:"tr",title:"Pazartesiyi bekleme. Bugün küçük bir başlangıç yap",goal:"Seçtiğin yolda işe yarayan küçük bir adım at. Ardından bir sonraki deneme zamanını belirle.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hangi isteğini hep gelecek pazartesiye bırakıyorsun? Bugün ona yer aç.",reason:{id:"turning-day-1-reason",label:"İki dakikanı neye ayırmak istersin, ne biraz daha bekleyebilir?",kind:"text",maxLength:160,optional:!0,suggestions:["Yaratıcılığıma zaman ayırmak","Hafta geçmeden küçük bir deneme yapmak","Önem verdiğim bir şeye zaman ayırmak"]},why:{id:"turning-day-1-why",label:"İki dakikanı neye ayırmak istersin, ne biraz daha bekleyebilir?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir tarihe nasıl baktığın, başlama kararını etkileyebilir. Bu, devam edeceğini göstermez. Bir deneyde aynı mart günü “baharın başlangıcı” diye sunulduğunda daha çok kişi o gün için hatırlatma seçti. Araştırma, bu hatırlatmalardan sonra kimlerin gerçekten bir adım attığını göstermedi. Hatırlatma seçmek ile işe başlamak ayrı şeyler.","Şimdi bu fırsatı kendi seçtiğin yolda küçük bir şey yapmak için kullan. Bir nesne çiz, işe yarayan bir cümle yaz veya ihtiyacın olan paragrafı oku. Tarih belirlemek hazırlıktır. Seçtiğin işi yap, ne yaptığını kaydet ve sıradaki başlangıç anını seç. Kurs boyunca aynı denemeyi sürdüreceğiz."],example:{title:"Derya ilk çizimini yapıyor",text:"Derya çizim yapmak için hep pazartesiyi bekliyor. Çarşamba günü mutfak masasında çayını bitirince iki dakika fincanını çiziyor. Kulp biraz yamuk oluyor. Bir çizim yaptığını kaydedip sıradaki deneme için yarınki çayını seçiyor. Çarşambaya “başlangıç” demek seçim yapmasını kolaylaştırdı. Çizim becerisini artırmadı. Elinde kusursuz bir sonuç yok, yaptığı küçük çizim var."}},move:{invitation:"Çizmek, yazmak veya okumak sana bir şey katacaksa bu örneklerden birini seç.",instructions:["Boş planı doldurmadan önce örneğin istediğin yola uyup uymadığını kontrol et.","Seçtiğin adımı dene, sonra buraya dönüp ne yaptığını kaydet."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Bir sonraki çayımı bitirince","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Daha küçük bir nesne veya uygun araçlar kullan","Yazmak zorsa bir cümleyi sesle yazdır","Bana uygun metni kullan veya sesli oku"],observation:["Tamamladığım küçük çizim","Yazdığım işe yarayan cümle","Okuyup bitirdiğim paragraf"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Bir sonraki çayımı bitirince",place:"Evde, mutfak masamın başında",fallback:"Daha küçük bir nesne veya uygun araçlar kullan",observation:"Tamamladığım küçük çizim",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Sonraki öğünümü bitirince",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Yazmak zorsa bir cümleyi sesle yazdır",observation:"Yazdığım işe yarayan cümle",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Bana uygun metni kullan veya sesli oku",observation:"Okuyup bitirdiğim paragraf",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Bir sonraki çayımı bitirince",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Kullanabildiğim zaman veya araçlar değişiyor",fallbackHint:"Daha küçük bir nesne veya uygun araçlar kullan",observationHint:"Tamamladığım küçük çizim",requiresChoice:!0},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Güvenli bir iş seç. Sağlık, bakım sorumlulukları veya erişim ihtiyaçları önce geliyorsa adımı değiştir ya da ara ver."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-1-decision",scenario:"Derya mutfak masasında. İki boş dakikası ve kâğıdı var. Çizim yapmak istiyor ama genellikle başlamak için pazartesiyi bekliyor.",question:"Bu durumda hangi adım ona daha uygun?",options:[{id:"draw-now",text:"Hemen yakındaki fincanı çiz, yaptığın çizimi kaydet ve yarın için uygun bir deneme zamanı seç.",feedback:"Bu adım, elindeki fırsatı gerçekten çizim yapmak için kullanıyor. Çizim kabataslak olabilir. Tamamladığın küçük işi kaydet. Sonra aynı denemeyi sürdürmek için bir sonraki başlangıç anını belirle."},{id:"schedule-course",text:"Bu iki dakikayı gelecek hafta başlayabileceğin kapsamlı bir çizim kursunun zamanını ayarlamak için kullan.",feedback:"Bir kurs ileride işe yarayabilir. Ama Derya şu anda bir çizim için yeterli zamana ve malzemeye sahip. Zaman ayarlamak plan yapmak olur. Çizmek ise bugün istediği yönde bir denemedir."},{id:"choose-supplies",text:"Yeni başlayanlara uygun çizim malzemelerini karşılaştır, sonra hangi nesneyi çizmenin daha kolay olacağına karar ver.",feedback:"Malzeme eksikse uygun araç seçmek gerekir. Derya’nın ise kâğıdı ve çizebileceği bir nesne var. Daha fazla seçim yapmak, bu fırsatı çizim denemesi yapmadan tüketir."}],bestOptionId:"draw-now"}},carry:{takeaway:"Küçük bir iş yaptığında, başlangıcının somut bir karşılığı olur.",followUp:{questionId:"turning-day-1-return",question:"Seçtiğin başlangıç anı geldiğinde işe yarayan küçük adımını gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"Hatırlatma seçmek, bir işi denemek değildir",paragraphs:["Dai, Milkman ve Riis, 2014’te üç arşiv veri kümesiyle yeni başlangıçları inceledi [T01]. Takvimde yeni bir dönemi işaretleyen bazı günlerin çevresinde diyet aramaları, üniversite spor salonu ziyaretleri ve yeni taahhüt sözleşmeleri arttı. Bunlar birbirinden farklı başlama ölçüleridir. Takvimdeki o günün değişime neden olduğunu veya insanların hedeflerini uzun süre sürdürdüğünü göstermez.","Daha sonraki bir deneyde, internet üzerinden katılan 165 yetişkin hedefleri için hatırlatma tarihleri arasından seçim yaptı [T02]. 20 Mart “baharın başlangıcı” diye sunulunca %25,61’i o tarihte hatırlatma istedi. Aynı tarih “ayın üçüncü perşembesi” diye sunulunca bu oran %7,23 oldu. Burada ölçülen şey hatırlatma seçmekti. Sonrasında kimin gerçekten bir şey yaptığını bu karşılaştırmadan bilmiyoruz.","Bugüne “benim başlangıcım” demek, ODA’nın sunduğu isteğe bağlı bir bakış açısıdır. Rastgele bir güne bu adı vermenin araştırmadaki sonuçları tekrarlayacağını söylemiyoruz. Senin kaydın, bugüne verdiğin addan değil, gerçekten yaptığın işten başlar."]},{heading:"Ne zaman, nerede, ne yapacağını belirle",paragraphs:["“Şu olursa bunu yapacağım” planı, tanıyabileceğin bir durumla önceden seçtiğin bir davranışı birleştirir. Gollwitzer ve Sheeran, 8.461 kişinin katıldığı 94 bağımsız testi bir araya getirdi [T03]. Bu planlar, incelenen ortamlarda hedefe ulaşmayı ortalama olarak artırdı. İşler, katılan kişiler ve araştırma yöntemleri farklıydı. Bu yüzden ortalama sonuç senin sonucunu önceden söylemez. Bu kısa ODA dersi o derlemede sınanmadı.","Bu deneme için istediğin yola katkısı olan küçük bir iş seç. “Mutfak masasında çayımı bitirince bir nesne çizeceğim” cümlesi başlangıç anını, yeri ve işi anlatır. Kâğıdı ortaya koymak hazırlıktır. Nesneyi çizmek çizim denemesidir. İkisi de gerekli olabilir. Kaydına hangisini gerçekten yaptığını yaz.","Seçtiğin yol bakım sorumluluklarını üstlenmek, toparlanmak, yakınlık kurmak veya öğrenmek için olabilir. Bulunduğun yer güvenli bir adıma uygun değilse daha sonra uygun bir zaman seç ya da destek al. Takvimde bir güne yeni bir ad vermek, önündeki gerçek engeli ortadan kaldırmaz."]}],sourceIds:["T01","T02","T03"]}},{schemaVersion:2,revision:2,id:"turning-day-2",courseId:"turning-day",locale:"tr",title:"Planın eve gelince dağılıyor mu? O ana hazırlan",goal:"Sürdürdüğün denemede önüne çıkabilecek tek bir engel için yapabileceğin bir adım seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kâğıt üzerinde iyi görünen planın, günün hangi anında gerçek hayatına uymuyor?",reason:{id:"turning-day-2-reason",label:"Son denemeni ne durdurdu, bunun hangi kısmını değiştirebilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Seçtiğim an geldiğinde hâlâ işteydim","Vardiyadan sonra dinlenmem gerekiyordu","Gereken araca ulaşamadım"]},why:{id:"turning-day-2-why",label:"Son denemeni ne durdurdu, bunun hangi kısmını değiştirebilirsin?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İşe yarayan küçük adımını koru. Önünü ne kesebilir, ona bak. Başa çıkabileceğin bir duygu veya tepki başka, çocuğa bakacak birinin, gerekli malzemenin ya da güvenli bir yerin olmaması başka. Gücünün yetmemesi de gerçek bir engel olabilir. Her engeli kendi içinde çözmen gereken bir sorun sayma. Plan hayatına uymuyorsa onu değiştir. Gerçek koşulları plana kat.","Bir engelle veya fırsatla karşılaştığında ne yapacağını seç: “İşten gelip montumu çıkarınca masada bir nesne çizeceğim.” Araştırmalar, böyle belirli planları ortalama olarak destekliyor. Sonuçlar değişiyor. Planı yazmak hazırlıktır. Seçtiğin işi o anda dene. Sonra bunu yapmanın mümkün olup olmadığını ve yapıp yapmadığını kaydet."],example:{title:"Derya için saat değil, eve dönüş",text:"Derya’nın vardiyaları farklı saatlerde bitiyor. Bu yüzden çizim planındaki 18.00 çoğu gün uymuyor. Başlangıç anını, eve gelip montunu çıkarmak olarak değiştiriyor. Diziyi açmadan önce mutfak masasında anahtarlarını çiziyor. Kabaca da olsa bir çizimi tamamlıyor. Ertesi gün vardiyası geç bitiyor ve bu kez dinlenmeye ihtiyaç duyuyor. O gün de koşullarına bakıyor."}},move:{invitation:"Kaydettiğin işi ve en küçük adımı koru. Gördüğün bir engele veya fırsata göre planını değiştir.",instructions:["Sana uyan başlama anını koru. Karşılaştığın engele göre “Engelle karşılaşınca” alanını değiştir.","Henüz denemediysen aynı iş için sana uygun bir başlangıç anı seç."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["İşten gelip montumu çıkardığım anda","Önceden ayırdığım mola başladığında","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Dinlen; yarın öğleden sonraki molada tekrar dene","Dinlen; yarın işte uygun olan molada dene","Dinlen; yarın yemeğini yedikten sonra okumayı dene"],observation:["Seçtiğim an geldi mi, çizimi yaptım mı?","Seçtiğim an geldi mi, cümleyi yazdım mı?","Seçtiğim an geldi mi, paragrafı okudum mu?"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"İşten gelip montumu çıkardığım anda",place:"Evde, mutfak masamın başında",fallback:"Dinlen; yarın öğleden sonraki molada tekrar dene",observation:"Seçtiğim an geldi mi, çizimi yaptım mı?",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Önceden ayırdığım mola başladığında",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Dinlen; yarın işte uygun olan molada dene",observation:"Seçtiğim an geldi mi, cümleyi yazdım mı?",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Dinlen; yarın yemeğini yedikten sonra okumayı dene",observation:"Seçtiğim an geldi mi, paragrafı okudum mu?",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"İşten gelip montumu çıkardığım anda",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Vardiya bittikten sonra dinlenip toparlanmaya ihtiyacım var",fallbackHint:"Dinlen; yarın öğleden sonraki molada tekrar dene",observationHint:"Seçtiğim an geldi mi, çizimi yaptım mı?"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Bitkinken, tehlike varken veya gereken şeylere erişemiyorken kendini zorlama. Dinlenmeyi, desteği ya da başka bir fırsatı seç."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-2-workday-cue-decision",scenario:"Derya normal iş günlerinde kısa çizimler yapmak istiyor. Vardiyalar değiştiği için 18.00’de çoğu zaman işte. Montunu evde çıkarıyor. O sırada genellikle iki boş dakikası oluyor.",question:"Her gün yeniden saat ayarlamadan hangi plan iş günlerine uyar?",options:[{id:"days-off-session",text:"Enerjisini korumak için izin günlerinde kısa çizimler yapmayı seçsin. Böylece iş günlerinde daha az çizim fırsatı olacağını kabul etsin.",feedback:"İzin günlerinde denemek dinlenmeyi koruyabilir ve başka bir amaca uyabilir. Derya ise iş günlerinde kısa fırsatlar istiyor. Eve dönüş anı, her vardiyanın bitişini tahmin etmeden böyle bir fırsat sunuyor."},{id:"coat-cue",text:"Montunu çıkardıktan sonra bir nesne çizsin. Çok yorgunsa dinlensin veya başka bir uygun başlangıç anı seçsin.",feedback:"Bu plan tanınabilir bir anı kullanıyor ve dinlenme ihtiyacını koruyor. Derya aynı küçük çizimi deneyebilir. Sabit bir saat veya daha güçlü bir hatırlatma, vardiyalarını değiştiremez."},{id:"shift-calendar-alert",text:"Her gün vardiya takvimini kontrol edip beklenen çıkış saatinden otuz dakika sonrasına bir çizim hatırlatması kursun.",feedback:"Çıkış saatleri tutuyorsa bu plan işe yarayabilir. Değişen vardiyalarda hatırlatmaları ayarlamak ek iş ve belirsizlik getirir. Eve dönüş, uygun yeri zaten işaretliyor. Dinlenme seçeneğini koruyarak o anı dene."}],bestOptionId:"coat-cue"}},carry:{takeaway:"Elindeki koşullara göre plan yap. Sonra seçtiğin işi o durumda dene.",followUp:{questionId:"turning-day-2-return",question:"Seçtiğin başlama anı geldi mi? O anda planladığın işi gerçekten yapabilir miydin?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"Her engel senin içinde değildir",paragraphs:["Zihinsel karşılaştırma, istediğin sonucu ona ulaşmanın önündeki engelle birlikte düşünmektir. Buna “şu olursa bunu yaparım” planı eklenince yöntem çoğu zaman MCII diye anılır. Wang ve arkadaşları, 15.907 kişinin katıldığı, 24 bağımsız etki içeren 21 makaleyi inceledi [T04]. Hedefe ulaşmada küçük bir ortalama yarar buldular. Sonuçlar araştırmalar arasında değişiyordu. Yayın yanlılığı olasılığı da vardı.","Bu yaklaşım bazen isteğin kendisini değiştirmek gerektiğini gösterir. Bir sonucu hayal etmenin onu hayatına çekeceğini, her engelin bir duygu olduğunu veya daha çok zorlanmanın her zaman doğru olduğunu göstermez. Planın mümkün olup olmadığını değerlendirirken dış koşulları da hesaba kat. Para, engellilikle ilgili erişim ihtiyaçları, iş yükü ve bakım sorumlulukları “canım istemiyor” diye açıklanamaz.","ODA’nın uyarlaması, seçtiğin yönü koruyup o durum için seçtiğin işi denemeni ister. Bu, işi küçültmek, başka bir an seçmek veya somut bir yardım istemek olabilir. İşe yarayıp yaramadığına karar vermeden önce o işi gerçekten yapıp yapamayacağını kaydet."]},{heading:"Daha çok saat planlamak hâlâ plan yapmaktır",paragraphs:["Zaman yönetimi üzerine bir araştırmada 84 Alman lisans öğrencisi rastgele üç gruba ayrıldı [T15]. Zihinsel karşılaştırmayı planlamayla birleştiren grup, kontrol gruplarından daha çok çalışma saati planladı. Önceden planlanan karşılaştırma istatistiksel olarak anlamlıydı. Koşulların genel testinde ise p = 0,057 bulundu. Ölçülen sonuç takvime ayrılan saatlerdi. Araştırma, öğrencilerin gerçekte kaç saat çalıştığını göstermedi.","Daha geniş bir derlemede, belirli “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı [T03]. Bu deneyler tek bir zamanlayıcı süresini veya herkese uyan günlük bir süreyi sınamadı. Burada seçtiğin işi denemek ve ertesi gün ne olduğuna bakmak eğitim için uyarlanmış adımlardır. Özgün araştırma uygulaması değildir.","Denemeye bakarken üç soruyu ayır: Başlama anı geldi mi? Planladığın işi yapabilir miydin? Yaptın mı? Engel hiç çıkmadıysa alternatif planın henüz sınanmadı. İşi yapman mümkün değilse kendini yargılamak yerine koşulları veya planını değiştir."]}],sourceIds:["T03","T04","T15"]}},{schemaVersion:2,revision:2,id:"turning-day-3",courseId:"turning-day",locale:"tr",title:"“Ben hiç sürdüremiyorum.” Kaydın da bunu mu söylüyor?",goal:"Aynı denemede işe yarayan küçük adımını tamamla. Bu denemenin tam olarak neyi gösterdiğini anlat.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tek bir kötü denemeden, bütün hayatın hakkında bir hüküm mü çıkardın?",reason:{id:"turning-day-3-never-fact-check-reason",label:"Son denemen “hiç yapamıyorum” sözünün hangi kısmını destekliyor, hangi kısmına uymuyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Bir iş yaptım; becerim hâlâ gelişmeli","Başlangıç anı gelmedi; becerimi henüz sınamadım","Henüz kaydettiğim bir deneme yok"]},why:{id:"turning-day-3-why",label:"Bu hafta dürüstçe kaydedeceğin küçük bir deneme neye katkı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Belirli bir işi yapabileceğine inanman ile insan olarak değerin ayrı şeyler. Bir kurama göre, bu beklentiyi şekillendiren önemli kaynaklardan biri daha önce başardığın işlerdir. Bu, her küçük adımın özgüvenini artıracağını veya birçok konuda yetenekli olduğunu kanıtlayacağını göstermez. Burada bütün kişiliğine bir not vermiyoruz. Tek bir işe bakıyoruz.","Aynı küçük adımına dön. Yaptığını tam anlat: “Bir nesne çizdim. Dış hatlarını çalışmam gerekiyor.” Kusurlu bir deneme, seçtiğin en küçük adımı karşılayıp becerindeki eksiği gösterebilir. İki dakika, başlamak için seçilmiş bir süre. Araştırmayla en iyi olduğu gösterilmiş süre değil. Özgüvenin aynı kalabilir. Yaptığın işi yine de kaydet."],example:{title:"Derya’nın fincan kulpu yine yamuk",text:"Derya montunu çıkardıktan sonra mutfak masasında bir fincan çiziyor. Kulp yine yamuk. Kendine daha fazla güvenmiyor. Notuna “Bir fincan çizdim. Kulpun oranlarını çalışmam gerekiyor” yazıyor. Sıradaki uygun öğleden sonra aynı küçük işi seçiyor. Bir fincan çizmiş olması, bir afiş tasarlayabildiğini göstermiyor. Notunda çizimin bittiği ve kulpun çalışılması gerektiği ayrı ayrı yazıyor."}},move:{invitation:"Kaydettiğin işi ve başlangıç anını koru. Ortaya çıkan işi ve kalan bir eksiği kaydet.",instructions:["Seçtiğin işi ve en küçük adımı aynı tut.","“Neye bakacaksın?” alanına çıkan işi ve kalan bir eksiği yaz."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Bir sonraki çayımı bitirince","Sonraki uygun molam başlayınca","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Fincanın kulpunu çizmek için birinden yardım iste","Kontrol etmem gereken bilgiyi cümlede işaretle","Açıklamasına ihtiyaç duyduğum yeri metinde işaretle"],observation:["Yaptığım çizim ve geliştirmem gereken bir ayrıntı","Yazdığım cümle ve kontrol etmediğim bir bilgi","Okuduğum paragraf ve anlamadığım bir nokta"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Bir sonraki çayımı bitirince",place:"Evde, mutfak masamın başında",fallback:"Fincanın kulpunu çizmek için birinden yardım iste",observation:"Yaptığım çizim ve geliştirmem gereken bir ayrıntı",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Sonraki uygun molam başlayınca",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Kontrol etmem gereken bilgiyi cümlede işaretle",observation:"Yazdığım cümle ve kontrol etmediğim bir bilgi",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Açıklamasına ihtiyaç duyduğum yeri metinde işaretle",observation:"Okuduğum paragraf ve anlamadığım bir nokta",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Bir sonraki çayımı bitirince",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Yaptığım işin bir kısmında yardıma ihtiyacım var",fallbackHint:"Fincanın kulpunu çizmek için birinden yardım iste",observationHint:"Yaptığım çizim ve geliştirmem gereken bir ayrıntı"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Gücüne uygun, güvenli bir deneme seç. Kötü bir sonuç destek, değişiklik veya ara verme gerektirebilir."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-3-specific-record-decision",scenario:"Derya söz verdiği tek fincan çizimini bitirdi. Kulp yamuk, özgüveni de aynı. Şimdi kaydına ne yazacağını seçiyor.",question:"Bir sonraki denemeye hangi kayıt daha iyi yön verir?",options:[{id:"repeat-before-assessing",text:"Bitirdiği çizimi kaydetsin. Hangi ayrıntıyı çalışacağına karar vermeden önce aynı fincanı hiçbir şeyi değiştirmeden yeniden çizsin.",feedback:"Neyi çalışacağını bilmiyorsan tekrar yardımcı olabilir. Derya ise yamuk kulpu şimdiden görebiliyor. O ayrıntıyı şimdi kayda eklesin. Böylece sıradaki deneme belirli bir beceriyi sınayabilir."},{id:"specific-evidence",text:"Tamamladığı bir fincan çizimini ve yamuk kulpu kaydetsin. Sonra bir sonraki uygun deneme zamanını seçsin.",feedback:"Bu kayıt, Derya’nın ne yaptığını ve hangi ayrıntı üzerinde hâlâ çalışması gerektiğini gösteriyor. Derya tek çizim hedefini karşıladı. Genel çizim becerisini kanıtlaması veya özgüveninin değişmesi gerekmiyor. Sıradaki denemede kulp üzerinde çalışabilir."},{id:"cue-reliability-from-once",text:"Çizimi bitirdiğini kaydetsin. Bugün işe yaradığı için bu başlangıç anını gelecek hafta da aynı şekilde kullansın.",feedback:"Umut veren bir başlangıç anını denemeye devam etmek makul. Ama tek tamamlanmış iş, düzenin güvenilir olduğunu göstermez. Kulptaki sorunu da kaydet. Sıradaki koşullarda aynı başlangıç anını yeniden sınayabilirsin."}],bestOptionId:"specific-evidence"}},carry:{takeaway:"Ne yaptığını tam anlat. Kalan beceri eksiği, sıradaki denemende ne çalışacağını göstersin.",followUp:{questionId:"turning-day-3-return",question:"Tamamladığın küçük iş neyi gösterdi, hangi kısmının üzerinde hâlâ çalışman gerekiyor?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"“Yapabilirim” dediğinde hangi işi kastediyorsun?",paragraphs:["Bandura’nın 1977 tarihli makalesi, öz yeterliği belirli bir davranışı yapmaya dair beklenti olarak anlatır [T09]. Kendi başardıkların, başkalarını gözlemek, cesaretlendirilmek ve bedensel durumlar bu beklentiye bilgi sağlar. Kuram, kişinin kendi deneyimine özellikle önem verir. Ama bu makale bir deney değildir. Her küçük işin özgüven yarattığını veya her ortamda kendi deneyiminin diğer desteklerden üstün olduğunu kanıtlamaz.","Bu ayrım, kurs boyunca kaydını işe yarar tutar. Tamamladığın çizim, o koşullarda o çizimi yaptığını gösterir. Araçların, başlangıç anın veya şu anki becerin hakkında bir şey öğretebilir. İnsan olarak değerini ölçmez. Gelecekteki her projeyi tamamlayabileceğini de göstermez. Bu tek denemeden, gösterdiğinden daha büyük bir sonuç çıkarma.","Yaptığın iş bir bilgi eksiğini gösteriyorsa sıradaki adım öğrenmek veya yardım almak olabilir. Gücün ya da güvenliğin değişirse adımı uyarla veya ara ver. Bu, gündelik gelişim için bir denemedir. Yoğun kaygının tedavisi veya kişiliğinin sınavı değildir."]},{heading:"Küçük bir başlangıç ile tamamlanmış iş aynı değil",paragraphs:["James Clear’ın iki dakika kuralı, uygulamaya dönük bir öneridir. İki dakikanın en iyi süre olduğunu gösteren kontrollü bir araştırma bulgusu değildir [T17]. Kısa bir başlangıç, işe el atmayı kolaylaştırabilir. Ama kalemi ortaya koymak hazırlık, bir nesne çizmek çizim denemesidir. İstediğin yola gerçekten katkısı olan en küçük adımı seç. Uygun adım hazırlıksa bunu dürüstçe hazırlık olarak kaydet.","Harkin ve arkadaşlarının 138 rastgele kontrollü araştırmayı birleştiren derlemesinde, ilerlemeyi izlemek hedefe ulaşmayı ortalama olarak artırdı [T05]. Hedefler ve yöntemler farklıydı. Ek analizlerde ilerlemeyi fiziksel olarak kaydetmek daha büyük etkilerle ilişkiliydi. Bu sonuç, ODA’nın tam bu not biçimini doğrulamaz. Başkalarıyla açıkça paylaşmayı da gerektirmez.","Kısa bir not hem yaptığın işi hem eksik kalan noktayı gösterebilir: işe yarayan bir cümle yazdım, ama bir bilgi hâlâ kontrol edilmeli. Adım iyi hissettirdi diye sonucu büyütme. Hayal kırıklığı yarattı diye de yaptığını silme. Sıradaki küçük işi elindeki kayda göre seç."]}],sourceIds:["T09","T05","T17"]}},{schemaVersion:2,revision:2,id:"turning-day-4",courseId:"turning-day",locale:"tr",title:"Sonraki adımını aramakla vakit kaybetme",goal:"Sürdürdüğün küçük adımı, seçtiğin başlangıç anında tek bir ortam değişikliğiyle dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Gereken malzeme ortada yokken dikkatini dağıtan şey hemen elinin altında mıydı?",reason:{id:"turning-day-4-reason",label:"Gereken şeyler ulaşılır kalsın. Hazırlığın hangi kısmını kolaylaştırabilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Başlama anında araçlarım hazır olsun","Gerekli arama ve mesajlara ulaşayım","Kendime sakladığım bir kayıt tutayım"]},why:{id:"turning-day-4-why",label:"Gereken şeyler ulaşılır kalsın. Hazırlığın hangi kısmını kolaylaştırabilirsin?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Başlangıç anı sadece telefondan gelen hatırlatma değildir. İşin yapılacağı ortam da buna dahildir. Araştırmalar, benzer ortamlarda tekrarlanan bir davranışın zamanla o ortamdaki işaretlerle daha çok başlayabildiğini anlatır. Gerekli malzemeyi hazır tutmak hazırlık yükünü azaltabilir. Ama çabayı ortadan kaldırmaz, hatırlayacağını da garanti etmez. Hazır olması, işi senin yerine yapması demek değil.","Son denemenin kaydına bak. Engel malzemeyi bulmaksa onu başlangıç anında kullanacağın yere koy. Sonra küçük işini orada dene. Gerekli aramalar, bakım sorumluluklarıyla ilgili bildirimler ve erişim araçları ulaşılabilir kalsın. Kaydını kendine saklayabilirsin. Bir nesnenin yerini değiştirmek hazırlıktır. Küçük işi yapmak ise bu hazırlığı sınar."],example:{title:"Derya telefonu ulaşılabilir tutuyor",text:"Derya son çizim fırsatını kâğıt ararken kaçırdı. Bu kez not kâğıdını ve kalemi çay fincanının yanına koyuyor. Çaydan sonra kaşığı çiziyor. Ailesi arayabilsin diye telefonu ulaşılabilir kalıyor. Çizimini sadece kendisinin gördüğü bir kayda ekliyor. Bu hazırlık bugün işe yaradı. Yarınki vardiya için başka bir başlangıç anı gerekebilir. Tek deneme henüz düzeni kanıtlamıyor."}},move:{invitation:"Kaydettiğin işi, başlangıç anını ve yeri koru. Hazırlıkta tek bir değişikliği dene.",instructions:["“Neye bakacaksın?” alanına bir malzeme veya erişim değişikliği yaz.","Aynı en küçük adımı bu yeni hazırlıkla dene."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Bir sonraki çayımı bitirince","Önceden ayırdığım mola başladığında","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Rahatça kullanabildiğim yedek kalemle çizimi dene","Bana uygun olan yedek yazma aracımı kullan","Metnin bana uygun, erişilebilir bir kopyasını aç"],observation:["Kalemin hangi yerde durması çizime yardımcı oldu?","Dosyaya erişimde hangi değişiklik yazmayı kolaylaştırdı?","Metne erişimde hangi değişiklik okumayı kolaylaştırdı?"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Bir sonraki çayımı bitirince",place:"Evde, mutfak masamın başında",fallback:"Rahatça kullanabildiğim yedek kalemle çizimi dene",observation:"Kalemin hangi yerde durması çizime yardımcı oldu?",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Önceden ayırdığım mola başladığında",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Bana uygun olan yedek yazma aracımı kullan",observation:"Dosyaya erişimde hangi değişiklik yazmayı kolaylaştırdı?",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Metnin bana uygun, erişilebilir bir kopyasını aç",observation:"Metne erişimde hangi değişiklik okumayı kolaylaştırdı?",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Bir sonraki çayımı bitirince",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Gereken malzemeleri bulmak ya da onlara ulaşmak zor",fallbackHint:"Rahatça kullanabildiğim yedek kalemle çizimi dene",observationHint:"Kalemin hangi yerde durması çizime yardımcı oldu?"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Hazırlığını değiştirirken acil iletişim, bakım sorumlulukları ve erişim için gereken arama ve mesajları ulaşılabilir tut."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Hangi hazırlık değişikliğini denedin, ardından gerçekte hangi işi yaptın?"},judgment:{primary:{id:"turning-day-4-decision",scenario:"Derya kâğıt ararken bir çizim fırsatını kaçırdı. Ailesi arayabilsin diye telefonu ulaşılabilir olmalı. İlerlemesini de kendine saklamak istiyor.",question:"Bu durumda hangi adım ona daha uygun?",options:[{id:"mute-nonessential-alerts",text:"Gereksiz bildirimleri kapatıp aile aramalarını açık tutsun. Kâğıdın nerede olduğunu hatırlamaya güvenerek aynı şekilde devam etsin.",feedback:"Bu seçim gerekli iletişimi korur ve kesintileri azaltabilir. Ama kayıtta görünen malzeme bulma sorununu değiştirmez. Çizim malzemelerini çay molasında kullanacağın yere koy. Sonra aynı küçük çizimi dene."},{id:"ready-tools",text:"Kâğıdı çay fincanının yanına koysun. Aile aramaları açık kalsın. Bir çizim yapıp kaydını kendine saklasın.",feedback:"Bu adım, kaydını paylaşmanı veya iletişimi kesmeni gerektirmeden malzeme bulma sorununa odaklanıyor. Bir çizim denemesi, hazır malzemenin bu belirli fırsatta yardımcı olup olmadığını gösterir."},{id:"private-reminder-first",text:"Çaydan sonrası için sadece kendisinin gördüğü bir çizim hatırlatması kursun. Kâğıdı her zamanki yerinde bıraksın.",feedback:"Hatırlatma, başlangıç anını fark etmeyi kolaylaştırabilir. Derya zaten çay molasını fark ediyor. Sorun kâğıdı bulamaması. Önce malzemenin yerini sınasın. Sonra fark etmek sorun olursa hatırlatmayı düşünsün."}],bestOptionId:"ready-tools"}},carry:{takeaway:"Hazırlığını işi yaparken dene. Kaydının gizliliğini ve gerekli araçlara, iletişim kanallarına erişimini koru.",followUp:{questionId:"turning-day-4-return",question:"Hazırlıktaki değişiklik, başlangıç anını kullanıp küçük işini yapmana yardımcı oldu mu?",observationPrompt:"Hangi hazırlık değişikliği kaydettiğin işi kolaylaştırdı, hangisi hiç yardımcı olmadı?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"Ortam yardımcı olabilir, işi senin yerine yapmaz",paragraphs:["Wood ve Rünger’in derlemesi, benzer ortamlarda tekrarlanan davranışların zamanla ortamdaki işaretlerle başlayabildiğini anlatır [T08]. Bilinçli hedefler ile alışkanlıklar birlikte işleyebilir. Bu, farklı araştırmaları birleştiren bir derlemedir. Bir nesneyi belirli yere koymanın herkeste işe yaradığını kanıtlayan bir deney değildir. İradenin sınırlı bir pil olduğunu veya hazırlığın planlama ve başlama güçlüklerini ortadan kaldırdığını göstermez.","Lally ve arkadaşları, gündelik sağlık davranışlarını 84 gün boyunca izledi [T06]. Aynı ortamda tekrarlarla birlikte, kişilerin bildirdiği otomatiklik arttı. Rastgele atanmış, deneme yapmayan bir kontrol grubu yoktu. Bu araştırmadan garantili bir süre çıkaramayız. Bir fincanın yanına kalem koymanın tam etkisini de bu çalışma kanıtlamaz.","ODA küçük bir ortam değişikliğini denemeni istiyor. Çünkü son kaydın belirli bir hazırlık yükü gösterdi. İşini, başlama anını ve en küçük adımını aynı tut. Böylece sıradaki gözlemin somut bir soruyu yanıtlar: gerekli malzemeler elinin altında mıydı, onları gerçekten kullandın mı?"]},{heading:"Kaydını kendine saklayarak da ilerleyebilirsin",paragraphs:["Harkin ve arkadaşları, ilerlemeyi izlemeye dair 138 rastgele kontrollü araştırmayı inceledi [T05]. İzlemeyi artıran uygulamalar hedefe ulaşmayı ortalama olarak artırdı. Ek analizlerde fiziksel kayıt ve bildirim daha büyük etkilerle ilişkiliydi. Ama bu karşılaştırmalar tek bir arkadaşın yeterli olduğunu, herkese açık paylaşım gerektiğini veya kaydını kendine saklamanın daha kötü bir yol olduğunu kanıtlamaz.","İstersen destekleyici biriyle konuşmayı seçebilirsin. Kişiyi, paylaşacağın bilgiyi ve zamanı sen belirlersin. Burada yalnızca senin gördüğün, somut bir not da tam bir seçenektir. Hedefini başkalarına anlatman, alkış istemen veya yanında güvende olmadığın birinden baskı görmen gerekmiyor.","Telefonun yerini değiştirirken de gereken iletişimi ve erişimi koru. Gördüğün engeli hedefle: ulaşamadığın malzeme, bulamadığın belge veya gereksiz bildirim. Hazırlığı hazırlık olarak kaydet. Ardından aynı küçük işi denediğinde ne olduğuna bak. Sadece ortamı değiştirmiş olman, işi yaptığını göstermez."]}],sourceIds:["T08","T05","T06"]}},{schemaVersion:2,revision:2,id:"turning-day-5",courseId:"turning-day",locale:"tr",title:"“Bugün yapamadım.” Önce kayıtta ne olduğuna bak",goal:"Gerçek denemene dönüp bak. Geçmişi değiştirmeden bir sonraki uygun fırsatı kaydet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bugüne “başarısızlık” mı diyorsun? Kaydında gerçekte ne var?",reason:{id:"turning-day-5-reason",label:"Kaydına bakınca hangi şeyin değişmesi gerektiğini görüyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Hazırlık ile gerçek denemeyi birbirinden ayrı tutmak","Kaçırdığım fırsatta ne olduğunu anlayıp öğrenmek","Yarın yapacağımı bugün yapılmış saymamak"]},why:{id:"turning-day-5-why",label:"Kaydına bakınca hangi şeyin değişmesi gerektiğini görüyorsun?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bugün yaptığını kayda, yarın yapmak istediğini plana koy. Araştırmalar ilerlemeyi kontrol etmeyi ortalama olarak destekliyor. Aracın hazır olması, denemeyi yaptığını göstermez. Seçtiğin en küçük adımı koru. Yeni planın geçmişte yaptığını değiştirmez. Hazırlığı ve asıl işi ayrı tut.","En son denemende ne yaptığını veya hangi adımın eksik kaldığını söyle. Sonra bir sonraki uygun fırsatı seç. Bir çalışmada kendini affetmek, sonraki sınav için daha az ertelemeyle ilişkiliydi. Bu ilişki, affetmenin ertelemeyi azalttığını veya kendine anlayışlı bir cümle söylemenin işe yaradığını göstermez. Kendine yüklenmeden, başarı uydurmadan bak. Geç saatte değerlendirmek kaygını artırıyorsa daha erken bir zaman seç."],example:{title:"Derya kâğıdı hazırladı ama çizmedi",text:"Derya kâğıdı fincanının yanına koydu. Ama işten geç çıktı. Akşam çayını içti ve çizmedi. Günü kapatmadan önce hazırlığı ayrı kaydediyor. Çizim için “Henüz değil” seçeneğini işaretliyor. Yarın çaydan sonra yapacağı çizim ise plan olarak kalıyor. Kısa bir değerlendirme yapıyor. Hâlâ hayal kırıklığı hissediyor. Bu his, hazırlığı yapılmış çizim saymasını gerektirmiyor."}},move:{invitation:"Kaydettiğin denemeye bak. İşi koru, kaydın gösterdiği tek bir koşulu değiştir.",instructions:["Bir sonraki denemeyi değiştirmeden önce gerçekten ne olduğunu kaydet.","İşi ve en küçük adımı koru. Sadece uymayan koşulu değiştir."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Bir sonraki erken çay molamda","Bir sonraki erken iş molamda","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Dinlen; yarın daha erken çay molasında dene","Dinlen; yarın daha erken iş molasında dene","Dinlen; yarın daha erken yemeğin ardından oku"],observation:["Yeni seçtiğim anda ortaya çıkan çizim","Yeni seçtiğim anda yazdığım işe yarayan cümle","Yeni seçtiğim anda okuyup bitirdiğim paragraf"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Bir sonraki erken çay molamda",place:"Evde, mutfak masamın başında",fallback:"Dinlen; yarın daha erken çay molasında dene",observation:"Yeni seçtiğim anda ortaya çıkan çizim",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Bir sonraki erken iş molamda",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Dinlen; yarın daha erken iş molasında dene",observation:"Yeni seçtiğim anda yazdığım işe yarayan cümle",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Dinlen; yarın daha erken yemeğin ardından oku",observation:"Yeni seçtiğim anda okuyup bitirdiğim paragraf",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Bir sonraki erken çay molamda",placeHint:"Evde, mutfak masamın başında",obstacleHint:"İş geç bitince başka bir şeye gücüm kalmıyor",fallbackHint:"Dinlen; yarın daha erken çay molasında dene",observationHint:"Yeni seçtiğim anda ortaya çıkan çizim"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Değerlendirmek kaygını artırıyor veya uykunu açıyorsa dur. Daha erken bir değerlendirme zamanı ya da dinlenmeyi seç."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-5-decision",scenario:"Derya işten geç çıktığı gün söz verdiği tek çizimi yapmadı. Kâğıdı hazırlamıştı. Yarın daha erken çay molası verebilir. Hafta sonu daha uzun zaman ayırması da mümkün.",question:"Bu durumda hangi adım ona daha uygun?",options:[{id:"same-cue-new-alert",text:"Çizim için “Henüz değil” kaydı girsin. Akşamki başlama anını koruyup aynı saate bir hatırlatma eklesin.",feedback:"Bu seçim kaydı dürüst tutuyor. Hatırlatma, başlama anını fark etmek içindir. Derya’nın sorunu ise işten geç çıktığında gücünün kalmamasıydı. Daha erken çay molasında aynı küçük adımı daha uygun koşullarda deneyebilir."},{id:"honest-change",text:"Hazırlığı ayrı kaydetsin. Çizim için “Henüz değil” seçeneğini seçsin. Aynı küçük iş için daha erken ve uygun bir an seçsin.",feedback:"Bu seçim söz verilen küçük adımı korur, ne olduğunu anlatır. Yarın yapacağı iş hâlâ plandır. Derya hazırlığı çizim saymadan ve bütün günü kötü ilan etmeden başlangıç anını değiştirebilir."},{id:"weekend-session",text:"Çizim için “Henüz değil” kaydı girsin. Denemesini hafta sonunda ayırabileceği daha uzun bir zamana taşısın.",feedback:"Hafta sonu hayatına daha iyi uyuyorsa onu seçebilir. Ama burada yarın erken bir mola var. Aynı küçük işi orada denemek, zamanı ve işin büyüklüğünü birlikte değiştirmeden önce daha küçük bir değişikliği sınar."}],bestOptionId:"honest-change"}},carry:{takeaway:"Geçmişi olduğu gibi dürüstçe kaydet. Elindeki gerçekler gerektiriyorsa bir sonraki deneme fırsatını değiştir.",followUp:{questionId:"turning-day-5-return",question:"Yeni seçtiğin fırsat hayatına daha iyi uydu mu, orada gerçekten ne yaptın?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"Dürüst değerlendirme sorumluluğu korur",paragraphs:["Wohl ve arkadaşları, iki ara sınavın çevresinde 119 birinci sınıf öğrencisini izledi [T12]. İlk erteleme için kendini daha fazla affetmek, sonraki sınav öncesinde daha az ertelemeyle ilişkiliydi. Bu, tek bir derste yapılmış gözlemsel araştırmaydı. Affetmenin değişime neden olduğunu, hazır bir cümlenin davranışı değiştirdiğini veya kendine yüklenmenin her zaman kaçınma yarattığını göstermez.","Doğru kayıt tutmak için önce kendini affetmiş hissetmen gerekmez. “Kâğıdı hazırladım ama iş geç bittiği için çizmedim” iki ayrı olguyu anlatır. “Yarın ilk çayımdan sonra çizeceğim” ise bir plandır. İlk deneme hayal kırıklığı yaratsa da bu ayrımları koru. Hazırlık yapılmış olabilir, asıl iş henüz yapılmamış olabilir.","İlerlemeyi izlemek için daha geniş deneysel destek var [T05]. Yine de o derleme ODA’nın bu belirli kayıt ve dönüş akışını değerlendirmedi. Buradaki amaç pratik: elindeki bilgiyle sıradaki koşulu seçmek. Planını kanıt gibi sunmadan, yaptığın iş ile yapmayı istediğin işi ayrı kaydetmek."]},{heading:"Yatmadan önce liste yazma bulgusunun sınırı var",paragraphs:["Scullin ve arkadaşları bir laboratuvar gecesinde, 18–30 yaşındaki 57 sağlıklı yetişkinin verisini inceledi [T11]. Katılanlar kâğıt ve kalemle beş dakika boyunca ya ilerideki işleri ya da tamamlanan işleri yazdı. Gelecek işleri yazan grup ortalama olarak daha çabuk uyudu: 15,82 dakikaya karşı 25,09 dakika. Karşılaştırma, hiç yazmamakla değil başka bir yazma işiyleydi. Toplam uykuda istatistiksel olarak anlamlı artış gösterilmedi.","Bu sonuç; sözlü telkinleri, yarını hayal etmeyi veya başarıları gözden geçirmeyi uyku tedavisi olarak doğrulamaz. Beş dakikalık kâğıt işi ayrı bir uygulamaydı. ODA’nın kısa değerlendirmesi ve planı, o sınanmış uygulama değildir. Uyku sözü vermez, yatmadan önce yazmanı da gerektirmez.","Değerlendirmek kaygını artırıyor veya seni uyanık tutuyorsa dur. Daha erken bir zaman seç. Dinlenmek uygun adım olabilir. Süren uyku güçlükleri için kursun bitmesini beklemeden bir uzmana danışabilirsin. Aynı küçük iş denemeni sürdür. Bunun için yeni bir gece ritüeli eklemene gerek yok."]}],sourceIds:["T05","T12","T11"]}},{schemaVersion:2,revision:2,id:"turning-day-6",courseId:"turning-day",locale:"tr",title:"Birkaç gün yapamadın mı? Haftanı hayatına göre planla.",goal:"Kayıtlarına bakarak aynı deneme için gerçekçi bir hafta planla. Güvenli molalara da yer bırak.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kayıtların, hayalindeki değil gerçekten yaşadığın hafta hakkında ne söylüyor?",reason:{id:"turning-day-6-reason",label:"Bu küçük iş, ayırabildiğin zaman ve güçle istediğin yola katkı sağlıyor mu?",kind:"text",maxLength:160,optional:!0,suggestions:["Hayatıma uyan kısmı aynı şekilde korumak","Telafi işi eklemek yerine başlama anını değiştirmek","Dinlenip toparlanmak için de yer ayırmak"]},why:{id:"turning-day-6-why",label:"Bu küçük iş, ayırabildiğin zaman ve güçle istediğin yola katkı sağlıyor mu?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Denemen için planladığın fırsatları, yaptığın denemeleri ve ortaya çıkan işi karşılaştır. Bir haftada planının hayatına uyumuna bakarsın. Alışkanlık oluştuğunu göstermez. Sık duyduğun 18–254 gün, insanları yalnızca 84 gün izleyen bir çalışmadaki model tahminlerinden geldi. Bunlar gözlenmiş bitiş günleri veya herkes için geçerli süreler değildi. Kendi haftanı o sayılarla yargılama.","Küçük işi koru veya küçült. Başlangıç anını değiştir ya da ara ver. İncelenen çalışmada tek kaçırılan fırsat süreci belirgin biçimde bozmadı. İki kez aksama sınırı belirlenmedi. Bir sonraki uygun fırsatı kaydet. ODA ertesi gün ne olduğuna bakman için zaman ayırır. Geçmiş kayıtlarını boşluklarıyla birlikte koru."],example:{title:"Derya’nın haftası eksiksiz değil",text:"Derya beş çizim fırsatı planladı, üçünde çizdi. İki boşluk da geç vardiyaların ardından geldi. Pazar çayında tek nesne hedefini koruyor. Yalnızca geç vardiya günlerindeki başlangıcı pazartesi öğleden sonraki molaya taşıyor. Bu fırsatı kaydedince ODA salı günü denemesine bakması için zaman ayırıyor. Kabaca yaptığı üç çizim yine üç çizim. Yapmadığı iki deneme kayıtta kalıyor."}},move:{invitation:"Kaydettiğin küçük işi ve sana uyan başlama anını koru. Sadece seni durduran koşulu değiştir.",instructions:["Henüz kaydın yoksa ilk uygun deneme fırsatını seç.","Sonraki fırsatı kaydet. ODA ertesi gün ne olduğunu gözden geçirmen için zaman ayırır."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Sonraki öğleden sonra çay molam başlayınca","İşte sonraki uygun molam başlayınca","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Dinlen; bir sonraki öğleden sonra molasında dene","Yarın işte önceden ayırdığım mola zamanında dene","Bir sonraki uygun yemekten sonra paragrafı oku"],observation:["Yaptığım çizim; zaman uygun muydu?","Yazdığım cümle; zaman uygun muydu?","Bitirdiğim paragraf; zaman uygun muydu?"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Sonraki öğleden sonra çay molam başlayınca",place:"Evde, mutfak masamın başında",fallback:"Dinlen; bir sonraki öğleden sonra molasında dene",observation:"Yaptığım çizim; zaman uygun muydu?",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"İşte sonraki uygun molam başlayınca",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Yarın işte önceden ayırdığım mola zamanında dene",observation:"Yazdığım cümle; zaman uygun muydu?",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Bir sonraki uygun yemekten sonra paragrafı oku",observation:"Bitirdiğim paragraf; zaman uygun muydu?",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Sonraki öğleden sonra çay molam başlayınca",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Geç biten vardiyalar bu deneme zamanına izin vermiyor",fallbackHint:"Dinlen; bir sonraki öğleden sonra molasında dene",observationHint:"Yaptığım çizim; zaman uygun muydu?"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Hastalık, bitkinlik, bakım sorumlulukları veya güvensiz koşullar bir süre ara vermeni gerektirebilir. Yeniden başlamak mümkün olduğunda dön."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-6-observed-fit-decision",scenario:"Derya beş çizim planladı, üçünü yaptı. İki boşluk geç vardiyaların ardından geldi. Tek nesne hedefi diğer deneme zamanlarında ona uydu.",question:"Bu durumda hangi adım ona daha uygun?",options:[{id:"shrink-before-moving",text:"Geç vardiya sonrasındaki başlangıcı korusun. Her çizimde yalnızca dış hatları çizsin. Sonraki haftayı yine dürüstçe karşılaştırsın.",feedback:"Engel işin büyüklüğüyse küçültmek yardımcı olabilir. Ama mevcut hedef başka fırsatlarda uydu. Önce işe yarayan kapsamı değiştirmek yerine daha uygun bir başlangıç anını dene. Kayıt şu anda bunu gösteriyor."},{id:"adjust-week",text:"Tek nesne hedefini korusun. Geç vardiya sonrasındaki başlangıç anını değiştirsin. Beş fırsatın bütün kayıtları olduğu gibi kalsın.",feedback:"Bu seçim, denemelerinde gördüğü soruna göre planı değiştiriyor ve geçmişi dürüst tutuyor. Derya başka bir uygun başlangıç anını sınayabilir. Elinde tamamladığın üç çizim var. Bu, alışkanlık oluştuğunun kanıtı değildir."},{id:"compensate-output",text:"Geç vardiya sonrasındaki başlangıcı korusun. Yapamadığı çizimleri telafi etmek için boş günlerinde daha fazla nesne çizsin.",feedback:"Fazladan çizmek, kendisi seçerse amacına katkı sağlayabilir. Ama başlama zamanındaki sorunu değiştirmez. Telafi yükü eklemeden önce geç vardiya günlerindeki fırsatı düzelt. Sonra daha fazla iş isteyip istemediğine bak."}],bestOptionId:"adjust-week"}},carry:{takeaway:"Kayıtlarına bakarak gelecek haftayı planla. Dinlenmeye ve güvenli molalara da yer ver.",followUp:{questionId:"turning-day-6-return",question:"Seçtiğin değişiklik, sıradaki fırsatta küçük işini yapmanı gerçekten mümkün kıldı mı?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"O alışkanlık süresi bir model tahminiydi",paragraphs:["Lally ve arkadaşları, 96 gönüllüyü 84 gün izledi [T06]. 82 kişi yeterli veri verdi. 62 kişinin verisi için eğriler hesaplandı. Bunların 39’u verilere iyi uydu. Bu 39 eğride, kişinin otomatiklik düzeyinin üst sınırının %95’ine ulaşması için tahmin edilen süre 18 ile 254 gün arasındaydı. Ortanca 66 gündü. 254 gün, gözlem süresinin ötesine uzanan bir model tahminiydi. Araştırmada görülmüş bir bitiş değildi.","Çalışma, gündelik sağlık davranışları için kişilerin kendi bildirimlerine dayanıyordu. Rastgele atanmış kontrol grubu yoktu. Tek bir fırsatın kaçırılması, incelenen süreci belirgin biçimde bozmadı. Bu bulgu, iki kez aksamanın alışkanlığı yok ettiği bir eşik belirlemez. Üst üste ara vermek, karakterinin zayıf olduğunu da göstermez.","Bu kursta planladığın hafta, planın hayatına uyup uymadığını sınar. Çizim, öğrenme, bakım veya toparlanma adımın çalışılan davranışlardan farklı olabilir. Uyumu gerçek fırsatlar ve çıkan işle değerlendir. Gün serisini, araştırmayla doğrulanmış bir dönüşüm ölçüsü gibi kullanma."]},{heading:"Elindeki denemeyi toparla, yenisini eklemek gerekmez",paragraphs:["2024 tarihli bir derleme, toplam 2.601 kişinin katıldığı 20 sağlık davranışı alışkanlık çalışmasını kapsadı [T07]. Yalnızca dört çalışma oluşma süresi tahmini verdi. On birinde yanlılık riski yüksekti. Tanımlar ve yöntemler farklıydı. Tek bir takvim çıkarmak mümkün değil. Alışkanlık gücünün öncesi ve sonrası arasındaki fark, kontrollü tedavi etkisini veya senin davranışının ne zaman otomatikleşeceğini göstermez.","İlerlemeyi izlemeyi artıran uygulamalar, 138 rastgele kontrollü çalışmada hedefe ulaşmayı ortalama olarak artırdı [T05]. Burada yeni ritüel eklemek yerine mevcut kayıtlarını kullan. Planladığın fırsatları, bildirdiğin denemeleri ve ortaya çıkan işleri ayrı say. Ne olduğunu söyleyene kadar eksik bir kayıt bilinmeyen olarak kalır.","Bu denemeyi hâlâ seçtiğin yol için yapmak istiyor musun? Sana uyan küçük işi tekrarla. Sorun çıkaran koşulu değiştir, destek al, dinlen veya dur. Bir sonraki denemeyi kaydedince ODA ertesi gün ne olduğunu gözden geçirmen için zaman ayırır. İstersen kendi takviminde haftalık karşılaştırma için de zaman seçebilirsin. Burada ikinci bir randevu oluşturulmaz. Dersi bitirmek ile planını uygulamak ayrı şeylerdir."]}],sourceIds:["T06","T07","T05"]}}],R=[{id:"1676475382103-54041209cf6c",alt:"Kahve fincanının yanında deftere not yazan kadın"},{id:"1740815897057-a93a8cf98a70",alt:"Parkta ağaçların arasındaki yolda yürüyen kadın"},{id:"1758854486305-eb7621f1e2e4",alt:"Büyük kemerli pencerenin yanında masada çalışan kişi"},{id:"1756312177615-e153c9db507d",alt:"Mutfakta telefonda konuşan kadın"},{id:"1768219565623-501f93ae384b",alt:"Akşam bir lambayla aydınlanan masa"},{id:"1529651737248-dad5e287768e",alt:"Planlama takviminin üzerinde duran kalem"}],k=[0,1,1,1,1,1],C=[3,3,3,3,3,3],N={id:"turning-day",title:"Pazartesiyi bekleme. Bugün küçük bir başlangıç yap",subtitle:"Altı ders. İşe yarayan tek değişikliği dene, engeli gör ve haftanı hayatına göre planla.",description:"Hayatında önem verdiğin bir konuda işe yarayan tek bir adım at. Aynı denemeyi altı ders boyunca sürdür. Engeli gör, hazırlığı işin içinde dene, yaptığını dürüstçe kaydet. Gelecek haftayı bu kayda göre planla.",scope:"Yetişkinler için kişisel gelişim eğitimi. Terapi, tanı veya tedavi değildir. Tek günde hayatının değişeceğine söz vermez. Doktorunla konuşmadan tedavini veya ilacını bırakma. Yoğun kaygı, çökkünlük veya günlük hayatını zorlaştıran sıkıntı yaşıyorsan bir sağlık uzmanına başvur. Kendine zarar verme düşüncen veya acil tehlike varsa bulunduğun yerdeki acil yardım numarasını ara.",outcome:"Denenmiş veya ara verilmiş bir değişiklik, gerçeklere dayalı kayıt ve sıradaki uygun tarih.",photo:{id:"1570821805833-1103c43f9c1d",alt:"Ağaçlar arasındaki patikaya düşen güneş ışınları"},lang:"tr",lessons:o.map((a,t)=>{const i=a.judgment.primary,e=i.options.find(n=>n.id===i.bestOptionId),l=i.options.filter(n=>n.id!==i.bestOptionId);return l.splice(k[t],0,e),{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,practice:[...a.move.instructions,"Buraya dönüp gerçekte ne olduğunu kaydet."].slice(0,C[t]),reflection:a.direction.reason.label,question:`${i.scenario} ${i.question}`,options:l.map(n=>n.text),correct:k[t],feedback:e.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,deeper:a.goDeeper.sections,example:a.idea.example,photo:R[t]}})},aa=Object.freeze(Object.defineProperty({__proto__:null,COURSE:N,LESSONS_V2:o,SOURCES:q},Symbol.toStringTag,{value:"Module"}));export{L as a,F as b,V as c,$ as d,J as e,X as f,Q as g,aa as h,Z as p,W as s,_ as t};
